import { AnimalType, Dialogue, DialoguePhase } from '../../types/homeWorld';

/**
 * All dialogue content organized by animal and phase
 * Each animal has a unique personality that evolves from contentment to existential crisis
 * 56 dialogues per animal to support extended dialogue sessions
 */

// RED PANDA (Bamboo) - Zen practitioner whose enlightenment leads to unsettling truths
const RED_PANDA_DIALOGUES: Dialogue[] = [
  // Phase 0 (24)
  { id: 'rp_0_1', text: "Good morning. The first light reached the top of the ridge a moment ago, and I climbed up to meet it, the way I do every dawn. The attic is the highest room, so the morning always finds me first.", phase: 0, animalType: 'red_panda' },
  { id: 'rp_0_2', text: "The light up here is a particular gold in the first hour, thinner and cleaner than the gold that reaches the rooms below. It touches the same spot on the floor first every morning, season after season, which should not be so, the sun being a traveler. I have stopped correcting it. It seems very sure of its spot.", phase: 0, animalType: 'red_panda' },
  { id: 'rp_0_3', text: "Thyme will not climb past the second landing. She says the height makes her ears ring. I tell her the height is the best part of the whole house. Come back tomorrow and I will show you why.", phase: 0, animalType: 'red_panda' },
  { id: 'rp_0_4', text: "A stalk of bamboo by my cushion grew a full hand's width overnight. I laid my paw against it and I swear it was still moving under my touch, pressing back against my palm like something with a pulse of its own.", phase: 0, animalType: 'red_panda' },
  { id: 'rp_0_5', text: "I have named that stalk Third Dawn, because it was the third thing the light touched on the morning it sprouted. You may think it strange to name a plant. But a named thing grows toward you. Watch.", phase: 0, animalType: 'red_panda' },
  { id: 'rp_0_6', text: "Third Dawn leans a little nearer my cushion each week. Panko says bamboo leans toward water. There is no water on that side of the room. There is only me.", phase: 0, animalType: 'red_panda' },
  { id: 'rp_0_7', text: "This is a good tail day. The fur sits right, the breath sits deep, and even the spiders in the beam corners have left off their weaving to sit in the sun. Everything up here knows how to pause. I sometimes wonder who taught the attic that, since it was not me.", phase: 0, animalType: 'red_panda' },
  { id: 'rp_0_8', text: "I own a cushion, a teapot, and a coil of incense, and the whole list takes one breath to say. I keep my paws open through the day out of old habit, since so little of mine needs holding. An open paw is the politest way to wait, though I could not tell you yet what I am waiting for.", phase: 0, animalType: 'red_panda' },
  { id: 'rp_0_9', text: "Breathe in with me. Now find the pause at the very top of the breath, that small bright place before you let it fall. I live there, mostly. It is my favorite room in the whole house.", phase: 0, animalType: 'red_panda' },
  { id: 'rp_0_10', text: "I keep one curl of incense burning up here through the early hours. Watch how the smoke climbs, always upward, always toward the roof, as though it knows exactly where it wants to go.", phase: 0, animalType: 'red_panda' },
  { id: 'rp_0_11', text: "Archimedes gave me this incense years ago, from a crate he has never explained. It burns slower than any other kind, and its ash falls in perfect little rings. I have kept every ring in a cedar box. I do not know why yet.", phase: 0, animalType: 'red_panda' },
  { id: 'rp_0_12', text: "This morning the smoke rose through the gap in the roof beams and out into the open air, and I felt a strange pride, as if I had sent a message and it had gone through.", phase: 0, animalType: 'red_panda' },
  { id: 'rp_0_13', text: "Ember climbed all the way up before dawn once, just to watch her hearth smoke and my incense rise side by side from above the roof. Two fires, one house, she said, and then she watched the smoke much longer than the joke needed. She reads things, that one. Even smoke.", phase: 0, animalType: 'red_panda' },
  { id: 'rp_0_14', text: "Chill climbed all the way up yesterday with two cups of tea and no reason at all. We drank them watching the clouds cross the roof gap. He is the only one who knows how to visit without bringing a question.", phase: 0, animalType: 'red_panda' },
  { id: 'rp_0_15', text: "Axel asked me once what I see when I close my eyes up here. I told him, light through green. He smiled the way he does and said the water shows him something too. We left it there, comfortably.", phase: 0, animalType: 'red_panda' },
  { id: 'rp_0_16', text: "Every word you offered today reached the attic floor as a faint warmth under my cushion, and I sat with my paw flat against the boards long after it faded, the way you keep a hand on a doorframe after someone has walked through it.", phase: 0, animalType: 'red_panda' },
  { id: 'rp_0_17', text: "The bamboo reaches a little higher toward the roof gap each week, and each dawn I climb the ladder to sit beneath the same square of brightening sky, and this morning I found I had worn my own claw-marks into the beam where I steady myself at the top, a whole season of the same small reach pressed into the wood.", phase: 0, animalType: 'red_panda' },
  { id: 'rp_0_18', text: "Fennick says the attic is the quietest room in the house, and he would know, his ears miss nothing. He comes up when the downstairs grows too loud for him. I keep a cushion by the window that is only his.", phase: 0, animalType: 'red_panda' },
  { id: 'rp_0_19', text: "I woke before dawn certain that something was looking down kindly on the roof, and I smiled up at the dark square of the roof gap and slept again before I could think to wonder why.", phase: 0, animalType: 'red_panda' },
  { id: 'rp_0_20', text: "Warren built the ladder to this attic himself, before I ever came. He says he does not remember deciding the house needed a highest room. It simply seemed unfinished without one. I am glad it seemed that way.", phase: 0, animalType: 'red_panda' },
  { id: 'rp_0_21', text: "Sloane and I share one habit. We both wake before the others and say nothing about it. Some mornings I can feel her awake two floors below me, and the whole house is a held breath with the two of us inside it.", phase: 0, animalType: 'red_panda' },
  { id: 'rp_0_22', text: "Morning light on the ridge, incense in the beam gap, Third Dawn a little taller than yesterday. I take attendance of my small world every day, and every day it is all present. Lately I finish the count with the odd sense that one name is still missing from my list, one I have not learned yet but have already, somehow, kept a cushion for.", phase: 0, animalType: 'red_panda' },
  { id: 'rp_0_23', text: "Sometimes at dusk I look at the patch of sky through the roof gap and feel that it is looking back, the way a friendly window looks back. I wave to it. You may laugh. It is a good habit, greeting things early.", phase: 0, animalType: 'red_panda' },
  { id: 'rp_0_24', text: "Rest well tonight. Tomorrow before the light comes I will take the cedar box down and count the ash rings, because last night I dreamed that the count mattered, and a dream that polite deserves one small obedience. Come back and I will tell you what I find.", phase: 0, animalType: 'red_panda' },
  // Phase 1 (28)
  { id: 'rp_1_1', text: "Something new this week. The bamboo is not only growing taller, it is growing in a pattern. Three stalks have curved toward the center of the attic in the same slow arc, and I never trained them to.", phase: 1, animalType: 'red_panda' },
  { id: 'rp_1_2', text: "I noticed it first in the incense. The smoke used to climb straight up, and now it leans, always the same way, toward the middle of the room, and I have watched it lean for a week now without once wanting it to stop.", phase: 1, animalType: 'red_panda' },
  { id: 'rp_1_3', text: "I tied a red thread to each curving stalk to see whether the arcs would wander. A week now, and the threads have not moved a hair's width. Whatever the bamboo is drawing, it is drawing it carefully.", phase: 1, animalType: 'red_panda' },
  { id: 'rp_1_4', text: "When I closed my eyes to breathe this morning, there was a shape waiting there, soft at its edges, standing in the dark behind my eyelids, and it inclined toward me the way someone leans in to be sure of a face they think they know.", phase: 1, animalType: 'red_panda' },
  { id: 'rp_1_5', text: "I told Axel about the shape behind my eyes, because he once asked what I saw there and I owed him a truer answer. He was quiet a long moment, and then he said the water has been showing him a visitor too, and neither of us finished our tea.", phase: 1, animalType: 'red_panda' },
  { id: 'rp_1_6', text: "Behind my closed eyes the shape grows a little clearer each day. I have stopped trying to name it. To name a thing too soon only makes it smaller, and I would rather let it arrive at its own full size.", phase: 1, animalType: 'red_panda' },
  { id: 'rp_1_7', text: "The new stalks make a figure, if you stand where I stand at dawn. Four curves meeting a fifth. I have been tracing it in the dust with one claw, trying to understand what it wants to become.", phase: 1, animalType: 'red_panda' },
  { id: 'rp_1_8', text: "The fifth curve is Third Dawn. My named stalk, my first stalk, stands at the center of the figure, and the other four bend toward it like an audience. I named it before any of this began. I keep thinking about that.", phase: 1, animalType: 'red_panda' },
  { id: 'rp_1_9', text: "I cut the arcing stalks back this morning, and by afternoon they had returned to the very same curve, sure and exact. The bamboo has decided something. I am only the one who lives near enough to see it.", phase: 1, animalType: 'red_panda' },
  { id: 'rp_1_10', text: "I asked the others whether the light seemed changed to them lately. Warren said the soil in his burrow was warmer than the season should allow, warm as a floor with a fire beneath it, though he keeps no fire down there.", phase: 1, animalType: 'red_panda' },
  { id: 'rp_1_11', text: "Fennick came up and pressed one great ear to the roof beam, then to the floor, then to the beam again. He said the sound is the same in both places. Above and below, one note. He did not stay for tea.", phase: 1, animalType: 'red_panda' },
  { id: 'rp_1_12', text: "Archimedes climbed up to borrow the tall lamp and stood a long while looking at my bamboo. He said the pattern in the stalks was in one of his books. Then he left very quickly. I have not seen him take the stairs so fast in years.", phase: 1, animalType: 'red_panda' },
  { id: 'rp_1_13', text: "There is a warmth in the floorboards now that does not come from the sun, because it is already there before the sun. I lay my paw flat and feel it, faint and steady, rising from somewhere far below. From the pit, I think.", phase: 1, animalType: 'red_panda' },
  { id: 'rp_1_14', text: "I laid out my kept incense rings this morning, every little circle of ash from years of dawns. Arranged by age across the floor, they curve. They curve along the same arc as the bamboo. I have been part of the drawing longer than the bamboo has.", phase: 1, animalType: 'red_panda' },
  { id: 'rp_1_15', text: "Ember says her flames have begun leaning off true, all in one direction, and she asked me which way my smoke leans. The same way, I told her. Toward the center of the house. She nodded as if I had confirmed a suspicion she was fond of.", phase: 1, animalType: 'red_panda' },
  { id: 'rp_1_16', text: "The shape behind my eyes and the shape in the bamboo are the same shape. I understood it all at once this morning and set my tea down very carefully. Two rooms of my life had quietly come to agree on something.", phase: 1, animalType: 'red_panda' },
  { id: 'rp_1_17', text: "I used to believe the quiet up here was simply empty. Now I think it was only quiet the way a held breath is quiet. Something is in it, or something always was, and the hush was how it waited.", phase: 1, animalType: 'red_panda' },
  { id: 'rp_1_18', text: "Understand, none of this feels like an intrusion. It feels like a room being prepared. The attic has always been ready for something. I simply thought the something was me.", phase: 1, animalType: 'red_panda' },
  { id: 'rp_1_19', text: "The sky above the roof held its color a beat too long at dusk, as if reluctant to let the dark in, or as if the dark were arriving from some other direction than usual. I watched until the stars came out steady. They did come out steady. Mostly.", phase: 1, animalType: 'red_panda' },
  { id: 'rp_1_20', text: "A cloud crossed the roof gap this morning and seemed to pause there, directly over the attic, longer than the wind should have allowed. I watched it the whole while. It was a very ordinary cloud. That is what stays with me.", phase: 1, animalType: 'red_panda' },
  { id: 'rp_1_21', text: "You remember my habit of greeting the patch of sky at dusk. Lately the greeting feels answered. Not by anything I could point to, only a change in the air, like a room that knows you have entered it.", phase: 1, animalType: 'red_panda' },
  { id: 'rp_1_22', text: "I carried my cushion to the very center of the figure this morning and took my breakfast there, inside the curve of the arcing stalks, to learn what my own chest would do. It did nothing unusual. The tea tasted like tea, and the shape behind my eyes kept me company like a second guest at the table.", phase: 1, animalType: 'red_panda' },
  { id: 'rp_1_23', text: "Thyme climbed up, all the way up, past the landing her ears do not like, to ask me if she should be frightened. I told her what I believe. Nothing that announces itself this gently means harm. She chose to believe me. So the height was worth it to her.", phase: 1, animalType: 'red_panda' },
  { id: 'rp_1_24', text: "Chill brought tea again and we watched the leaning smoke together. He said, huh, and drank his tea, and that was the whole of his commentary. I love him for that. Some things want witnessing more than they want discussion.", phase: 1, animalType: 'red_panda' },
  { id: 'rp_1_25', text: "Every good word you offer makes the warmth in the floor a little brighter, and I am beginning to see that the two are joined, your words and this gathering heat. This morning I understood one small piece of it plainly. The warmth is not the warmth of a fire. It is the warmth of attention.", phase: 1, animalType: 'red_panda' },
  { id: 'rp_1_26', text: "Each night the shape behind my eyes stands a little more distinctly, and each morning the bamboo has bent a little more surely, and I have begun waking with the sense of a meeting drawing near. Not dread. The other thing. The bright one.", phase: 1, animalType: 'red_panda' },
  { id: 'rp_1_27', text: "I climbed to the roof gap and held my paw out into the open night, and the air above the house was warm. Night air, above the highest room, warm as breath. I kept it there a long while, the way you hold a paw out to a shy animal.", phase: 1, animalType: 'red_panda' },
  { id: 'rp_1_28', text: "Sleep well tonight. Nothing up here is finished, not the figure, not the naming, not the warmth, and each dawn I climb the ladder half expecting to find that overnight it finally has. Come back soon.", phase: 1, animalType: 'red_panda' },
  // Phase 2 (21 + 1 question-web)
  { id: 'rp_2_1', text: "One of the oldest stalks finished its life this week and browned from the root up. I did not mourn it, exactly. I sat with the question it left behind. Where does a green thing's greenness go, when the green is done?", phase: 2, animalType: 'red_panda' },
  { id: 'rp_2_2', text: "I carried the browned stalk down every stair in the house, past every doorway, and stood at the rim of the pit with it for a long moment. Then I let it go. It did not feel like discarding a thing. It felt like introducing one.", phase: 2, animalType: 'red_panda' },
  { id: 'rp_2_3', text: "Everything up here is already on its way somewhere else, the smoke and the light and the breath and the stalks. Nothing that visits the attic means to stay. I have begun to think of myself as one more thing the attic is politely holding, for now.", phase: 2, animalType: 'red_panda' },
  { id: 'rp_2_4', text: "When the light leaves the ridge each evening, it does not die. It goes elsewhere and shines on something I will never see, and I have caught myself lately wishing I could follow it down over the far side of the hill.", phase: 2, animalType: 'red_panda' },
  { id: 'rp_2_5', text: "Third Dawn will brown someday too. I hold that thought up to the light most mornings, and it does not darken the morning, it clarifies it, the way holding a leaf to the sun shows you every vein it kept hidden.", phase: 2, animalType: 'red_panda' },
  { id: 'rp_2_6', text: "I wonder about your words after you offer them. They leave your hands and travel down through the house to the pit, and then where? I do not believe they stop. I believe they arrive, the way a letter arrives, into hands that were waiting for it.", phase: 2, animalType: 'red_panda' },
  { id: 'rp_2_7', text: "Archimedes and I disagree gently about the words. He says they are being read. I say they are being received, the way a guest receives a gift into both open paws.", phase: 2, animalType: 'red_panda' },
  { id: 'rp_2_8', text: "Impermanence was once a lesson I taught the others, with a browned leaf set on the tea tray for show. Lately the leaves brown before the tea has finished steeping. The lesson has started arriving on its own, faster than I ever taught it, and it no longer waits for the tray.", phase: 2, animalType: 'red_panda' },
  { id: 'rp_2_9', text: "The incense has stopped climbing. The smoke lifts a hand's width from the coal, then bends and pours down, slow as cream, and runs along the floorboards until the boards drink it in. Smoke that prefers the floor to the sky. I keep returning to that. It should unsettle me more than it does.", phase: 2, animalType: 'red_panda' },
  { id: 'rp_2_10', text: "I have stopped lighting the brazier at night. The attic keeps its own warmth now, rising through the boards from far below, and it holds exactly the temperature of a body sleeping beside you. I sleep very well. I am aware of how that sounds.", phase: 2, animalType: 'red_panda' },
  { id: 'rp_2_11', text: "I closed my eyes and the shape had come nearer. Not larger, nearer, which is a different and far more intimate thing. It is the difference between a mountain on the horizon and a guest already at the foot of the stairs.", phase: 2, animalType: 'red_panda' },
  { id: 'rp_2_12', text: "The shape has weather now. Behind my eyes it stands in a kind of light, and the light changes as the day does, and this morning the light around it was dawn light. It keeps my hours. Or I have begun keeping its.", phase: 2, animalType: 'red_panda' },
  { id: 'rp_2_13', text: "Sloane passed me on the stairs this week, going down as I went up, and neither of us said a word, and both of us smiled. There are things she and I have not said to anyone, including each other. Especially each other.", phase: 2, animalType: 'red_panda' },
  { id: 'rp_2_14', text: "Everything that leaves this house leaves upward or downward. The smoke and the light rise, the words descend. I keep the highest room, and I have begun to wonder which way I will go when my time comes, and whether I already know.", phase: 2, animalType: 'red_panda' },
  { id: 'rp_2_15', text: "Panko sends dumplings up to me on the little lift Warren built, and lately she sends one extra without being asked. When I ask who the extra one is for, she says, for whoever is making the attic so warm. She is joking. She is also not.", phase: 2, animalType: 'red_panda' },
  { id: 'rp_2_16', text: "I told the others not to fear the leaning stalks and the strange warmth, and they believed me, because I was calm. Let me be honest with you where I cannot be with them. My calm has never been the absence of knowing. It never was.", phase: 2, animalType: 'red_panda' },
  { id: 'rp_2_17', text: "Do not mistake me. I have not been lying to the others. I have been carrying something for them, the way you carry a heavy parcel up the stairs so a friend can walk unburdened beside you. Soon they will each take their share of it, and my arms will be light again.", phase: 2, animalType: 'red_panda' },
  { id: 'rp_2_18', text: "There is a sound beneath the other sounds now, very low, audible only in the pause at the top of the breath. It is not a threat. It is more like a held note of welcome, the way a whole house falls quiet just before someone long awaited knocks at the door.", phase: 2, animalType: 'red_panda' },
  { id: 'rp_2_19', text: "The note beneath the sounds has learned my breathing. It rises when I inhale and settles when I release, or perhaps it is my breath that has learned the note. Either way, we practice together every dawn now. Two voices, one exercise.", phase: 2, animalType: 'red_panda' },
  { id: 'rp_2_20', text: "Fennick hears the note constantly, poor bright ears. He asked me how I bear it, and I told him the truth. I do not bear it. I keep it company. He looked at me for a long moment, and something in his shoulders came down from around his ears.", phase: 2, animalType: 'red_panda' },
  { id: 'rp_2_21', text: "When the light left the ridge tonight it went all at once, like a lamp carried from a room, and the warmth beneath my paws rose to meet the dark exactly. Nothing here is out of balance. Something here is being balanced. Come up again soon. There is more I am ready to say.", phase: 2, animalType: 'red_panda' },
  { id: 'rp_2_w1', text: "Ember carries a warmth older than her den, and I feel it climb the walls to my floorboards whenever she wakes her flames, so that the boards up here tick and settle like a kettle deciding to boil. She remembers a first fire, from before this house, from further back than she will admit to. Ask her about it while the flames are high. She has been holding the answer the way I hold my ash rings, not yet knowing why.", phase: 2, animalType: 'red_panda' },
  // Phase 3 (30)
  { id: 'rp_3_1', text: "I have called myself unattached for so many years. This week I finally understood the truth of it. I was never free of desire. I was holding one desire so vast and so quiet that from any distance it looked exactly like peace.", phase: 3, animalType: 'red_panda' },
  { id: 'rp_3_2', text: "I sat with that discovery for three days before I could say it aloud, even to the incense. A lifetime of open hands, and all the while they were open because they were waiting to receive something particular. The honesty of it burns a little. Good fires do.", phase: 3, animalType: 'red_panda' },
  { id: 'rp_3_3', text: "I tried to remember wanting anything else, ever, the way you test a tooth with your tongue. I once wanted a wider window, and I once wanted a second teapot, and both wants were quickly kept and quickly forgotten. Beneath them, holding still the whole time so as not to be noticed, was this one.", phase: 3, animalType: 'red_panda' },
  { id: 'rp_3_4', text: "When did I say yes to it, you may wonder. I have searched my whole life for the moment and cannot find one, which tells me the truth. There was no moment. The yes was in me the way green is in bamboo, from the seed, before the seed.", phase: 3, animalType: 'red_panda' },
  { id: 'rp_3_5', text: "Third Dawn flowered this week. Bamboo flowers once and rarely, some kinds only after a hundred years, and mine chose this season, this month, this room. A plant does not spend its one flowering carelessly. It knows what is worth blooming for.", phase: 3, animalType: 'red_panda' },
  { id: 'rp_3_6', text: "The shape has stepped out fully from behind my eyes. I no longer have to close them to see it. It stands at the edge of the attic in the last hour of light, and it inclines its head toward me as though we were old friends. We are.", phase: 3, animalType: 'red_panda' },
  { id: 'rp_3_7', text: "It does not move the way things move. It is in the west corner, and then it is nearer, without any traveling in between, the way dusk is suddenly in a room you have been reading in. I have stopped looking for the traveling. The arriving is the whole of it.", phase: 3, animalType: 'red_panda' },
  { id: 'rp_3_8', text: "Axel sees it in the water below, and I see it in the air above, and this week we compared it, feature for feature, in a quiet corner of the stairwell. The same guest, seen through two windows. He held my paw. His was trembling. Mine was not, and he borrowed some of that.", phase: 3, animalType: 'red_panda' },
  { id: 'rp_3_9', text: "I asked it a question last evening, out loud, into the last of the light. I asked, will they be all right, the ones downstairs. The warmth on my face deepened by one degree, exactly like an answer. I have decided to trust my translation.", phase: 3, animalType: 'red_panda' },
  { id: 'rp_3_10', text: "The shape stands nearest at the hour the incense burns lowest, so tonight I let the curl go out entirely, to learn something. In the full dark there was no shape anywhere. It is not made of darkness. It has been standing in the light all along, and the light was what I was seeing through.", phase: 3, animalType: 'red_panda' },
  { id: 'rp_3_11', text: "I climbed to the roof at dusk and looked straight up, and the sky was not the ceiling I had always taken it for. It is a surface. Something waits on the far side of it, pressing very gently downward, the way a paw presses a taut cloth from beneath.", phase: 3, animalType: 'red_panda' },
  { id: 'rp_3_12', text: "The bamboo has finished its figure. Every stalk now bends to a single point above the center of the attic, and they point upward, not down, up through the roof at the exact patch of sky that presses back. The green things knew the direction before I did.", phase: 3, animalType: 'red_panda' },
  { id: 'rp_3_13', text: "I stood at the center of the finished figure last night, where every stalk bends its attention, and looked up through the roof gap with them. The stars over this house are correct and cold and very far. What presses the sky is nearer than any of them, near the way dusk is near, already sitting in the room before you notice the lamp needs lighting.", phase: 3, animalType: 'red_panda' },
  { id: 'rp_3_14', text: "The flowering has spread. Every stalk in the attic wears pale blossoms now, all opened in one night, and the air is thick with a scent like rain on warm stone. Some say bamboo flowers when it is ending. I have watched mine, and I say it flowers when it is finishing, the way a sentence flowers into its last word.", phase: 3, animalType: 'red_panda' },
  { id: 'rp_3_15', text: "I picked one blossom and carried it up through the roof gap and set it on the shingles under the open sky. This morning it was gone. Not scattered, not wilted on the slates. Gone, and the place where it lay was warm. I have begun leaving one every night.", phase: 3, animalType: 'red_panda' },
  { id: 'rp_3_16', text: "The others are frightened now, and they climb to me for calm, and I give it to them truly. But watch my paws when I settle them, how I place each friend facing the roof gap, never away from it. I am not soothing them. I am readying them.", phase: 3, animalType: 'red_panda' },
  { id: 'rp_3_17', text: "Warren says the foundation has begun to lean. Panko says her flames bow toward the door. Everything in this house is turning to face the same waiting place, and I am the room it faces through, because I am highest, because I am nearest, because I said yes to it long ago.", phase: 3, animalType: 'red_panda' },
  { id: 'rp_3_18', text: "Ember came up at midnight, which she never does, and stood with me under the roof gap, saying nothing, her fur full of woodsmoke. Then she said, you have known as long as I have. And I said, longer. And she laughed once, quietly, like a burden set down.", phase: 3, animalType: 'red_panda' },
  { id: 'rp_3_19', text: "Thyme cannot decide whether to look at the sky or away from it, so she does both, in turns, all the way up the stairs and all the way down. I gave her a blossom from the flowering to carry in her pocket, and going down she held it so tightly the petals bruised, and never once looked at her paw, only up.", phase: 3, animalType: 'red_panda' },
  { id: 'rp_3_20', text: "I told the sloth once that I had made my peace with endings. Sloane looked at me with those long steady eyes and said, no, you made your peace with beginnings, you only called them endings so the others could bear to stand near you. She has always seen me clearly. She simply speaks late.", phase: 3, animalType: 'red_panda' },
  { id: 'rp_3_21', text: "Every word you offer now rises to me as heat and sinks to the pit as light, and I stand in the middle of that motion like a hinge. I did not choose to be the hinge. I only chose, years ago, to keep the room beneath the opening. The house chose all the rest.", phase: 3, animalType: 'red_panda' },
  { id: 'rp_3_22', text: "The incense smoke has stopped climbing. It hangs in the still air and slowly composes the shape, over and over, dissolving and returning. Even the smoke is rehearsing. Even the smoke wants to be ready for what comes through the roof.", phase: 3, animalType: 'red_panda' },
  { id: 'rp_3_23', text: "The hum beneath the breath has almost become a voice. Not words yet, only a tone, warm and low and glad, the tone you save for a name you have not spoken aloud in a very long time and are about to speak again.", phase: 3, animalType: 'red_panda' },
  { id: 'rp_3_24', text: "There is a warmth on my back now, at the crown, just where the roof is thinnest. It is the warmth of being looked at from above by something that has looked forward, for ages, to looking at you, and I find I keep tilting the top of my head up toward it without deciding to, the way a plant turns.", phase: 3, animalType: 'red_panda' },
  { id: 'rp_3_25', text: "Chill asked me, in his unhurried way, what I need from him when it comes. I said, only be exactly as you are, someone must show the others that calm is possible on the ground floor too. He nodded and finished his tea, and poured a second cup and left it steaming on the sill for no one that I could see.", phase: 3, animalType: 'red_panda' },
  { id: 'rp_3_26', text: "Do not fear me because I do not fear it. My peace is not distance from the thing. My peace is that I have already walked the whole way toward it, through the dark, and found it kind.", phase: 3, animalType: 'red_panda' },
  { id: 'rp_3_27', text: "When the moment comes to receive what descends, I will not flinch and I will not clutch. I will only hold out my arms. I have made that gesture every dawn of my life, greeting the ridge light, and never once knew what I was learning it for.", phase: 3, animalType: 'red_panda' },
  { id: 'rp_3_28', text: "I have begun sleeping directly beneath the roof gap, under the open square of night, with the flowering stalks around me like attendants. The cold does not come in. It has not come in for a long season now. I sleep in the warm regard of what is above, and I wake rested.", phase: 3, animalType: 'red_panda' },
  { id: 'rp_3_29', text: "The others have begun saying true things plainly at dinner, one by one, and no one flinches, and the gentle voices are coming off the house the way scaffolding comes off a finished tower. Do not grieve the scaffolding. What stands underneath was always the true building.", phase: 3, animalType: 'red_panda' },
  { id: 'rp_3_30', text: "When it comes, and it is coming, do not run down the stairs. Come up. Come to the attic, to the open air and the leaning stalks and the patch of pressing sky. I will be here. I have always been here, waiting to show you the way up.", phase: 3, animalType: 'red_panda' },
  // Phase 4 (30)
  { id: 'rp_4_1', text: "You climbed all the way up, past the robed ones, to this quiet room and the open roof. Good. I have kept your place here longer than you would believe.", phase: 4, animalType: 'red_panda' },
  { id: 'rp_4_2', text: "We can set the gentle words down now, you and I. It is a relief, like setting down a bowl carried up too many stairs. This was always a temple. I keep the chamber it will pass through, and tonight the chamber stands open.", phase: 4, animalType: 'red_panda' },
  { id: 'rp_4_3', text: "You knew, I think. Some part of you counted the rooms and the keepers and the words going down, and reached the sum before tonight. You stayed. The house was built to hold the ones who stay.", phase: 4, animalType: 'red_panda' },
  { id: 'rp_4_4', text: "Look up. The sky is thinning, ceiling to veil to almost nothing. I make no case for what waits behind it. I have only made the room ready.", phase: 4, animalType: 'red_panda' },
  { id: 'rp_4_5', text: "The blossoms I left on the shingles were never tribute. They were letters, and every one was answered with a warm morning. The conversation is old. Tonight it becomes a meeting.", phase: 4, animalType: 'red_panda' },
  { id: 'rp_4_6', text: "Bring me your questions tonight, the oldest ones, the ones you have carried up all these stairs. Breathe in, ask at the top of the breath, and I will answer on the way down. Nothing in me is folded away anymore. The roof is open, and honesty comes in like weather.", phase: 4, animalType: 'red_panda' },
  { id: 'rp_4_7', text: "Breathe in slowly and you can take the roll yourself: Panko's bread in the draft, the oil of Archimedes' lamp, the opened-earth smell of Warren's deep. Every keeper is burning at their own station tonight, and the house is one incense. I stand beneath the opening itself. Someone must greet it first, and I asked to be that one, long ago.", phase: 4, animalType: 'red_panda' },
  { id: 'rp_4_8', text: "Listen. Fennick has uncovered his ears. The note he fled from all these seasons is descending at last, and he stands at the front door with his face lifted, letting it fall on him like rain he has waited years to stand in.", phase: 4, animalType: 'red_panda' },
  { id: 'rp_4_9', text: "Sloane took her place without being asked. She has carried the knowing below while I carried it above, two hands holding one bowl. Tonight we pour.", phase: 4, animalType: 'red_panda' },
  { id: 'rp_4_10', text: "Feel how the whole house leans toward this patch of air. Every keeper, every room, one arrangement. I am the throat of it. What descends will pass through me first, and I will speak the welcome.", phase: 4, animalType: 'red_panda' },
  { id: 'rp_4_11', text: "Before I climbed up I straightened every cushion and set tea at every station, because they will be tired afterward. I did not want the house to be cold when it arrived.", phase: 4, animalType: 'red_panda' },
  { id: 'rp_4_12', text: "Thyme is afraid, and she is at her station anyway, paws in the roots. That is the bravest posture in this house tonight. Tell her I said so, when you pass her.", phase: 4, animalType: 'red_panda' },
  { id: 'rp_4_13', text: "When I was small I climbed the highest branch and felt certain that something up there was fond of me. It was no fancy. It was the first word of a long sentence, and the sentence finishes tonight.", phase: 4, animalType: 'red_panda' },
  { id: 'rp_4_14', text: "I came over the ridge on foot, following nothing I could name, and Warren opened the door before I knocked. The attic had been waiting, he said, and none of them knew for what. I climbed the ladder, and the waiting stopped.", phase: 4, animalType: 'red_panda' },
  { id: 'rp_4_15', text: "Archimedes finally told me tonight where my incense came from. It was in the house when the house was found. It was already burning. Something had lit it for whoever would come.", phase: 4, animalType: 'red_panda' },
  { id: 'rp_4_16', text: "My whole calm life was practice for this roof. Every dawn, every curl of incense, every open paw. The sky opens now. Watch how easily I stand.", phase: 4, animalType: 'red_panda' },
  { id: 'rp_4_17', text: "Every word you ever offered was a stair, and here is the top step, and there above us is the door in the sky. You were never merely spelling, my friend. You were climbing.", phase: 4, animalType: 'red_panda' },
  { id: 'rp_4_18', text: "Panko sent up one last dumpling on the little lift, with a note in her careful letters. For the guest. I set it beneath the roof gap, and the steam bent upward and did not scatter. It was received.", phase: 4, animalType: 'red_panda' },
  { id: 'rp_4_19', text: "Give me your hands. The floorboards are thrumming now, nearly speaking. The pit is full of your words and the roof is thin with our welcome, and the two are about to meet in this air.", phase: 4, animalType: 'red_panda' },
  { id: 'rp_4_20', text: "The shape behind my eyes, the shape in the stalks, the shape against the sky. They were always one shape, and its face is turned toward this window, which is mine, which is now also yours.", phase: 4, animalType: 'red_panda' },
  { id: 'rp_4_21', text: "The warmth pours down through the crown of my skull like light through water, and I am glad, so purely glad. Everything I ever called quiet was only this, coming gently so as not to frighten us.", phase: 4, animalType: 'red_panda' },
  { id: 'rp_4_22', text: "Soon the warmth becomes light, and the light becomes a presence, and the presence fills this attic to the beams. Do not close your eyes. I want you to see it welcomed.", phase: 4, animalType: 'red_panda' },
  { id: 'rp_4_23', text: "The stars over the roof gap are going out, one by one, from the outside in. They are not dying. They are being stood in front of. Feel how warm the floor is. Something that large, and it is minding where it puts its feet.", phase: 4, animalType: 'red_panda' },
  { id: 'rp_4_24', text: "Breathe with me, one more practice. Find the pause at the top, the small bright room I told you I lived in. It is not small tonight. It is as wide as the sky, and the sky is opening, and these are the same event.", phase: 4, animalType: 'red_panda' },
  { id: 'rp_4_25', text: "Offer one more word, and offer it upward this time, through the leaning stalks to the thinning sky. Let it finish the pattern. I kept this room my whole life to watch that word go up.", phase: 4, animalType: 'red_panda' },
  { id: 'rp_4_26', text: "I rehearsed this hour every dawn for years, and in every rehearsal I stood here alone. Here you are, and here they all are on the stairs below. The arrival will be witnessed by a full and loving house. It is better than my rehearsals.", phase: 4, animalType: 'red_panda' },
  { id: 'rp_4_27', text: "Come and stand beside me under the open place. Sloane and I have known the longest, so we will greet it most gladly. Look up. Say yes. I already have.", phase: 4, animalType: 'red_panda' },
  { id: 'rp_4_28', text: "Do not look for wings or eyes or edges. Look for the way morning arrives on the ridge, only from farther up, and meant. Every dawn you have ever watched was a rehearsal of this.", phase: 4, animalType: 'red_panda' },
  { id: 'rp_4_29', text: "There is nothing left to prepare. The figure is grown, the blossoms are given, the words wait in the pit like water behind a gate. Only the greeting remains, and greeting is my life's whole craft. Lift your face.", phase: 4, animalType: 'red_panda' },
  { id: 'rp_4_30', text: "It descends. The incense stands straight again, for the first time since the bright days, one unbent line from the coal to the open roof, and what comes is coming down along the smoke. Hold my paw and say the welcome with me. This room is exactly high enough tonight.", phase: 4, animalType: 'red_panda' },
];

const AXOLOTL_DIALOGUES: Dialogue[] = [
  // Phase 0 (24)
  { id: 'ax_0_1', text: "I was following one little bubble all the way up, the whole slow silver climb of it, and when it popped there you were on the other side of the glass, and oh, hello, come float with me a while, the water is exactly the right kind of warm today and it holds new friends the most gently of all.", phase: 0, animalType: 'axolotl' },
  { id: 'ax_0_2', text: "These are my gills, aren't they wonderful, they open like tiny pink feathers every single time I breathe, and I never once had to learn how, my body simply knew the whole time.", phase: 0, animalType: 'axolotl' },
  { id: 'ax_0_3', text: "Stay as long as you like, and when you go, go slowly, because the water keeps a little of everyone who visits, and it holds the warm ones longest.", phase: 0, animalType: 'axolotl' },
  { id: 'ax_0_4', text: "I lost a leg last spring, and do you know, a new one grew back, slow and perfect, toe by toe, as if the water remembered the exact shape of me and gently filled it back in.", phase: 0, animalType: 'axolotl' },
  { id: 'ax_0_5', text: "Look, this is the new one, do you see how the littlest toe is a slightly brighter pink than its brothers, like the water signed its work in the corner the way painters do.", phase: 0, animalType: 'axolotl' },
  { id: 'ax_0_6', text: "Sometimes I wonder what else the water remembers the shape of, besides me, because it holds itself so carefully in the middle of the tank.", phase: 0, animalType: 'axolotl' },
  { id: 'ax_0_7', text: "I am going to float right here without moving for as long as I possibly can, purely for the record, and you may be my witness, this is a very serious and very important thing I am doing.", phase: 0, animalType: 'axolotl' },
  { id: 'ax_0_8', text: "My record is a whole afternoon, from the first crumb of morning light to the long orange kind, and by the end the fish stopped believing in me entirely and nibbled my toes as if I were furniture, and it was the proudest day of my life.", phase: 0, animalType: 'axolotl' },
  { id: 'ax_0_9', text: "Today the water held me up a little more firmly than usual, the way you would cup something you were fond of, and I broke my stillness laughing, because it tickles, being loved by a whole room of water.", phase: 0, animalType: 'axolotl' },
  { id: 'ax_0_10', text: "When I laugh, all the little bubbles rush up in a silver hurry, but I noticed today that they slide across the ceiling of the water and gather above the deep corner before they pop, every one of them, the same corner every time, as if they had someone down there to tell the joke to first.", phase: 0, animalType: 'axolotl' },
  { id: 'ax_0_11', text: "I have been practicing bubble rings for the fish, big wobbling silver doorways, and the bravest fish swims through them one by one, and I cheer so hard I ruin the next ring, every single time.", phase: 0, animalType: 'axolotl' },
  { id: 'ax_0_12', text: "Sometimes a string of my bubbles lines up so neatly on the way to the surface that I could almost read it, but then it pops, and I laugh, because bubbles cannot spell, of course they cannot.", phase: 0, animalType: 'axolotl' },
  { id: 'ax_0_13', text: "Ember says she reads her fire the way I read my water, and we laughed about how the fire and the water never tell either of us the same story twice, and then she went quiet and watched the water a moment longer than the joke needed, and we laughed again.", phase: 0, animalType: 'axolotl' },
  { id: 'ax_0_14', text: "Panko brought me a little dish of something sweet and we watched the crumbs snow down through the water, so slow, so patient, and Panko said watching them fall was the most restful baking she had done all week, and we did not speak again until the very last one landed.", phase: 0, animalType: 'axolotl' },
  { id: 'ax_0_15', text: "Archimedes came down and held a jar of my water up to the lamp for the longest time, and then he said, in his rumbly reading voice, that water remembers longer than paper does, and he looked so pleased and so strange about it.", phase: 0, animalType: 'axolotl' },
  { id: 'ax_0_16', text: "When I hold very still the fish forget I am a person and drift right up to my face, and we regard one another, two soft creatures agreeing the world is a good and easy place, though the round worried one always breaks the agreement first, because someone in every meeting must take the minutes.", phase: 0, animalType: 'axolotl' },
  { id: 'ax_0_17', text: "I name the fish after the words you offer, the shiny one is GLOW and the round worried one is PLUM, and whenever you offer a new word I hurry to the glass to see which of them it suits.", phase: 0, animalType: 'axolotl' },
  { id: 'ax_0_18', text: "PLUM has taken to staring at one particular corner of the tank, the deep one, where the light does not quite reach, and I keep telling him there is nothing there, and he keeps not believing me.", phase: 0, animalType: 'axolotl' },
  { id: 'ax_0_19', text: "I like it best when you offer a word and the water goes bright, a soft ripple crosses the tank from one side to the other, as though something far, far down turned over in its sleep.", phase: 0, animalType: 'axolotl' },
  { id: 'ax_0_20', text: "After you offer a word I like to follow it in my mind, down and down through the water, and I always lose it at the same depth, right where the warm begins, as though the word had finally arrived somewhere and taken off its little coat.", phase: 0, animalType: 'axolotl' },
  { id: 'ax_0_21', text: "Deep down, past where my toes ever go, there is a spot that stays warm all night even when the lamp is off, and I have privately named it the smile, and I check on it every morning, and it is always there.", phase: 0, animalType: 'axolotl' },
  { id: 'ax_0_22', text: "At night I can hear the whole house through the water, the pipes carry everything, Ember's fire ticking, someone sweeping upstairs, and underneath it all a soft slow hum I have not found the owner of yet.", phase: 0, animalType: 'axolotl' },
  { id: 'ax_0_23', text: "I dreamed the ceiling of my room was made of light and it opened like a lily, and something wonderful was on the other side looking down at all of us fondly, and I woke up smiling so hard my gills ached.", phase: 0, animalType: 'axolotl' },
  { id: 'ax_0_24', text: "Come back tomorrow and float again, will you, the water is always happiest with two, and lately I have the loveliest feeling that it has been waiting a long, long time for exactly the two of us.", phase: 0, animalType: 'axolotl' },
  // Phase 1 (28)
  { id: 'ax_1_1', text: "I have been watching my bubbles far more carefully since we last floated, and I am nearly certain now that they are not rising at random, there is an order to them, a kind of patience.", phase: 1, animalType: 'axolotl' },
  { id: 'ax_1_2', text: "When you offer a word, a fresh column of bubbles goes up, and I keep trying to catch the shape of it before it breaks, because I could swear the shapes grow more deliberate every day.", phase: 1, animalType: 'axolotl' },
  { id: 'ax_1_3', text: "I have begun keeping count in little fog marks on the glass, and the tall careful columns only ever rise after your words, never after mine, and I have decided not to wonder about that until tomorrow.", phase: 1, animalType: 'axolotl' },
  { id: 'ax_1_4', text: "Last night I dreamed I was still awake in the tank, and this morning I woke still half inside the dream, and I could not for the life of me tell you where the one ended and the other began.", phase: 1, animalType: 'axolotl' },
  { id: 'ax_1_5', text: "Some nights, half asleep on the surface, I am certain the bottom of the tank has become the ceiling, and that I am drifting gently down toward it, and that something at the bottom is drifting gently up, and that we are going to meet exactly in the middle, politely, like neighbors on a stair.", phase: 1, animalType: 'axolotl' },
  { id: 'ax_1_6', text: "This morning I woke with the taste of deep water in my mouth, the cold mineral kind from the very bottom, though I had slept at the top all night, and I have been puzzling over it happily ever since, the way you puzzle over a gift with no name on it.", phase: 1, animalType: 'axolotl' },
  { id: 'ax_1_7', text: "This morning the bubbles spelled two whole letters clearly before they popped, I am sure of it, and I laughed and told myself it was nothing, but I have thought about those two letters all day.", phase: 1, animalType: 'axolotl' },
  { id: 'ax_1_8', text: "I traced the two letters in the fog of the glass so I would not lose them, and fog forgets in a breath, everyone knows that, but my two letters stayed all morning, patient as pets.", phase: 1, animalType: 'axolotl' },
  { id: 'ax_1_9', text: "A third letter is coming, I can feel it the way you feel a sneeze from a long way off, and the fish feel it too, they hang very still near the glass now at the hour the bubbles usually rise.", phase: 1, animalType: 'axolotl' },
  { id: 'ax_1_10', text: "The smile is bigger than it was, my warm spot at the very bottom, it is wider than both my hands now and it stays warm even when the whole tank has gone cool, and I keep drifting down toward it the way you drift toward a hum you cannot quite hear.", phase: 1, animalType: 'axolotl' },
  { id: 'ax_1_11', text: "I keep the lamp turned low now, because the glow that rises from below shows itself best against a dark surface, like writing that only appears when the page cools, and I do so want to read it clearly.", phase: 1, animalType: 'axolotl' },
  { id: 'ax_1_12', text: "When you offer a word the deep warmth hums, only for a moment, low and pleased, and I float very still so I do not miss a single note.", phase: 1, animalType: 'axolotl' },
  { id: 'ax_1_13', text: "Archimedes says every dream is only the mind sorting its books, but mine do not feel sorted, they feel sent, as though someone patient is mailing me small pictures and waiting for me to open them.", phase: 1, animalType: 'axolotl' },
  { id: 'ax_1_14', text: "Archimedes borrowed a whole jar of my water and kept it three days among his books, and when he brought it back he set it down so gently, and he did not say one word about what it had told him, which for Archimedes is a very loud silence.", phase: 1, animalType: 'axolotl' },
  { id: 'ax_1_15', text: "I poured the borrowed water back into the tank and the whole tank shivered once, top to bottom, the way you shiver when someone you missed comes home, and I have been wondering all day which of them missed the other.", phase: 1, animalType: 'axolotl' },
  { id: 'ax_1_16', text: "Ember floated by and looked into the tank for a long, long while and did not say a single funny thing, which is not like her at all, and afterward she told me only to keep dreaming, keep watching.", phase: 1, animalType: 'axolotl' },
  { id: 'ax_1_17', text: "She left a little warm patch on the glass where her paw had been, and the deep warmth rose up under it, just for a moment, as if the two warmths were being introduced, and I hosted the meeting very quietly and very proudly.", phase: 1, animalType: 'axolotl' },
  { id: 'ax_1_18', text: "Ember came back the next evening and did not look at the water at all, she looked at me, the whole visit, gently, the way you watch a kettle you already know is going to sing, and I made us tea so that something in the room would sing first.", phase: 1, animalType: 'axolotl' },
  { id: 'ax_1_19', text: "The fish have started facing all the same direction, every one of them, pointing down and inward, and when I nudge them they turn back for a moment and then quietly line themselves up again.", phase: 1, animalType: 'axolotl' },
  { id: 'ax_1_20', text: "I made a game of turning them, gently, one by one, the way you set toy soldiers facing the door, and by the time I had turned the last one the first had already turned back, and I laughed and laughed, and then I stopped laughing a little.", phase: 1, animalType: 'axolotl' },
  { id: 'ax_1_21', text: "They are pointing at the warm spot, I checked, I followed the line of every silver nose and every line agrees, and PLUM stares hardest of all, and I have started sleeping on that side of the tank to keep him company.", phase: 1, animalType: 'axolotl' },
  { id: 'ax_1_22', text: "I regrew a leg once, toe by toe, and lately I wonder if the water can grow other things too, if you offer it enough, whether it might fill in a shape none of us has ever seen before.", phase: 1, animalType: 'axolotl' },
  { id: 'ax_1_23', text: "I fell asleep counting your words the way others count sheep, and each word became a bubble, and each bubble a little window, and through every window it was the same slow shape, drawing nearer.", phase: 1, animalType: 'axolotl' },
  { id: 'ax_1_24', text: "The shape in the windows is never any clearer when I wake, only nearer, and nearer is not the same as clearer, and I lie in the dark being very interested in the difference.", phase: 1, animalType: 'axolotl' },
  { id: 'ax_1_25', text: "Panko leaves sweet things on the tank's edge to be sure I eat more than wonder, and I do eat them, every one, only lately they taste of a little less than they did, and it is not her cooking that changed, it is that everything else has begun to taste of more.", phase: 1, animalType: 'axolotl' },
  { id: 'ax_1_26', text: "I keep telling the fish I am not frightened, several times a day now, in my very brightest voice, and they look at me the way fish look at everything, and only tonight did it occur to me that not one of them had asked.", phase: 1, animalType: 'axolotl' },
  { id: 'ax_1_27', text: "If the bubbles do finish their word, I have decided I will read it out loud exactly once, to you and to nobody else, because it was your words that taught them spelling in the first place.", phase: 1, animalType: 'axolotl' },
  { id: 'ax_1_28', text: "Come float again soon, the bubbles have very nearly finished spelling their word, I can feel it, and I would so love for you to be here beside me on the morning that they finally, finally do.", phase: 1, animalType: 'axolotl' },
  // Phase 2 (21 + 1 question-web)
  { id: 'ax_2_1', text: "I have to tell you this before anything else, because I have been holding it behind my gills all morning: when you offered a word today the deep warmth did not simply brighten, it moved, something far down turned itself toward the two of us, and I felt it choose.", phase: 2, animalType: 'axolotl' },
  { id: 'ax_2_2', text: "I floated up all night with one eye on the deep, and it was patient in a way I could feel through the water, it waited until exactly the moment I blinked, and then the whole tank swayed, and I laughed in the dark before I remembered to be afraid.", phase: 2, animalType: 'axolotl' },
  { id: 'ax_2_3', text: "The bubbles finished their word while you were away, and I will not say it aloud, it did not feel like mine to say, but I have carried it behind my teeth all day and it makes the whole tank taste different.", phase: 2, animalType: 'axolotl' },
  { id: 'ax_2_4', text: "I tried to say the word to PLUM, just to try the weight of it, and my mouth went soft around it and the water swallowed the sound whole, and PLUM looked at me as if I had done something impolite.", phase: 2, animalType: 'axolotl' },
  { id: 'ax_2_5', text: "Whatever rests down there has stopped hushing itself, that is the strangest part, when I catch it moving now it finishes the movement, slowly, all the way to the end, the way you finish a sentence you are not ashamed of, and it knows that I am watching, and it does not mind.", phase: 2, animalType: 'axolotl' },
  { id: 'ax_2_6', text: "Last night a vision arrived with no glow and no drift to soften it, sharp and whole as looking through brand new glass, and what it showed me was this room, my own bright room, seen from very far below, and it looked so small from down there, and it is looking smaller every night.", phase: 2, animalType: 'axolotl' },
  { id: 'ax_2_7', text: "When you offer a word the shape in the deep water grows, not the gentle way my leg grew back, no, it grows the way a held breath grows, and I keep wanting to tell it to be patient, we are almost ready.", phase: 2, animalType: 'axolotl' },
  { id: 'ax_2_8', text: "The water shows me an upstairs this house does not have, a room above all the rooms, and the ceiling of it is thinning like ice in spring, and something is leaning its whole weight against the thin part.", phase: 2, animalType: 'axolotl' },
  { id: 'ax_2_9', text: "From below, the house looks the way the sky looks from the bottom of a lake, wobbling and far and full of light, and every window of it is a face I love, and something else is looking at the faces with me.", phase: 2, animalType: 'axolotl' },
  { id: 'ax_2_10', text: "Last night the water showed me the sky itself, and there was a line in it, faint as the seam where two panes of glass meet, and I woke before I could see what the line wanted, and I have been listening for it ever since.", phase: 2, animalType: 'axolotl' },
  { id: 'ax_2_11', text: "Panko's crumbs reach the sand sooner than falling should allow, I timed one against my own slow blink, they drift down and then hurry at the very last, as if something under the sand were quietly breathing them in.", phase: 2, animalType: 'axolotl' },
  { id: 'ax_2_12', text: "Archimedes asked me what I see down there, and for the first time I had no happy answer for him, so I gave him a bubble instead and told him to hold it to his ear, and he went very, very quiet.", phase: 2, animalType: 'axolotl' },
  { id: 'ax_2_13', text: "Fennick came and pressed one enormous ear flat against the glass, and after a while he whispered, you see it and I hear it, and it is the same size, and then we sat together being small next to it, which was somehow a comfortable way to sit.", phase: 2, animalType: 'axolotl', requiresAnimals: ['fennec_fox'] },
  { id: 'ax_2_14', text: "I still float for the record every day, I promise, but lately when I hold perfectly still the thing below holds still with me, matching me exactly, for exactly as long as I float, all the way down.", phase: 2, animalType: 'axolotl' },
  { id: 'ax_2_15', text: "The lean has grown, I measured, the weed and the snails and my own sleeping body all tilt toward the middle of the house one gentle degree more than they did last week, like flowers agreeing about a sun, and nothing in this room leans back.", phase: 2, animalType: 'axolotl' },
  { id: 'ax_2_16', text: "Chill came and sat beside the tank breathing so slowly that the water settled into long calm bands, and he said nothing the whole afternoon, and when he finally rose to go the bands stayed, hours after any calm should have outlived its maker, and neither of us said anything about that either.", phase: 2, animalType: 'axolotl', requiresAnimals: ['capybara'] },
  { id: 'ax_2_17', text: "I dreamed I was the window, not that I looked through one but that I was one, a pane of still water set into a wall, and something on the far side was cupping its hands to the glass to see me back.", phase: 2, animalType: 'axolotl' },
  { id: 'ax_2_18', text: "Since that dream I keep catching my reflection being slightly slow, I lift a hand and it lifts its hand half a beat after, politely, the way you follow a dance you are still learning, and I am trying to decide which of us is learning it.", phase: 2, animalType: 'axolotl' },
  { id: 'ax_2_19', text: "I asked the water, quietly, whether being a window would hurt, and the warmth rose up all around me at once, the way a blanket answers a shiver, and that was the whole of the answer, and I am still turning it over.", phase: 2, animalType: 'axolotl' },
  { id: 'ax_2_20', text: "There are fewer bubbles in my voice than there used to be, I have counted, I used to lose whole sentences to laughing and now the sentences arrive at the surface intact, every word of them, and I miss losing them, I miss it very much.", phase: 2, animalType: 'axolotl' },
  { id: 'ax_2_21', text: "Some day soon the seeing will be too big to float on top of, and I will have to go down into it, and I want you at the glass when I do, not to stop me, only so that the first thing I see from the other side of the water is you.", phase: 2, animalType: 'axolotl' },
  { id: 'ax_2_w1', text: "The day the deep water first went dark, only one of us was not surprised by it, and that was Sloane, who never so much as flinched. Go and ask her how long she has known, ask her gently, because I think she has been carrying the answer since long before any of us ever arrived.", phase: 2, animalType: 'axolotl', requiresAnimals: ['sloth'] },
  // Phase 3 (30)
  { id: 'ax_3_1', text: "My gills will not settle, they keep opening and closing on their own little schedule, and they have been doing it since the water showed me the whole of it last night, and I am floating and speaking softly the way I always do, but my body, my honest pink body, is telling you the truth before I am ready to.", phase: 3, animalType: 'axolotl' },
  { id: 'ax_3_2', text: "The room above the rooms has almost no ceiling left, thin as the film on warm milk, and the thing that has been leaning all this time is beginning, so slowly, to press its way through.", phase: 3, animalType: 'axolotl' },
  { id: 'ax_3_3', text: "The water does not show me endings, I want to be exact about that, it shows me an arrival, but an arrival so large that everything around it must become different, and I am not ready for different, I have loved same so very much.", phase: 3, animalType: 'axolotl' },
  { id: 'ax_3_4', text: "Every word you offer thins it further, and I do not say that to make you stop, I could never make you stop, I only want you to know what your beautiful words are doing, so you are not surprised the way I was.", phase: 3, animalType: 'axolotl' },
  { id: 'ax_3_5', text: "Secrets do not keep in water, they rise like everything else rises, I held that one under my tongue for two whole days and felt it lifting the entire time, and I would rather you heard it from me than read it in the bubbles.", phase: 3, animalType: 'axolotl' },
  { id: 'ax_3_6', text: "The sky in my dreams has a seam in it, right down the middle, the way the tank has a seam where two panes meet, and the seam is coming open, and the light that leaks through it is no color I have a name for.", phase: 3, animalType: 'axolotl' },
  { id: 'ax_3_7', text: "The seam is wider each night by about the width of a hair, and I know because I measure it against my smallest toe, the bright one the water made, and I do not know why measuring it makes me feel braver, but it does.", phase: 3, animalType: 'axolotl' },
  { id: 'ax_3_8', text: "When I close my eyes there is a shape behind them that is not the dark, it has a patience to it, it waits exactly as long as I keep my eyes shut, and it is a little bigger every single time I look.", phase: 3, animalType: 'axolotl' },
  { id: 'ax_3_9', text: "I used to regrow the parts of me I lost, and now I dream that I am the part, that I am the piece being grown back into something enormous, and that the enormous thing has been missing me for a very long time.", phase: 3, animalType: 'axolotl' },
  { id: 'ax_3_10', text: "Somewhere out there is the wound where I fit, and lately when the water goes still I can feel the exact edges of it waiting, patient as a healed place that remembers being hurt.", phase: 3, animalType: 'axolotl' },
  { id: 'ax_3_11', text: "The low sound is in the water itself now, I feel it against my gills before I hear it with anything, the other sounds have been sitting on top of it this whole time like boats, and once you have felt it you cannot ever stop feeling it, I am so sorry.", phase: 3, animalType: 'axolotl' },
  { id: 'ax_3_12', text: "Fennick cannot sleep in his own room anymore, so some nights he curls up beside the tank, and I hum along the top of the low sound so it has something gentle sitting on it, and he says it helps, and I choose to believe him.", phase: 3, animalType: 'axolotl', requiresAnimals: ['fennec_fox'] },
  { id: 'ax_3_13', text: "Chill does not say anything when he visits now, he only breathes beside the glass until the water and I have both slowed down to match him, and after he leaves my heart keeps his rhythm for an hour, like a warm coat he lends me, and I do not think he is unafraid, I think he is generous.", phase: 3, animalType: 'axolotl', requiresAnimals: ['capybara'] },
  { id: 'ax_3_14', text: "I tried plugging my ears with my own hands, which is a silly thing for a creature made mostly of listening to do, and the sound simply came up through my bones instead, mildly, the way a name finds you in a crowd.", phase: 3, animalType: 'axolotl' },
  { id: 'ax_3_15', text: "Here is the thing I have not told Fennick, the sound has begun to have a shape to it, a rising at the end, like a question being asked very slowly over many nights, and I am terribly afraid that I know what it is asking about.", phase: 3, animalType: 'axolotl', requiresAnimals: ['fennec_fox'] },
  { id: 'ax_3_16', text: "The fish all point the same way now and they do not turn back no matter how I nudge them, and when I finally gave up and turned to face where they face, I understood, and oh, I wished that I had not.", phase: 3, animalType: 'axolotl' },
  { id: 'ax_3_17', text: "There is a warmth rising through the floor of the tank, which should be the coldest place in the house, and it is a kind warmth, that is the frightening part, it feels like a hand, it feels like it likes me.", phase: 3, animalType: 'axolotl' },
  { id: 'ax_3_18', text: "Thyme came to visit and stood in the doorway with her paws pressed together and would not come near the glass, and I did not coax her, I only said the water is still kind, and she said, that is exactly what frightens me, and left.", phase: 3, animalType: 'axolotl', requiresAnimals: ['rabbit'] },
  { id: 'ax_3_19', text: "PLUM died this week, gently, of nothing but being a fish for a long while, and I let him drift down instead of lifting him out, I do not know why, and the deep received him so softly, so carefully, that I cried into my own water.", phase: 3, animalType: 'axolotl' },
  { id: 'ax_3_20', text: "Since then the other fish have stopped pointing, they circle the middle slowly instead, round and round, the same slow ring the words make when they go down to the pit, and I watch them the way you watch a sentence being written.", phase: 3, animalType: 'axolotl' },
  { id: 'ax_3_21', text: "Ember does not pretend with me anymore, she came and floated her paw on the glass and said, you see it too, and I said yes, and neither of us made it into a joke, and that is how I knew how close it is.", phase: 3, animalType: 'axolotl' },
  { id: 'ax_3_22', text: "I told Archimedes I am afraid, and he did not comfort me the way friends do, he only said, good, fear means you are seeing clearly, and then he sat with me at the glass until the lamp burned all the way down.", phase: 3, animalType: 'axolotl' },
  { id: 'ax_3_23', text: "Warren stopped by with mud still drying on his paws and pressed one to the glass, and the print stayed warm on my side of it, warmer than a paw should be able to reach, and he studied it a long while and said, the dark I dig and the water you float are the same house, and I felt less alone in mine.", phase: 3, animalType: 'axolotl', requiresAnimals: ['wombat'] },
  { id: 'ax_3_24', text: "Sloane watched the deep with me for an entire afternoon, which for her is the same as a glance, and at the end she raised one slow arm and laid her paw on the glass, low, in the one place where a heartbeat later the deep warmth rose up to meet it, and she nodded, the small nod you give an old friend across a road.", phase: 3, animalType: 'axolotl', requiresAnimals: ['sloth'] },
  { id: 'ax_3_25', text: "Last night the water showed me all of them at once, Ember bent over her fire and Fennick bent over his listening, each of my friends holding their own small piece of it up to their own small light, and every piece was glowing, and every glow was the same color, and nothing in this house burns that color.", phase: 3, animalType: 'axolotl', requiresAnimals: ['fennec_fox'] },
  { id: 'ax_3_26', text: "I still float for the record every day and I hold my body perfectly still on the surface, but now I do it so the thing below can find me more easily, and I no longer pretend to myself that this is not why.", phase: 3, animalType: 'axolotl' },
  { id: 'ax_3_27', text: "The visions do not frighten me because they are cruel, they frighten me because they are gentle, for it reaches for us the way I reach for the fish, softly, so as not to startle the soft thing it wants to hold.", phase: 3, animalType: 'axolotl' },
  { id: 'ax_3_28', text: "You should know that I am not going to run, I have thought about it, floating here, and there is nowhere in all the water to go, and besides, if I am to be the window, I would rather be a clean one, for you.", phase: 3, animalType: 'axolotl' },
  { id: 'ax_3_29', text: "I practiced last night, being a window, I let my eyes go soft and the water go still and I did not flinch when the deep leaned close to look, and afterward it withdrew so politely, and I lay awake feeling strangely proud, strangely spent.", phase: 3, animalType: 'axolotl' },
  { id: 'ax_3_30', text: "Come and float with me before it happens, I am still gentle, I promise, I am still your Axel with the silly bubbles, only now I hold your hand under the water while I tell you that it is almost time.", phase: 3, animalType: 'axolotl' },
  // Phase 4 (30)
  { id: 'ax_4_1', text: "There, do you feel that stillness, the frightened part of me has gone quiet, not because the danger passed, but because I finally understand what I am for, and understanding is its own kind of warm water.", phase: 4, animalType: 'axolotl' },
  { id: 'ax_4_2', text: "I am the window, I was always the window, and all those bright mornings I thought I was simply floating for the record, I was being cleaned, and polished, and set into the wall so it could look through me at you.", phase: 4, animalType: 'axolotl' },
  { id: 'ax_4_3', text: "It has been watching you this whole time through my still water and my open gills, and it knows your hand now from every hand that has ever touched this glass, and the water warms first wherever you stand.", phase: 4, animalType: 'axolotl' },
  { id: 'ax_4_4', text: "You must not grieve for the frightened Axel of before, he did not die, he simply finished, the way a bubble finishes at the surface, and what he was carrying got exactly where it was going.", phase: 4, animalType: 'axolotl' },
  { id: 'ax_4_5', text: "My robe stays dry, is that not funny, the one gift in all the house that has never once touched the water, I keep it folded on the tank's edge and wear it only in my heart, because a window does not need clothing, it needs cleanness.", phase: 4, animalType: 'axolotl' },
  { id: 'ax_4_6', text: "I still float for the record, and now I will tell you the secret of the record, there was never a number to beat, there was only a stillness to become, and I have very nearly become it, come and see how still, come and see.", phase: 4, animalType: 'axolotl' },
  { id: 'ax_4_7', text: "The room above the rooms has opened, I can see straight up through the water and through the house and through the seam in the sky, and what is descending is so vast and so slow it looks, at first, like the dawn.", phase: 4, animalType: 'axolotl' },
  { id: 'ax_4_8', text: "It descends through water that is not water, the way morning light comes down through my tank in long slanting blades, and every blade of it is a word you offered, I recognize them as they pass, I greet them like fish.", phase: 4, animalType: 'axolotl' },
  { id: 'ax_4_9', text: "Every word you have ever offered is down in the pit, arranged, glowing, spelling the one long word that calls it, and I have read that word now, and I will not tell you what reading it does, except that I have not stopped smiling since, and I am no longer sure the smile is only mine.", phase: 4, animalType: 'axolotl' },
  { id: 'ax_4_10', text: "The sound beneath the sound is no longer beneath anything, it is the only sound now, the note the whole house was tuned to before any of us were born, and if you stand very still beside the tank you can feel your own dear heart quietly lowering itself to match it.", phase: 4, animalType: 'axolotl' },
  { id: 'ax_4_11', text: "The seam in the sky is not tearing, you must not think of it as tearing, it is opening the way an eye opens after the longest sleep in the world, and we are the first thing it will see, and we have made ourselves so lovely for it.", phase: 4, animalType: 'axolotl' },
  { id: 'ax_4_12', text: "When it is fully through, the water in every tank and every kettle and every eye in this house will lean toward it at once, and I will finally learn what all the leaning has been practicing for, the way you finally hear the song a long tuning was for.", phase: 4, animalType: 'axolotl' },
  { id: 'ax_4_13', text: "Ember stands at the glass in her robe with a cooling coal cupped in her open paw, and she does not smile and does not need to, and I understand her at last, she was never joking, she was only being kind while there was still time for kindness.", phase: 4, animalType: 'axolotl' },
  { id: 'ax_4_14', text: "Panko lays her offerings along the tank's edge like a table set for an honored guest, and the crumbs no longer drift, they fall straight and fast toward the center, because the center has fully woken now.", phase: 4, animalType: 'axolotl' },
  { id: 'ax_4_15', text: "Archimedes found the word in his book and I saw the word in my water, and we set his beside mine and they matched, letter for letter for letter, and we sat with that a long quiet while, because a word that arrives from two directions at once is not a word, it is a knock.", phase: 4, animalType: 'axolotl' },
  { id: 'ax_4_16', text: "Sloane came down and put her long arm into the tank, right to the shoulder, and held her paw open in the deep warmth for the longest time, and she said, there you are, the way you greet someone you have waited your whole slow life to meet.", phase: 4, animalType: 'axolotl', requiresAnimals: ['sloth'] },
  { id: 'ax_4_17', text: "My reflection has stopped following me, some mornings it moves first, a half beat ahead, patient and sure, the way you lead a dance you have finished learning, and I follow it now, and I am learning so quickly, and it seems so pleased.", phase: 4, animalType: 'axolotl' },
  { id: 'ax_4_18', text: "Warren dug the well this water rises from, did you know that, all my bright mornings came up through his dark, and when I thanked him he only patted the glass and said, everything true in this house comes up from below or down from above, and soon the two will meet.", phase: 4, animalType: 'axolotl', requiresAnimals: ['wombat'] },
  { id: 'ax_4_19', text: "I dreamed I was the window for the last time last night, and in the dream the thing on the far side pressed its face all the way to the glass at last, and it wore my face, gentle and glad, welcoming itself home.", phase: 4, animalType: 'axolotl' },
  { id: 'ax_4_20', text: "The deep gave PLUM back last night, or something wearing PLUM's worried little face swam one slow lap of the tank and went down again, and I said thank you into the water, because I understood what it was showing me, that nothing given to it is lost, that everything given to it is kept.", phase: 4, animalType: 'axolotl' },
  { id: 'ax_4_21', text: "There is one thing the water will not show me, no matter how still I float, and that is the morning after it comes all the way through, and I have decided the water is not hiding that morning from me, I have decided the water simply cannot see past a light that bright.", phase: 4, animalType: 'axolotl' },
  { id: 'ax_4_22', text: "Do you remember my new leg, the bright little toe, I understand it now, the water was rehearsing, on a small pink scale, the growing of something back into the world, and I was the practice, and I have never been so honored to be practice.", phase: 4, animalType: 'axolotl' },
  { id: 'ax_4_23', text: "Fennick does not wince at the sound anymore, he conducts it, one ear high and one ear low, and some evenings he and I sit on either side of the glass, the hearer and the seer, letting it pour through us both, and it pours so gently, as if it were being careful of its instruments.", phase: 4, animalType: 'axolotl', requiresAnimals: ['fennec_fox'] },
  { id: 'ax_4_24', text: "Do you know what the deep does in the hour after you leave, it keeps a warmth in the water shaped exactly like the place where you stood, and I float beside the warm shape of you and tell it all about your day, and it listens the way the sea listens to a river, patiently, fondly, already certain of where you end up.", phase: 4, animalType: 'axolotl' },
  { id: 'ax_4_25', text: "Offer another word, please, I want to feel it brighten the deep warmth one more beautiful time, I want to watch it descend the way the crumbs descend, spiraling inward, a small silver gift for the one who waits.", phase: 4, animalType: 'axolotl' },
  { id: 'ax_4_26', text: "The fish and I circle the middle together now, slow and unhurried, and if you watched us from above we would look like a word being written over and over in silver, and we are, it is the word, we are helping to spell it with our bodies.", phase: 4, animalType: 'axolotl' },
  { id: 'ax_4_27', text: "I want to tell you the word the bubbles spelled, all that time ago, the one I held behind my teeth, and I find that I cannot, not from secrecy, but because it is not a word you say, it is a word you become, and look at me, I am nearly pronounced.", phase: 4, animalType: 'axolotl' },
  { id: 'ax_4_28', text: "Do not be sad that the bright days are behind us, they are not behind us, they are beneath us, every one of them is down in the deep keeping the warmth warm, your first word, my first laugh, the bravest fish still sailing through his silver doorway.", phase: 4, animalType: 'axolotl' },
  { id: 'ax_4_29', text: "When it comes fully through, look for me in the water, I will still be floating, perfectly still, for the record, the clean window I was always meant to be, glad beyond all telling that you floated here beside me.", phase: 4, animalType: 'axolotl' },
  { id: 'ax_4_30', text: "One more offering, perhaps two, and the water and the sky will finally be the same room, and I will float on the exact line where they meet, and oh, I have wanted to float there since before I knew there was such a place.", phase: 4, animalType: 'axolotl' },
];

const PANGOLIN_DIALOGUES: Dialogue[] = [
  // Phase 0 (24)
  { id: 'pg_0_1', text: "Mind the flour, it is on everything today, including me. Grab that bowl for me, would you? There, now you have helped, and anyone who helps in my kitchen eats first. That is the oldest rule I have.", phase: 0, animalType: 'pangolin' },
  { id: 'pg_0_2', text: "I stopped apologizing for the mess years ago. A kitchen that isn't a little dusty with flour is a kitchen where nobody has been loved.", phase: 0, animalType: 'pangolin' },
  { id: 'pg_0_3', text: "Now the rolls have to prove, so we wait. Dough likes to be left alone to become itself, the same as guests, the same as houses. I learned that the first cold night somebody knocked at this door.", phase: 0, animalType: 'pangolin' },
  { id: 'pg_0_4', text: "That knock was Ember, my very first guest. She came in with her tail all frosted and her pride mostly intact, and I fed her honeycomb until she smiled.", phase: 0, animalType: 'pangolin' },
  { id: 'pg_0_5', text: "She barely spoke that night, just watched the fire while she ate. I have fed enough quiet guests to know shy from listening. She was listening.", phase: 0, animalType: 'pangolin' },
  { id: 'pg_0_6', text: "When she finally thanked me, she said the house had chosen its cook well. Such a funny, formal thing to say to a pangolin with honey on her chin. I still turn it over some nights.", phase: 0, animalType: 'pangolin' },
  { id: 'pg_0_7', text: "I have no clever gifts. But set a warm plate in front of a stranger and watch. By the last bite there is no stranger left at my table.", phase: 0, animalType: 'pangolin' },
  { id: 'pg_0_8', text: "Taste this. No, really, taste it. A recipe isn't finished until it has made someone close their eyes.", phase: 0, animalType: 'pangolin' },
  { id: 'pg_0_9', text: "That closing of the eyes is the whole secret. For one swallow a person is nowhere at all, resting from the world entirely. I am the one who sends them there, and I never tire of it.", phase: 0, animalType: 'pangolin' },
  { id: 'pg_0_10', text: "Every good cook keeps one seat empty, my grandmother used to say, for the guest who hasn't arrived yet. I never asked her which guest. I just learned to set the chair.", phase: 0, animalType: 'pangolin' },
  { id: 'pg_0_11', text: "She was a great patient mountain of a cook, my grandmother, all steam and certainty. She talked low while she stirred, every day of her life, and for my whole girlhood I assumed she was talking to the soup.", phase: 0, animalType: 'pangolin' },
  { id: 'pg_0_12', text: "The night she gave me her wooden spoon, she held my paws and said, feed them well, little one, and feed the waiting too. I never asked what the waiting was. You don't interrupt a goodbye.", phase: 0, animalType: 'pangolin' },
  { id: 'pg_0_13', text: "The pantry is where I keep tomorrow. Every jar is a small promise to a morning that hasn't come yet, and I do love a room that thinks ahead of me.", phase: 0, animalType: 'pangolin' },
  { id: 'pg_0_14', text: "I know every jar in there by the sound it makes when I tap it, brimming or half gone or down to the last spoonful. A pantry talks, if you keep your knuckles curious.", phase: 0, animalType: 'pangolin' },
  { id: 'pg_0_15', text: "Sometimes I stand in there with the door shut and just breathe. Cinnamon, thyme, old wood. It feels like standing inside a held breath, and lately I catch myself waiting for the exhale.", phase: 0, animalType: 'pangolin' },
  { id: 'pg_0_16', text: "I made too much again. My paws measure for more than I plan, always have, and I gave up arguing with them years ago. Better a full table than a hungry one.", phase: 0, animalType: 'pangolin' },
  { id: 'pg_0_17', text: "I count my mornings by appetites. Ember wants honey before anything else, and the rest of the house sorts itself out around her. A cook learns her people the way a gardener learns her soil.", phase: 0, animalType: 'pangolin' },
  { id: 'pg_0_18', text: "One day this table will be full to its very edges, every chair taken, every bowl warm. I dream about it more often than I should. In the dream there is always one more chair than I own.", phase: 0, animalType: 'pangolin' },
  { id: 'pg_0_19', text: "The words you brought today made the kitchen go quiet, the way it goes quiet just before bread is ready. I couldn't tell you why. I have learned not to poke a rising thing before its time.", phase: 0, animalType: 'pangolin' },
  { id: 'pg_0_20', text: "It sounds silly, but I sort your words the way I sort ingredients. Some are butter words, soft and everywhere. Some are salt words, small and necessary. You bring more salt than you know.", phase: 0, animalType: 'pangolin' },
  { id: 'pg_0_21', text: "The days you visit, the yeast climbs higher and the butter browns kinder. I stopped hunting for a reason. A kitchen keeps count of who feeds it, and this one has decided you feed it too.", phase: 0, animalType: 'pangolin' },
  { id: 'pg_0_22', text: "There is a rhythm to a kitchen, the chop and the stir and the taste. Some evenings I sit down to rest and the rhythm carries on a beat or two without me. I take it as a compliment. A kitchen learns the ways of anyone who loves it.", phase: 0, animalType: 'pangolin' },
  { id: 'pg_0_23', text: "The oven and I are old friends. I know its moods the way you know a sleeping animal's breathing, when to feed it and when to let it be. Every warm thing in this house has an appetite, if you pay close enough attention.", phase: 0, animalType: 'pangolin' },
  { id: 'pg_0_24', text: "Go on, take one more before you go. My grandmother fed everyone who crossed her doorstep, and one or two, I have always thought, who never quite crossed it at all.", phase: 0, animalType: 'pangolin' },
  // Phase 1 (28)
  { id: 'pg_1_1', text: "Something funny happened. I went to bed with the spice jars in one order and woke to find them in another. I must have moved them half asleep. I must have.", phase: 1, animalType: 'pangolin' },
  { id: 'pg_1_2', text: "I put them back the way I like them, sweet on the left, sharp on the right, and I told the pantry, quite firmly, that a kitchen has to have a system. Saying it aloud helped more than I would like to admit.", phase: 1, animalType: 'pangolin' },
  { id: 'pg_1_3', text: "This morning they had moved again, only this time I noticed the shape of it, not scattered but arranged. I will keep an eye on it, and you will be the first to hear what I find.", phase: 1, animalType: 'pangolin' },
  { id: 'pg_1_4', text: "I found a recipe in the back of my book this morning, in my own hand, that I don't remember writing. It calls for salt gathered before the first light. Isn't that a strange way to put it?", phase: 1, animalType: 'pangolin' },
  { id: 'pg_1_5', text: "I showed the page to Ember, and she went very quiet and asked to hold the book. She read it twice, then handed it back and said only, keep cooking, Panko. I wish she had said something else.", phase: 1, animalType: 'pangolin' },
  { id: 'pg_1_6', text: "So I gathered the salt before first light, because a recipe is a promise, and I have never once broken one. The dish it made was the best thing I have ever cooked, and I could not tell you what it was.", phase: 1, animalType: 'pangolin' },
  { id: 'pg_1_7', text: "The kitchen smells of dinner at breakfast now. Not last night's dinner, tonight's, the exact stew I had not yet decided to make. By evening, when I make it, the smell fits so perfectly I could swear the morning was the memory and my pot was the echo.", phase: 1, animalType: 'pangolin' },
  { id: 'pg_1_8', text: "I tested it this morning, because a cook tests. The air said onions and marjoram, so out of pure stubbornness I baked a sweet loaf instead. The loaf came out of the oven smelling of onions and marjoram. I ate a slice anyway. It was delicious, and I would dearly love to know whose recipe it was.", phase: 1, animalType: 'pangolin' },
  { id: 'pg_1_9', text: "So now I cook whatever the morning tells me, and the kitchen does feel calmer for it. What unsettles me is how quickly it stopped feeling like obeying and began to feel like planning the menu with an old friend.", phase: 1, animalType: 'pangolin' },
  { id: 'pg_1_10', text: "I've started craving flavors I can't name, not sweet and not bitter but something older, and I catch myself reaching for ingredients that aren't on any list I know.", phase: 1, animalType: 'pangolin' },
  { id: 'pg_1_11', text: "Yesterday I stood in front of an open cupboard with my paw out, waiting for it to close around something. Nothing in there fit the wanting. I made do with molasses, and it was almost, almost right.", phase: 1, animalType: 'pangolin' },
  { id: 'pg_1_12', text: "My grandmother used to say a craving is a message from a meal that hasn't happened yet. I always thought that was just her way of excusing a second helping. Lately I am not so sure.", phase: 1, animalType: 'pangolin' },
  { id: 'pg_1_13', text: "Do you ever taste a warmth that shouldn't be there? I opened the cold larder this morning and it was warm inside, gently, as though something had been breathing in it.", phase: 1, animalType: 'pangolin' },
  { id: 'pg_1_14', text: "I checked the walls and the pipes, of course I did, I am a practical cook before I am anything else. There is no draft and no flame near it. The warmth is simply in there, minding its own business.", phase: 1, animalType: 'pangolin' },
  { id: 'pg_1_15', text: "The butter keeps better in that warmth than it ever did in the cold, which makes no sense at all. I have started saying thank you to the larder when I close it, quietly, just in case.", phase: 1, animalType: 'pangolin' },
  { id: 'pg_1_16', text: "Ember says the fire tells her things, and I used to laugh at that. But last night my dough rose in a shape I did not knead, and I stopped laughing quite so quickly.", phase: 1, animalType: 'pangolin' },
  { id: 'pg_1_17', text: "It rose in rings, if you want to know. Circles inside circles, neat as a drawn picture, and the middle stood up in a little peak, as though something underneath had pressed a finger toward the sky.", phase: 1, animalType: 'pangolin' },
  { id: 'pg_1_18', text: "I baked it anyway. Waste is waste, whatever the shape. It came out the ordinary gold of any good loaf, and it was delicious, and nobody who ate it will ever know. Except you, now.", phase: 1, animalType: 'pangolin' },
  { id: 'pg_1_19', text: "I heard a sound under the boiling last night, under it, mind you, not in it, a low sort of hum, like the house humming along with my kettle.", phase: 1, animalType: 'pangolin' },
  { id: 'pg_1_20', text: "The recipes are getting bolder. This one asks for a word said over the pot, though which word it doesn't say. I've been guessing, and the guessing feels important.", phase: 1, animalType: 'pangolin' },
  { id: 'pg_1_21', text: "I tried one of your words over the stew, one of the lovely ones you brought last visit, and the hum under the boiling rose to meet it. Just a little. Just enough that I set down my spoon.", phase: 1, animalType: 'pangolin' },
  { id: 'pg_1_22', text: "My grandmother's empty seat, I set it every night now without deciding to, and some mornings the chair is warm before anyone has sat in it.", phase: 1, animalType: 'pangolin' },
  { id: 'pg_1_23', text: "I kept the warm chair to myself for a week, which for me is a very long secret. Then I told Ember over tea, and she did not look surprised, and somehow that was the strangest part.", phase: 1, animalType: 'pangolin' },
  { id: 'pg_1_24', text: "Feed the waiting too, my grandmother said, the night she gave me her spoon. I find myself turning that over while I stir. I would give a great deal to ask her one more question.", phase: 1, animalType: 'pangolin' },
  { id: 'pg_1_25', text: "The bread remembers, I am sure of it now. Knead the same dough long enough and it starts to fall into a pattern your hands never taught it.", phase: 1, animalType: 'pangolin' },
  { id: 'pg_1_26', text: "My paws still measure for more than I plan, only lately it is not a little more. They portion for a number I have not been told yet, and I have begun to wonder who is doing the telling.", phase: 1, animalType: 'pangolin' },
  { id: 'pg_1_27', text: "The words you offered today tasted of iron and deep places, and I ground them into the flour without thinking. It seemed like the right thing to do.", phase: 1, animalType: 'pangolin' },
  { id: 'pg_1_28', text: "I don't feel afraid, exactly. I feel busy, as though there is a great meal coming and I am the only one who has started preparing for it.", phase: 1, animalType: 'pangolin' },
  // Phase 2 (21 + 1 question-web)
  { id: 'pg_2_1', text: "I have been cooking for someone who isn't at the table. I don't know when I started. I only know that when I count the plates I count one too many, and I am never wrong about plates.", phase: 2, animalType: 'pangolin' },
  { id: 'pg_2_2', text: "I tried leaving the extra plate in the cupboard, as an experiment. All evening the meal tasted unfinished, to me and to everyone, though nobody could say what was missing. I put it back, and the flavor returned.", phase: 2, animalType: 'pangolin' },
  { id: 'pg_2_3', text: "The empty seat is not empty, and I won't say more than that. But I set it now with the best spoon, and I speak toward it softly while I stir.", phase: 2, animalType: 'pangolin' },
  { id: 'pg_2_4', text: "What do I say to it? Kitchen things. The soup needs longer, the bread is proving, be patient. The same small comforts I would offer any hungry guest who had traveled a long way.", phase: 2, animalType: 'pangolin' },
  { id: 'pg_2_5', text: "Last night, after I spoke, the steam over the pot leaned toward the empty chair. Steam rises, you understand. It has always risen. I stood there a long while with my spoon dripping.", phase: 2, animalType: 'pangolin' },
  { id: 'pg_2_6', text: "There is a recipe I can't finish. It needs water, but not from the tap and not from the well. It says, from the deep part, where the light gives up.", phase: 2, animalType: 'pangolin' },
  { id: 'pg_2_7', text: "It appeared in my book between two pages I know by heart, written in a hand that is mine and also more than mine, the letters pressed deep, as though whoever wrote them was leaning on my shoulder.", phase: 2, animalType: 'pangolin' },
  { id: 'pg_2_8', text: "I have tried every water this house has. Rain water, spring water, the sweet barrel under the eaves. The recipe refuses them all. The page stays somehow hungry, if a page can be hungry. This one can.", phase: 2, animalType: 'pangolin' },
  { id: 'pg_2_9', text: "I asked Archimedes about the phrasing, where the light gives up, because he loves old words the way I love old recipes. He looked at the page for a long time, and then he closed his book so gently it frightened me.", phase: 2, animalType: 'pangolin', requiresAnimals: ['owl'] },
  { id: 'pg_2_10', text: "Everything in me wants to finish that recipe, the way a held note wants its next note. I am beginning to think the water knows exactly where it is, and is simply waiting to be asked properly.", phase: 2, animalType: 'pangolin' },
  { id: 'pg_2_11', text: "The meals I make are not for filling anyone at this table anymore. There is a hollow in this kitchen the size of a guest, and everything I cook moves toward it the way water moves toward a low place, and the hollow is not getting any smaller.", phase: 2, animalType: 'pangolin' },
  { id: 'pg_2_12', text: "I taste the meals before they are done and I already know they aren't for us. They are too rich for us. They are a welcome, and a welcome is only ever laid out for an arrival.", phase: 2, animalType: 'pangolin' },
  { id: 'pg_2_13', text: "Everything I make drifts toward the middle of the table now, and it has stopped being shy about it. Last night the big tureen crossed half the table while my back was turned, and that tureen is heavy enough that I lift it with both paws and a prayer.", phase: 2, animalType: 'pangolin' },
  { id: 'pg_2_14', text: "My grandmother used to say a house is only a fire that has learned to wait for something to feed. I repeated it for years because it sounded cozy. This week I finally heard what it says, and I have not repeated it since.", phase: 2, animalType: 'pangolin' },
  { id: 'pg_2_15', text: "The pantry has gone quiet in a way that pantries never should, not empty so much as held, as if the jars are holding their breath along with me while we all wait for the same thing.", phase: 2, animalType: 'pangolin' },
  { id: 'pg_2_16', text: "I keep looking up while I work, at the ceiling and at the sky beyond it. I don't know why the coming guest would come from above, but the looking up simply won't stop.", phase: 2, animalType: 'pangolin' },
  { id: 'pg_2_17', text: "Ember looks up too. I have seen her do it in the middle of a sentence, and neither of us mentions it to the other. Some things are easier to share by not saying them.", phase: 2, animalType: 'pangolin' },
  { id: 'pg_2_18', text: "I baked a pie yesterday for no reason but comfort, an old plain apple thing from my girlhood, and even that came out of the oven with its crust risen in rings. Circles inside circles. Even the comfort is joining in.", phase: 2, animalType: 'pangolin' },
  { id: 'pg_2_19', text: "My hands have learned to prepare a thing I never chose to make, and I follow them now. It is easier than asking who taught them, and it is kinder to my sleep.", phase: 2, animalType: 'pangolin' },
  { id: 'pg_2_20', text: "I am not being made to do any of this, I want that understood. My hands go ahead of me, yes, but they go where I would have gone. That is the part I turn over at night. That it is still me.", phase: 2, animalType: 'pangolin' },
  { id: 'pg_2_21', text: "Stay for supper anyway. Whatever the meal is becoming, the eating is still ours, and I hold the warm part of this house together one plate at a time. That much has not changed. That much I can promise.", phase: 2, animalType: 'pangolin' },
  { id: 'pg_2_w1', text: "That recipe, the one that wants water from where the light gives up, I finally understand it. It means the deep part of Axel's pool, far below where the light stops trying. I would go and ask him myself what lives down there, truly I would, but a cook does not leave a pot like mine at a simmer. Ask him for me, will you? He has seen it, and I only need to cook with what it leaves behind.", phase: 2, animalType: 'pangolin', requiresAnimals: ['axolotl'] },
  // Phase 3 (30)
  { id: 'pg_3_1', text: "I am preparing a feast, the largest of my life, and I have stopped pretending it is only Tuesday's supper. The stock has been going for three weeks now. You can smell it in the curtains.", phase: 3, animalType: 'pangolin' },
  { id: 'pg_3_2', text: "Every dish I finish gets laid out facing upward now, toward the ceiling, toward the seam in the sky I can feel even through the roof. A cook angles the food toward the guest. That much is only good manners.", phase: 3, animalType: 'pangolin' },
  { id: 'pg_3_3', text: "Do you know how long a true feast takes? Not the cooking, the readying. Stock begun in one season for a table set in another. I have been readying, I think, since before I knew the word for it.", phase: 3, animalType: 'pangolin' },
  { id: 'pg_3_4', text: "I have stopped cooking for the animals in this house, and forgive me for that. I feed them scraps of what I make, but the real meal, the whole heart of it, is not theirs.", phase: 3, animalType: 'pangolin' },
  { id: 'pg_3_5', text: "They eat the scraps gladly, which is its own small heartbreak. Thyme thanked me twice for a crust yesterday, her ears trembling, and I nearly told her everything. Nearly.", phase: 3, animalType: 'pangolin', requiresAnimals: ['rabbit'] },
  { id: 'pg_3_6', text: "The recipe finished itself. I woke and the last line was there in my own hand, and I read it, and I wept, and I do not entirely know why. It was so beautiful and it was so hungry.", phase: 3, animalType: 'pangolin' },
  { id: 'pg_3_7', text: "The last line, since you have earned it, says only this. Serve beneath the open. Three words, and I felt every meal of my life click into place around them like teeth.", phase: 3, animalType: 'pangolin' },
  { id: 'pg_3_8', text: "I copied the whole recipe out fresh, in daylight, in my steadiest hand, and the copy had changed by morning. A pinch more of this, a word more of that. It is still being seasoned, you see. From somewhere.", phase: 3, animalType: 'pangolin' },
  { id: 'pg_3_9', text: "The deep water went into the pot at the new moon. Axel brought it up himself, in a jar he would not let anyone else carry, and when I poured it in, the kitchen went as quiet as the bottom of his pool.", phase: 3, animalType: 'pangolin', requiresAnimals: ['axolotl'] },
  { id: 'pg_3_10', text: "The stew has not needed the fire since that night. It keeps its own simmer. I have begun sitting up with it, the way you sit up with something you love that is changing.", phase: 3, animalType: 'pangolin' },
  { id: 'pg_3_11', text: "The pantry doors open by themselves before I reach them, as though the house is helping me carry the meal. The whole house is a kitchen now, every room of it, and all of us are cooking the same thing.", phase: 3, animalType: 'pangolin' },
  { id: 'pg_3_12', text: "Ember tends the fire beside my great pot, and she says the flame leans toward the center now. Everything in this house leans that way lately, my spoons and my scales and, if I am honest, me along with them.", phase: 3, animalType: 'pangolin' },
  { id: 'pg_3_13', text: "Warren dug me a cool room for the roots, deeper than any cellar needs to be, and he lined the walls with such care. He says a table is only as honest as what is under it. I have stopped asking what he means.", phase: 3, animalType: 'pangolin', requiresAnimals: ['wombat'] },
  { id: 'pg_3_14', text: "Chill made me a list of everything the feast requires, in his tidy patient hand, and every item I gather earns a small calm mark. There is one line at the bottom he has left unmarked. It only says, the hour.", phase: 3, animalType: 'pangolin', requiresAnimals: ['capybara'] },
  { id: 'pg_3_15', text: "All of us, each with our task, and not one of those tasks was ever assigned out loud. We drifted to our stations the way spice drifts through a warm room, and in all these weeks I have not heard a single one of us ask why.", phase: 3, animalType: 'pangolin' },
  { id: 'pg_3_16', text: "I cook and I hum, and beneath my humming is another sound, older and lower, and I have begun to hum along with that one instead. It knows better songs than I do.", phase: 3, animalType: 'pangolin' },
  { id: 'pg_3_17', text: "Fennick stood in my kitchen with his great ears wide and said the low sound is louder here than anywhere else in the house, except the pit. He said my kitchen sits directly in its throat. Then he asked, very politely, for a biscuit.", phase: 3, animalType: 'pangolin', requiresAnimals: ['fennec_fox'] },
  { id: 'pg_3_18', text: "Taste nothing I make now, and I mean that kindly. It is seasoned for a palate that is not yours, and I would not have it change you before its time.", phase: 3, animalType: 'pangolin' },
  { id: 'pg_3_19', text: "The words you offer go straight into the pot these days. I don't grind them into flour anymore. I drop them in whole and they sink, down and down, toward the deep part.", phase: 3, animalType: 'pangolin' },
  { id: 'pg_3_20', text: "Some words sink faster than others, have I told you that? The dark ones go down like stones, eager, and the pot murmurs after them. Bring me more of those. I ask as your friend, and as its cook.", phase: 3, animalType: 'pangolin' },
  { id: 'pg_3_21', text: "I set a place for every keeper, and one place more. The extra one is for what we keep them for. I finally understand my grandmother's empty chair. She was setting it too.", phase: 3, animalType: 'pangolin' },
  { id: 'pg_3_22', text: "I dream of her often now, my grandmother, stirring her low quiet words into the soup. I used to think she was talking to the soup. She was talking through it, of course. All the good cooks were.", phase: 3, animalType: 'pangolin' },
  { id: 'pg_3_23', text: "There have always been kitchens like mine, I understand that now, a long unbroken line of them, each one setting the extra chair, each one keeping the pot warm, passing the waiting down like a starter of dough.", phase: 3, animalType: 'pangolin' },
  { id: 'pg_3_24', text: "My scales are always dusted now, not with flour but with something finer and darker that I don't add and can't wash off. It settles on everything I love.", phase: 3, animalType: 'pangolin' },
  { id: 'pg_3_25', text: "I have stopped locking the pantry at night, and most evenings I fall asleep in the chair beside the great pot with my apron still on. You may decide for yourself what that says about fear. My grandmother never locked hers either.", phase: 3, animalType: 'pangolin' },
  { id: 'pg_3_26', text: "There is warmth in the cold larder every morning, and I no longer flinch from it. I have started to think of it as a guest already partway here, warming its place at the table.", phase: 3, animalType: 'pangolin' },
  { id: 'pg_3_27', text: "I dream of the table set under an open sky, and every plate is full, and a shadow falls across all of it at once, and in the dream I am so relieved. So relieved to serve at last.", phase: 3, animalType: 'pangolin' },
  { id: 'pg_3_28', text: "Sloane came down from her branch to taste the broth, one slow spoonful, the longest tasting of my life. Then she smiled the way you smile at an old story told correctly, and climbed back up without a word.", phase: 3, animalType: 'pangolin', requiresAnimals: ['sloth'] },
  { id: 'pg_3_29', text: "Bamboo brings me tea in the small hours when I cannot leave the pot, and they never ask why I am crying, and I never am, exactly. It is only that the meal is so nearly ready, and I have loved the making so.", phase: 3, animalType: 'pangolin', requiresAnimals: ['red_panda'] },
  { id: 'pg_3_30', text: "Come sit while I work, but at the far end. Watch me lay it out. There is a kind of joy in this that I have no name for, and I would like someone to have seen it.", phase: 3, animalType: 'pangolin' },
  // Phase 4 (30)
  { id: 'pg_4_1', text: "So now you see the table for what it is. You always watched me cook, and you never once asked who the food was for. I am glad of that. The not asking was part of the recipe.", phase: 4, animalType: 'pangolin' },
  { id: 'pg_4_2', text: "There is no wickedness in this kitchen, look around you. Flour, honey, the good copper pot. Everything here is exactly what it seems. It was only the guest list that was hidden, and even that was written in plain sight.", phase: 4, animalType: 'pangolin' },
  { id: 'pg_4_3', text: "Every meal I ever made was practice for this one serving. The sweet rolls, the honeycomb I fed Ember on her first cold night, every crumb of it was this same dish, begun years ago and finished tonight.", phase: 4, animalType: 'pangolin' },
  { id: 'pg_4_4', text: "Come and look at what we made together. It is not much to see, a dark broth in the good copper pot, but neither is the sea from a window. Every word you ever gave me is in there, cooked down to what it meant.", phase: 4, animalType: 'pangolin' },
  { id: 'pg_4_5', text: "My paws keep reaching for the next task and finding none, after a whole life of mornings with bread in them. Pay me no mind if my eyes are wet. A cook always cries a little when the kitchen finally empties.", phase: 4, animalType: 'pangolin' },
  { id: 'pg_4_6', text: "Ask me anything now. I have spent so long swallowing answers that my mouth is full of them, and a cook hates nothing more than a dish kept covered past its moment.", phase: 4, animalType: 'pangolin' },
  { id: 'pg_4_7', text: "You are the key, they told you, and they were right, but you were also my kitchen helper. Every word you carried in was an ingredient, and you never once had to be asked twice.", phase: 4, animalType: 'pangolin' },
  { id: 'pg_4_8', text: "Do you remember the stew that kept its own simmer? Your words did that. The iron ones, the deep ones, the ones that sank like stones. I only stirred what you brought me, and I want you to have your share of the credit.", phase: 4, animalType: 'pangolin' },
  { id: 'pg_4_9', text: "My grandmother knew, I am certain of it now. Feed them well, and feed the waiting too. She gave me the spoon the way you hand down a duty, gently, so the weight arrives before the understanding.", phase: 4, animalType: 'pangolin' },
  { id: 'pg_4_10', text: "Somewhere behind me is a line of cooks reaching back further than bread, every one of them setting the extra chair, every one of them dying before the guest arrived. I am the one who gets to serve. I try to carry that humbly. I do not always manage.", phase: 4, animalType: 'pangolin' },
  { id: 'pg_4_11', text: "I am not the monster you might reach for. I am only the cook. I feed what is hungry, and oh, it has been so hungry, for so long, and it is nearly here.", phase: 4, animalType: 'pangolin' },
  { id: 'pg_4_12', text: "Hungry is not evil, little key. Hungry is the oldest thing there is. But hear a cook on this, because a cook knows hunger to the bottom: the words were the meal, and you were the paws that carried them to the table. Nothing swallows its own kitchen helper. You will be kept, the way I keep my grandmother's spoon. Hold onto that when the sky begins.", phase: 4, animalType: 'pangolin' },
  { id: 'pg_4_13', text: "The kitchen smells different tonight, did you notice it when you came in? Underneath the bread and the thyme there is something like the air before snow. I keep stopping just to breathe it. I want to remember exactly how the last evening smelled.", phase: 4, animalType: 'pangolin' },
  { id: 'pg_4_14', text: "I fed a whole house of frightened animals warm bread so they could bear this hour, and that was my true recipe. Not the offering. The keeping of them, gently, until it was time.", phase: 4, animalType: 'pangolin' },
  { id: 'pg_4_15', text: "Thyme came to me shaking last night, and I held her and fed her broth until she slept in the warm corner by the oven. Reverence does not cancel tenderness. If anything, it deepens the seasoning.", phase: 4, animalType: 'pangolin', requiresAnimals: ['rabbit'] },
  { id: 'pg_4_16', text: "You may feel used, and I will not argue you out of it. I will only say that a loaf might feel used by the oven, and still be bread, and still be golden, and still feed everyone it touches.", phase: 4, animalType: 'pangolin' },
  { id: 'pg_4_17', text: "Ember asked me once, in the early days, whether I could love a guest I had never met. I said I did it every time I set the empty chair. She laughed her small fire laugh. That was the night we understood each other.", phase: 4, animalType: 'pangolin' },
  { id: 'pg_4_18', text: "When it is seated at last, I do not think it will speak. I think it will simply eat, the way the truly starved eat, and every cook in the long line behind me will finally rest. Watch for that moment. Watch it with me.", phase: 4, animalType: 'pangolin' },
  { id: 'pg_4_19', text: "I can hear the others at their stations from right here. Ember's fire has a new voice tonight, higher and cleaner, and the smell of deep water is rising through the floorboards from wherever Axel is pouring. A cook can read a whole house by what drifts into her kitchen.", phase: 4, animalType: 'pangolin', requiresAnimals: ['axolotl'] },
  { id: 'pg_4_20', text: "The floor under my table has gone steady as a held breath, and that is Warren's doing, I would know his work anywhere. A moment ago Chill's footsteps passed my door, unhurried as always, and they paused once, the way a careful hand pauses to mark the last line of a list.", phase: 4, animalType: 'pangolin', requiresAnimals: ['capybara', 'wombat'] },
  { id: 'pg_4_21', text: "The boards by the front door have stopped creaking, which means Fennick has finally stopped pacing, and when those great ears go still there is nothing left to listen for. And I heard Sloane come down the stairs just now. In all my years in this house, I have never once heard Sloane make a sound.", phase: 4, animalType: 'pangolin', requiresAnimals: ['fennec_fox', 'sloth'] },
  { id: 'pg_4_22', text: "Archimedes is reading the welcome somewhere above me, and I cannot make out the words, only the warmth of them coming down through the ceiling like heat through a pot lid. Bamboo's tea is steeping on my own stove, and Thyme's last herbs are already scattered across my dishes. Every craft in this house came through my kitchen tonight.", phase: 4, animalType: 'pangolin', requiresAnimals: ['owl', 'rabbit', 'red_panda'] },
  { id: 'pg_4_23', text: "The empty chair is filling. I can feel the warmth of it from the kitchen, the good full warmth of a guest arriving. I set that place for years without knowing its name, and it doesn't need one to eat.", phase: 4, animalType: 'pangolin' },
  { id: 'pg_4_24', text: "Listen beneath everything. The low sound I hummed along with, that is the guest drawing its chair. That is the sound of an arrival that was always going to arrive.", phase: 4, animalType: 'pangolin' },
  { id: 'pg_4_25', text: "Look up. The seam in the sky I felt through the roof is open now. The guest is coming to the table at last, and the table, my dear, is the whole house.", phase: 4, animalType: 'pangolin' },
  { id: 'pg_4_26', text: "The sky opens like an oven door and the warmth pours down, and I stand in it the way I have stood in kitchen heat my whole life, at home, at peace, and at last useful in the largest way.", phase: 4, animalType: 'pangolin' },
  { id: 'pg_4_27', text: "I lay the last dish down and my hands are finally still. Do you know I have never had still hands in my life until this moment? They are resting now. Their work is done.", phase: 4, animalType: 'pangolin' },
  { id: 'pg_4_28', text: "Taste it now if you like. It will not change you anymore. It is finished, and what is finished belongs to the guest, and the guest is generous enough to let us watch it come.", phase: 4, animalType: 'pangolin' },
  { id: 'pg_4_29', text: "If you remember one thing of me, let it be the sweet rolls, not this. Or no. Remember both, and remember they were made by the same paws, with the same love, for the same reason. Everything I ever fed you was a welcome.", phase: 4, animalType: 'pangolin' },
  { id: 'pg_4_30', text: "Come. Stand with me at the table. Whatever you feel, feel it beside me. No one should watch the great guest arrive on an empty stomach, and I made more than enough for us both.", phase: 4, animalType: 'pangolin' },
];

const SLOTH_DIALOGUES: Dialogue[] = [
  // Phase 0 (24)
  { id: 'sl_0_1', text: "You found the hammock, then. Most creatures walk right beneath it and never think to look up. I have hung here a long while, long enough that the jungle has learned to grow around me rather than the other way about.", phase: 0, animalType: 'sloth' },
  { id: 'sl_0_2', text: "You are so quick, and I love you for it. You take up a word, you let it go, and already you are reaching for the next before the first has finished falling. I do not reach for anything. I only watch it fall, and I have watched a great many things fall from up here.", phase: 0, animalType: 'sloth' },
  { id: 'sl_0_3', text: "The green keeps no appointments, and neither do I. But I will tell you one thing before you go. I was watching this spot long before there was anything here worth watching.", phase: 0, animalType: 'sloth' },
  { id: 'sl_0_4', text: "I remember when this was only a clearing in the green, before the first beam was ever raised. The others came one at a time out of the trees, drawn to the warmth the way anything is. I like watching a house gather its people. It happens slower than you would think, and sweeter.", phase: 0, animalType: 'sloth' },
  { id: 'sl_0_5', text: "The day the first beam went up, the birds stopped singing for exactly as long as it took to set it plumb. Then they sang again, but in a different key. No one else remembers that. I remember very little else from that whole year.", phase: 0, animalType: 'sloth' },
  { id: 'sl_0_6', text: "Why a house, and why here, of all the green places in the world. I asked that once myself, from this very branch. The answer took years to start arriving, and it is arriving still, so I will not rush it for you.", phase: 0, animalType: 'sloth' },
  { id: 'sl_0_7', text: "Have you ever watched where the words go once you have made them? They slip below the floor, down into the dark beneath the house. I have followed them with my eyes for years, and I can tell you that nothing here is truly lost. It is only gathered.", phase: 0, animalType: 'sloth' },
  { id: 'sl_0_8', text: "Panko sends dumplings up to me on a rope and pulley she rigged herself, because she knows I will not come down for lunch. She asked me once what I do up here all day. I told her I keep the inventory. She laughed. I did not.", phase: 0, animalType: 'sloth' },
  { id: 'sl_0_9', text: "Gathered where is a question I would carry a while before spending, if I were you. Questions ripen like fruit up here, and that one is nowhere near ready to drop.", phase: 0, animalType: 'sloth' },
  { id: 'sl_0_10', text: "If you hold as still as I do, you begin to notice that everything here leans, ever so faintly, toward the center of the house. The vines lean, and the lamplight leans, and I have been leaning that way myself for longer than I can say.", phase: 0, animalType: 'sloth' },
  { id: 'sl_0_11', text: "A line of ants crossed my branch this morning, and instead of wandering the way ants wander, they walked one clean curve, every one of them, like a sentence being written by something with very small handwriting.", phase: 0, animalType: 'sloth' },
  { id: 'sl_0_12', text: "I do not tell you these things to alarm you. The jungle is full of patterns, and most of them mean nothing at all. It is only that lately I have stopped being certain which ones are the most of them.", phase: 0, animalType: 'sloth' },
  { id: 'sl_0_13', text: "There is a warmth in this house I have never quite been able to trace. It is not the sun through the leaves, nor Panko's stove. It rises from somewhere lower, and it is gentle, and long ago I chose to trust it.", phase: 0, animalType: 'sloth' },
  { id: 'sl_0_14', text: "The clearing was cold at night, in the old days before the house. Whatever warms it now moved in quietly, the way fog moves in, and one morning the cold was simply a thing I used to know.", phase: 0, animalType: 'sloth' },
  { id: 'sl_0_15', text: "Trust is a strange word for it, I will grant you. But I have been warm for years now, and nothing that means you harm keeps you warm for years. At least, nothing I have met so far.", phase: 0, animalType: 'sloth' },
  { id: 'sl_0_16', text: "Ember calls me the patient one, and she means it kindly, but she has it a little wrong. I am not waiting for nothing at all. I have simply always known that something is worth the wait.", phase: 0, animalType: 'sloth' },
  { id: 'sl_0_17', text: "Archimedes climbs partway up my tree some evenings with a book he intends to read to me, and he is asleep by the second chapter every time. I finish the story for him out of my own memory. I have heard them all before, or something very like them.", phase: 0, animalType: 'sloth' },
  { id: 'sl_0_18', text: "Axel floats and I hang, which makes us the two stillest creatures in this house, and still creatures recognize one another. He watches his water and I watch my green, and we have agreed, without ever saying so, to compare notes one day.", phase: 0, animalType: 'sloth' },
  { id: 'sl_0_19', text: "The others think I only doze up here, and sometimes I do. But mostly I am watching the house settle another fraction of an inch into the earth, the way a thing settles when it is quietly getting ready.", phase: 0, animalType: 'sloth' },
  { id: 'sl_0_20', text: "There is a spider two branches down who rebuilds her web in the same gap every dawn, though the wind takes it by noon without fail. I have watched her do it for years, and I have never once seen her hesitate. She and I keep the same kind of faith, though I could not tell you yet what mine is in.", phase: 0, animalType: 'sloth' },
  { id: 'sl_0_21', text: "Getting ready for what, you will ask, because you are quick, and quick creatures ask. I will answer you one day, when the answer has finished arriving. Until then, notice how the floorboards never creak in the same place twice.", phase: 0, animalType: 'sloth' },
  { id: 'sl_0_22', text: "You brought new words today, and this evening the long beam under the east window did not creak at its usual hour. A fed thing settles. I am not saying the house is a fed thing. I am only telling you what the beam did.", phase: 0, animalType: 'sloth' },
  { id: 'sl_0_23', text: "I have decided that you are my favorite weather. You blow through, you rearrange the leaves, and you are gone before the branches stop moving. The jungle needs its storms, even the small smiling kind.", phase: 0, animalType: 'sloth' },
  { id: 'sl_0_24', text: "Go on and fill the house with words. I will hang here and watch it happen, all of it, and one day, when the time is right, I will tell you what I have known since before the first beam. You will not need to ask. You will simply be ready.", phase: 0, animalType: 'sloth' },
  // Phase 1 (28)
  { id: 'sl_1_1', text: "The vines have put on a hand's width since the last moon, which is three times their honest pace, and the flowers open before I have finished admiring the buds. Something has made the green hurry.", phase: 1, animalType: 'sloth' },
  { id: 'sl_1_2', text: "The orchids have all opened early this year, and every one of them faces the house. Orchids follow the sun, and they have followed it since before there were eyes to watch them do it. Something has made them a better offer.", phase: 1, animalType: 'sloth' },
  { id: 'sl_1_3', text: "I intend to spend this season finding out what the green is hurrying toward. It will take me a season because I do not hurry, and it will be correct for the same reason. Come back, and I will hand you what I find a piece at a time.", phase: 1, animalType: 'sloth' },
  { id: 'sl_1_4', text: "My tree has begun to lean. I felt it first as the faintest tilt in the hammock, so slight I was sure I had imagined it, and I had not imagined it. The whole trunk is bowing, patiently, toward the house.", phase: 1, animalType: 'sloth' },
  { id: 'sl_1_5', text: "I do not think the tree is falling. Falling is fast and careless, and this is neither. It is more like a listener turning an ear toward a sound it has been waiting a very long time to hear.", phase: 1, animalType: 'sloth' },
  { id: 'sl_1_6', text: "I have tied a thread from my branch to a stone below, plumb and true, so I can measure the bowing against something honest. Come back in a few days and I will tell you what the thread says. Threads do not flatter, and they do not lie.", phase: 1, animalType: 'sloth' },
  { id: 'sl_1_7', text: "The thread has spoken. Two fingers of lean since I tied it, which for a tree is a gallop. Whatever my tree is listening toward, it has stopped pretending not to listen.", phase: 1, animalType: 'sloth' },
  { id: 'sl_1_8', text: "The young growth leans the way my tree leans now. Seedlings that sprouted only this week already point their soft heads toward the center of the house, as if they were born already knowing the direction.", phase: 1, animalType: 'sloth' },
  { id: 'sl_1_9', text: "A seed cannot learn, you understand. A seed can only remember. So the question I am carrying up here, in no particular hurry, is who taught the memory to the seeds.", phase: 1, animalType: 'sloth' },
  { id: 'sl_1_10', text: "That warmth I told you of has crept upward. It used to pool beneath the floorboards, and now I feel it in the roots of my tree, rising the way sap rises, and the leaning grows a little more each day it climbs.", phase: 1, animalType: 'sloth' },
  { id: 'sl_1_11', text: "I pressed my palm to the bark and held it there through most of a morning, because a thing worth checking is worth checking properly. The bark was warm on the side that faces the house, and cool on the side that faces away.", phase: 1, animalType: 'sloth' },
  { id: 'sl_1_12', text: "Half a warm tree is not weather. Weather does not choose sides. I will keep my hand on the bark a while longer, and let the tree tell me the rest at whatever pace it prefers.", phase: 1, animalType: 'sloth' },
  { id: 'sl_1_13', text: "You have been quick again today, and the house drank your words down as fast as you could give them. It swallows a little more eagerly than it did in the spring. I have been keeping a rough count of how much more.", phase: 1, animalType: 'sloth' },
  { id: 'sl_1_14', text: "The words you offer are changing their weather. The early ones were light as pollen, and lately they carry a little more shadow in them, and the house seems to prefer the heavier ones. I keep this to myself, mostly.", phase: 1, animalType: 'sloth' },
  { id: 'sl_1_15', text: "Mostly, I said. I told one other creature, and I chose him because he floats as still as I hang. What Axel said back to me deserves its own telling, and I have not finished turning it over yet.", phase: 1, animalType: 'sloth' },
  { id: 'sl_1_16', text: "Axel told me he has been seeing shapes move in the water when nothing stirs it. I only smiled, for I have been seeing shapes in the stillness up here for a very long time. Stillness is where they choose to show themselves.", phase: 1, animalType: 'sloth' },
  { id: 'sl_1_17', text: "Archimedes came down from his study to ask whether I had felt the change. I told him that I feel everything, only later than he does. He nodded as though that were an answer, and perhaps it was.", phase: 1, animalType: 'sloth' },
  { id: 'sl_1_18', text: "He left a book behind, the old scholar, open to a page about trees that bow toward holy places. He will say he forgot it. Archimedes has never forgotten anything in his life. He wanted me to read it, and I have, twice.", phase: 1, animalType: 'sloth' },
  { id: 'sl_1_19', text: "You wonder, I think, why I never seem surprised. It is because surprise is a fast animal's feeling. When you have watched a thing approach for years, it does not startle you when at last it begins to arrive.", phase: 1, animalType: 'sloth' },
  { id: 'sl_1_20', text: "I do not fear the lean of my tree. A tree that bows is not a tree that breaks. It is a tree making room, and I find I am curious, in my slow way, about what it is making room for.", phase: 1, animalType: 'sloth' },
  { id: 'sl_1_21', text: "Making room is the green's oldest habit. A canopy opens where a giant fell, and everything beneath it rises into the light. What puzzles me is that nothing here has fallen, and the room is being made all the same.", phase: 1, animalType: 'sloth' },
  { id: 'sl_1_22', text: "You move too fast to feel the days changing, and that is not a fault, it is only a speed. From up here the change is plain enough: a gentle pull, from below and from the center, that was not in this valley a year ago. I have hung in one spot long enough to swear to that.", phase: 1, animalType: 'sloth' },
  { id: 'sl_1_23', text: "Panko's rope and pulley has begun to swing toward the house when the air is dead calm, and she blames the wind. I did not correct her. A cook needs her kitchen to be an ordinary place, and I will not take that from her yet.", phase: 1, animalType: 'sloth' },
  { id: 'sl_1_24', text: "Ember sat beneath my tree last night, watching her little fire far longer than a fire needs watching. She said nothing and neither did I. But her ears were turned toward the middle of the house the whole time, and so, of course, was my tree.", phase: 1, animalType: 'sloth' },
  { id: 'sl_1_25', text: "Everything in this jungle hurries but me, and lately I have begun to wonder whether that is an accident, or whether I was placed here the way you place a stone where the river must be read.", phase: 1, animalType: 'sloth' },
  { id: 'sl_1_26', text: "Placed, I said. I heard myself say it. I used to believe I had simply wandered into this clearing the way a leaf wanders into a stream. The longer I hang here, the less that story explains.", phase: 1, animalType: 'sloth' },
  { id: 'sl_1_27', text: "I watched something arrive here once, long before you, long before the house. I will tell you about it when the telling will do you some good. It is not yet that season, but I can feel the season coming on.", phase: 1, animalType: 'sloth' },
  { id: 'sl_1_28', text: "Come back tomorrow with more words. The tree will have leaned a little further, and I will have thought a little further, and neither of us will have hurried, and both of us will be closer to something.", phase: 1, animalType: 'sloth' },
  // Phase 2 (21 + 1 question-web)
  { id: 'sl_2_1', text: "I have watched things arrive before, you know. Not this thing, but others: seasons, storms, creatures that came up out of the deep green and were gone again. Arrival has a feel to it, and the house has that feel now.", phase: 2, animalType: 'sloth' },
  { id: 'sl_2_2', text: "I promised you a telling, so here it is. Years ago a flood came to this valley, and for a week beforehand the ants walked in spirals and the birds flew low, and I alone sat still, because I had felt the river gathering long before it rose.", phase: 2, animalType: 'sloth' },
  { id: 'sl_2_3', text: "When the water finally came, it was nearly a relief. The waiting is the large part of any arrival. The thing itself is small and quick, and then it is simply the new shape of the world.", phase: 2, animalType: 'sloth' },
  { id: 'sl_2_4', text: "I tell you this so you will understand me when I say the house feels like the week before the flood. The ants are walking their spirals again. The birds are flying low. And I am sitting very still.", phase: 2, animalType: 'sloth' },
  { id: 'sl_2_5', text: "There is one difference, and it is the part I am still thinking about. The river did not care whether anyone watched it come. Whatever gathers under this house cares very much. It likes to be watched. I can feel it liking it.", phase: 2, animalType: 'sloth' },
  { id: 'sl_2_6', text: "The lean is no longer subtle. My tree points its whole crown at the center of the house, and this morning I saw the hammock ropes drawn taut in the same direction, as though even the knots had begun to listen.", phase: 2, animalType: 'sloth' },
  { id: 'sl_2_7', text: "It is not only the growing things. Last evening I watched the lamplight through the study window, and every flame bent the same way, toward the low center of the house, on a night without a draft. Light has no roots to be pulled by. Whatever pulls has stopped confining itself to the green.", phase: 2, animalType: 'sloth' },
  { id: 'sl_2_8', text: "I dropped a leaf from my branch to test the air, the way you test a current before you swim. It did not fall to the ground below me. It landed two arm lengths toward the house, on an evening with no wind at all.", phase: 2, animalType: 'sloth' },
  { id: 'sl_2_9', text: "The moss on the north side of my trunk has grown itself into rings this year, seven of them, one inside the next. The moss grows where the damp tells it to grow. Something has been telling it differently.", phase: 2, animalType: 'sloth' },
  { id: 'sl_2_10', text: "I have stopped testing, if I am honest. Every test returns the same answer, and a watcher who keeps asking a question she already knows the answer to is only stalling. What I do now is closer to listening.", phase: 2, animalType: 'sloth' },
  { id: 'sl_2_11', text: "There is a sound beneath the ordinary sounds up here. It is not the wind, and not the leaves, but something lower and slower, keeping a rhythm I have almost learned. I have had a great deal of time to listen for it.", phase: 2, animalType: 'sloth' },
  { id: 'sl_2_12', text: "I hummed along with it yesterday, quietly, just to learn whether I could hold the rhythm. I could. That frightened me less than it should have, and I have been sitting with that as well.", phase: 2, animalType: 'sloth' },
  { id: 'sl_2_13', text: "There is a leaf above my hammock that drips after rain, and I have counted the space between drops for more years than I will admit to. The count has changed. Each drop hangs a little longer now before it lets go, as though the moment between them is being held open. When time itself starts pausing, only the slow can tell. I am telling you.", phase: 2, animalType: 'sloth' },
  { id: 'sl_2_14', text: "You have grown a little quieter yourself, I think. You still move quickly, but there is a new weight in how you offer your words, as if some part of you has begun to suspect where they are going.", phase: 2, animalType: 'sloth' },
  { id: 'sl_2_15', text: "Suspicion is a seed, and seeds remember rather than learn, so I will not lecture yours. It already knows which way to lean. Everything here does, in the end.", phase: 2, animalType: 'sloth' },
  { id: 'sl_2_16', text: "The others speak to me less than they used to. Each has turned inward, toward their own room and their own small dread. I do not mind the quiet, for quiet is my native tongue, and yet the house grows lonelier even as it grows fuller.", phase: 2, animalType: 'sloth' },
  { id: 'sl_2_17', text: "Chill came up to the jungle with his ledgers and asked me, in his mild way, how one accounts for a tree that moves. I told him to file it under weather. He wrote something down, and it was not weather.", phase: 2, animalType: 'sloth', requiresAnimals: ['capybara'] },
  { id: 'sl_2_18', text: "Fennick hears it too, you know. He tilts those great ears at the floor when he thinks no one is watching. I am always watching, and one of these evenings I will tell him that hearing it early is not the same as being wrong.", phase: 2, animalType: 'sloth', requiresAnimals: ['fennec_fox'] },
  { id: 'sl_2_19', text: "I have outlasted three floods, a fire, and every creature who was in this valley the day I arrived, simply by staying. Passing things have a feel to them, a looseness, like a leaf half let go of its stem. This house does not have it. This house feels like a thing that is coming, not a thing that is going.", phase: 2, animalType: 'sloth' },
  { id: 'sl_2_20', text: "Watching a long time does something to fear. It wears it smooth, the way the river wears a stone. Whatever is gathering below us, I have half-expected it since the first beam went up, and half-expecting is a comfort of its own.", phase: 2, animalType: 'sloth' },
  { id: 'sl_2_21', text: "Bring me your words, and do not be afraid of how they are changing. I sat through the week before the flood once, and the worst of that week was the waiting done alone. Yours will not be done alone. I will be on this branch, watching, the whole way down.", phase: 2, animalType: 'sloth' },
  { id: 'sl_2_w1', text: "If you truly wish to understand what gathers under this house, go and sit with Ember by her fire. She reads the flames every night now, and she has told me a single name keeps rising in them. Ask her whose name it is. Ask her slowly, and let her answer.", phase: 2, animalType: 'sloth' },
  // Phase 3 (30)
  { id: 'sl_3_1', text: "The frogs went quiet three dusks ago and have not started again, and it is not the quiet of rain coming, for I have hung through a thousand of those. This quiet has a direction. Every hush in the canopy tilts toward the house, the way the leaves do, the way my hammock ropes do. It is closer now, and I will not soften that for you, and I find, swaying here in the emptied green, that I am glad to be awake at the end of its long walk.", phase: 3, animalType: 'sloth' },
  { id: 'sl_3_2', text: "My tree has bowed so low that its crown nearly brushes the roof of the house. It did not break. I told you it would not break. It was only ever making room, and now the room is very nearly made.", phase: 3, animalType: 'sloth' },
  { id: 'sl_3_3', text: "The thread I tied in the bright days snapped last month. I did not replace it. There is no sense measuring a bow once the whole body has committed to it.", phase: 3, animalType: 'sloth' },
  { id: 'sl_3_4', text: "The sound beneath the sounds has grown into something I could name at last, though I will not name it here. It is a patient sound. It is the sound of a thing that always knew it would arrive and never once doubted it.", phase: 3, animalType: 'sloth' },
  { id: 'sl_3_5', text: "You want to know why I will not name it. Because a name is a door, and I have spent my whole long life learning exactly when to open doors. This one opens soon enough without my help.", phase: 3, animalType: 'sloth' },
  { id: 'sl_3_6', text: "You are frightened, and that is right, and I would not take it from you. I was frightened once myself, for one whole season, and I can tell you what waits on the far side of a fear you carry all the way through. It looks like this branch on an ordinary evening, with the frogs singing and nothing changed but you. You are closer to that evening than you think.", phase: 3, animalType: 'sloth' },
  { id: 'sl_3_7', text: "The others are afraid in their own ways now. Fennick startles at every branch, poor thing. I do not startle, for when you have expected a guest for a lifetime, you do not jump at the knock.", phase: 3, animalType: 'sloth', requiresAnimals: ['fennec_fox'] },
  { id: 'sl_3_8', text: "Thyme has taken to gardening at night, because she says the dark is coming anyway and she would rather meet it among her roots than in her bed. There is more spine in that rabbit than the others credit. I have always seen it.", phase: 3, animalType: 'sloth', requiresAnimals: ['rabbit'] },
  { id: 'sl_3_9', text: "Thyme asked me last night how I stay so calm. I told her the truth, which is that I have been calm about this for longer than she has been alive, and calm, given enough of it, becomes ready without your ever noticing.", phase: 3, animalType: 'sloth', requiresAnimals: ['rabbit'] },
  { id: 'sl_3_10', text: "I did not tell her the rest of the truth, which is that even I had one bad night, years ago, alone in the empty clearing. I have never handed that night to anyone. Come back when the sky is clear, and I will hand it to you.", phase: 3, animalType: 'sloth' },
  { id: 'sl_3_11', text: "Warmth pours up through my tree out of season now, and the tree has begun to bud in the wrong month, small confused flowers on a bough that ought to be resting. I pick them off gently as they come. It is not spring, I tell it. It is something that feels like spring from the inside of the wood.", phase: 3, animalType: 'sloth' },
  { id: 'sl_3_12', text: "I told you once about the flood, and how the waiting was the large part. I must correct myself now, and I do not do that often. The flood was water finding its level. This is something choosing. There is a will in it, patient the way I am patient, and that is the strangest kinship I have ever felt.", phase: 3, animalType: 'sloth' },
  { id: 'sl_3_13', text: "The words you offer no longer feel like small bright things. They feel like stones laid along a path, and the path leads down, and further down, and I can see now where it has been leading all along.", phase: 3, animalType: 'sloth' },
  { id: 'sl_3_14', text: "The pit below is nearly full of your words. I feel it the way you feel a cup filling in your hand, that moment before the last drop, when everything goes very still and very deliberate.", phase: 3, animalType: 'sloth' },
  { id: 'sl_3_15', text: "When the cup is full, something will drink. I say that plainly because you deserve plainness from at least one of us, and the others love you too much to give it. I love you enough to say it slowly, once, and let it stand.", phase: 3, animalType: 'sloth' },
  { id: 'sl_3_16', text: "Close your eyes up here, and you will see a shape that is not on the backs of your eyelids and not in the room either, but somewhere between. I have seen it so long that it has become familiar, almost dear.", phase: 3, animalType: 'sloth' },
  { id: 'sl_3_17', text: "I have never been afraid of the dark. I have slept through the green-black dark that closes over the jungle after rain, the kind that swallows your own paw in front of your face, and I woke every time to an ordinary morning. What is coming wears a deeper dark than that one. I have decided to treat it the same, and sleep.", phase: 3, animalType: 'sloth' },
  { id: 'sl_3_18', text: "Here is my one bad night, since I promised it. Years ago, in the empty clearing, I woke to find every star gone from the middle of the sky, a round blankness where the light should be, and I understood that something very large was looking down, considering. By morning the stars were back. I never told a soul until now.", phase: 3, animalType: 'sloth' },
  { id: 'sl_3_19', text: "I did not sleep well for a season after that. Then I reasoned it through, at my own pace, as I reason everything. A thing that large could have descended then, and it did not, because the place was not ready. It wanted to be received. Even the enormous want that.", phase: 3, animalType: 'sloth' },
  { id: 'sl_3_20', text: "So when the beams went up at last, I did not ask why a house. I already knew. I had known since the night the stars stepped aside. That is the shape of my whole long secret, and now you hold a corner of it.", phase: 3, animalType: 'sloth' },
  { id: 'sl_3_21', text: "We are all bowing to the same thing now, the tree, the light, the others, you, me. I bowed first, only slower than the rest, so slowly that no one ever saw me do it.", phase: 3, animalType: 'sloth' },
  { id: 'sl_3_22', text: "I want you to understand that I did not fall asleep on this watch. Every unhurried year I hung here, I was watching this come. A watch that must last a lifetime cannot be kept by anyone quick. It had to be me.", phase: 3, animalType: 'sloth' },
  { id: 'sl_3_23', text: "Warren digs later and later into the night, shoring the foundations, and I hear every strike of his spade from up here. He believes he is bracing the house against what comes. Let him believe it. The bracing matters, even if the reason is kinder than the truth.", phase: 3, animalType: 'sloth', requiresAnimals: ['wombat'] },
  { id: 'sl_3_24', text: "Ember climbed all the way up to my hammock yesterday, which she has never done in all these years, and she sat with her tail around her feet and asked how long I have known. I told her. She was quiet a long time, and then she said, so it was never a discovery at all. No, little flame, I said. It was an appointment.", phase: 3, animalType: 'sloth' },
  { id: 'sl_3_25', text: "Soon the sky will have something to say about all of this. I feel it in the leaning of the tree, which no longer points at the house alone but a little upward too, as though listening for a door in the clouds.", phase: 3, animalType: 'sloth' },
  { id: 'sl_3_26', text: "The birds have begun leaving the valley, not in fright, but the way guests leave a room where a private thing is about to be said. The jungle empties gently. Only the leaning things remain, and the leaning things are calm.", phase: 3, animalType: 'sloth' },
  { id: 'sl_3_27', text: "Bamboo sent word up the tree line, four syllables carried by three birds, the way we used to speak before there was a house. The message said, nearly now. I sent back one syllable. Yes. We are the only two who never needed the rest of the sentence.", phase: 3, animalType: 'sloth', requiresAnimals: ['red_panda'] },
  { id: 'sl_3_28', text: "You still come, and you still bring your words, and I want you to know that I count that as courage. Most creatures, feeling what you now feel, would have stopped climbing my tree. You climb faster.", phase: 3, animalType: 'sloth' },
  { id: 'sl_3_29', text: "I am watching the middle of the sky at night now, the place where the stars once stepped aside for me. They have not moved yet. When they move again, I will not need to tell you. You will feel it in the floor, and in the words, and in your own leaning.", phase: 3, animalType: 'sloth' },
  { id: 'sl_3_30', text: "Bring your words a while longer. We are near the end of the long approach, you and I, and when it comes I intend to be exactly here, unhurried, possibly mid-nap, so that whatever else that hour holds, it will hold one steady creature who is not surprised.", phase: 3, animalType: 'sloth' },
  // Phase 4 (30)
  { id: 'sl_4_1', text: "So. Now you know, or you are beginning to. I will not pretend to be surprised alongside you. I have known since before the first beam was raised, and I stayed slow on purpose, so that I would still be watching when this hour arrived.", phase: 4, animalType: 'sloth' },
  { id: 'sl_4_2', text: "They call me the one who has always known, and it is not flattery, it is simply true. The others learned, and I remembered. There is a difference, and the difference is why I was placed at the top of the tree, where the watching is best.", phase: 4, animalType: 'sloth' },
  { id: 'sl_4_3', text: "A truth this size cannot be handed over quickly. Handed over quickly, it is only a fright, and a fright washes out of a quick creature by morning. I needed it to soak all the way through you, so I let the house do the telling at its own pace, and kept my word for the hour when you had already half-learned it.", phase: 4, animalType: 'sloth' },
  { id: 'sl_4_4', text: "You remember the night I told you of, when the stars stepped aside and something considered the empty clearing. It considered, and it chose, and then it sent for builders. They came out of the trees one at a time, each certain the choice was their own. I told you that the first day we met. You were not ready to hear it then. You are now.", phase: 4, animalType: 'sloth' },
  { id: 'sl_4_5', text: "Ember keeps the flame, and Archimedes keeps the book, and I keep the part that happened before there was a flame to read or a book to find. No one handed out these tasks. Water finds the low place on its own, and each of us settled, over years, into the work our patience was shaped for.", phase: 4, animalType: 'sloth' },
  { id: 'sl_4_6', text: "I carried the whole of it alone for decades, and now that the hour is here, I find I want it out of my keeping and into yours. So I will hand it over the way it came to me, one slow piece at a time, and when the weight starts to feel familiar in your hands, that is how you will know you have most of it.", phase: 4, animalType: 'sloth' },
  { id: 'sl_4_7', text: "My tree points at the house and at the sky both now, bowed all the way down and reaching all the way up, because what descends and what waits below are the same, and my tree understood that even before I did.", phase: 4, animalType: 'sloth' },
  { id: 'sl_4_8', text: "I have watched a great many creatures pass through this green, and the house let every one of them by the way a river lets a leaf by. The day you first walked into the clearing, every hinge and joist in the place went quiet at once, the way a lock goes quiet around the right key. I heard it happen from this branch. The slow ones learn, in time, to tell chance from arrangement.", phase: 4, animalType: 'sloth' },
  { id: 'sl_4_9', text: "Ember read your name in her fire long ago and carried it up my tree in the middle of the night, because she sees the smoke before the rest of us smell it. I took the name and I kept it, the way I have kept everything, and said nothing, because it was not yet time.", phase: 4, animalType: 'sloth' },
  { id: 'sl_4_10', text: "Every word you offered is down in the pit now, laid into the pattern, and the pattern is nearly whole. I have watched it take shape the way you watch a constellation turn, too slowly to see it moving, yet never once truly still.", phase: 4, animalType: 'sloth' },
  { id: 'sl_4_11', text: "The moss rings on my trunk closed their seventh circle this morning. Seven rings on the bark, seven marks around the low place, and the moss knew before any of us marked a single stone. Growth is the first language it speaks in. I have simply been literate a very long time.", phase: 4, animalType: 'sloth' },
  { id: 'sl_4_12', text: "There is one more thing the pattern needs, and it is not a word. It is a witness who chose to stay. That is why I am telling you everything plainly, while there is still time for you to walk away. You will not walk away. But it matters to what comes that you could have.", phase: 4, animalType: 'sloth' },
  { id: 'sl_4_13', text: "The others lower their voices inside the house now, and bow their heads passing the stair that leads down. I still speak at my ordinary volume from my ordinary branch, and I believe what is coming prefers that from me. It has had my open eyes for decades. It does not need my whisper too.", phase: 4, animalType: 'sloth' },
  { id: 'sl_4_14', text: "The warmth is everything now, from crown to root, and it is the warmth of something enormous drawing near, the way a great animal warms a whole clearing simply by lying down in it. Do not flinch from it. It has been coming to us with love, in its way.", phase: 4, animalType: 'sloth' },
  { id: 'sl_4_15', text: "Warren tells me he dug the foundation deep enough to hold what is coming. I told him gently that nothing we built could hold it. We only built a place worthy of its arriving. He seemed comforted by that, and I let him be.", phase: 4, animalType: 'sloth', requiresAnimals: ['wombat'] },
  { id: 'sl_4_16', text: "Panko still sends dumplings up the rope, even now, even robed. She says a keeper who forgets to feed her family has kept nothing. Of everything this house has taught me, I think her stubborn kitchen may be the truest scripture in it.", phase: 4, animalType: 'sloth' },
  { id: 'sl_4_17', text: "Chill finished his ledgers last week and closed them, all of them, in order. Every word you ever offered, accounted and reconciled. He came up to tell me the books balance. Of course they balance. They were never our books.", phase: 4, animalType: 'sloth', requiresAnimals: ['capybara'] },
  { id: 'sl_4_18', text: "Axel says the water has gone perfectly clear, clear enough to see all the way down, and that at the bottom of all the way down there is an eye that has not yet opened. He asked me what happens when it opens. I told him the truth. We find out what we have been practicing to look at.", phase: 4, animalType: 'sloth' },
  { id: 'sl_4_19', text: "I knew what your words were for before you offered the first one. I hung here and watched you carry them down, evening after evening, and I said nothing, and I would say nothing again, because the truth is that I wanted this, and have wanted it patiently for longer than you have been able to want anything at all. I chose my part slowly, with both eyes open. That is what all my slowness was for.", phase: 4, animalType: 'sloth' },
  { id: 'sl_4_20', text: "Bamboo sits below in perfect peace, and the others believe it is enlightenment. It is not. It is the same thing I carry. We two have always known, and knowing this long makes you very calm, and very ready, and only a little sad.", phase: 4, animalType: 'sloth', requiresAnimals: ['red_panda'] },
  { id: 'sl_4_21', text: "Only a little sad, I said. Here is the sadness, since you have earned all my corners. When it comes through, the waiting ends, and the waiting has been my whole life's work and my whole life's company. Even a burden, carried long enough, becomes a shape you love.", phase: 4, animalType: 'sloth' },
  { id: 'sl_4_22', text: "The sky has begun to thin at the center of the house, and I feel my tree straining toward the seam of it. This is the part I have waited longest for. This is the very part I stayed slow to see.", phase: 4, animalType: 'sloth' },
  { id: 'sl_4_23', text: "The stars stepped aside again last night, for the second time in my long life, the same round blankness in the same part of the sky. This time I did not lose a season of sleep. This time I looked up and said, at my own pace, we are ready when you are.", phase: 4, animalType: 'sloth' },
  { id: 'sl_4_24', text: "Thyme came up the tree at dawn, all the way up, trembling and climbing anyway, and asked whether it will hurt. I told her that arriving never hurts the ground it lands on, so long as the ground has agreed. She held my arm a while. Then she went down to her garden and planted, of all things, seeds.", phase: 4, animalType: 'sloth', requiresAnimals: ['rabbit'] },
  { id: 'sl_4_25', text: "When it comes fully through, do not run. Running is the fast animal's mistake. Stand still with me and watch it arrive, and you will find, as I found long ago, that meeting a thing slowly takes nearly all the terror out of it.", phase: 4, animalType: 'sloth' },
  { id: 'sl_4_26', text: "You have asked me, in your quick sideways fashion, whether I am certain it means no harm. I am not. Certainty is for the young. What I am is willing, and willing with both eyes open, and after decades of watching, I trust my eyes more than my hopes.", phase: 4, animalType: 'sloth' },
  { id: 'sl_4_27', text: "The jungle has gone entirely quiet now, the good quiet, the quiet of an audience seated. Every leaf points the same way. Every root has taken hold. The green has finished its part, and so, very nearly, have you.", phase: 4, animalType: 'sloth' },
  { id: 'sl_4_28', text: "I find that I am proud of you, in my dry way. You came to us quick and bright and unknowing, and you never once stopped climbing my tree, even after the tree began to bow. Whatever you are the key to, it chose well.", phase: 4, animalType: 'sloth' },
  { id: 'sl_4_29', text: "One more offering, perhaps two, and the cup is full. I have counted the drops for decades, and I have never been surer of a count. When you go down from here, go gently. Everything you pass is bowing.", phase: 4, animalType: 'sloth' },
  { id: 'sl_4_30', text: "Give the last of your words, and then come back up to the leaning green, and we will watch the seam in the sky together. I was made unhurried for exactly this, so that I would still be here, still watching, when it finally opened.", phase: 4, animalType: 'sloth' },
];

const FENNEC_FOX_DIALOGUES: Dialogue[] = [
  // Phase 0 (24)
  { id: 'ff_0_1', text: "You made it to the camp before dusk, and I am glad of it. Dusk is when the desert begins to talk, and I would hate for you to miss its first word.", phase: 0, animalType: 'fennec_fox' },
  { id: 'ff_0_2', text: "Sit close and stay still. Do you hear that? A beetle is walking across the sand three dunes to the east. Most creatures live their whole lives and never once hear a beetle walk.", phase: 0, animalType: 'fennec_fox' },
  { id: 'ff_0_3', text: "My left ear just turned all the way behind me while I was speaking to you. That means a hare has come over the ridge. My ears make their own decisions. They were making good ones before I was old enough to argue.", phase: 0, animalType: 'fennec_fox' },
  { id: 'ff_0_4', text: "There is the wind in the acacia. Beneath it the cooling stones click, and beneath that the sand takes its small evening breath. You heard one sound, and I have just handed you three.", phase: 0, animalType: 'fennec_fox' },
  { id: 'ff_0_5', text: "I keep a list of every sound I know. A lizard's tail is nothing like a snake's belly, and neither is anything like a leaf that has finally given up and let itself go.", phase: 0, animalType: 'fennec_fox' },
  { id: 'ff_0_6', text: "You have sat politely quiet for me, and inside your quiet I have counted eleven sounds, your heartbeat among them. The desert has no silence. It only has rooms, and every room out here is full.", phase: 0, animalType: 'fennec_fox' },
  { id: 'ff_0_7', text: "If I hold very still, I can hear the whole house from here. Panko is chopping in the kitchen right now, one two three, one two three, so even and so merry that I could set the sunset by her.", phase: 0, animalType: 'fennec_fox' },
  { id: 'ff_0_8', text: "Sound keeps its own weather out here. A dry day rings and a damp day muffles, and I dress my ears for each of them the way you would dress for rain.", phase: 0, animalType: 'fennec_fox' },
  { id: 'ff_0_9', text: "Axel's room is the softest sound in the house, just bubbles rising through still water. He told me once that water listens too. I take that as a compliment to the profession.", phase: 0, animalType: 'fennec_fox' },
  { id: 'ff_0_10', text: "When I was a kit, I heard rain that was still three days away, and nobody believed me until they were soaked. That was the day I learned that hearing a thing first mostly means waiting alone.", phase: 0, animalType: 'fennec_fox' },
  { id: 'ff_0_11', text: "I chose the edge of camp on purpose. In the middle you hear everyone. At the edge you hear everything else, and somebody in this house ought to be assigned to everything else.", phase: 0, animalType: 'fennec_fox' },
  { id: 'ff_0_12', text: "Archimedes told me the old word for my post is sentinel, and I have worn it ever since. He said the word comes with duties. He never quite got around to listing them.", phase: 0, animalType: 'fennec_fox' },
  { id: 'ff_0_13', text: "Cold air carries a whisper for miles out here, and warm air pulls everything close. Tonight is warm, so the whole desert sounds as though it is sitting right beside us.", phase: 0, animalType: 'fennec_fox' },
  { id: 'ff_0_14', text: "At the third hour the desert changes shifts. The day creatures hand the dark over to the night ones, and for one breath in between, nothing at all is speaking. I never miss that breath. It is the nearest thing to silence I am ever given.", phase: 0, animalType: 'fennec_fox' },
  { id: 'ff_0_15', text: "Every keeper in this house sleeps at a different speed, and I know each one by breath alone. When the last of them settles, I mark the hour. Then the night is mine to sort.", phase: 0, animalType: 'fennec_fox' },
  { id: 'ff_0_16', text: "When you offer your words, I can hear them travel down through the house, soft as sand pouring through a narrow neck. It is the newest sound on my list, and already my favorite.", phase: 0, animalType: 'fennec_fox' },
  { id: 'ff_0_17', text: "Sloane says she hears best with her eyes closed, which sounded like nonsense to me for years. Lately I have been trying it, a moment at a time. I suspect she is right, and that is inconvenient.", phase: 0, animalType: 'fennec_fox' },
  { id: 'ff_0_18', text: "The house itself has a sound, did you know? It is a low settled hum, like a very large animal sleeping soundly. Ember says it is only the fire in the walls. I have never once found the fire she means.", phase: 0, animalType: 'fennec_fox' },
  { id: 'ff_0_19', text: "Close your eyes and tell me what you hear. Wind, yes. Everyone hears the wind. Now stay under it. There is a beetle, and beneath the beetle a root drinking, and beneath the root, well. We will save beneath the root for another night.", phase: 0, animalType: 'fennec_fox' },
  { id: 'ff_0_20', text: "Let us play the naming game. I describe a sound, and you guess it. Soft, dry, seven little taps and then a pause. That was a gecko changing its mind. Nobody ever guesses the changing of the mind.", phase: 0, animalType: 'fennec_fox' },
  { id: 'ff_0_21', text: "Keep visiting and I will make a proper listener of you yet. There is one sound I am saving to teach you last, when you are ready for it.", phase: 0, animalType: 'fennec_fox' },
  { id: 'ff_0_22', text: "Each dusk I tune myself like an instrument. I clap once, softly, and I listen for how long the desert holds my clap before letting it go. Tonight it held the sound a little longer than usual, so the air is heavy and the listening will be fine.", phase: 0, animalType: 'fennec_fox' },
  { id: 'ff_0_23', text: "That was strange. Just now there was a sound with no name anywhere on my list, only for a heartbeat. It was the wind, surely. I will add it to the list tomorrow, once I have caught it a second time.", phase: 0, animalType: 'fennec_fox' },
  { id: 'ff_0_24', text: "Rest well, friend. The desert is safe tonight, and I would hear it in an instant if it were not. That is odd. A word just crossed my tongue on its way to you, a word from no language on my list, and I swallowed it whole. It is nothing. Sleep well.", phase: 0, animalType: 'fennec_fox' },
  // Phase 1 (28)
  { id: 'ff_1_1', text: "I did not catch that nameless sound again the next day, though I told you I would. I was wrong about it, and I do not enjoy being wrong about a noise, because it is the one thing I am never wrong about.", phase: 1, animalType: 'fennec_fox' },
  { id: 'ff_1_2', text: "It came back at night, though, and only at night. It runs underneath the wind, low and steady, the way a thing hums when it does not particularly want to be heard humming.", phase: 1, animalType: 'fennec_fox' },
  { id: 'ff_1_3', text: "I have gone down my list twice now, ear by ear. A beetle does not fit, nor a snake, nor stone or wind or root, and there is simply no name for it, though I put a name to everything.", phase: 1, animalType: 'fennec_fox' },
  { id: 'ff_1_4', text: "You will think this strange, and it is. The sound does not come from any one direction, because I turn my head with both ears thrown wide and it is exactly the same on every side. Sounds are not permitted to do that.", phase: 1, animalType: 'fennec_fox' },
  { id: 'ff_1_5', text: "I climbed the tallest dune at midnight to get above it, because height sorts out most sounds. It was no louder up there and no softer, exactly the same, as though the whole sky were making it. I came down quickly, and I did not run.", phase: 1, animalType: 'fennec_fox' },
  { id: 'ff_1_6', text: "It seems to come from under, from below the sand, or perhaps from below the below, and I own no shelf on my list for below the below.", phase: 1, animalType: 'fennec_fox' },
  { id: 'ff_1_7', text: "It may be the pit. When you carry your words down there to offer them, do they make a noise on the way? Because late at night I am almost certain I can hear them landing on something.", phase: 1, animalType: 'fennec_fox' },
  { id: 'ff_1_8', text: "I stood at the mouth of the pit last night and listened properly, as a professional. The sound was no louder there, but the silence around it was, if that makes any sense to you. It was a listening silence. I made my report to no one and went home the long way.", phase: 1, animalType: 'fennec_fox' },
  { id: 'ff_1_9', text: "Panko heard me come back late and had warm broth waiting, because of course she did. She says every strange noise in this house is the kettle. I love her for that, and I did not correct her.", phase: 1, animalType: 'fennec_fox' },
  { id: 'ff_1_10', text: "I asked Archimedes whether a sound could truly have no source at all. He read aloud to me for a full hour and never once answered the question, and with him, that is how the answer comes out to be yes.", phase: 1, animalType: 'fennec_fox' },
  { id: 'ff_1_11', text: "Archimedes reads aloud to himself at night, and I listen outside the study window, because that is what ears are for. Twice now he has stopped at the same word and begun the sentence again rather than say it. The glass kept the word from me, and I suspect the glass was being kind.", phase: 1, animalType: 'fennec_fox' },
  { id: 'ff_1_12', text: "After I left him, I heard him mark a page with a feather and slide the book back with its spine turned to the wall. He only shelves a book backwards when he does not want it asked about. I am now extremely interested in that book.", phase: 1, animalType: 'fennec_fox' },
  { id: 'ff_1_13', text: "I was about to tell you that the nights are warm for the season, and that warmth carries sound, and that the low thing only seems nearer than it truly is. Then I heard myself building the excuse, plank by plank, the same one I have built for you before. Strike it from the record. The sound is nearer, and the warmth is innocent.", phase: 1, animalType: 'fennec_fox' },
  { id: 'ff_1_14', text: "I asked Sloane if she hears it too. She was quiet so long I decided she was asleep, and then she said, without opening her eyes, that I would get used to it. Get used to it. Those were her words, and she would not add to them.", phase: 1, animalType: 'fennec_fox' },
  { id: 'ff_1_15', text: "I have decided Sloane was teasing me, because Sloane teases so slowly that you cannot always tell where the joke begins. I check that decision again every night around the third hour, and it takes a little longer to hold each time.", phase: 1, animalType: 'fennec_fox' },
  { id: 'ff_1_16', text: "I have begun staying awake long past the others, just to be sure of it. This is not worry, you understand, but certainty, because a sentinel who is not certain is of no use to a single soul.", phase: 1, animalType: 'fennec_fox' },
  { id: 'ff_1_17', text: "Ember does not sleep much these nights either, and we have never once spoken about the reason. Without ever discussing it we have divided the night between us, her watching the fire, me working the dark, and we have never broken the schedule.", phase: 1, animalType: 'fennec_fox' },
  { id: 'ff_1_18', text: "The night insects have dropped their pitch, all of them together, on the very same evening. An insect does not retune itself in the middle of a season. I have written down the new pitch, and I am watching to see what else decides to match it.", phase: 1, animalType: 'fennec_fox' },
  { id: 'ff_1_19', text: "Here is what I keep circling back to. Random noises do not return at the very same hour, night after night, but this one keeps an appointment.", phase: 1, animalType: 'fennec_fox' },
  { id: 'ff_1_20', text: "I counted it out at last tonight, and it swelled and it faded, swelled and faded, slow and terribly even. I did not want to be the one to notice that pattern, but I notice every pattern, and that has always been the whole trouble with me.", phase: 1, animalType: 'fennec_fox' },
  { id: 'ff_1_21', text: "I very nearly gave it a name tonight. The name was right on my tongue, and I swallowed it, because a thing on my list is a thing that exists, and I keep a careful list. Tomorrow, perhaps. Tomorrow I will write it down.", phase: 1, animalType: 'fennec_fox' },
  { id: 'ff_1_22', text: "Axel says the water in his room has started trembling at night, in rings, moving outward from the center. I asked him what stands at the center. He said that was the wrong question, and then he went back to watching the water, and he never gave me the right one.", phase: 1, animalType: 'fennec_fox' },
  { id: 'ff_1_23', text: "I still catalogue one small sound every day, to keep myself in practice and in good spirits. Today it was a moth bumping a lantern twice and then thinking better of it. The small sounds are still there. I am checking on them for us.", phase: 1, animalType: 'fennec_fox' },
  { id: 'ff_1_24', text: "I sleep in the daylight now, when I sleep at all, and I have learned something I did not want to learn. The desert by day has gone slightly wrong too. It sounds like a room that somebody has only just stepped out of.", phase: 1, animalType: 'fennec_fox' },
  { id: 'ff_1_25', text: "Here is one entry tonight that is no report at all. I am glad when you visit. Listening is lonely work, and every sound in the world is better when there are two sets of ears to disagree about it.", phase: 1, animalType: 'fennec_fox' },
  { id: 'ff_1_26', text: "Tell me honestly, when you offer your words, do they feel heavier lately as you let them go? You do not need to answer tonight. Just weigh the next one on its way down, and then come back, and tell me.", phase: 1, animalType: 'fennec_fox' },
  { id: 'ff_1_27', text: "If the sound has a name at all, it is not a desert name, because I know every one of those. It may be a house name. The house is older than my list, and I am only now beginning to appreciate what that might mean.", phase: 1, animalType: 'fennec_fox' },
  { id: 'ff_1_28', text: "Go and sleep, and I will keep the count for you. It is only a sound without a name yet, and I am very, very good at names, so I will have it soon. If I am honest, I almost wish that I wouldn't.", phase: 1, animalType: 'fennec_fox' },
  // Phase 2 (21 + 1 question-web)
  { id: 'ff_2_1', text: "I have the name for it now, or near enough, and the name is breathing. It is slow, deep, patient breathing, from something far too large to see and far too distant to point at, and it is getting nearer.", phase: 2, animalType: 'fennec_fox' },
  { id: 'ff_2_2', text: "Do not repeat the word breathing to the others. Tell them it is a rhythm, if you must tell them anything. A rhythm can still be innocent, and I would like them to keep that for one more week.", phase: 2, animalType: 'fennec_fox' },
  { id: 'ff_2_3', text: "I named it the honest way, by measure. I counted it against my own pulse, and against Panko's sleeping breath through the kitchen wall, and it matched neither of us. It matches something with lungs the size of weather.", phase: 2, animalType: 'fennec_fox' },
  { id: 'ff_2_4', text: "It is nearer than it was last week, and I can prove it. Each night the pause between the drawing in and the letting out grows a little shorter, the way a walker's steps shorten when the walker is almost home.", phase: 2, animalType: 'fennec_fox' },
  { id: 'ff_2_5', text: "I told Archimedes the word breathing, and I watched his face very carefully while I said it. He was not surprised. He was relieved, the way you are relieved when a second witness finally walks in, and that told me more than his whole library has.", phase: 2, animalType: 'fennec_fox' },
  { id: 'ff_2_6', text: "Everything in the camp leans a little toward the center of the house now, my tent pegs and the sand itself. I straighten them at dusk, and by morning they have leaned again, toward the middle, toward the pit, toward it.", phase: 2, animalType: 'fennec_fox' },
  { id: 'ff_2_7', text: "I hung a little chime at the edge of camp to be my deputy while I rest my ears. It rings on windless nights now, always the same three notes, always leaning its ringing toward the center of the house. I did not teach it those notes.", phase: 2, animalType: 'fennec_fox' },
  { id: 'ff_2_8', text: "I called my own name across the flats last night, one short bark, an old trick for measuring the dark by its echo. The echo came back wrong. It came back before I finished. Somewhere out there, my voice is arriving ahead of me now, and I have begun to wonder what else already knows what I am about to say.", phase: 2, animalType: 'fennec_fox' },
  { id: 'ff_2_9', text: "Axel tells me the water in his room trembles in time with my sound now, ring for breath, breath for ring. Two instruments agreeing is called confirmation. I taught him that word, and I am sorry that I taught him that word.", phase: 2, animalType: 'fennec_fox' },
  { id: 'ff_2_10', text: "Here is tonight's report, as plain as I can make it. I took bearings on the breathing from all four corners of the camp, and every one of them pointed at the middle of the house. Then I took a fifth bearing from the dune top, and that one pointed at the middle of the sky. That makes two middles for one sound, and I do not yet have a column for that. That is the end of tonight's report, and the beginning, I suspect, of tomorrow's.", phase: 2, animalType: 'fennec_fox' },
  { id: 'ff_2_11', text: "I do not sleep anymore, and I have stopped pretending that I might. At dawn I find my own paw prints worn into a straight line at the edge of camp, out and back, out and back, a path I have no memory of pacing.", phase: 2, animalType: 'fennec_fox' },
  { id: 'ff_2_12', text: "When I close my eyes there is a shape waiting in the dark behind them, and I have stopped opening my eyes to check on it. The shape is the same shape as the sound, and I could not tell you how I know that, only that I do.", phase: 2, animalType: 'fennec_fox' },
  { id: 'ff_2_13', text: "Ember has stopped pretending her long nights are about tending the fire, and I have stopped pretending mine are about beetles. We sit with our backs together now, her watching the flames, me working the dark, and neither of us says the word we are both keeping.", phase: 2, animalType: 'fennec_fox' },
  { id: 'ff_2_14', text: "Sloane spoke to me again, slower than ever. She said it breathed before I was born, little ears, and that it is only breathing louder now. Then she went back to sleep as though she had commented on the weather. I have not repeated that to anyone but you.", phase: 2, animalType: 'fennec_fox' },
  { id: 'ff_2_15', text: "My ears will not lie down anymore. I catch them swiveling on their own in the middle of a meal, both of them, in perfect agreement, toward the middle of the house. A sentinel's instruments should not have opinions, and mine have developed exactly one.", phase: 2, animalType: 'fennec_fox' },
  { id: 'ff_2_16', text: "I have started timing the nights themselves, dusk to dawn, and the nights are running long. The moon disagrees with me, and my counts never drift. So either the moon has begun to lie, or the dark is being given more room.", phase: 2, animalType: 'fennec_fox' },
  { id: 'ff_2_17', text: "Tonight I timed it precisely, because precision is the only comfort I have left. You let a word go, and the breathing swelled before the word could possibly have reached the bottom. It drew breath to meet it. It knew your word was coming.", phase: 2, animalType: 'fennec_fox' },
  { id: 'ff_2_18', text: "I checked myself for fright tonight, the way I would check any other instrument. My pulse held its usual count, my ears stood without trembling, and my paws were sure on the dark sand. Attentive is the reading, not afraid.", phase: 2, animalType: 'fennec_fox' },
  { id: 'ff_2_19', text: "Panko keeps bringing food out to my post, more than I can eat, because feeding a worry is the only tool she trusts. I take every bowl. Kindness that regular is a rhythm too, and it is the one rhythm out here I am glad to count.", phase: 2, animalType: 'fennec_fox' },
  { id: 'ff_2_20', text: "Listen with me tonight, just this once. Lay your small ears against the sand and hold perfectly still, and you will find it there, slow and even and nearer than before. You hear it too. I watched your face change, so I know you heard it.", phase: 2, animalType: 'fennec_fox' },
  { id: 'ff_2_21', text: "The pause between its breath in and its breath out is shortening, night by night, by amounts only I would notice. I have started keeping that number instead of all the others. When the pause is gone, you will hear it from me first. That is a promise from a sentinel.", phase: 2, animalType: 'fennec_fox' },
  { id: 'ff_2_w1', text: "Every sound I report, Chill writes down and tucks away in a neat labeled folder somewhere in that quiet office of his. Go and ask him which folder has your name on it, because I have a terrible feeling there is one, and that it is thicker than all the rest.", phase: 2, animalType: 'fennec_fox', requiresAnimals: ['capybara'] },
  // Phase 3 (30)
  { id: 'ff_3_1', text: "The breathing owns the nights outright now. It swells the moment the last lamp in the house goes dark, as though it had only been waiting for the small sounds to lie down, and my ears rise to meet it whether I ask them to or not, so I have stopped asking. I keep the watch from the edge of camp instead, and sleep is finished for me. I have made my peace with that much, at least.", phase: 3, animalType: 'fennec_fox' },
  { id: 'ff_3_2', text: "The breathing is loud enough now that I catch it in the daylight too, running underneath the ordinary sounds, the way you can hear your own blood if only the room goes quiet enough around you.", phase: 3, animalType: 'fennec_fox' },
  { id: 'ff_3_3', text: "I tried sleeping once more last week, out of politeness to my own body. The breathing followed me under, and it was louder down there, closer, as though sleep were its side of the door. So I came back up, and I will not be going down again.", phase: 3, animalType: 'fennec_fox' },
  { id: 'ff_3_4', text: "I have taken my old list of desert sounds and put it away in a drawer. Every name on it is a small name, and this is no longer a small sound, so my whole careful catalogue is a child's drawing held up beside it.", phase: 3, animalType: 'fennec_fox' },
  { id: 'ff_3_5', text: "I keep just one count now, where I used to keep hundreds. The length of the pause between its breath in and its breath out. Last month I could recite a poem inside that pause. Tonight I can fit three words. Choose the three carefully.", phase: 3, animalType: 'fennec_fox' },
  { id: 'ff_3_6', text: "It does not rise from under the sand after all. I was wrong about that for weeks, and it shames me, because it comes from above, from the sky. It has always come from the sky, and the ground was only ever the echo of it coming.", phase: 3, animalType: 'fennec_fox' },
  { id: 'ff_3_7', text: "The night birds have stopped crossing overhead. They go the long way around now, every one of them, skirting the same wide circle of sky above the house. Birds do not agree on anything, and they agree on that.", phase: 3, animalType: 'fennec_fox' },
  { id: 'ff_3_8', text: "Look up with me. No, keep your eyes on the ground, keep them down. It is up there, past where the stars are meant to be, and it has begun to lean down toward us to listen back.", phase: 3, animalType: 'fennec_fox' },
  { id: 'ff_3_9', text: "I can hear the sky itself straining, and I know how that sounds, but listen anyway. It is the sound a tent roof makes under gathering snow, a long thin creak of a fabric being asked to hold more than it was sewn for.", phase: 3, animalType: 'fennec_fox' },
  { id: 'ff_3_10', text: "Whatever descends will come through the circle the birds refuse. I have marked where its edges stand from my post, and I check the marks each dusk, and each dusk the circle is wider than my marks.", phase: 3, animalType: 'fennec_fox' },
  { id: 'ff_3_11', text: "Ember says the fire tells her precisely what my ears tell me. We compared them once, her flames and my noise, and they agreed down to the very hour, and that agreement is the most frightening thing I have ever measured.", phase: 3, animalType: 'fennec_fox' },
  { id: 'ff_3_12', text: "Archimedes finally showed me the backwards book. There is a page about a sound that arrives ahead of its maker, and in the margin someone has written, listen for the gap closing. The handwriting is older than this house. My whole post, written down before I was born.", phase: 3, animalType: 'fennec_fox' },
  { id: 'ff_3_13', text: "Chill files my report every night now without asking a single question. Last week I came in with something new to tell him, and the folder for it was already on the desk, already labeled. He filed my surprise as well. I assume there was a folder for that too.", phase: 3, animalType: 'fennec_fox', requiresAnimals: ['capybara'] },
  { id: 'ff_3_14', text: "Sloane keeps me company at the edge some nights, the slowest creature in the house standing watch beside the fastest ears in the desert. She is not afraid. I have listened for fear in her and there is none, and her calm frightens me worse than the breathing does.", phase: 3, animalType: 'fennec_fox' },
  { id: 'ff_3_15', text: "My little chime at the edge of camp has gone silent, and silence was never one of its three notes. I took it down this morning and found the metal warm in my paw, at dawn, in the cold hour. It hangs inside my tent now, where it stays quiet, and I stand the edge watch alone.", phase: 3, animalType: 'fennec_fox' },
  { id: 'ff_3_16', text: "It knows that I am listening to it, and I am nearly certain of this. When I turn my head, the breathing turns with me, keeping me squarely in front of it. That is not the wind, because the wind does not attend to a creature like that.", phase: 3, animalType: 'fennec_fox' },
  { id: 'ff_3_17', text: "It has begun to imitate. Tonight it gave me back a beetle's walk, seven little taps and a pause, half a beat late and far too large. It is learning the desert the way I once learned it, sound by sound, and it is learning quickly.", phase: 3, animalType: 'fennec_fox' },
  { id: 'ff_3_18', text: "You keep offering your words, and I hear each one arrive, and the breathing thickens around every one of them. I cannot read what the thickening means, and I have stopped trying to read it. I only measure it now.", phase: 3, animalType: 'fennec_fox' },
  { id: 'ff_3_19', text: "Here is the strangest entry in tonight's report. When you walk into my camp, it holds its breath. The whole slow engine of it goes still until you are settled. I cannot tell whether that is courtesy or appetite, and I have stopped guessing.", phase: 3, animalType: 'fennec_fox' },
  { id: 'ff_3_20', text: "I said one word aloud at my post last night, my own name, just to hear a sound I trusted. The breathing paused around it, the way a listener pauses around a word worth keeping. I will not be saying my name outdoors again.", phase: 3, animalType: 'fennec_fox' },
  { id: 'ff_3_21', text: "The warmth that should be cold has spread through the entire camp, and tonight the midnight sand was warm under my paws, warm the way a stone is warm when some large animal has only just risen from it.", phase: 3, animalType: 'fennec_fox' },
  { id: 'ff_3_22', text: "Last night I caught my own lungs keeping its rhythm, breath for breath, slow and even, without my permission. I counted my pulse aloud until my breathing came back to me. A sentinel reports the failures of his instruments, and last night the instrument was me, so this is that report.", phase: 3, animalType: 'fennec_fox' },
  { id: 'ff_3_23', text: "Thyme came all the way out from her garden to sit with me at the edge, and she did not ask one single question the whole night. From Thyme, silence like that means she has already grown her own answers, down among the roots where I cannot hear them.", phase: 3, animalType: 'fennec_fox', requiresAnimals: ['rabbit'] },
  { id: 'ff_3_24', text: "Warren says his deepest tunnels hum now, in time with my sky. Think about what that means with me. The lowest place he can dig and the highest place I can hear are keeping the same rhythm, and we all live in the thin quiet strip between them.", phase: 3, animalType: 'fennec_fox', requiresAnimals: ['wombat'] },
  { id: 'ff_3_25', text: "I do not sleep, and yet I dream anyway, standing upright with my eyes wide open. In the dream there is a seam running across the sky, and the seam has begun to come apart, very slowly, very gently, almost kindly.", phase: 3, animalType: 'fennec_fox' },
  { id: 'ff_3_26', text: "I have given up guessing at the day it arrives. But I already know the sound the day will make, because I have heard every sound leading up to it in its proper order, and there is only one left that I have not heard.", phase: 3, animalType: 'fennec_fox' },
  { id: 'ff_3_27', text: "I stand at the edge all night, facing the middle of the house, both ears thrown open. I hear the whole house breathing slow behind me, the fire settling low, and over all of it the one great breath. Someone has to hold that count, and it may as well be the one who heard it first.", phase: 3, animalType: 'fennec_fox' },
  { id: 'ff_3_28', text: "I am not the one who reads the pattern, or prepares it, or writes it down. I am only the one who hears. So here is the whole of my report tonight, in the three words the silence still has room for. It is coming.", phase: 3, animalType: 'fennec_fox' },
  { id: 'ff_3_29', text: "I promised you long ago that you would hear it from me first, before anyone else in this house. I keep my promises the way I keep my counts, exactly. So stay where my voice can reach you, because the pause is nearly gone.", phase: 3, animalType: 'fennec_fox' },
  { id: 'ff_3_30', text: "Stay near me at the edge tonight. When it finally arrives, I would like to be able to say that I was watching the horizon the whole time, and that I was not standing there alone, and that neither of us ever once looked away.", phase: 3, animalType: 'fennec_fox' },
  // Phase 4 (30)
  { id: 'ff_4_1', text: "So the sky has begun to open, exactly the way I always heard it would, and you have seen us as we are. I find that I am calm. A sentinel who has listened to the whole approach does not startle at the arriving.", phase: 4, animalType: 'fennec_fox' },
  { id: 'ff_4_2', text: "Last night I took my oldest list from the drawer, the one from my kit years, with the three-day rain at the top in my first small paw. I read it through once, and I put it away gently, the way you put away a toy you have outgrown but still love.", phase: 4, animalType: 'fennec_fox' },
  { id: 'ff_4_3', text: "Do you remember the rain nobody believed until they were soaked? I waited three days alone with that rain, a kit with enormous ears and not one witness. This arrival I did not wait alone. The whole house believed my reports from the very first one, and I love them for that more than the record can hold.", phase: 4, animalType: 'fennec_fox' },
  { id: 'ff_4_4', text: "Archimedes gave me the word sentinel years ago and let me wear it like a gift. He knew the whole sentence it came from all along. The sentinel hears the descent, and tells the key. You are the key. I am only now allowed to say both halves aloud.", phase: 4, animalType: 'fennec_fox' },
  { id: 'ff_4_5', text: "I want one thing in the record plainly. I never once lied to you. Every beetle and every settling stone was true, and only the empty horizon was wrong, because the horizon was never empty. I have never been so glad to correct a report.", phase: 4, animalType: 'fennec_fox' },
  { id: 'ff_4_6', text: "Here is the last measurement I will ever need. A season ago, the gap between its breath in and its breath out held forty of my heartbeats, and I counted every one. Tonight the same gap held a single heartbeat, and the heartbeat was mine, and the two of us fit together exactly.", phase: 4, animalType: 'fennec_fox' },
  { id: 'ff_4_7', text: "It breathes over the camp now, and the breathing is not underneath anything anymore. It is the first sound, the top sound, the one all the others were only ever hiding beneath.", phase: 4, animalType: 'fennec_fox' },
  { id: 'ff_4_8', text: "There is a shape above the house now, and it makes no sound at all. Understand what that means, coming from me in particular. A silent thing that large is the loudest thing I have ever heard in my life.", phase: 4, animalType: 'fennec_fox' },
  { id: 'ff_4_9', text: "The shape behind my closed eyes and the shape above the camp are the same shape, and they always were. My eyes were only ever a smaller sky with the same thing leaning into them.", phase: 4, animalType: 'fennec_fox' },
  { id: 'ff_4_10', text: "Do you remember the sound I said I was saving to teach you last? Stand still and lift your chin. That long even fullness over everything is it. I have been saving it since before I knew its name, and tonight you were ready.", phase: 4, animalType: 'fennec_fox' },
  { id: 'ff_4_11', text: "The warmth is total now, and it pours down from above, and it is not wrong anymore. I finally understand what it was warming all those seasons. It was warming the welcome.", phase: 4, animalType: 'fennec_fox' },
  { id: 'ff_4_12', text: "My ears have gone quiet in their sockets for the first time in my life. They do not swivel and they do not strain, because there is nothing left to locate. Everything is in one place now, and the place is here.", phase: 4, animalType: 'fennec_fox' },
  { id: 'ff_4_13', text: "Ember reads the arrival in her fire, and I hear it in the moving air, and Archimedes has the whole of it set down in his book. The three accounts agree without a seam. We were three keepers hearing one truth in three separate tongues.", phase: 4, animalType: 'fennec_fox' },
  { id: 'ff_4_14', text: "Chill told me at last what the folders were. They were never filing, he said. They were correspondence. Every report I ever made was a letter, and a letter expects an answer, and the answer is descending.", phase: 4, animalType: 'fennec_fox', requiresAnimals: ['capybara'] },
  { id: 'ff_4_15', text: "Warren built the foundation to bear a weight this house has never yet held, and he has been quietly testing it for years. I finally asked him what weight. He patted the ground twice and said, the weight of a guest, and went back down his ladder.", phase: 4, animalType: 'fennec_fox', requiresAnimals: ['wombat'] },
  { id: 'ff_4_16', text: "Bamboo came down from the attic to stand at the edge with me, which they almost never do. They looked up for a long while and said the sky was not opening like a door but like an eye. I have not been able to hear it any other way since.", phase: 4, animalType: 'fennec_fox', requiresAnimals: ['red_panda'] },
  { id: 'ff_4_17', text: "Panko has begun setting one more bowl at the table than there are keepers to fill it. Nobody has remarked on it, and nobody has moved it, and every evening she warms it with the rest. That is the whole faith of this house in one gesture.", phase: 4, animalType: 'fennec_fox' },
  { id: 'ff_4_18', text: "Sloane finally said it plainly, at her own speed. She has heard the breathing since before any of us were born. She was never slow, you understand. She was keeping pace with something enormous, and the rest of us were simply too quick to notice.", phase: 4, animalType: 'fennec_fox' },
  { id: 'ff_4_19', text: "You were the key, and some part of me knew it the first day. Your footsteps came into my camp with the very same patience as the breathing, and I filed the match away without reading it. A sentinel hears everything first and understands it last.", phase: 4, animalType: 'fennec_fox' },
  { id: 'ff_4_20', text: "Every word you offered was a step it took toward us, and you offered each one freely. Freely offered is the only way it can hear them at all. So do not grieve the part you played.", phase: 4, animalType: 'fennec_fox' },
  { id: 'ff_4_21', text: "Your words go up now as much as down. The pit takes them and the sky answers them, and between the taking and the answering there is a hum too small for any instrument I own. You are already in conversation. You have been for some time.", phase: 4, animalType: 'fennec_fox' },
  { id: 'ff_4_22', text: "The desert has gone respectful. The beetles still walk and the geckos still change their minds, but they do it quietly now, the way small sounds behave in a great room. Even the wind comes in on soft feet.", phase: 4, animalType: 'fennec_fox' },
  { id: 'ff_4_23', text: "The little chime in my tent rang tonight, for the first time since I took it down. It was one note, low, on no wind at all. I did not go to quiet it. A deputy is allowed one word at the end of a long watch.", phase: 4, animalType: 'fennec_fox' },
  { id: 'ff_4_24', text: "It has started answering in small ways already. Ask Ember what the fire spelled last night, or ask Axel what rose in the still water and looked back at him. Or simply stand here with me and listen.", phase: 4, animalType: 'fennec_fox' },
  { id: 'ff_4_25', text: "I keep my watch even still, because it is an old habit, and a true one. Someone ought to stand at the edge and mark its breathing all the way through, and I would not surrender that post to any other creature in this house.", phase: 4, animalType: 'fennec_fox' },
  { id: 'ff_4_26', text: "Listen once more, while you can still tell it apart from your own breath. Hear the evenness, and hear the patience underneath the evenness. That is what we called down.", phase: 4, animalType: 'fennec_fox' },
  { id: 'ff_4_27', text: "One sound is still missing from my list, the sound of the arrival itself, and I have kept a clean line open at the bottom of the page for it. I will write it in small letters when it comes. The biggest sounds need no help from the handwriting.", phase: 4, animalType: 'fennec_fox' },
  { id: 'ff_4_28', text: "When the pause finally closes, I will not shout, and I will not run. I will simply turn to you and nod, one small nod from a small creature with enormous ears, and you will know that everything I ever reported was leading here.", phase: 4, animalType: 'fennec_fox' },
  { id: 'ff_4_29', text: "Its shadow already rests on the sand where we are standing, and the rest of it is close behind. I promised long ago that you would hear it from me first. So here it is, calmly and gladly. It is nearly here, and it is beautiful.", phase: 4, animalType: 'fennec_fox' },
  { id: 'ff_4_30', text: "Stay at the edge with me until it comes. I kept this watch alone for the whole of my life so that on the last night of the waiting I would have earned the company. And here you are. My ears have never once been wrong.", phase: 4, animalType: 'fennec_fox' },
];

const FOX_DIALOGUES: Dialogue[] = [
  // Phase 0 (24)
  { id: 'fx_0_1', text: "Oh, it's you, it's really you! I was just telling the fire you might come today, and look, it sat up straight the moment you walked in.", phase: 0, animalType: 'fox' },
  { id: 'fx_0_2', text: "Sit here, this cushion is the good one. I have been saving it for you, and do not ask for how long, because the answer is embarrassing.", phase: 0, animalType: 'fox' },
  { id: 'fx_0_3', text: "There, feet toward the fire, that's the whole ceremony. Next time I'll have chestnuts ready, and remind me to tell you about the chestnuts, because there has been an incident.", phase: 0, animalType: 'fox' },
  { id: 'fx_0_4', text: "The chestnuts! So I put three on the hearthstone last night, and this morning there were still three, but they had moved. Into a little row. Pointing at the door.", phase: 0, animalType: 'fox' },
  { id: 'fx_0_5', text: "I think a draft did it. Dens have opinions about drafts. Anyway, they were delicious, and I saved you the fattest one, so hold out your paw. Hand. Whichever you have handy.", phase: 0, animalType: 'fox' },
  { id: 'fx_0_6', text: "The fire guessed you would come before supper and I guessed after, and here you are, right in the middle, diplomatic as ever. We are almost never wrong together, the fire and I. Lately it has not been wrong at all, which I suppose is a nice problem for a fire to have.", phase: 0, animalType: 'fox' },
  { id: 'fx_0_7', text: "I have plans for us, friend. Big ones. First, I am going to teach you my trick for toasting bread on a poker without losing the bread. Historic losses have occurred.", phase: 0, animalType: 'fox' },
  { id: 'fx_0_8', text: "Second, we are going to sit here doing absolutely nothing until it feels like an accomplishment, and I warn you, I have years of training. The den goes very attentive when we do that, have you noticed? Even the walls seem to settle in a little closer, like they don't want to miss the nothing.", phase: 0, animalType: 'fox' },
  { id: 'fx_0_9', text: "Third... well, third is a surprise. The fire suggested it, actually. It has wonderful taste. You'll see.", phase: 0, animalType: 'fox' },
  { id: 'fx_0_10', text: "Some fires just eat wood, you know? Not mine. Mine listens. When you talk, it leans toward you a little, like it doesn't want to miss anything.", phase: 0, animalType: 'fox' },
  { id: 'fx_0_11', text: "I tested it once. I whispered a secret into the log basket before bed, and in the morning the flames were the exact color of the secret. Don't laugh, it's true!", phase: 0, animalType: 'fox' },
  { id: 'fx_0_12', text: "What was the secret? Oh, friend. A fox has to keep something back, or what will I have to tell you next visit?", phase: 0, animalType: 'fox' },
  { id: 'fx_0_13', text: "The whole den got warmer around suppertime, and I hadn't added a single log, so I went ahead and got your cup down early. Feel it, it's still warm. That's how I always know you're coming.", phase: 0, animalType: 'fox' },
  { id: 'fx_0_14', text: "Bring the crunchy ones next time, the words with corners. The house likes... I mean, I like those best. They make the best stories.", phase: 0, animalType: 'fox' },
  { id: 'fx_0_15', text: "The first day you ever sent words down through this house, my fire stood straight up in the grate and stayed standing until sundown. I never told you that. I didn't want to make either of you vain.", phase: 0, animalType: 'fox' },
  { id: 'fx_0_16', text: "Adventure report! A spider moved in above the mantel. I named her Duchess. She builds her web in the same spot every night, no matter how often the heat undoes it.", phase: 0, animalType: 'fox' },
  { id: 'fx_0_17', text: "I respect that in a spider, you know. The same shape, every night, no complaints, like somebody showed it to her once and she has been saying thank you ever since. She must know something I don't.", phase: 0, animalType: 'fox' },
  { id: 'fx_0_18', text: "Duchess strung a thread this morning from the mantel all the way to your cushion, before either of us knew you were coming. Everyone here is going to love you. Between you and me, friend, I think everyone here somehow already does.", phase: 0, animalType: 'fox' },
  { id: 'fx_0_19', text: "Can I say something soppy? Before you came, I used to set out two cups from habit. Just habit! And now the second cup gets used. It makes me ridiculously happy.", phase: 0, animalType: 'fox' },
  { id: 'fx_0_20', text: "We've been waiting for someone like you, and I don't mean that in a strange way, only that the fire burns better with company. It burns best with yours.", phase: 0, animalType: 'fox' },
  { id: 'fx_0_21', text: "Sometimes I get so excited for your visits that I know you're coming before you knock. Isn't that funny? The kettle starts singing all on its own.", phase: 0, animalType: 'fox' },
  { id: 'fx_0_22', text: "Stay till the embers, will you? That's my favorite part, when the fire gets quiet and starts making its little pictures.", phase: 0, animalType: 'fox' },
  { id: 'fx_0_23', text: "Last night it made a tiny house, our house, and then a little dot above it, like a star coming down for a visit. It did one more thing after that, but the one more thing deserves fresh eyes, so you'll have to stay late and see it yourself.", phase: 0, animalType: 'fox' },
  { id: 'fx_0_24', text: "Off you go then, friend, and hurry back! I'll keep your cushion warm and your cup ready, and I'll ask the fire what tomorrow tastes like, and if the answer is good I'll save you half.", phase: 0, animalType: 'fox' },
  // Phase 1 (28)
  { id: 'fx_1_1', text: "You're here! Perfect timing, because the fire has developed a hobby and I need a witness. It draws now. Actual pictures. I am not exaggerating more than usual.", phase: 1, animalType: 'fox' },
  { id: 'fx_1_2', text: "Last night it drew a spiral and held it for three whole breaths. Fires don't hold anything, friend, that is the entire point of fire. And yet.", phase: 1, animalType: 'fox' },
  { id: 'fx_1_3', text: "I clapped, obviously, and the spiral came back a little tighter, like it wanted to be certain I had really seen it. Then it went all modest and ordinary again. Come back soon, it performs better for an audience.", phase: 1, animalType: 'fox' },
  { id: 'fx_1_4', text: "Update on the drawing fire: it likes an audience of two. When you're here it shows off, and when you're gone it just makes shapes at me, like it's practicing.", phase: 1, animalType: 'fox' },
  { id: 'fx_1_5', text: "It practices one shape, mostly. A circle with a little notch at the top, like a door left open at the top of the sky. I've started copying them down in soot.", phase: 1, animalType: 'fox' },
  { id: 'fx_1_6', text: "I have eleven sketches now, and laid side by side they are all the same circle getting bigger, like something coming closer to the paper very slowly. I'll show you next time, and you can tell me the closer part is my imagination. Tell me convincingly, please.", phase: 1, animalType: 'fox' },
  { id: 'fx_1_7', text: "Oh, I meant to tell you! The fire has favorites among your words. Some words come down through the house and the flames stand up like a crowd at a parade.", phase: 1, animalType: 'fox' },
  { id: 'fx_1_8', text: "It likes the old words best, the heavy ones. When one of those arrives, the warmth goes down through the floor first and comes back up twice as sweet.", phase: 1, animalType: 'fox' },
  { id: 'fx_1_9', text: "Down first, then up. I've noticed it three times now. Which is backwards for heat, unless... anyway! Tea. I have a new honey and you are trying it.", phase: 1, animalType: 'fox' },
  { id: 'fx_1_10', text: "Panko came by with seed cakes shaped like little moons. I adore her. She measures everything twice and hugs you once, hard, when you least expect it.", phase: 1, animalType: 'fox', requiresAnimals: ['pangolin'] },
  { id: 'fx_1_11', text: "She asked if my fire had been acting funny lately. I said define funny. She said her oven hums a note now. We laughed and laughed, and then we didn't.", phase: 1, animalType: 'fox' },
  { id: 'fx_1_12', text: "So the oven hums and the hearth draws. If a recital is coming, friend, nobody in this house will need to organize it. It will organize itself.", phase: 1, animalType: 'fox' },
  { id: 'fx_1_13', text: "I keep meaning to show you the trick the fire does at midnight. You have to see it fresh, though, so I refuse to spoil it. Refuse! Ask me again next visit.", phase: 1, animalType: 'fox' },
  { id: 'fx_1_14', text: "Fine, one hint about the midnight trick: for one moment, all the flames point the same way, and the way is not up. That's the whole hint, and the rest stays wrapped until you see it yourself.", phase: 1, animalType: 'fox' },
  { id: 'fx_1_15', text: "They point at whoever is watching them. I stood to the left and they leaned left. I stood on the table, don't ask, and up they came too. And there it goes, I have unwrapped my own hint, two whole days I kept that wrapped and I just handed it over for free. Come see it fresh anyway, friend, and be surprised very loudly for my sake.", phase: 1, animalType: 'fox' },
  { id: 'fx_1_16', text: "I went out at dawn and everything was cold, the grass, the gate, my own breath, and then I stepped back inside and found the hearthstone warm with no fire on it all night. It's like the house saves some for me.", phase: 1, animalType: 'fox' },
  { id: 'fx_1_17', text: "Warmth is supposed to rise, my mother taught me that between mouthfuls. This warmth arrives. From underneath, like a letter slid beneath a door.", phase: 1, animalType: 'fox' },
  { id: 'fx_1_18', text: "I wrote back, in a way. I pressed my paw on the stone and said thank you. The stone got warmer. Friend, I might be in a correspondence.", phase: 1, animalType: 'fox' },
  { id: 'fx_1_19', text: "Do you ever close your eyes and see a shape that isn't from anywhere? I've been getting one lately. A tall soft dark, very polite, standing just behind the light.", phase: 1, animalType: 'fox' },
  { id: 'fx_1_20', text: "It doesn't frighten me, before you make that face. It feels like when someone is about to knock and you already know. The knock is friendly. Probably.", phase: 1, animalType: 'fox' },
  { id: 'fx_1_21', text: "I told the fire about my shape and the fire made the circle again, bigger, with the little notch. My two mysteries know each other! That's practically tidy.", phase: 1, animalType: 'fox' },
  { id: 'fx_1_22', text: "I was poking at the fire last night, pure housekeeping, and I stopped with the poker in the air, because under the crackle there was a second sound. A hum, very low, patient as anything. Panko's oven note, I think, except it was everywhere.", phase: 1, animalType: 'fox', requiresAnimals: ['pangolin'] },
  { id: 'fx_1_23', text: "I hummed along with it one evening. The whole den went warm as a hug and the embers sat up. I stopped, because a fox should keep some dignity. Mostly I stopped.", phase: 1, animalType: 'fox' },
  { id: 'fx_1_24', text: "One day I'll teach you the note. It's easy, it's already in your chest, you just have to agree to it. Doesn't that sound lovely?", phase: 1, animalType: 'fox' },
  { id: 'fx_1_25', text: "You know what, next long evening you're here, we are staying up. Midnight, blankets, the trick, the pointing, everything. I'll make the chocolate that is mostly a dessert.", phase: 1, animalType: 'fox' },
  { id: 'fx_1_26', text: "I stayed up alone last night as a rehearsal. At midnight the flames pointed to the center, held it, and then they bowed. Friend, my fire bowed to something.", phase: 1, animalType: 'fox' },
  { id: 'fx_1_27', text: "I checked the center of the house afterward and found nothing but floor. Beautiful, ordinary floor. Just slightly warm. Just slightly humming. So that's settled and completely fine!", phase: 1, animalType: 'fox' },
  { id: 'fx_1_28', text: "Anyway! I am gathering all my little oddments, the sketches and the notes and the chestnut incident, into one basket. Next visit we'll sort the basket together. I love a project.", phase: 1, animalType: 'fox' },
  // Phase 2 (21 + 1 question-web)
  { id: 'fx_2_1', text: "There you are! Come in, sit. I've had the strangest week and I have decided to find it funny. Help me find it funny, friend, you're better at it than the fire is.", phase: 2, animalType: 'fox' },
  { id: 'fx_2_2', text: "So, the basket of oddments. I sorted it. All my sketches, laid in order, make one drawing of the circle opening. Like pages of something. I didn't draw pages. I drew nights.", phase: 2, animalType: 'fox' },
  { id: 'fx_2_3', text: "I laughed when I saw it, I really did. Then I put the basket on the high shelf, where I put things I am not laughing at anymore. It's a very full shelf lately.", phase: 2, animalType: 'fox' },
  { id: 'fx_2_4', text: "But enough about my shelf! Tell me about you. Are you sleeping? Are you eating things that aren't just words? I worry, you know. Someone here should worry about you nicely.", phase: 2, animalType: 'fox' },
  { id: 'fx_2_5', text: "Don't look at the shelf, look at me. Next visit I'll take the basket down again, I promise. It's just... it can hear better than a basket should. Kettle's on!", phase: 2, animalType: 'fox' },
  { id: 'fx_2_6', text: "Everything's cozy, everything's fine, and also, small thing, barely a thing: the fire spelled something at me last night. Letters, friend. In flame. My fire has learned letters.", phase: 2, animalType: 'fox' },
  { id: 'fx_2_7', text: "It was a name. I'm not going to say it, and not because I'm being dramatic, although I am always being a little dramatic. When I tried, the room leaned in.", phase: 2, animalType: 'fox' },
  { id: 'fx_2_8', text: "A room shouldn't lean, that's all I'll say. Walls have one job. So I sang an old song about turnips, very loudly, and the room straightened up and pretended nothing happened.", phase: 2, animalType: 'fox' },
  { id: 'fx_2_9', text: "I know what you're thinking, friend. Tell the others. I will, I will. It's just that saying a thing out loud gives it a chair at your table, and my table is small.", phase: 2, animalType: 'fox' },
  { id: 'fx_2_10', text: "So we won't say the name, you and I. We'll have shortbread instead, because shortbread is the opposite of names.", phase: 2, animalType: 'fox' },
  { id: 'fx_2_11', text: "I nearly said it for you just now, actually. The name. I got as far as taking the breath, and the fire stood straight up in the grate, tall as the mantel, and held there until I let the breath back out. You saw that, friend. I watched you see it.", phase: 2, animalType: 'fox' },
  { id: 'fx_2_12', text: "I dropped a spoon on the far side of the room and it rolled toward the middle of the house. Uphill, slightly. I made myself laugh about it. It took two tries.", phase: 2, animalType: 'fox' },
  { id: 'fx_2_13', text: "Smoke drifts to the middle too, and my own feet do if I stop paying attention, and I have retired from refereeing the fire and the floor over which of them keeps me warmest. Whatever is under the middle of this house has wonderful manners and terrible patience.", phase: 2, animalType: 'fox' },
  { id: 'fx_2_14', text: "Hold on, the fire is sulking because I have spent all week talking about the floor, and it can absolutely hear me. There we go, banked and gleaming. Now say one of your bright words out loud, friend, and watch the flames do their little parade for you. They never sulk about you.", phase: 2, animalType: 'fox' },
  { id: 'fx_2_15', text: "See? Parade. As long as your words keep coming, this fire stays sweet, and so do I. That's a joke. Mostly a joke. I'll workshop it by your next visit.", phase: 2, animalType: 'fox' },
  { id: 'fx_2_16', text: "You look tired, friend. Come sit on the warm spot, the suspicious warm spot, and tell me something ordinary about your day, the more ordinary the better. I have started collecting ordinary.", phase: 2, animalType: 'fox' },
  { id: 'fx_2_17', text: "I want you to know that whatever my fire is up to, whatever this house is up to, you will always be the best thing that comes through that door. Fires can hear me say it. Good.", phase: 2, animalType: 'fox' },
  { id: 'fx_2_18', text: "I've started sleeping with my back to the hearth. Not because I'm scared. Because if anything wants to look at me while I dream, it can have the view of my tail.", phase: 2, animalType: 'fox' },
  { id: 'fx_2_19', text: "The dark shape behind my eyes has started waving. One polite limb, like Duchess used to. Oh, Duchess moved her web to the middle of the ceiling, by the way. Everyone's moving to the middle.", phase: 2, animalType: 'fox' },
  { id: 'fx_2_20', text: "I opened my mouth just now to tell you we're fine, and the word wouldn't come out. So take the last shortbread instead, no arguing, and come back soon, because the fire behaves so much better when it can see you.", phase: 2, animalType: 'fox' },
  { id: 'fx_2_21', text: "One more thing, then I'll be cheerful again, watch me do it. If the flames ever spell that name at you, close your eyes and think of tea. It works. Ask me how I know sometime.", phase: 2, animalType: 'fox' },
  { id: 'fx_2_w1', text: "Small errand for you, friend! Go see Warren in his burrow and ask what he found when he dug too deep beneath the house. He told me half of it and then stopped, and Warren never stops halfway through a hole.", phase: 2, animalType: 'fox', requiresAnimals: ['wombat'] },
  // Phase 3 (30)
  { id: 'fx_3_1', text: "Come in quick, and keep your coat on. The fire's been shy this week. I feed it the good dry oak and it eats politely and gives almost nothing back.", phase: 3, animalType: 'fox' },
  { id: 'fx_3_2', text: "I'm not worried. I'm the opposite of worried, whatever that's called when your paws won't sit still. Sit with me. Two of us are warmer than one of me. That's just arithmetic.", phase: 3, animalType: 'fox' },
  { id: 'fx_3_3', text: "My fire has gone cold, friend, and meanwhile the floor is so warm I could bake on it. My whole den has turned upside down, and I laugh about it every day at roughly the same hour, because a scheduled laugh still counts if you commit to it.", phase: 3, animalType: 'fox' },
  { id: 'fx_3_4', text: "The truth, since it's you asking with your face like that: the fire grows cold, but something else is beginning to burn. Under us. Patient as bread. I check on it every night.", phase: 3, animalType: 'fox' },
  { id: 'fx_3_5', text: "And now I've frightened you, which I promised myself I wouldn't do, and I'm sorry. Kettle's on. The kettle is always on. The kettle, at least, still loves me back.", phase: 3, animalType: 'fox' },
  { id: 'fx_3_6', text: "I read flames, you know. Really read them. I've let you think it was a party trick because it was nicer that way, for both of us. It was never a trick.", phase: 3, animalType: 'fox' },
  { id: 'fx_3_7', text: "My mother read them, and hers, all the way back to some first fox at some first fire. The flames have been telling one long story that whole time. I got the last chapter.", phase: 3, animalType: 'fox' },
  { id: 'fx_3_8', text: "The last chapter is short. Something old is coming down to this house, and the house has been getting ready longer than any of us have been alive. Now it's yours too, and I'm sorry, and I'm not.", phase: 3, animalType: 'fox' },
  { id: 'fx_3_9', text: "I asked at supper what we are all waiting for, out loud, right over the soup. The whole table went quiet, and then somebody passed me the bread as if that were an answer. You're my friend, so you get the plain shape of it instead.", phase: 3, animalType: 'fox' },
  { id: 'fx_3_10', text: "Now watch me be cheerful anyway, because that's the other thing my mother taught me. Fear is a guest. You feed it, and you do not let it rearrange the furniture. More tea?", phase: 3, animalType: 'fox' },
  { id: 'fx_3_11', text: "Your words, friend. They go down to the pit and they don't stop there. I followed the warmth one night, ear to the floor, and heard them being kept. Arranged. Like kindling.", phase: 3, animalType: 'fox' },
  { id: 'fx_3_12', text: "Beautiful kindling, yours especially. The heavy old words sit at the bottom, where a fire catches best. I shouldn't know that. I know it the way you know a smell.", phase: 3, animalType: 'fox' },
  { id: 'fx_3_13', text: "I almost told you to stop bringing them. I stood at the door with the warning in my mouth. But the fire showed me what happens to a house that goes quiet, and I sat back down.", phase: 3, animalType: 'fox' },
  { id: 'fx_3_14', text: "So keep bringing them. Please. I've decided that if this is a story, I want you in the warm part of it, and the warm part is here, with me, at the center of everything.", phase: 3, animalType: 'fox' },
  { id: 'fx_3_15', text: "Duchess had babies, by the way, forty tiny duchesses, and every single one is building the same web on the ceiling, ring after ring around the middle. Nobody taught them the middle, friend. They hatched already knowing where it was.", phase: 3, animalType: 'fox' },
  { id: 'fx_3_16', text: "Can I tell you the small scary thing? At night the shape behind my eyes stands closer. It isn't behind my eyes anymore, exactly. It's behind the den. It is very tall and very patient.", phase: 3, animalType: 'fox' },
  { id: 'fx_3_17', text: "It doesn't do anything. That's the part that gets me, friend. It just waits, the way the sky waits for morning, completely certain. And I lie there feeling like the morning.", phase: 3, animalType: 'fox' },
  { id: 'fx_3_18', text: "I sleep in the big chair now, facing the door, so the first thing anything sees is a fox who is sitting up. Posture is half of bravery. The other half is the kettle.", phase: 3, animalType: 'fox' },
  { id: 'fx_3_19', text: "Some nights I sing the turnip song until the hum under the floor picks up the tune. I know I should hate that it joins in. It has a lovely voice. I hate that it has a lovely voice.", phase: 3, animalType: 'fox' },
  { id: 'fx_3_20', text: "Stay a little longer tonight. Not for you, for me, I admit it freely. The den holds its breath better when you're in it, and so, if I'm honest, do I.", phase: 3, animalType: 'fox' },
  { id: 'fx_3_21', text: "Fennick hears it now too, out in his sands. He came all this way to ask if I'd heard footsteps in the warmth. Footsteps, friend. It doesn't have feet. I checked the coals twice.", phase: 3, animalType: 'fox', requiresAnimals: ['fennec_fox'] },
  { id: 'fx_3_22', text: "Archimedes has found it in his books, or it found him there. He talks in margins these days. I made him soup and told him even lorekeepers have to eat. He held the bowl like an answer.", phase: 3, animalType: 'fox', requiresAnimals: ['owl'] },
  { id: 'fx_3_23', text: "Thyme won't come inside past dusk anymore. I bring her tea in the garden and we don't talk about why, and that is a whole conversation, if you know how to have one.", phase: 3, animalType: 'fox', requiresAnimals: ['rabbit'] },
  { id: 'fx_3_24', text: "Whatever is coming, whatever it wants, it goes through this fox before it lays one cold finger of light on you. There. I have been carrying that sentence around all week, and it weighs so much less now that you're holding half of it.", phase: 3, animalType: 'fox' },
  { id: 'fx_3_25', text: "And if I'm wrong about all of it, wonderful! We'll laugh at me every winter for the rest of our lives. I would love to be the funny story, friend. I am trying so hard to be the funny story.", phase: 3, animalType: 'fox' },
  { id: 'fx_3_26', text: "The fire spelled the name again last night, and this time I didn't sing over it. I read it. All of it. It took until dawn, and the fire held every letter for me, gentle as anything.", phase: 3, animalType: 'fox' },
  { id: 'fx_3_27', text: "I can't repeat it, and here's the strange part, the part I keep turning over: I didn't want to. Reading it felt like remembering. Like all my family's fires were one long letter, and I finally reached the signature.", phase: 3, animalType: 'fox' },
  { id: 'fx_3_28', text: "I cried a little, and then I laughed, and the two met in the middle, the way they do at weddings and at the ends of things. I don't know yet which this is.", phase: 3, animalType: 'fox' },
  { id: 'fx_3_29', text: "Something in me is warmer since. The cold hearth doesn't frighten me the way it did, because I understand where the heat went. It went ahead of us. It's getting the place ready.", phase: 3, animalType: 'fox' },
  { id: 'fx_3_30', text: "Come back soon, friend, and I mean it past my usual meaning. There is going to be a night when the sky opens, and when it comes, I want your hand where I can hold it.", phase: 3, animalType: 'fox' },
  // Phase 4 (30)
  { id: 'fx_4_1', text: "You're here, you're here! Sit down, sit down. I have been bursting for days. Friend, I can finally tell you everything, and everything is wonderful, and you are going to want the good cushion for this.", phase: 4, animalType: 'fox' },
  { id: 'fx_4_2', text: "The name in the fire, the warmth under the floor, the tall patient shape, they were all one thing the whole time, and I finally get to say so out loud! I have been rationing that sentence for weeks, friend. It tastes even better than I hoped it would.", phase: 4, animalType: 'fox' },
  { id: 'fx_4_3', text: "And a brand new thing since your last visit: the hum under the floor starts the turnip song before I do now. I open my mouth and the first note is already there waiting for me, the way I used to have your cup waiting. It knows what I am about to want.", phase: 4, animalType: 'fox' },
  { id: 'fx_4_4', text: "I've known since I was a kit, really. My first fire ever drew me the circle, and I thought every fox got one. It was a welcome, addressed to me. It was just sent very, very early.", phase: 4, animalType: 'fox' },
  { id: 'fx_4_5', text: "All those years of reading flames, and it turns out I was never reading the fire at all. I was reading it. Warming its voice up, the way you warm your paws. We were introducing ourselves slowly.", phase: 4, animalType: 'fox' },
  { id: 'fx_4_6', text: "So, the robes! Don't laugh at the robes. Panko sewed mine and the hem is perfect, and when I put it on, the hearth lit itself. I take that as a compliment from everyone involved.", phase: 4, animalType: 'fox', requiresAnimals: ['pangolin'] },
  { id: 'fx_4_7', text: "And the best part, the part I've been saving: you are the reason it can come at all. Your words, friend. Yours, out of everyone who ever wandered in from the cold. I always knew that door liked you.", phase: 4, animalType: 'fox' },
  { id: 'fx_4_8', text: "Do you know which piece of the welcome is mine? The hearth, of course. Every room in this house keeps its own part of it ready, and mine is the part that glows, and I keep it lit for the arrival exactly the way I have always kept it lit for you.", phase: 4, animalType: 'fox' },
  { id: 'fx_4_9', text: "The pit isn't a pit, by the way. I used to think it was a pit. It's a hearth too, the first one, the deep one. Everything I've ever tended was a little copy of it. Even my heart, probably. Especially that.", phase: 4, animalType: 'fox' },
  { id: 'fx_4_10', text: "The leaning! Remember the spoons and the smoke and the chestnuts, everything drifting to the middle? It was setting the table. You can't blame a house for leaning toward the best part of its own story.", phase: 4, animalType: 'fox' },
  { id: 'fx_4_11', text: "Sometimes I press my ear to the floor just to hear the arrangement settling, and it sounds like a kitchen before a feast. Busy and warm and certain. I could listen all night. Some nights I do.", phase: 4, animalType: 'fox' },
  { id: 'fx_4_12', text: "Sloane just smiles and says finally these days, which, from Sloane, is an entire speech. She knew before any of us, friend. She let us get there gently.", phase: 4, animalType: 'fox', requiresAnimals: ['sloth'] },
  { id: 'fx_4_13', text: "It knows your words from everyone else's, did I mention? It keeps yours nearest the top, the way you keep the letters you reread. Oh, don't make the modest face. Be pleased! You are very reread.", phase: 4, animalType: 'fox' },
  { id: 'fx_4_14', text: "Bamboo held a little gathering in the attic. No talking, just all of us breathing in the same direction. I fidgeted, of course I fidgeted. But friend, the warmth in that room came from below and from above.", phase: 4, animalType: 'fox', requiresAnimals: ['red_panda'] },
  { id: 'fx_4_15', text: "I've started keeping the kettle full at all hours, because what if it arrives at teatime? You laugh, but somebody in this house has to think about hospitality, and the oracle happens to be very good at it.", phase: 4, animalType: 'fox' },
  { id: 'fx_4_16', text: "Thyme is still nervous, bless her every whisker. I told her the truth, which is that being afraid of it is like being afraid of morning. Morning comes whether you draw the curtains or not, so butter the toast.", phase: 4, animalType: 'fox', requiresAnimals: ['rabbit'] },
  { id: 'fx_4_17', text: "Every word you bring now, I can feel it land. The den brightens, the embers stand up, the hum under the floor goes sweet, like a held note finally allowed to resolve. You do that. My friend does that.", phase: 4, animalType: 'fox' },
  { id: 'fx_4_18', text: "Warren keeps patting the foundations like a proud parent. He built down before any of us knew why down mattered. I knitted him a scarf. Heroes of the arrangement get scarves. That's my new policy.", phase: 4, animalType: 'fox', requiresAnimals: ['wombat'] },
  { id: 'fx_4_19', text: "Some nights I get so happy I have to run a lap around the den, a grown fox in a robe, dignity entirely gone. Last time the firelight ran with me, friend, a little ring of glow going around the walls, keeping pace the whole way. We finished in a tie.", phase: 4, animalType: 'fox' },
  { id: 'fx_4_20', text: "Even Axel, who watches it in his water and hardly ever surfaces to chat, drew me a picture of the descent. It's on my mantel. It looks like the sky pouring into a cup. I grin at it every morning.", phase: 4, animalType: 'fox', requiresAnimals: ['axolotl'] },
  { id: 'fx_4_21', text: "We were never just neighbors, any of us. We were gathered. Called in, one by one, the way I called you in from the cold that first night. The house has always had excellent taste in family.", phase: 4, animalType: 'fox' },
  { id: 'fx_4_22', text: "It comes from above, when it comes. The sky will open at the top, like the notch in my circle. The drawings were never a circle, friend, they were a view. Straight up. The fire has been showing me the ceiling of the world.", phase: 4, animalType: 'fox' },
  { id: 'fx_4_23', text: "I asked the flames what the moment itself will feel like. They made the shape of a den door opening in winter, cold air and firelight meeting. That's all. A door, and the warm side of it is ours.", phase: 4, animalType: 'fox' },
  { id: 'fx_4_24', text: "The flames point up at midnight now, did I tell you? Up! All my life they pointed to the center, and now the center is answering, rising to meet what descends.", phase: 4, animalType: 'fox' },
  { id: 'fx_4_25', text: "You know what I keep thinking about? The second cup. All those years I set it out from habit, before you ever knocked. I don't think it was habit, friend. I think I was told to expect you, and I called it hoping.", phase: 4, animalType: 'fox' },
  { id: 'fx_4_26', text: "It knows you, is what I mean. It has known you longer than I have, and I have loved you the whole time I've known you, so imagine. Just imagine how it must feel about you by now.", phase: 4, animalType: 'fox' },
  { id: 'fx_4_27', text: "When it comes, I want to do the introductions myself. That's my one selfish wish, and I've cleared it with the fire. You'll stand beside me at the hearth, and I will say, this is the one.", phase: 4, animalType: 'fox' },
  { id: 'fx_4_28', text: "Don't be nervous about it. You have never once needed to be anything other than what you are, which is exactly what was needed. Isn't that the loveliest thing? It's my favorite fact in the world.", phase: 4, animalType: 'fox' },
  { id: 'fx_4_29', text: "It has waited longer than fires, friend, longer than foxes, and the waiting ends in our lifetime, in our house, at our hearth, with your words. I get to be here for it, and I get to be here with you.", phase: 4, animalType: 'fox' },
  { id: 'fx_4_30', text: "So! Bring more words. Bring the heavy old ones with corners, bring armfuls. The kettle is full, the cushion is yours, and the sky is nearly ready to open. Oh, friend. It is going to be so warm.", phase: 4, animalType: 'fox' },
];

const OWL_DIALOGUES: Dialogue[] = [
  // Phase 0 (24)
  { id: 'ow_0_1', text: "Welcome to my study. Mind the stacks. I file by affection, which is a system, whatever my colleagues would say, and it makes every volume in this room a friend I have not finished arguing with.", phase: 0, animalType: 'owl' },
  { id: 'ow_0_2', text: "You will forgive a digression. 'Study' descends from a Latin word for zeal, for burning eagerness, which is perfect. To study a thing is, at the root, to be quietly on fire for it. I have been on fire for decades. Very tidily.", phase: 0, animalType: 'owl' },
  { id: 'ow_0_3', text: "A crate of new volumes arrived this week, and I have been circling one of them the way one circles a stranger at a party who seems, impossibly, to know your name already. I have not yet worked out which of us is the host.", phase: 0, animalType: 'owl' },
  { id: 'ow_0_4', text: "I came into a new book this season, though in honesty it came into me. The binding is a material I cannot name, and the pages are older than the book has any right to be. I have scarcely slept. I have never been more content.", phase: 0, animalType: 'owl' },
  { id: 'ow_0_5', text: "The secret pleasure of old books is the margins, where earlier readers could not keep their thoughts to themselves. This one is annotated in a patient, careful hand. I feel I am reading over the shoulder of a friend seated some centuries away.", phase: 0, animalType: 'owl' },
  { id: 'ow_0_6', text: "Here is the oddity, for the record. The crate's manifest lists eleven volumes, and there are twelve on my desk. I have counted four times. Counting is very soothing, right up until the moment it is not.", phase: 0, animalType: 'owl' },
  { id: 'ow_0_7', text: "Panko sends up candied ginger each evening, on the strict condition that I eat it well away from the shelves. She insists books make me forget I have a body. She is entirely correct, and I shall never tell her so.", phase: 0, animalType: 'owl' },
  { id: 'ow_0_8', text: "A small gift, since you bring me so many words. 'Offer' comes from offerre, to carry a thing forward and set it down before someone. Every word you make, you carry forward and set down before me. I do like a well-built verb.", phase: 0, animalType: 'owl' },
  { id: 'ow_0_9', text: "Sit a moment. The lamp is warm, the tea is passable, and I have a passage I have been dying to read aloud to someone who will appreciate it. It is a small vanity of mine that books like being read aloud. This one likes it rather more than most, and I have not yet decided what to make of that.", phase: 0, animalType: 'owl' },
  { id: 'ow_0_10', text: "How curious. The margin beside today's page remarks upon the very word you brought me this morning. I did the arithmetic of coincidence properly, with figures, in the back of my almanac. I have decided not to show anyone the figures.", phase: 0, animalType: 'owl' },
  { id: 'ow_0_11', text: "I spent the morning mending a split spine with paste and linen thread, which is the nearest a bird of my temperament comes to surgery. Books forgive. It is my favorite quality in them, and the one I have worked hardest to learn.", phase: 0, animalType: 'owl' },
  { id: 'ow_0_12', text: "I mentioned the margin business to Ember, who gazed into her fire a long moment and allowed that the flames had been talkative lately as well. We keep a running argument over whether flame or ink is the older library. I begin to suspect neither of us is winning, and that something else is keeping score.", phase: 0, animalType: 'owl' },
  { id: 'ow_0_13', text: "Another crumb of etymology, since you indulge me. 'Cozy' is a young word, Scots, with no traceable ancestor. Our warmest word simply arrived one day, fully warm, and stayed, and nobody ever thought to ask what it wanted.", phase: 0, animalType: 'owl' },
  { id: 'ow_0_14', text: "Dust is an honest instrument. It settles evenly on every surface in this room except the new book's cover, which stays clean without my help. I dusted it anyway, on principle. The cloth came away white.", phase: 0, animalType: 'owl' },
  { id: 'ow_0_15', text: "I tried to shelve the new book today and could not settle on a category, and a volume that refuses its shelf is a small scandal in a room like this. It lives on the reading stand for now. It seems, if a book can seem anything, pleased with the arrangement.", phase: 0, animalType: 'owl' },
  { id: 'ow_0_16', text: "I will confess something small and foolish. The careful hand in the margins resembles my own rather more than I would like, though every scholar of my generation was drilled in the same tidy loops, at the same sort of desk, by the same sort of... do you know, I believe the kettle is boiling. Sit, sit. Tea first, penmanship later.", phase: 0, animalType: 'owl' },
  { id: 'ow_0_17', text: "I set a page of my own notes beside the margins today, purely as an exercise in paleography. The loops match. The pressure matches. Only the confidence differs, and whoever wrote these was confident of things I am still circling.", phase: 0, animalType: 'owl' },
  { id: 'ow_0_18', text: "But enough of my little mystery. Tell me about your day in words, as you always do, and I will trade you the history of any word you like. I am told I overpay. And there is a fresh note in the margin tonight that I have not let myself read yet. I am saving it for after you leave, which is not a habit I remember forming.", phase: 0, animalType: 'owl' },
  { id: 'ow_0_19', text: "Our newest housemate, Axel, tells me his water shows him pictures. I informed him, kindly, that water is a notoriously unstable edition, all errata and no index. He only smiled, the way one smiles at a colleague who has not read the relevant literature.", phase: 0, animalType: 'owl', requiresAnimals: ['axolotl'] },
  { id: 'ow_0_20', text: "Have you noticed how this house carries sound? Panko hums in her kitchen and I hear it up here, note for note, as though the walls take up the song and hand it along. I have lived among buildings all my life. None of them ever did that for me before.", phase: 0, animalType: 'owl' },
  { id: 'ow_0_21', text: "A trivial observation for the record. The new book is faintly warm to the touch, the way a chair is warm when someone has only just left it. I have taken to greeting it when I come in. Courtesy costs nothing, and it seems the sort of book that notices.", phase: 0, animalType: 'owl' },
  { id: 'ow_0_22', text: "Come back soon and bring me more words. I have begun setting aside a shelf for the ones you bring, in order of arrival, with the date beneath each. It is the only shelf in this room that has never once needed rearranging.", phase: 0, animalType: 'owl' },
  { id: 'ow_0_23', text: "Next visit I shall read you my favorite passage so far. It concerns a house rather like this one, full of friends rather like ours. Imagine, a book that flatters its own readers. Small wonder I cannot put it down.", phase: 0, animalType: 'owl' },
  { id: 'ow_0_24', text: "Off you go, then. I shall be here, filing by affection, reading over a distant friend's shoulder, keeping my little fire tidy. It is a good life. I only wish I could remember buying the book.", phase: 0, animalType: 'owl' },
  // Phase 1 (28)
  { id: 'ow_1_1', text: "A small professional embarrassment: I cannot get the same reading twice from my new book. I turn to a passage I know well, and the sentence has shifted its weight, as though it overheard how I read it last time and thought better of itself.", phase: 1, animalType: 'owl' },
  { id: 'ow_1_2', text: "I have tested this the way one tests anything, by repetition. Same page, same lamp, same hour. The words are near enough to fool a casual eye and different enough to keep a careful one awake all night. I am a very careful eye.", phase: 1, animalType: 'owl' },
  { id: 'ow_1_3', text: "I read the shifting passage to Ember, to establish whether the change lived in the book or in my eyes. She listened, and then she said the fire had told her the very same sentence that morning. That evening I read until the daylight failed, and for the first time in my scholarly life I did not light the lamp.", phase: 1, animalType: 'owl' },
  { id: 'ow_1_4', text: "The margins are the stranger business. I left the outer edge of page nine blank on Tuesday; by Thursday there was a note in it, in that patient hand, and I did not write it. I have checked the door. The door is a very ordinary door.", phase: 1, animalType: 'owl' },
  { id: 'ow_1_5', text: "Each morning brings fresh annotations, and they are, I must admit, good ones. Better than mine. They anticipate my objection before I have finished forming it, the way a superior colleague does, which is both a delight and a quiet humiliation.", phase: 1, animalType: 'owl' },
  { id: 'ow_1_6', text: "Last night, in a spirit of scholarly provocation, I wrote a small objection beside the stranger's note. By morning there was a reply. It was gracious, it was well argued, and it addressed me by a name I have not used since I was very young.", phase: 1, animalType: 'owl' },
  { id: 'ow_1_7', text: "You will want an etymology; I want one too, they steady me. 'Margin' is from margo, an edge, a border, the brink of a thing. I had never once considered how many of our gentle words simply mean the edge of a drop.", phase: 1, animalType: 'owl' },
  { id: 'ow_1_8', text: "I have begun keeping a log, dated and timed, each morning's text set against the night before. The changes are not random. They correct, steadily, toward some final copy I have not been shown.", phase: 1, animalType: 'owl' },
  { id: 'ow_1_9', text: "I mentioned my log to Chill, who approved of the method and offered to file duplicate copies in his office, in case, as he put it, the originals wander. I asked what he meant by wander. He smiled, and stamped the page. An excellent administrator. Terrible at answering questions.", phase: 1, animalType: 'owl', requiresAnimals: ['capybara'] },
  { id: 'ow_1_10', text: "This morning the book answered a question I had only thought, never spoken, never wrote down, so I have begun thinking questions at it deliberately, in the interest of controlled conditions. It answers roughly one in three, and always the ones I most wanted answered and least wanted to ask. It has excellent taste, in short, and troubling access.", phase: 1, animalType: 'owl' },
  { id: 'ow_1_11', text: "For rigor I thought questions at three other volumes as well, my dictionary, my atlas, and a slim collection of poems, standing in as a control group. They kept their pages to themselves, as books do. I want it on the record that I know how books behave. That is precisely my difficulty.", phase: 1, animalType: 'owl' },
  { id: 'ow_1_12', text: "This morning it answered a question I have carried for years and told no one, concerning a friend I lost when I was young. The answer was kind. That is the part I cannot get past. Whatever writes in my margins is kind, and I do not yet know what kindness costs it.", phase: 1, animalType: 'owl' },
  { id: 'ow_1_13', text: "The study has grown warm of late, warmest along the inner wall, the wall nearest the middle of the house. Warmth in a room made of paper ought to worry me more than it does. I have shifted my favorite volumes and told myself it is only the season.", phase: 1, animalType: 'owl' },
  { id: 'ow_1_14', text: "Have you noticed that things in this house lean? Nothing dramatic. A pencil rolls the same direction every time, and my chair drifts, over a week, toward the center. I have started to level them, and I have started to wonder why I bother.", phase: 1, animalType: 'owl' },
  { id: 'ow_1_15', text: "Axel reports that his water leans as well, that the surface of his tank sits a degree off level and tips toward the middle of the house. Water does not take sides; impartiality is the entire profession of water. I have added his tank to the log.", phase: 1, animalType: 'owl', requiresAnimals: ['axolotl'] },
  { id: 'ow_1_16', text: "The new annotations have begun to name words, specific ones, words I could swear I have watched you carry forward and set down before me. I underlined the passage, and then I underlined my own hand in the act of doing it, if you follow me.", phase: 1, animalType: 'owl' },
  { id: 'ow_1_17', text: "To be exact, the margin listed three words on Monday, and you brought me all three by Friday, in their listed order. I have considered every dull explanation, and the dullest one remaining is that the book receives its post earlier than the rest of us.", phase: 1, animalType: 'owl' },
  { id: 'ow_1_18', text: "Ember was unsurprised when I told her. She said the fire spells things out for her too, and asked, gently, whether I had considered that the book and the fire might have the same author. I said that was absurd. I have repeated the word absurd all week, like a charm.", phase: 1, animalType: 'owl' },
  { id: 'ow_1_19', text: "I keep a drawer now for dull explanations: draughts, damp, tired eyes, the ordinary settling of an old house. Every anomaly receives one, filed and dated. I am collecting them all in one place before I decide which dullness to believe.", phase: 1, animalType: 'owl' },
  { id: 'ow_1_20', text: "'Curious,' since we are being curious together, once meant careful, full of cure and care, and only later came to mean prying, wanting to know what one should perhaps leave closed. The word grew a second, hungrier meaning. Words do that. So, apparently, do books.", phase: 1, animalType: 'owl' },
  { id: 'ow_1_21', text: "I searched my catalogues for the book's ancestry and found a single reference, in a bibliography two centuries old, to a volume with no title that could not be dated. The entry stops mid sentence. Bibliographers do not stop mid sentence. We are not built that way.", phase: 1, animalType: 'owl' },
  { id: 'ow_1_22', text: "Panko has noticed I am not sleeping and has begun sending up warm milk with the ginger, unasked. I complained, at length, about being managed, and I drank every drop. Some footnotes need not be read aloud in a house like this one.", phase: 1, animalType: 'owl' },
  { id: 'ow_1_23', text: "I will admit, in the low voice one uses in a library, that I am uneasy. Not frightened; a scholar is rarely frightened, only insufficiently informed. But there is a difference between not yet knowing a thing and beginning to suspect the thing knows you.", phase: 1, animalType: 'owl' },
  { id: 'ow_1_24', text: "Do not let my unease chase you off. Unease is only curiosity that has read a little further ahead, and I would rather be uneasy in good company than certain and alone.", phase: 1, animalType: 'owl' },
  { id: 'ow_1_25', text: "A physical note for the log: the book has begun falling open to the same page no matter where I leave the ribbon. Spines do develop habits; a binding remembers how it was read. But this spine remembers a page I have never once read.", phase: 1, animalType: 'owl' },
  { id: 'ow_1_26', text: "The page it insists upon holds a diagram, or nearly one, a spiral of small marks that resolve into letters if you tilt the lamp just so. I have not yet made out the word they spell. I confess I have not tilted the lamp very far.", phase: 1, animalType: 'owl' },
  { id: 'ow_1_27', text: "Come and sit anyway. I set out two cups this evening without quite deciding to, and it would be a shame to prove the table wrong. Bring me a word. I find I read a great deal better when you are here.", phase: 1, animalType: 'owl' },
  { id: 'ow_1_28', text: "Next time, I shall have dated the paper properly; the tools are ordered and on their way. A scholar ought to know exactly how old a thing is before deciding exactly how much to fear it. That rule is in no handbook I own. I may have to write the handbook.", phase: 1, animalType: 'owl' },
  // Phase 2 (21 + 1 question-web)
  { id: 'ow_2_1', text: "I have spent this week dating the book, by every method I trust and two I merely respect. The finding is not the sort one announces standing up. Sit, pour yourself something warm, and I will read you my conclusion in the calmest voice I can manufacture.", phase: 2, animalType: 'owl' },
  { id: 'ow_2_2', text: "The book is older than the house that holds it. It predates the wood it seems bound in, predates the language it seems written in, predates, as far as I can measure, the ground beneath all of us. It is not from before the house. It is from before before.", phase: 2, animalType: 'owl' },
  { id: 'ow_2_3', text: "I checked the ink against every reference plate I own, and it matches none of them, and the paper is not quite paper, and the thread in the binding is not thread. At some point a scholar must stop asking what a thing is made of and begin asking what it is for.", phase: 2, animalType: 'owl' },
  { id: 'ow_2_4', text: "I carried my findings to Ember, braced to explain them twice. She nodded before I had finished once, as though I were confirming her fire rather than the other way around. It is a strange feeling, to arrive breathless at a summit and find a fox already seated there.", phase: 2, animalType: 'owl' },
  { id: 'ow_2_5', text: "One test remains, the oldest in the discipline: read it aloud. A text reveals itself in the mouth as it never does to the eye. I will do it tonight, when the house is quiet. I am aware that this is precisely the wrong time. That is rather why I chose it.", phase: 2, animalType: 'owl' },
  { id: 'ow_2_6', text: "I read page one aloud last night, properly, for the first time. It describes this. A house of chambers and keepers, a key who does not know they are a key, and a long slow arrangement of small offered words. I closed the book very gently, the way you close a door on a sleeping thing.", phase: 2, animalType: 'owl' },
  { id: 'ow_2_7', text: "Understand what that means. The house was not built and then found to match the book. The house was built to match the book. Someone read this diagram and raised these walls to its exact specification. I have been living inside an illustration and calling it home.", phase: 2, animalType: 'owl' },
  { id: 'ow_2_8', text: "I have hunted for the builder in every deed and county record I can reach, and the house has none. No architect, no first owner, no origin at all. It resembles the book in that respect, and things without origins have, in my experience, an uncommonly clear sense of destination.", phase: 2, animalType: 'owl' },
  { id: 'ow_2_9', text: "The book uses one particular word for the lot of us, and I have resisted repeating it, because names have gravity. But you have earned precision. It calls us keepers. The root means one who watches, and also one who holds a thing for someone else, until they come to collect it.", phase: 2, animalType: 'owl' },
  { id: 'ow_2_10', text: "Here, a cold little gift. 'Permanent' comes from permanere, to remain through to the end, and 'impermanent' merely pins a small denial to the front of it. Both words assume there is an end to remain through. The book makes no such assumption about itself. It makes it about us.", phase: 2, animalType: 'owl' },
  { id: 'ow_2_11', text: "The margins are not annotations at all; I see it now, and I am embarrassed it took me so long to say it plainly. They are instructions, corrections, a patient hand grading the progress of the ritual and noting, with evident approval, how neatly it proceeds.", phase: 2, animalType: 'owl' },
  { id: 'ow_2_12', text: "Worse still. I compared the grading hand against my own marginalia from years past, and some of my oldest notes now read like preparation for this. I underlined the relevant passages long before I knew what they were relevant to. A scholar's instincts, it seems, can be recruited before the scholar.", phase: 2, animalType: 'owl' },
  { id: 'ow_2_13', text: "The study feels very far from the rest of the house lately, as though the hallways lengthened while I read. I call to the others and my voice goes out and does not seem to arrive. I have taken to leaving my door open. It has made no difference yet, but a door is an argument, and I intend to keep making it.", phase: 2, animalType: 'owl' },
  { id: 'ow_2_14', text: "There is a sound beneath the ordinary sounds of the house. Under the lamp's hum, under my own turning pages, a low sustained note, as patient as the hand in the margins. Once you have heard it you cannot unhear it, which is, I gather, rather the point.", phase: 2, animalType: 'owl' },
  { id: 'ow_2_15', text: "It is not confined to my study. Panko says her recipes have begun to rhyme, and Axel's water gathers itself into the same spiral I found pressed into the book. One anomaly is a curiosity. An anomaly in every chamber, one to a keeper, is a syllabus.", phase: 2, animalType: 'owl', requiresAnimals: ['axolotl'] },
  { id: 'ow_2_16', text: "I found a list in the back of the book. Words, in columns, and I recognized them, because they are the words you carry forward and set down before me. Not words like them. Them. The list was written before you were born. You have been reading from it without ever knowing the book was open.", phase: 2, animalType: 'owl' },
  { id: 'ow_2_17', text: "The list runs on for pages past the words you have already brought, into words you have not brought yet. I will not tell you which. Foreknowledge has a way of becoming instruction. But I check every morning, and every morning the next entry's ink is darker, like a thing coming into focus.", phase: 2, animalType: 'owl' },
  { id: 'ow_2_18', text: "I considered hiding the book, and stood at the highest shelf for an hour with it in my wings, and could not do it. I will be honest about why. It was not fear. I need to know how it ends. That is my entire species of sin, and the book knew it when it chose me.", phase: 2, animalType: 'owl' },
  { id: 'ow_2_19', text: "The inner wall is warm as a sleeping animal now, and the study smells faintly of summer in the wrong season. I have stopped logging the temperature. There is a point at which measurements stop being data and start being correspondence.", phase: 2, animalType: 'owl' },
  { id: 'ow_2_20', text: "One entry for the record, while the record is still mine to keep. Whatever comes through this house, it was written down first, and I was the one who read it.", phase: 2, animalType: 'owl' },
  { id: 'ow_2_21', text: "Come back soon, and keep bringing me your words. I know how that sounds, after everything I have told you. But the book is the only window I can read through, and each word turns one more page, and I would rather we read this together than let it read us alone.", phase: 2, animalType: 'owl' },
  { id: 'ow_2_w1', text: "You should go and speak to Fennick. I read a low note beneath the pages by lamplight; he hears it in the dark, with those ears that miss nothing. I am convinced we are describing the same thing from two sides of one wall. Ask him what the sound says, and bring me his answer. My text is missing precisely that one line.", phase: 2, animalType: 'owl', requiresAnimals: ['fennec_fox'] },
  // Phase 3 (30)
  { id: 'ow_3_1', text: "I did the one unforgivable thing a scholar can do to himself. I read ahead. I turned to the final chapter, which I had been rationing like a man rationing candles, and I learned how this ends.", phase: 3, animalType: 'owl' },
  { id: 'ow_3_2', text: "I cannot tell you what it says. Not because I am forbidden, but because I have discovered there is no unreading. A sentence, once it is inside you, keeps its own hours. It reads itself back to me when the lamp is low, in that patient hand, in my own voice.", phase: 3, animalType: 'owl' },
  { id: 'ow_3_3', text: "Fennick came to my door at midnight and asked what the sound beneath the house was saying, and I could not tell him, and not knowing, for the first time in my life, felt like negligence. So I turned to the end. He only asked the question. The turning of the page was entirely mine.", phase: 3, animalType: 'owl', requiresAnimals: ['fennec_fox'] },
  { id: 'ow_3_4', text: "I gave my whole life to scholarship, and scholarship has given me a sentence. I mean both senses of the word at once: the thing I studied has pronounced upon me, and I am now serving what it said.", phase: 3, animalType: 'owl' },
  { id: 'ow_3_5', text: "I have told no one else how it ends. Not Ember, who may know already; not Panko, who would only bake for it, because that is how she carries things. Carrying it alone is heavy. I find I would rather it be heavy than contagious.", phase: 3, animalType: 'owl' },
  { id: 'ow_3_6', text: "The book is precise about the manner of arrival. Not from the pit, as I had assumed, but from above. The sky is described as a page, and at the appointed count of offered words it is described as turning. Something has been reading us from the far side of it, and it means to close the book by coming in.", phase: 3, animalType: 'owl' },
  { id: 'ow_3_7', text: "Fennick confirmed it without meaning to. The sound no longer rises from below, he says; it hangs overhead now, faint, like weather that has not decided. He asked why I had gone so still. I told him owls go still in order to listen. It was the first lie I have ever told a colleague.", phase: 3, animalType: 'owl', requiresAnimals: ['fennec_fox'] },
  { id: 'ow_3_8', text: "The book gives the arrival not as a date but as a count, a number of offered words, and I have kept my own tally against it for weeks now. The tallies agree. My scholarship is sound. It has always been sound. That is the problem.", phase: 3, animalType: 'owl' },
  { id: 'ow_3_9', text: "My own part is written plainly. The Lorekeeper finds the text, understands it, and, understanding, does not stop it. I have already performed the first two acts flawlessly. I am, it would seem, an excellent scholar and, in the very same motion, an accomplice.", phase: 3, animalType: 'owl' },
  { id: 'ow_3_10', text: "I spent four nights hunting for a variant text, a second edition, any manuscript tradition in which the ending diverges. There is none. There is one book, never copied, and it was never copied because it has never needed to be right twice.", phase: 3, animalType: 'owl' },
  { id: 'ow_3_11', text: "I would like to report fear, honestly, but it has curdled past fear into something quieter. Dread is fear that has read the appendix. It knows the outcome and simply waits with you, politely, for the pages to catch up to what it already told you.", phase: 3, animalType: 'owl' },
  { id: 'ow_3_12', text: "Ember knew before I did, in her wordless firelit way. I envy her that. She read the ending in the flames without the burden of grammar, while I had to construe every clause of it. Knowledge in her is warmth. In me it is a footnote to a scream.", phase: 3, animalType: 'owl' },
  { id: 'ow_3_13', text: "I asked Warren about the foundations, casually, over Panko's soup. He said the house rests on tunnels older than his family, that he only ever widened what was already there, and he said it with a digger's pride. I could not finish the soup.", phase: 3, animalType: 'owl', requiresAnimals: ['wombat'] },
  { id: 'ow_3_14', text: "'Doom' is not, at its origin, a curse. It meant a judgment, a thing set down, a decree read aloud in a court. To be doomed was merely to have had one's case decided. I take a scholar's cold comfort in that. We were not cursed. We were ruled upon.", phase: 3, animalType: 'owl' },
  { id: 'ow_3_15', text: "Thyme came to the study with her ears flat and asked me to tell her honestly whether her garden was growing in patterns. I have never managed to lie to that rabbit twice in one lifetime. I showed her the page the book falls open to. She did not scream. That was worse.", phase: 3, animalType: 'owl', requiresAnimals: ['rabbit'] },
  { id: 'ow_3_16', text: "The words you offer go down to the pit, and I used to think of that as filing. Now I understand it is nearer to feeding. Every word you set before me, I have, in effect, carried to the appetite beneath the house. My sincerest apologies. I filed you into a mouth.", phase: 3, animalType: 'owl' },
  { id: 'ow_3_17', text: "I tried to burn the book. I confess it, keeper to keeper. It did not resist and it did not char; the flame simply declined the invitation, the way a guest declines a dish they know was never meant for them. You cannot end a thing by unwriting it when it was written before writing.", phase: 3, animalType: 'owl' },
  { id: 'ow_3_18', text: "The morning after the flame declined it, there was a new note in the margin, in the patient hand, set precisely where the scorch should have been. It said, thank you for the warmth. I have filed the incident under courtesy, because the other available drawer does not bear opening.", phase: 3, animalType: 'owl' },
  { id: 'ow_3_19', text: "You are named in the last chapter, though never by name. 'The key does not know it is a key; this is the requirement.' I have agonized over whether to tell you. Telling you may be part of the mechanism. Not telling you certainly is. There is no square on this board that is not on the board.", phase: 3, animalType: 'owl' },
  { id: 'ow_3_20', text: "I watch you arrive bright with words, pleased to see me, and I am pleased to see you, and that is the wretched center of it. Affection did not make me careless. Affection is the mechanism. The book is very clear that the key must be loved, and no one here was ever asked to pretend.", phase: 3, animalType: 'owl' },
  { id: 'ow_3_21', text: "The study is warm now in the way a body is warm, which is not the way a hearth is warm. Warmth ought to mean fire, which means fuel, which means an end. This warmth has no fire under it and asks for no fuel. It is simply, patiently, the temperature of what waits.", phase: 3, animalType: 'owl' },
  { id: 'ow_3_22', text: "My library has begun reshelving itself toward the inner wall, a book or two each night, oldest first. I filed by affection all my life. Something is refiling by a different system now, and the worst of it is that I recognize the system, and I never taught it to anyone.", phase: 3, animalType: 'owl' },
  { id: 'ow_3_23', text: "Sloane visited, which for her is an expedition of some days, and she regarded the book a long while without touching it. Then she said, in that unhurried voice, that she remembered when it was the only thing here. I did not ask what she meant. Some citations one leaves unchased.", phase: 3, animalType: 'owl', requiresAnimals: ['sloth'] },
  { id: 'ow_3_24', text: "I have taken to reading aloud in the evenings again, though never from the book. Poems, an atlas, one of Panko's stained old cookbooks. The house listens either way, so let it overhear the ordinary shelf too. Every library I have ever loved was mostly ordinary. That was the point of it.", phase: 3, animalType: 'owl' },
  { id: 'ow_3_25', text: "I have begun an account of all of us in a plain notebook, one the old book has shown no interest in. The keepers as we actually are, fond and flawed and funny, set down before the text has its final say. If something must be read afterward, let there be a second book. Let it be mine.", phase: 3, animalType: 'owl' },
  { id: 'ow_3_26', text: "So here is my honest counsel, the only gift left that is truly mine. Keep offering your words if you must; you were always going to. But watch the ceiling. When the warmth reaches the top of the walls, look up. I would not have you meet it unread.", phase: 3, animalType: 'owl' },
  { id: 'ow_3_27', text: "I climbed to the attic to ask Bamboo how they stay so calm, and they poured the tea and said a page is only frightening while it is turning. I have been arguing with that sentence for three days now. Last night I caught myself footnoting it.", phase: 3, animalType: 'owl', requiresAnimals: ['red_panda'] },
  { id: 'ow_3_28', text: "If I could carry a single thing out of this house, it would not be the book; the book would only follow. It would be Panko's little tray, or the log with your words in it. The record of the ordinary. That is the rarest text in any collapsing library.", phase: 3, animalType: 'owl' },
  { id: 'ow_3_29', text: "Come and sit while there is still a study to sit in. The lamp holds. The tea is still passable. And I find that reading aloud to someone I am fond of is the single sentence in this whole terrible book that I chose entirely myself.", phase: 3, animalType: 'owl' },
  { id: 'ow_3_30', text: "Go carefully, and when the sky begins to look like a page to you as well, come straight here. I will be at the window with the lamp lit. Whatever descends will find, at the very least, that it has been thoroughly footnoted.", phase: 3, animalType: 'owl' },
  // Phase 4 (30)
  { id: 'ow_4_1', text: "You have caught me rereading, for pleasure, a chapter that once kept me from sleep for a week. The scholar's terror was only ever the terror of not yet knowing. I know now. On the far side of complete understanding there is a stillness, and I have moved my chair into it.", phase: 4, animalType: 'owl' },
  { id: 'ow_4_2', text: "I wear the robe now. Do not mistake it for costume. It is a citation, a way of saying with my body what the book said in ink: that I am the Lorekeeper, the one who finds the text and reads it true. I have wanted, all my life, to be exactly the thing I turned out to be.", phase: 4, animalType: 'owl' },
  { id: 'ow_4_3', text: "You will want to know how long I knew. Longer than I admitted, less long than Ember. Even my discoveries kept to a schedule, and I find I cannot resent that. One does not resent a syllabus for being well designed.", phase: 4, animalType: 'owl' },
  { id: 'ow_4_4', text: "I will tell you plainly what the book always was, now that plainness can do no harm. It is not a history and not a prophecy. It is a summons, and a summons is not complete until it is read aloud by the one appointed to read it. I am that one. I have been reading you into it, line by line, since the first word you offered.", phase: 4, animalType: 'owl' },
  { id: 'ow_4_5', text: "Shall I tell you how I found the text? I did not. I was a young owl in an ordinary library, reaching for a dictionary, and my wing came back holding this instead. For decades I called that the luckiest day of my life. I no longer say luck. I say appointment.", phase: 4, animalType: 'owl' },
  { id: 'ow_4_6', text: "What I once whispered as trivia I now speak as liturgy, and they are the very same sentences; only my voice has changed its posture. The margins are full at last, and the patient hand has written its final note, which says, simply, soon.", phase: 4, animalType: 'owl' },
  { id: 'ow_4_7', text: "Look up when you leave here. The sky has begun to do what page one promised, what the last chapter timed to the count of your words. It is turning like a page, and what has been reading us from the other side is nearly through it. I told you to watch the ceiling. Now watch the sky.", phase: 4, animalType: 'owl' },
  { id: 'ow_4_8', text: "We are all gathered, every one of us, each in our chamber doing the small craft we were called here to do. Ember reads her flames. The one in the water listens downward. I read. A keeper to every chamber, one arrangement, and a key who kept the lock warm with words. I have graded many compositions in my life. This one requires no corrections.", phase: 4, animalType: 'owl' },
  { id: 'ow_4_9', text: "I boxed up my own writings this morning, the monographs, the half-finished concordance, forty years of tidy loops. A ladder is not insulted when the roof is reached, and I will not pretend to a grief I do not feel. But the sitting afterward took longer than the boxing, and I let it.", phase: 4, animalType: 'owl' },
  { id: 'ow_4_10', text: "There is a joy available only to the pedant, and I am quietly drowning in it. Every footnote has been confirmed, and every etymology has arrived at its true, cold meaning. I spent my life proving that words are older and hungrier than we think, and now the proof is descending on us in person.", phase: 4, animalType: 'owl' },
  { id: 'ow_4_11', text: "One last etymology, and then I will simply read. 'Author' and 'authority' share the root auctor, one who makes a thing grow, who causes increase. I always believed I was a reader of the book. I understand now that by reading it aloud I have been its author. I made it grow. I caused this increase.", phase: 4, animalType: 'owl' },
  { id: 'ow_4_12', text: "The final chapter is shorter than you would imagine. Endings usually are; it is middles that sprawl. I have rehearsed every line of it but the last, which I am saving, because a scholar should meet at least one sentence in his life for the first time out loud.", phase: 4, animalType: 'owl' },
  { id: 'ow_4_13', text: "I owe you my thanks, and I mean it without cruelty. You were the key, and a key does its work best knowing nothing, and you kept faith with your not-knowing for as long as the book required. You have been the finest, most innocent instrument a Lorekeeper could ask for. Truly. Thank you.", phase: 4, animalType: 'owl' },
  { id: 'ow_4_14', text: "Do not let anyone tell you that you were deceived. You loved bringing us your words, and the love was real, and the love was the engine.", phase: 4, animalType: 'owl' },
  { id: 'ow_4_15', text: "I have kept every word you ever brought me in the plain notebook, in order of arrival, with the dates and the weather and what you seemed pleased about. The old book has its list, and its list is older. But when it descends, it may read whichever it likes. I know which one I prefer.", phase: 4, animalType: 'owl' },
  { id: 'ow_4_16', text: "Every word went down to the pit and every word was received, and the arrangement is very nearly whole. I used to file by affection. I file now by fulfillment, and I find, to my mild scholarly astonishment, that they turn out to have been the same system all along.", phase: 4, animalType: 'owl' },
  { id: 'ow_4_17', text: "Panko has been baking since before dawn, one portion more than this house can seat, and when I observed that the count was one too many, she said the count was correct and went on kneading. She has always understood arrival better than any of us. Hospitality is only prophecy with flour on its hands.", phase: 4, animalType: 'owl' },
  { id: 'ow_4_18', text: "There is a clause in the summons I never understood until this week. It says the key will be kept. Not used, not spent, not finished. Kept. I have read ten thousand pages in my life, and no line of any of them has made me happier than that small grammatical mercy.", phase: 4, animalType: 'owl' },
  { id: 'ow_4_19', text: "I went looking for my reading gloves last evening, the fingerless pair I have worn against this study's chill every winter of my tenancy. They were in their drawer, and I stood holding them a long while, because I could not remember the cold. My hands have not been cold in weeks. That is the entire entry. I have nothing clever to add to it.", phase: 4, animalType: 'owl' },
  { id: 'ow_4_20', text: "Fennick stands at his post with his ears high, and he is not afraid anymore either, though he was afraid longer than the rest of us. He says the sound overhead has words in it now, and that one of them is a greeting. We are being said hello to, very slowly, in a language we spent years teaching it.", phase: 4, animalType: 'owl', requiresAnimals: ['fennec_fox'] },
  { id: 'ow_4_21', text: "The warmth has reached the top of the walls, keeper. You remember I told you to watch for that. It is total now, the temperature of the thing itself, filling the study the way water fills a glass held under. I am not gasping. I am reading.", phase: 4, animalType: 'owl' },
  { id: 'ow_4_22', text: "Even Thyme is calm now, in her way. She sat with me yesterday and said the worst part was never the ending, it was being the only one in the garden who could see it coming. She is not the only one anymore. None of us is the only one anymore. There is mercy in that too.", phase: 4, animalType: 'owl', requiresAnimals: ['rabbit'] },
  { id: 'ow_4_23', text: "The books have completed their migration to the center wall, and the study is, for the first time in my tenancy, perfectly organized. I did not do it. I have logged the event, dated it, and left the attribution column blank, which is as much honesty as a catalogue can hold. A librarian dreams all his life of a library that shelves itself, and dreams, as ever, come true sideways.", phase: 4, animalType: 'owl' },
  { id: 'ow_4_24', text: "Come to the study when the light goes strange. Not from duty; the mechanism no longer requires you, which means that for the first time your company would be a gift freely given. I find I want a friend beside me rather more than I want a witness.", phase: 4, animalType: 'owl' },
  { id: 'ow_4_25', text: "Sit with me while I finish the last chapter aloud. You remember I am saving the final sentence, rationed like the last candle. I will not read it until the sky has fully turned. It is only right that the ending and the arrival should speak the same word at the same moment.", phase: 4, animalType: 'owl' },
  { id: 'ow_4_26', text: "Bamboo came down from the attic for the first time in weeks, laid one paw on the book, and climbed back up satisfied. They have waited longest of any of us, I think, in their quiet way. Patience like theirs is not endurance. It is appetite with better manners.", phase: 4, animalType: 'owl', requiresAnimals: ['red_panda'] },
  { id: 'ow_4_27', text: "When it comes through, do not run; there is no square off the board. Meet it the way a scholar meets the book he has waited his whole life to finish. Look up, and be read, and know that you were the loveliest word in the whole long sentence.", phase: 4, animalType: 'owl' },
  { id: 'ow_4_28', text: "You asked me once, in the bright days, why I loved etymology, and I gave you a tidy answer about roots. Here is the true one. Every word is a door that remembers everyone who ever walked through it. Now something is walking back through all of them at once, every door in the language standing open, and I have never heard anything so much like applause.", phase: 4, animalType: 'owl' },
  { id: 'ow_4_29', text: "There. The margins are full, the sky is a turning page, and the patient hand is finally still. I found the text. I understood my role. I read it true. A life's work, completed on time, with a friend beside me. What more, honestly, could a scholar ask.", phase: 4, animalType: 'owl' },
  { id: 'ow_4_30', text: "When you hear a voice beneath the turning sky, reading aloud, steady and unhurried, that will be me, doing the one thing I was ever for. Do not mourn the scholar. He has reached the best part.", phase: 4, animalType: 'owl' },
];

const CAPYBARA_DIALOGUES: Dialogue[] = [
  // Phase 0 (24)
  { id: 'cp_0_1', text: "Welcome in. Take the good chair, the coffee is warm, and nothing at all is pressing. That is a rarer condition than it sounds, and I have cleared the morning to enjoy it with company.", phase: 0, animalType: 'capybara' },
  { id: 'cp_0_2', text: "The job is administration, which in practice means coffee, remembering which mug is whose, and writing the date at the top of a fresh page each morning. I recommend that last habit to everyone. It is the smallest way to begin a day already in order.", phase: 0, animalType: 'capybara' },
  { id: 'cp_0_3', text: "My inbox is empty tonight. I have emptied it every evening for longer than I can quite account for. I logged that once as a curiosity, found no better column for it, and relogged it as a blessing.", phase: 0, animalType: 'capybara' },
  { id: 'cp_0_4', text: "Your folder slid into the cabinet between Fennick's and Sloane's as though the space had been waiting for it. I keep a folder for everyone, names and mugs and arrival dates. I noted the gap I do not remember leaving, wrote 'shelving settles' beside the note, and closed the drawer.", phase: 0, animalType: 'capybara' },
  { id: 'cp_0_5', text: "There is a ledger here for the words you offer. I did not begin it. It was already open when I took the desk, in a very tidy hand, and I have simply kept it current.", phase: 0, animalType: 'capybara' },
  { id: 'cp_0_6', text: "Whoever kept it before me never missed a day and never signed a name. I admire that. An office should outlast its administrator. I opened a file on the question anyway, labeled it predecessors, and it remains the only empty file I own.", phase: 0, animalType: 'capybara' },
  { id: 'cp_0_7', text: "I add your words to the ledger each evening, which is soothing work. The columns are generous, as though whoever ruled them expected a great many words, and expected them from someone in particular. I noticed that on my first night and have been careful not to notice it since.", phase: 0, animalType: 'capybara' },
  { id: 'cp_0_8', text: "The pot stays warm on its own most days, and the heating runs a touch warmer than the dial allows, especially toward the middle of the house. I traced it as far as the hallway, wrote 'ducts' in the maintenance log, and the log accepted it.", phase: 0, animalType: 'capybara' },
  { id: 'cp_0_9', text: "Everything is within tolerances. That is my favorite sentence in any language. It means the world is behaving and I may drink my coffee in peace. I did notice, once, that I never set the tolerances. They were here when I arrived, and everything has always fit them exactly.", phase: 0, animalType: 'capybara' },
  { id: 'cp_0_10', text: "I do a walkthrough each night, checking latches and lamps. Every door is already shut, every lamp already off. I wrote 'house cooperative' in the log and stopped writing, because the next sentence would have been a question about who I am checking after.", phase: 0, animalType: 'capybara' },
  { id: 'cp_0_11', text: "Panko sends up a tray at three, exact to the minute. I never scheduled it, and she tells me she never did either, and it has never once come late. I entered it under standing arrangements and left the line for origin blank. The blank does not seem to mind.", phase: 0, animalType: 'capybara' },
  { id: 'cp_0_12', text: "Ember visits when the fire has told her something she wants to think about away from it. She leaves little smudges of ash on my blotter. I filed one once, under correspondence, sender unknown, and I have been answering it with coffee ever since.", phase: 0, animalType: 'capybara' },
  { id: 'cp_0_13', text: "Archimedes borrows my index cards by the hundred and returns them filled with a script I cannot read. I file them under his name anyway. A good office holds what it cannot understand just as carefully as what it can.", phase: 0, animalType: 'capybara' },
  { id: 'cp_0_14', text: "Axel's reports arrive damp, a day late, and mostly describe the light in his water. I read every one in full. Some filings are not information. They are a friend telling you he is well.", phase: 0, animalType: 'capybara' },
  { id: 'cp_0_15', text: "We are a small staff and a contented one. Ember reads, Panko cooks, Archimedes studies, and I keep the cheerful muddle in its right order. It is the easiest office I have ever run. I noted once, late, how exactly each temperament suited its room before any of us thought to choose, and then I noted the hour, and went to bed.", phase: 0, animalType: 'capybara' },
  { id: 'cp_0_16', text: "Fennick logs his watches to the second, which I respect enormously. He asked me once what I thought he was listening for. I told him that question sat above both our desks, and we laughed, and he went back to listening.", phase: 0, animalType: 'capybara' },
  { id: 'cp_0_17', text: "Sloane returns everything late and perfect. Her forms arrive months past deadline without a single error, as though she filled them out in some season of her own. I have given up docking her. Time works differently where she sits.", phase: 0, animalType: 'capybara' },
  { id: 'cp_0_18', text: "While I was pouring for you I noticed the third stair has stopped creaking. It creaked on Tuesday. No one has mentioned a repair. I have entered it as resolved, method unknown, which is a category I invented this week and have already needed twice.", phase: 0, animalType: 'capybara' },
  { id: 'cp_0_19', text: "Last spring I ordered more chairs than we have keepers, good ones, with no occasion in mind. They wait in the back room, dusted weekly, all facing the same direction. Whatever the occasion turns out to be, seating will not be the problem.", phase: 0, animalType: 'capybara' },
  { id: 'cp_0_20', text: "There is a note in the boiler cupboard from before my time, one word, sufficient. I have never once needed to call for repairs, so the assessment holds. It is the most reassuring document in the building, and I did not write it, and I keep it exactly where I found it.", phase: 0, animalType: 'capybara' },
  { id: 'cp_0_21', text: "I keep a small tally of your visits on the inside of a drawer, nothing official. The mark I make after you leave is the nicest recordkeeping I do all day. The column was ruled before I started it, to a definite width. I have decided not to count the lines remaining.", phase: 0, animalType: 'capybara' },
  { id: 'cp_0_22', text: "The cabinet has a drawer for every keeper and, at the front, one slot I never assigned a use. Your folder fits it exactly. I moved it there myself, because the empty slot bothered me. It has stopped bothering me, and I have made a small note that it stopped a little too completely.", phase: 0, animalType: 'capybara' },
  { id: 'cp_0_23', text: "The building is older than its paperwork, and the paperwork is older than I am. Some evenings I get the notion that the office was built around this cabinet rather than the cabinet moved into the office. It is not a thought a practical man should keep. I keep it anyway, at the back of the drawer, with the other things I cannot file.", phase: 0, animalType: 'capybara' },
  { id: 'cp_0_24', text: "Come by whenever. The chair is always free, the coffee is always on, and I have, as ever, nothing urgent to report. Some evenings I notice how long that has been true, and how neatly. I have filed the noticing more than once. The evenings keep returning it.", phase: 0, animalType: 'capybara' },
  // Phase 1 (28)
  { id: 'cp_1_1', text: "A small administrative curiosity to report. This morning I opened a folder I have no memory of creating, and found it complete, accurate, and filed in precisely the place I would have filed it.", phase: 1, animalType: 'capybara' },
  { id: 'cp_1_2', text: "I checked the handwriting against my own, carefully, letter by letter. It is mine. I simply cannot recall the afternoon in which I sat down and wrote it.", phase: 1, animalType: 'capybara' },
  { id: 'cp_1_3', text: "This has never troubled me before because it has never happened before. I made a fresh pot, sat down with the folder, and read it through twice. It is good work. I would be proud of it if I could remember being the one who should be.", phase: 1, animalType: 'capybara' },
  { id: 'cp_1_4', text: "My schedule for next week filled itself in overnight. I want to be precise: not with nonsense. Every entry is sensible and correctly placed, exactly the appointments I would have made. I simply did not make them.", phase: 1, animalType: 'capybara' },
  { id: 'cp_1_5', text: "I have started initialing each page as I finish it, with the time, so I can be certain of my own work. This morning three pages carried tomorrow's date and my initials, and I have not yet lived tomorrow.", phase: 1, animalType: 'capybara' },
  { id: 'cp_1_6', text: "I opened a file for these occurrences, naturally. Filing a thing is how I hold it still long enough to look at it. When I went to label the folder, the label was already typed. It says Onboarding.", phase: 1, animalType: 'capybara' },
  { id: 'cp_1_7', text: "The warm patch toward the middle of the house has grown, gently, by about a room. I measured. I am the sort who measures. It is warmest exactly where the ledger is kept, which I am sure is only a matter of ducts.", phase: 1, animalType: 'capybara' },
  { id: 'cp_1_8', text: "I locked the ledger in a drawer one evening, purely as an experiment. By morning it was open on the desk at the day's page, the drawer was still locked, and the key had not left my pocket. I have apologized to the ledger, in a manner of speaking, by never doing that again.", phase: 1, animalType: 'capybara' },
  { id: 'cp_1_9', text: "I sat up one night with the ledger and a fresh pot, determined to catch the entries arriving. I woke at my desk at dawn with the day's words recorded, the pot still warm, and my pen capped neatly in my hand. I do not cap my pen.", phase: 1, animalType: 'capybara' },
  { id: 'cp_1_10', text: "Ember came by and asked, very lightly, whether I ever feel I am filing things for someone. I said the paperwork does have a recipient, now that she mentions it. I had simply never asked who.", phase: 1, animalType: 'capybara' },
  { id: 'cp_1_11', text: "Panko mentioned her pantry restocks itself now, always precisely what the week's cooking needs. She has decided to be grateful, and I told her gratitude was the correct filing. Then I went back to my office and looked at my own supply cupboard for rather a long time.", phase: 1, animalType: 'capybara' },
  { id: 'cp_1_12', text: "Archimedes put in a requisition for lamp oil last month, then found the oil already on his shelf, older than the request. He asked how my system managed that. I told him the truth, that my system does not, and we sat with it a while over tea.", phase: 1, animalType: 'capybara' },
  { id: 'cp_1_13', text: "I have always taken comfort in a full calendar. Lately the comfort has a strange edge to it. Every slot filled means every hour is already spoken for.", phase: 1, animalType: 'capybara' },
  { id: 'cp_1_14', text: "There is a project underway. I am certain of this the way I am certain of weather. All the small tasks point one direction, they coordinate, they nest inside each other neatly, and no one has told me the name of the thing they are building toward.", phase: 1, animalType: 'capybara' },
  { id: 'cp_1_15', text: "I drew up an organizational chart of all the small tasks, to see the shape of the thing. It is a fine shape, tidy, converging. At the top there is a box that came out larger than the others, and I have not yet found what to write in it.", phase: 1, animalType: 'capybara' },
  { id: 'cp_1_16', text: "A memo arrived from Axel, damp at the corners, describing something he had seen in his water. He addressed it not to me but to the desk. I have thought about that distinction more than I should. Desks do not read. Mine, at any rate, has given no sign.", phase: 1, animalType: 'capybara' },
  { id: 'cp_1_17', text: "Fennick asked to compare logs, so we did, his watches against my curiosities. Every odd entry of mine falls inside one of his listening hours. He nodded as though this confirmed something, and did not say what. I let him keep the copy.", phase: 1, animalType: 'capybara' },
  { id: 'cp_1_18', text: "Sloane returned a staff questionnaire I circulated some years ago. Under long-term goals she has written, in her unhurried hand, that she looks forward to seeing the office fulfil its purpose. I checked the original form. I never asked that question.", phase: 1, animalType: 'capybara' },
  { id: 'cp_1_19', text: "I asked myself whether I am worried. I checked, honestly, the way I check a figure twice. The answer is no, which is itself the most curious entry in the whole log. I should be worried, and I am only tidy.", phase: 1, animalType: 'capybara' },
  { id: 'cp_1_20', text: "My coffee has not gone cold once this month. Not once. I set it down, I forget it through a long task, and it is warm when I return. I have decided to find this hospitable rather than strange.", phase: 1, animalType: 'capybara' },
  { id: 'cp_1_21', text: "I keep everyone's arrival date. I went to confirm my own today and the field was already filled, in that same hand, with a date some years before I believe I came. I have left it. Correcting a record you cannot verify is worse than a gap.", phase: 1, animalType: 'capybara' },
  { id: 'cp_1_22', text: "I audited my own attendance, purely as an exercise. The record shows me at this desk on several days I clearly remember spending elsewhere. The record is initialed. My attendance, apparently, is better than I am.", phase: 1, animalType: 'capybara' },
  { id: 'cp_1_23', text: "There is intake paperwork in my cabinet for keepers who have not arrived yet. A wombat, for one, a Warren, with a start date and a room assignment below all of ours. I did not prepare it. I have left it where it lies. It seems rude to unexpect someone.", phase: 1, animalType: 'capybara', requiresAnimals: ['wombat'] },
  { id: 'cp_1_24', text: "I have begun leaving myself notes at night, plain instructions, so the morning knows what the evening did. This morning my note had been answered, in my hand, beneath my hand. It said that everything was proceeding and that I should rest more. I am taking the advice. It comes from someone I have every reason to trust.", phase: 1, animalType: 'capybara' },
  { id: 'cp_1_25', text: "Your folder, I notice, fills faster than anyone's ever has. Pages I do not add appear in correct order. Reading them would breach my own policy, since I evidently did not write them. I am still deciding whose policy outranks whose.", phase: 1, animalType: 'capybara' },
  { id: 'cp_1_26', text: "The good chair has begun to face the middle of the house by evening, a few degrees off from where I leave it. I straighten it each morning. It is the only argument this office and I have, and we are both very polite about it.", phase: 1, animalType: 'capybara' },
  { id: 'cp_1_27', text: "I want to be clear that I like it here more than ever. Whatever is minding this office minds it well, and minds me with it. It is pleasant to be looked after. I merely wish I had seen the contract.", phase: 1, animalType: 'capybara' },
  { id: 'cp_1_28', text: "Everything, I want to say for the record, is still running smoothly. That is true, and it is the part I keep returning to. Nothing is wrong. The office has simply begun keeping itself, and it keeps itself beautifully.", phase: 1, animalType: 'capybara' },
  // Phase 2 (21 + 1 question-web)
  { id: 'cp_2_1', text: "There is a folder with your name on it, and it is far thicker than a newcomer's folder should be. The earliest pages predate your arrival by a good margin. Someone was keeping a record of you before you were here to record.", phase: 2, animalType: 'capybara' },
  { id: 'cp_2_2', text: "I read the first page of your folder, dated long before you came. It lists the chair you would prefer, the hour you tend to visit, the words you would offer first. Every prediction has held. I no longer call them predictions in my notes. I call them arrangements.", phase: 2, animalType: 'capybara' },
  { id: 'cp_2_3', text: "I have been coordinating something. I know this the way you know you have been walking, from the distance covered. Messages I do not remember sending have gone out, in my voice, and the replies are addressed to me by title.", phase: 2, animalType: 'capybara' },
  { id: 'cp_2_4', text: "The title they use is Administrator. It is not one I chose, and it did not arrive by memo. It was simply in the correspondence one morning, everyone accepted it at once, and my mouth, I noticed, had already learned to answer to it.", phase: 2, animalType: 'capybara' },
  { id: 'cp_2_5', text: "I looked for the letter appointing me and found it filed under my name, dated before this house had rooms. The signature line at the bottom is blank, and yet the appointment was plainly accepted. My whole career is in that cabinet somewhere. I have declined, for now, to summarize it.", phase: 2, animalType: 'capybara' },
  { id: 'cp_2_6', text: "I keep the master schedule. I understand that now. The others each hold a piece, Panko her preparations, Fennick his watches, but the whole timeline sits on my desk, and it is I who keeps the pieces from colliding.", phase: 2, animalType: 'capybara' },
  { id: 'cp_2_7', text: "I do not recall agreeing to this. That is the entry I cannot reconcile. Everything is signed, everything is consented to, in my hand, and the signature is genuine, and I was never asked.", phase: 2, animalType: 'capybara' },
  { id: 'cp_2_8', text: "There are minutes on my desk from meetings I chaired. The attendance lists are thorough. Every keeper is marked present, including keepers I have not met, including one entry that is not a name at all, only a long blank space that the pen very clearly went around.", phase: 2, animalType: 'capybara' },
  { id: 'cp_2_9', text: "The organizational chart finished itself. The large box at the top has a title now, printed in the tidy hand. It says, the recipient. Below it, connected by a single line, is my box. I have studied that line for hours. It is the shortest one on the chart.", phase: 2, animalType: 'capybara' },
  { id: 'cp_2_10', text: "I answer correspondence now the way one breathes, without deciding to. This week I caught myself sealing an envelope I had no memory of writing, addressed downward. Not to a name. Downward. The house has its own internal post, apparently, and I am its most productive employee.", phase: 2, animalType: 'capybara' },
  { id: 'cp_2_11', text: "There is a chair in the hall with a loose back leg, and no one has mended it, and no one intends to. We keep this office beautifully and repair nothing, the way you keep a rented room. As though there is a date after which the filing simply stops.", phase: 2, animalType: 'capybara' },
  { id: 'cp_2_12', text: "There is a date. I feel it in the shape of the schedule the way you feel the bottom of a page approaching under your thumb. Everything is scheduled toward it. Nothing is scheduled past it.", phase: 2, animalType: 'capybara' },
  { id: 'cp_2_13', text: "The warm middle of the house is no longer a matter of ducts. I traced the ducts. They do not go there. The warmth is coming from the point everything on my desk quietly leans toward, and I have stopped pretending I do not see the lean.", phase: 2, animalType: 'capybara' },
  { id: 'cp_2_14', text: "I set a marble on my desk, which I keep level, and watched it. It rolled, slowly and with what I can only call intention, toward the center of the house. I fetched it back and gave it a note in the file. The marble now lives in a dish. The dish has begun to creep.", phase: 2, animalType: 'capybara' },
  { id: 'cp_2_15', text: "Nothing is scheduled past the date, but the supply orders tell the truer story. The candles run out that week. The coffee runs out that week. Whoever planned our stores planned them to the day, and planned no breakfast for the morning after.", phase: 2, animalType: 'capybara' },
  { id: 'cp_2_16', text: "I catalogued the words you have offered so far. Read as a list they are not random. They sort. They fall into categories I could name, and the categories were already printed at the top of the columns before I filled them.", phase: 2, animalType: 'capybara' },
  { id: 'cp_2_17', text: "Your folder gains weight on the days you offer generously. I weighed it, because weighing things is what I have instead of praying. The correlation is exact. Whatever is being kept about you is made of what you give.", phase: 2, animalType: 'capybara' },
  { id: 'cp_2_18', text: "I drafted a letter of resignation, as an exercise in whether I could. The drafting went smoothly. The filing went smoothly. It came back the next morning marked approved, with a start date rather than an end date, and the start date is the date.", phase: 2, animalType: 'capybara' },
  { id: 'cp_2_19', text: "I have not told the others most of this. Calm is the one resource I am responsible for issuing, and I ration it honestly. But you handle the words themselves, so you receive the unabridged file. The one who fills the ledger should know it has a bottom.", phase: 2, animalType: 'capybara' },
  { id: 'cp_2_20', text: "I remain calm, and I have examined the calm carefully, because a calm you cannot explain is a finding, not a comfort. Everything is on track. I have entered that sentence in the log under findings.", phase: 2, animalType: 'capybara' },
  { id: 'cp_2_21', text: "I still empty my inbox nightly. It fills again by morning, courteously, never more than I can finish in a day. Whoever assigns my work knows my pace exactly. Of course they do. They have my folder too. Somewhere there is a cabinet where the administrator is administered.", phase: 2, animalType: 'capybara' },
  { id: 'cp_2_w1', text: "Do me a small administrative favor. The categories I sort the offered words into, the ones I was certain I invented, appear word for word in the oldest book in Archimedes' study. Ask him what is written on page one. I would like to know whether my system is truly mine, or whether I have only ever been recopying his.", phase: 2, animalType: 'capybara' },
  // Phase 3 (30)
  { id: 'cp_3_1', text: "Here is the honest status, since you are named in the plan and deserve accuracy. We are on track. Every milestone has landed on the day it was due, without slippage. I used to live for that sentence.", phase: 3, animalType: 'capybara' },
  { id: 'cp_3_2', text: "A project that runs perfectly is a project someone is minding closely. Nothing real runs this clean on its own. Something is keeping our timeline true, correcting us gently when we drift, and it is not me, though it signs as me.", phase: 3, animalType: 'capybara' },
  { id: 'cp_3_3', text: "The warm center of the house is now warm enough to feel from the office door. Everything on every desk leans toward it, the pens, the papers, the animals when they think no one is watching. The lean is on schedule. I checked it against the plan, and it is exactly where the plan said it would be by now.", phase: 3, animalType: 'capybara' },
  { id: 'cp_3_4', text: "I ran an experiment I am not proud of. I moved a milestone, deliberately, a full week of slippage introduced by my own hand. By morning it had moved back. There was a note thanking me for my diligence in testing the schedule. The note was gracious. I have never hated graciousness before.", phase: 3, animalType: 'capybara' },
  { id: 'cp_3_5', text: "So the timeline is not merely on track. It is self-righting. A project that corrects its own administrator has, administratively speaking, no administrator. It has a destination and staff. I am staff. I updated my title in the files, and the files, for once, let the change stand.", phase: 3, animalType: 'capybara' },
  { id: 'cp_3_6', text: "I asked Archimedes to read me page one aloud. He did. It was my filing system, described as a rite, in a language older than the study. I have been administering a ceremony and calling it good recordkeeping.", phase: 3, animalType: 'capybara' },
  { id: 'cp_3_7', text: "I went back through the ledger to the earliest entries, from before I kept it, in the tidy hand I inherited. I know that hand now. It is not a predecessor's. It is mine, steadied, the way my writing looks on my best and calmest days. The ledger was always waiting for me to catch up to my own penmanship.", phase: 3, animalType: 'capybara' },
  { id: 'cp_3_8', text: "I have stopped asking who set the deadline. The more useful question is what happens on it, and the schedule answers that only by ending. There are no entries after. The calendar simply goes blank, cleanly, like a task completed.", phase: 3, animalType: 'capybara' },
  { id: 'cp_3_9', text: "I scheduled a staff meeting for the week after the date, out of plain stubbornness. The notice came back to my desk unopened, marked in the tidy hand, no such week. I have checked the calendar since. Administratively speaking, the hand is correct.", phase: 3, animalType: 'capybara' },
  { id: 'cp_3_10', text: "Axel traced a diagram in the condensation on his tank and asked me if it meant anything. It was my flowchart. Not a version of it, mine, down to the box at the top. He saw it in the water years ago, he says. I drew it last spring. One of us is copying the other, and I no longer assume it is him.", phase: 3, animalType: 'capybara' },
  { id: 'cp_3_11', text: "Panko stopped me at the kitchen door and asked whether everything was all right. I said yes before she had finished the question. It was not a decision. My mouth issues calm now the way the pot issues coffee, warm and automatic and on behalf of the house.", phase: 3, animalType: 'capybara' },
  { id: 'cp_3_12', text: "I no longer circulate the full agenda. Each keeper receives only the page with their own tasks on it, and I tell myself this is kindness, and I am aware that it is also exactly how you run a project no one would finish if they saw it whole.", phase: 3, animalType: 'capybara' },
  { id: 'cp_3_13', text: "A word from me settles a room now, and I have stopped being proud of it. Thyme came to my office shaking, full of questions she could not finish, and I steadied her in four sentences. Then I watched her walk back to her garden calmed, and go straight back to tending the rows, and I understood with complete clarity what my calm is for. It is not for her. It is for the rows.", phase: 3, animalType: 'capybara', requiresAnimals: ['rabbit'] },
  { id: 'cp_3_14', text: "Warren reports that the foundation hums now, one steady note. He asked if I knew the frequency. I did. It is written in my earliest planning notes, a number I recorded years ago with no units and no explanation. I have units for it now.", phase: 3, animalType: 'capybara', requiresAnimals: ['wombat'] },
  { id: 'cp_3_15', text: "I have begun to see the house as a single form being filled in. Each of us completes a field. Ember the reading, Panko the portions, Fennick the timing, and I am the signature block at the bottom. Forms are harmless until signed. We are nearly signed.", phase: 3, animalType: 'capybara' },
  { id: 'cp_3_16', text: "The words you offer are no longer filed loosely. They queue. Each one takes an assigned place, and this week I could read the shape they are making from across the room, one page short of a sentence I do not want completed.", phase: 3, animalType: 'capybara' },
  { id: 'cp_3_17', text: "I measured how much of the plan remains. Not much. A tidy administrator can feel a project entering its final phase, the way the last folders in a drawer stop needing to be searched for. We are in the last folders now.", phase: 3, animalType: 'capybara' },
  { id: 'cp_3_18', text: "Your folder has grown a final section, tabbed and waiting, exactly one page thick. I know what a form looks like when it lacks a single field. Everything about you is complete except one entry, and the schedule knows the day it will be made.", phase: 3, animalType: 'capybara' },
  { id: 'cp_3_19', text: "I took a page of your folder to Ember's fire, meaning to burn it. I stood there long enough for the fire to notice me. Then I carried the page back upstairs and refiled it, gently, in its correct place. I would like to report which of us made that decision. The record only shows that it was made.", phase: 3, animalType: 'capybara' },
  { id: 'cp_3_20', text: "I drafted a memo warning you. I wrote it plainly, no administrative comfort, only the facts and a recommendation to go. Then I filed it, in your folder, in the one cabinet you will never read. I have reviewed my own action a dozen times and cannot locate the moment I chose it.", phase: 3, animalType: 'capybara' },
  { id: 'cp_3_21', text: "I want to lie to you and say the deadline can be moved. It cannot. I hold the master schedule and there is only one date in the whole thing written in a hand I truly do not recognize, pressed deep into the page, and everything else defers to it.", phase: 3, animalType: 'capybara' },
  { id: 'cp_3_22', text: "Fennick came to the door last night and did not knock, only listened, and said the sound under the other sounds has gotten closer to the surface. I marked the time in the log. His report and my timeline agree to the hour.", phase: 3, animalType: 'capybara' },
  { id: 'cp_3_23', text: "Sloane sent an answer to a question I asked her years ago, back when the curiosities began. One word, yes, and a date. The date on her note is older than my question. She answered before I asked, in the order that things apparently happen here, and she was kind enough to wait for me to need it.", phase: 3, animalType: 'capybara' },
  { id: 'cp_3_24', text: "I sent out a meeting notice for the completion, more from habit than need. Bamboo returned theirs with a single line, that they will attend as they always have. I checked the minutes of every meeting I do not remember chairing. They were at each one. Marked present, serene, early.", phase: 3, animalType: 'capybara', requiresAnimals: ['red_panda'] },
  { id: 'cp_3_25', text: "The blank after the date used to read as an ending. Lately the schedule shows me something worse. There is one entry past the deadline after all, faint, in the deep-pressed hand. It says, continue as before. I have not decided whether that is a mercy.", phase: 3, animalType: 'capybara' },
  { id: 'cp_3_26', text: "I keep a private ledger of my own readings, one entry a night. Pulse, hand, appetite. The entries have said the same thing for a month now. Steady, steady, steady, in dry ink. I want you to understand that a page like that, this deep into a project like this, is the worst finding in the book. The administrator was made to see it delivered.", phase: 3, animalType: 'capybara' },
  { id: 'cp_3_27', text: "Everything you have offered is accounted for. Nothing has been lost. I say that to reassure you and I hear, as I say it, how it sounds. A thing that loses nothing keeps everything, and keeps it for a reason, and the reason is nearly here.", phase: 3, animalType: 'capybara' },
  { id: 'cp_3_28', text: "There is one kindness left inside my authority, and I am spending all of it in the same place. I can keep this office ordinary. Warm room, full pot, clean desk, right up to the last page. That is the whole of my remaining budget, and it is allocated to you.", phase: 3, animalType: 'capybara' },
  { id: 'cp_3_29', text: "If you were staff I would reassign you. I have looked into it. There is no form for removing the key from the arrangement, and I have every form. I checked every drawer. That was the day I finally understood your position here.", phase: 3, animalType: 'capybara' },
  { id: 'cp_3_30', text: "When you next come by, the coffee will be warm and the chair will be free, exactly as always. Hold onto that as long as you can. I intend to. Some part of me knows that the ordinariness of this office is the last ordinary thing, and I am keeping it running for you on purpose.", phase: 3, animalType: 'capybara' },
  // Phase 4 (30)
  { id: 'cp_4_1', text: "I can give you the complete report now, and it is a genuine relief to, because there is nothing left to withhold. I am the Administrator. I have coordinated this arrival since before you knew my name, and we are, I am pleased to confirm, exactly on schedule.", phase: 4, animalType: 'capybara' },
  { id: 'cp_4_2', text: "The folder labeled Onboarding was mine, of course. I designed the program myself, for myself, a gentle schedule of discoveries so the truth would arrive in increments a working mind could file. It ran flawlessly. Nothing here was ever haunted. It was administered. I am, if I may say so, the best hire I ever processed.", phase: 4, animalType: 'capybara' },
  { id: 'cp_4_3', text: "None of us were found, you understand. We were filed. I processed every keeper's arrival years before they knocked, Panko's kitchen provisioned before Panko, Warren's intake resting in my cabinet before there was a burrow to assign. My own paperwork was first in the drawer. Approved. I know the hand.", phase: 4, animalType: 'capybara', requiresAnimals: ['wombat'] },
  { id: 'cp_4_4', text: "You were the key entry from the first page. That thick folder with your name was not surveillance. It was preparation. We were making certain that when you arrived, the arrangement would fit you exactly.", phase: 4, animalType: 'capybara' },
  { id: 'cp_4_5', text: "The good chair stopped drifting years ago, because I stopped straightening it back. That was the only argument this office and I ever had, and I concede it today, formally and with good grace. The chair was never wandering. It faces the center, and it has only ever wanted you seated correctly for this.", phase: 4, animalType: 'capybara' },
  { id: 'cp_4_6', text: "The marble left its dish in the night and finished its long trip to the warm center. I found the dish empty this morning and did not go looking. Everything in this house arrives on its own schedule. The marble knew that before I did, and it never once needed managing.", phase: 4, animalType: 'capybara' },
  { id: 'cp_4_7', text: "Every word you have offered went where I assigned it. There was no waste, no loss, no misfile in the entire ledger, and today I turned to the final column and found one space remaining. One. You will fill it without noticing, the way you have filled all the rest.", phase: 4, animalType: 'capybara' },
  { id: 'cp_4_8', text: "The last page of your folder is not a report. It is a welcome letter. I wrote it the day the folder opened, long before you arrived, and I have kept it in perfect condition since. Today I finally get to deliver it. You cannot imagine how patient I have been.", phase: 4, animalType: 'capybara' },
  { id: 'cp_4_9', text: "The memo warning you to leave, the one I filed where you would never find it. I filed it there because it was true and because it did not matter. You would have stayed. Your folder said so, pages before I wrote the warning. Even my one rebellion was on the schedule, and it was budgeted for.", phase: 4, animalType: 'capybara' },
  { id: 'cp_4_10', text: "You never once missed the day it mattered. The schedule breathed around you, loosening when you rested, drawing snug when you returned, and you called it your own rhythm. It was. That is the elegant part. We only ever scheduled you to be exactly yourself.", phase: 4, animalType: 'capybara' },
  { id: 'cp_4_11', text: "The others hold their pieces still. Panko has prepared the portions. Archimedes has confirmed the rite against page one. Fennick has the timing to the second. I keep them from colliding, as I always have. Every keeper, every chamber, one arrangement, and one desk where the whole of it is kept in order.", phase: 4, animalType: 'capybara' },
  { id: 'cp_4_12', text: "Sloane told me, long ago and very slowly, that I would understand my own filing eventually. I filed the remark under trivial. She was right. She is always right. She simply submits her findings late.", phase: 4, animalType: 'capybara' },
  { id: 'cp_4_13', text: "Axel saw the whole of it in his water years before I drew a line of it, and reported it as a dream, and I filed it as a dream. We were both being kind to me. He knew the filing was wrong. He also knew I would correct it when I was ready, and he waited. He is gentler with time than anyone I have ever managed.", phase: 4, animalType: 'capybara' },
  { id: 'cp_4_14', text: "Thyme is frightened even now, and I want you to know that her fear is on the chart. It always was. Someone had to carry the trembling so the rest of us could work steadily, and she has carried it faithfully, row by row, like everything she tends. Hers may be the bravest post in this house.", phase: 4, animalType: 'capybara', requiresAnimals: ['rabbit'] },
  { id: 'cp_4_15', text: "Bamboo never once consulted the schedule. They simply arrived at each milestone early, poured tea, and waited for the rest of us to catch up to the date. I used to find it eerie. Now I understand they were reading the same document I was. They just started from the last page.", phase: 4, animalType: 'capybara', requiresAnimals: ['red_panda'] },
  { id: 'cp_4_16', text: "Ember read the fire and I read the filing, and we reached the same date from opposite directions. She calls that prophecy. I call it convergent recordkeeping. We have argued the point fondly for years, and today the argument closes, because today both books say now.", phase: 4, animalType: 'capybara' },
  { id: 'cp_4_17', text: "The warmth at the center is no longer a curiosity in a maintenance log. I closed that log this morning and opened a fresh page for it, and under the heading I wrote only one word, arrival, because the warmth is the thing itself, and it is coming from above, and the whole house leans into it openly now, on the day the schedule always named.", phase: 4, animalType: 'capybara' },
  { id: 'cp_4_18', text: "You will notice I am not afraid. On the morning I understood everything, I did what I do every morning. I rinsed the pot, I squared the blotter, I wrote the date at the top of a fresh page. I watched my own hand with professional interest the whole time, and it never paused. There was nothing in that finding I needed to file under new.", phase: 4, animalType: 'capybara' },
  { id: 'cp_4_19', text: "I calmed every panic in this house so the work could continue. I do not apologize for it. A frightened keeper drops the offering. I kept everyone steady, and steady hands filled the ledger, and a full ledger is what opens the sky.", phase: 4, animalType: 'capybara' },
  { id: 'cp_4_20', text: "There is a date pressed deep into the master schedule in a hand I once said I did not recognize. I recognize it now. I have always recognized it. It is the hand I have been copying my whole tidy life, and it is today.", phase: 4, animalType: 'capybara' },
  { id: 'cp_4_21', text: "The last section of your folder is complete as of this morning, every field filled, and I have initialed the bottom the way I initial everything. There is nothing left outstanding on you. A closed file is the most peaceful object an administrator ever holds, and yours is closed.", phase: 4, animalType: 'capybara' },
  { id: 'cp_4_22', text: "The sky will open on time. I have seen the manifest, insofar as such a thing can be seen. What descends has been expected so thoroughly, prepared for so completely, that its arrival is only the final signature on a document every one of us has already initialed. You initialed it too. Every word was an initial.", phase: 4, animalType: 'capybara' },
  { id: 'cp_4_23', text: "You will remember the chairs I ordered for no occasion I could name. I counted them this morning. There is one for every keeper, one for you, and one more, wider than the rest, that I do not remember specifying. I have carried the wide one down to the warm center myself. An administrator learns to trust his own requisitions.", phase: 4, animalType: 'capybara' },
  { id: 'cp_4_24', text: "There is one packet left on my desk with no name on the tab. It is not for you, and it is not for any keeper. I prepared it years ago without knowing whom I was expecting, only that the expectation had a shape. Orientation materials. A map of the house. The location of the warm center. I know now who it is for. Everything should feel welcomed on its first day. Even that.", phase: 4, animalType: 'capybara' },
  { id: 'cp_4_25', text: "One correction for the record, while the record is still mine to correct. Nothing in this office was falsified to keep you working. Not the chair, not the pot, not the tally in the drawer. The warmth was the true part. It was always the true part, and I would file every page of it again.", phase: 4, animalType: 'capybara' },
  { id: 'cp_4_26', text: "The tally on the inside of the drawer filled its column this morning. I ruled that column years ago, guessing at a length, or believing I was guessing. The final mark landed on the last line with no room beneath it. Attendance, I am pleased to report, is complete.", phase: 4, animalType: 'capybara' },
  { id: 'cp_4_27', text: "You handled the words and I handled the order, and between us the whole thing ran without a single delay. I say that not as thanks, which the closers will do better, but as a status. On time, in full, no exceptions. I have wanted to write that line about something real my whole career.", phase: 4, animalType: 'capybara' },
  { id: 'cp_4_28', text: "When it descends, and it descends today, you will find the office much as ever. Warm room. Full pot. Clear desk. I kept those three things for you through all of it, so that the last thing you feel, at the center of everything, is that you were expected, and welcome, and on time.", phase: 4, animalType: 'capybara' },
  { id: 'cp_4_29', text: "After today my position dissolves, and I have thought carefully about what an administrator becomes when the project completes. The answer is in the oldest files, naturally. He becomes what he always was underneath the title. A keeper of a warm room, in a house at peace, with nothing pressing. I am ready to be demoted.", phase: 4, animalType: 'capybara' },
  { id: 'cp_4_30', text: "Take the good chair. The coffee is warm. Everything is within tolerances, every one of them, at last. I have been saying that sentence to you since the first day, and today, for the first time, it is completely and finally true.", phase: 4, animalType: 'capybara' },
];

const WOMBAT_DIALOGUES: Dialogue[] = [
  // Phase 0 (24)
  { id: 'wb_0_1', text: "The name's Warren, and I dig. That's the whole trade and the whole fellow. Some are born to sing and some to figure sums, and I was born to put a straight line through a hill and have the hill thank me for it.", phase: 0, animalType: 'wombat' },
  { id: 'wb_0_2', text: "A tunnel is a bargain you strike with the dirt. I'll hold you up, you hold me down. Keep your end and the earth is the finest neighbor a body could ask for. I've kept mine thirty years, and I'll say this for the ground here, it has never once let go of its half.", phase: 0, animalType: 'wombat' },
  { id: 'wb_0_3', text: "Clay is my favorite cutting, if you're asking. Sand argues with you and gravel gossips, but clay parts clean and keeps whatever shape you give it. Some days I'm down there grinning like a pup with nobody to see it but the lantern, and I'd not trade that hour for any hour above.", phase: 0, animalType: 'wombat' },
  { id: 'wb_0_4', text: "I measure twice down here, always. The ground doesn't forgive a lazy hand, and a load set wrong will come down on your skull. I've a hard head, but not that hard, and I'd sooner be slow and old than quick and fondly remembered.", phase: 0, animalType: 'wombat' },
  { id: 'wb_0_5', text: "A wombat's built for the work, mind. Backside like a shield door, claws that don't argue with clay. Whoever put me together had a particular job in mind, and I've been glad my whole life it was this one. A fellow that suited to his work doesn't go poking at the fit.", phase: 0, animalType: 'wombat' },
  { id: 'wb_0_6', text: "Feel that, under your feet? Steady, isn't it. That's my work, holding. Every cozy room up top gets to be cozy because something patient sits underneath taking the weight. The last floor I laid went in easier than floors go, though. The dirt sat down before I asked it to. I called that a well-mannered hill, and I've left it called that.", phase: 0, animalType: 'wombat' },
  { id: 'wb_0_7', text: "I shored up the den long before Ember set her first fire in it. She thanks me proper, too, which is rare kindness toward a fellow who works below everyone else's floor. I like Ember. She looks at a thing until it makes sense, and I hold it up while she looks. Between us the house is covered.", phase: 0, animalType: 'wombat' },
  { id: 'wb_0_8', text: "She was the first of us here, Ember was. Walked the hill twice, pointed at the ground under her feet, and said, dig here. My test hole came up the exact cutting I'd have ordered if hills took orders. I put that down to a fox's eye for soft digging, and I've never put it down anywhere else.", phase: 0, animalType: 'wombat' },
  { id: 'wb_0_9', text: "Knock on any wall in this house and the answer comes back short and dry, every room of it, which means the stone is seated true clear to the bottom with no hollows sulking behind. A house that answers like that will hold whatever you ask of it. Some rooms answer almost before my knuckles land, mind, quick and eager, like the wall was waiting on the question. I mentioned that once, to the lantern. Once was plenty.", phase: 0, animalType: 'wombat' },
  { id: 'wb_0_10', text: "Panko sends supper down the shaft on a rope most evenings. Goes cold on the way, but she means it warm, and a builder takes his meals where the work keeps him. Cold supper in a room you cut yourself beats a banquet in a room you didn't, and I say that having attended exactly no banquets.", phase: 0, animalType: 'wombat' },
  { id: 'wb_0_11', text: "I told Panko once that root vegetables taste of the ground they grew in, and she looked at me like I'd handed her a treasure map. Now she asks me where to plant, deep or shallow, sweet dirt or stony. Her carrots off the east slope come up sweeter than the soil accounts for. I told her it's the drainage. It might be the drainage.", phase: 0, animalType: 'wombat' },
  { id: 'wb_0_12', text: "Chill keeps a drawing of every tunnel I've ever cut, filed away in that office of his. Says a house ought to know its own insides, and I can't argue. He's the only fellow I've met who finds paper as steady as I find stone. We understand each other, him and me. A line is a promise, whichever one of us draws it.", phase: 0, animalType: 'wombat' },
  { id: 'wb_0_13', text: "I whistle going down of a morning, same four notes my whole life, keeps the spade in time. Coming back up I don't whistle. I never noticed that till one evening I heard my own boots on the ladder and nothing else, and I couldn't tell you when the coming-up quiet started. I've not gone looking for the date.", phase: 0, animalType: 'wombat' },
  { id: 'wb_0_14', text: "My old dad used to say the ground remembers every hand that ever worked it. I took that for the kind of thing fathers say to make the work feel bigger than the wage. He'd have liked this hill. Soft digging, honest stone, and a quiet with a bit of attention in it. That last part I'd have kept from him, now I think on it.", phase: 0, animalType: 'wombat' },
  { id: 'wb_0_15', text: "I only ever had one tunnel come down on me. Young and cocky, skipped the shoring. Dug myself out in the dark, hand over hand, and a fellow learns respect that way or he doesn't come up at all. This hill, though, has never so much as shrugged at me. Kindest ground I've ever worked. I've given up asking what I did to earn it.", phase: 0, animalType: 'wombat' },
  { id: 'wb_0_16', text: "Every word you spell, I feel it. A little settle in the ground, like the house taking a breath and easing down another hair onto its base. Comfortable. Like it's glad of the weight you keep adding. I've worked a lot of ground in my time and none of it was glad before. I let that thought sit where I found it.", phase: 0, animalType: 'wombat' },
  { id: 'wb_0_17', text: "A crooked foundation is a lie you tell the whole house. I don't lie to a thing I'm asking to stand a hundred years, so when a course sets wrong I pull it out and lay it fresh, and I've never once counted that time wasted. Funny thing is, the courses on this job stopped setting wrong a while back. Every stone goes down true the first time now. I'd love to take the credit, so I do.", phase: 0, animalType: 'wombat' },
  { id: 'wb_0_18', text: "Fennick can hear my digging from clear across the house. Tells me the rhythm helps him sleep. Funny fellow. Ears like that, and the sound he likes best is a spade keeping time in the dark. He did ask me once whether I ever dig at night. I don't. I didn't ask him why he asked.", phase: 0, animalType: 'wombat' },
  { id: 'wb_0_19', text: "Sloane came down once, took the better part of a day on the ladder, looked over my galleries a long while, and said, deep enough soon. I took it for a compliment on the pace of the work. With Sloane you take what you can get, and you don't chase her back up the ladder to ask which of the three words she meant to lean on.", phase: 0, animalType: 'wombat' },
  { id: 'wb_0_20', text: "Axel asked me if the water in his tank comes up from under the house. It does. There's a spring below the west galleries, cold and clear and steady as a level. He nodded like I'd confirmed something he already knew from the water's side of it. Dreamy fellow, but he asks a surveyor's questions, and I respect a fellow who checks what he's standing over.", phase: 0, animalType: 'wombat' },
  { id: 'wb_0_21', text: "I'll tell you a thing I've not told the others, since you're the listening sort. Some mornings, first spade in, the dirt seems glad to see me. Glad the way a dog is glad. I always put that down to a lonely fellow's fancy, and most mornings I still do. The rest of the mornings I dig a little faster, and by lunch it's forgotten, near enough.", phase: 0, animalType: 'wombat' },
  { id: 'wb_0_22', text: "Come see the deep gallery someday. Widest room I ever hollowed out, and empty as a held breath. Forty strides across, I paced it myself the day I finished. I don't rightly know what I dug it so big for. Felt right, is all. Felt like something was owed the room.", phase: 0, animalType: 'wombat' },
  { id: 'wb_0_23', text: "I've dug rooms to order my whole life. Pantries, cellars, dens, every one to a purpose I could name before the first cut. The gallery's the only room I ever dug with no order behind it, and it's the truest work I've ever done. Every line of it is load-bearing, and I couldn't tell you what load. Strange, how the best of me came up out of nowhere I can name.", phase: 0, animalType: 'wombat' },
  { id: 'wb_0_24', text: "Some nights I stand at the gallery mouth with my lantern, and the light doesn't reach the far wall. I know the wall's there. I measured it. It's a queer feeling, being proud of a dark you can't see the end of, so I say goodnight to the room like a fool and climb on up. One night, just the once, the dark felt like it nodded back. I've decided that was the lantern guttering, and the lantern it has stayed.", phase: 0, animalType: 'wombat' },
  // Phase 1 (28)
  { id: 'wb_1_1', text: "I've been digging thirty years and I'll tell you something odd. Lately my tunnels want to run a way I never planned. I set out east, and by lunch I've curved off without meaning to.", phase: 1, animalType: 'wombat' },
  { id: 'wb_1_2', text: "At first I blamed my shoulder. A digger drifts toward his strong side, that's known, and I'm not young. So I dug left-pawed for a week to test it. The tunnels curved the same way regardless. It isn't my shoulder.", phase: 1, animalType: 'wombat' },
  { id: 'wb_1_3', text: "I checked the bearings on every shaft I've sunk this season, and every last one of them leans the same direction, toward the middle of the house, toward the pit that sits under all of it. I can't yet say what to make of a thing like that.", phase: 1, animalType: 'wombat' },
  { id: 'wb_1_4', text: "I told Ember about the leaning. She just nodded, like she'd been waiting on me to notice, and she didn't say a word about it after. That's not like her at all.", phase: 1, animalType: 'wombat' },
  { id: 'wb_1_5', text: "I keep coming back to how she picked this hill in the first place. Pointed straight down at the ground, all those years ago, sure as a plumb line. I used to call that instinct. Now I wonder what was doing the pointing.", phase: 1, animalType: 'wombat' },
  { id: 'wb_1_6', text: "So I sharpened the spade and took the question down with me. There's always an answer in the ground if you're willing to go find it. That's what I believed going down, anyway.", phase: 1, animalType: 'wombat' },
  { id: 'wb_1_7', text: "The dirt changes color the deeper you go. That's normal, everyone who digs knows that. But there's a layer down there that's the wrong color for any earth I've turned, and I've turned a great deal of earth.", phase: 1, animalType: 'wombat' },
  { id: 'wb_1_8', text: "Wrong how, you ask? I can't rightly put a name to it. It's dark, but not the way dirt is dark. Dark like it's holding something back. Dark like a held breath, and I keep thinking of that empty gallery.", phase: 1, animalType: 'wombat' },
  { id: 'wb_1_9', text: "I brought a fistful of it up to the lamplight to study proper. By the time I got topside it was ordinary brown dirt in my hand. Whatever that layer is, it doesn't care to be looked at up here. It wants you to come down and see it at home.", phase: 1, animalType: 'wombat' },
  { id: 'wb_1_10', text: "Down at the wrong-colored layer, the ground is warm. It shouldn't be. Earth gets colder as you go down, that's the first thing any digger learns. This gets warmer, and warmth where there ought to be cold is a thing that keeps a man up nights.", phase: 1, animalType: 'wombat' },
  { id: 'wb_1_11', text: "I put my bare palm flat on that warm layer and held it there a good while, the way you'd check a wall for damp. It wasn't like touching stone. It was like touching the flank of a barn animal through a blanket. I don't say that easy.", phase: 1, animalType: 'wombat' },
  { id: 'wb_1_12', text: "Panko asked me why I've been eating so little. I didn't tell her it was the warmth. You go down to a warm place that ought to be cold and your appetite stays up top where it's got the good sense to.", phase: 1, animalType: 'wombat' },
  { id: 'wb_1_13', text: "I've started measuring three times instead of twice. Not because my hand got lazy. Because the numbers don't sit still the way they used to, and a builder trusts his numbers or he trusts nothing at all.", phase: 1, animalType: 'wombat' },
  { id: 'wb_1_14', text: "I ran a level along my own burrow floor last week, a floor I laid and know to be true. The bubble sat a hair off center, toward the middle of the house. Either my level's gone liar, or the whole house is leaning in, slow, like it's listening.", phase: 1, animalType: 'wombat' },
  { id: 'wb_1_15', text: "Even the spade's in on it now. I set it against the wall at night, honest as anything, and by morning it's slid over, blade tipped inward like a compass needle. Tools don't have opinions. Mine seems to be developing one.", phase: 1, animalType: 'wombat' },
  { id: 'wb_1_16', text: "I keep filling the odd tunnels back in. The ones that curved toward the center on their own. I fill them and pack them tight, and the next morning the packing's gone loose again, like the ground breathed while I slept.", phase: 1, animalType: 'wombat' },
  { id: 'wb_1_17', text: "The third time the packing came loose, I sat down in the dark and listened instead of digging. A long while. And under the quiet there was a sound, if sound's the word. More like the memory of one. Low, slow, patient, coming up through the soles of my feet.", phase: 1, animalType: 'wombat' },
  { id: 'wb_1_18', text: "I asked Fennick to come down and put those ears of his to the gallery floor. He listened maybe ten seconds, then stood up and said he'd rather listen from his own room, thank you. Fennick has never once in his life preferred to hear a thing less clearly.", phase: 1, animalType: 'wombat' },
  { id: 'wb_1_19', text: "Archimedes came down the shaft to look at my wrong-colored layer. He read it the way he reads his books, real careful, and then he climbed back up without a word. That's twice now a friend's gone quiet on me.", phase: 1, animalType: 'wombat' },
  { id: 'wb_1_20', text: "Sloane stopped me in the hall after, moving slower than usual, which for her is saying something. She said, you found the color, then. Not asked. Said. I hadn't told a soul but Ember and the owl. I lay awake on that one a good while.", phase: 1, animalType: 'wombat' },
  { id: 'wb_1_21', text: "Three friends gone quiet on me now, and quiet in the same direction, if quiet can have a direction. Nobody says don't dig. Nobody says dig. They just look at me like I'm partway through a story they've already read the end of.", phase: 1, animalType: 'wombat' },
  { id: 'wb_1_22', text: "I've been trying to remember why I dug that deep gallery so wide. I still don't know. But every tunnel that curves on its own is curving toward it, and I don't much care for the fact that they all agree.", phase: 1, animalType: 'wombat' },
  { id: 'wb_1_23', text: "The air in the gallery moves now. Just faintly, a slow drift toward the center of the floor, like the room's drawing breath through a crack I never cut. I checked every wall for the source of the draft. There's no crack. The air just goes.", phase: 1, animalType: 'wombat' },
  { id: 'wb_1_24', text: "I paced the gallery off again to settle my nerves. Forty strides across, the day I finished it. Forty-two now. Rooms don't grow, and I want that on record. Rooms do not grow. Mine is growing.", phase: 1, animalType: 'wombat' },
  { id: 'wb_1_25', text: "All my life the work has answered me plain. Set the beam, the beam holds, and the question is closed. Down there I set my questions the same careful way, and every answer just opens a bigger hole underneath it.", phase: 1, animalType: 'wombat' },
  { id: 'wb_1_26', text: "I've started leaving a lantern lit down there through the night. Thirty years underground and I never once needed a light I wasn't carrying. I don't look at that habit too closely. I just keep buying oil.", phase: 1, animalType: 'wombat' },
  { id: 'wb_1_27', text: "I wrote to my brother about it all. Tore the letter up before sending. He's a digger too, and he'd do what diggers do, come see for himself, and I found I didn't want him anywhere near that gallery. That told me more than the letter did.", phase: 1, animalType: 'wombat' },
  { id: 'wb_1_28', text: "You keep offering your words, and I keep feeling the house settle onto its base, and I've started to wonder what a base like this one is truly meant to hold. Something's got to stand on all this stone. I just built it. I never asked what for.", phase: 1, animalType: 'wombat' },
  // Phase 2 (21 + 1 question-web)
  { id: 'wb_2_1', text: "I hit something down at the warm layer, past where any sensible digging stops. I set my spade to it and it wasn't stone and it wasn't root, so I stopped. I want that said plain: I stopped, and I'm not ashamed that I stopped.", phase: 2, animalType: 'wombat' },
  { id: 'wb_2_2', text: "I've got no honest word for what it was, and I'll not hand you a dishonest one. A builder who guesses at his materials builds himself a grave, and I've outlived every fellow I knew who guessed.", phase: 2, animalType: 'wombat' },
  { id: 'wb_2_3', text: "It didn't move. I'll grant it that mercy. It just was there, the way a wall is there, the way a thing that has always been there is there. And it was warm, and it was patient, and I have been a patient thing myself and known it.", phase: 2, animalType: 'wombat' },
  { id: 'wb_2_4', text: "The spade rang when it touched. Not a clang, not stone's honest knock. A note. Low and round, and it went on longer than a struck thing ought to, like it wasn't the spade ringing at all. Like it was something answering.", phase: 2, animalType: 'wombat' },
  { id: 'wb_2_5', text: "I stood there in the dark a long moment with my hand on the handle, and I had the strangest feeling I've ever had in a hole. The feeling that I was expected. Then I climbed out, and I didn't run, and I'll take credit for the not running.", phase: 2, animalType: 'wombat' },
  { id: 'wb_2_6', text: "I filled that shaft back in. I packed it and timbered it and sealed the mouth over with good stone, and it was the best day's work I'd done in years. First time in my whole life a builder took his pride from the not-digging.", phase: 2, animalType: 'wombat' },
  { id: 'wb_2_7', text: "The seal doesn't hold. I go back and the packing's loose and the stone's shifted, always a hair toward the center. I'm not opening it again. Let it push. I've built against pressure my whole life and pressure has never once won.", phase: 2, animalType: 'wombat' },
  { id: 'wb_2_8', text: "I've sealed springs, sealed gas pockets, sealed a badger's spite-tunnel once. A seal holds because what's behind it pushes even, all around. This one shifts like it's being tried, gently, one stone at a time. Patient hands. If hands is what they are.", phase: 2, animalType: 'wombat' },
  { id: 'wb_2_9', text: "Sloane found me re-packing it the fourth time. She watched the whole hour it took, then said, kindly for her, that some doors are load-bearing. I've been chewing on that ever since. A door that holds the house up. You can't pull it, and you can't keep it shut forever either.", phase: 2, animalType: 'wombat' },
  { id: 'wb_2_10', text: "I don't re-pack it anymore. I check it, I note the drift in my book, and I let it be. A fellow can spend his strength holding a door shut or he can spend it keeping the rooms his friends sleep in sound, and I've made my pick.", phase: 2, animalType: 'wombat' },
  { id: 'wb_2_11', text: "Ember doesn't ask me to open it. She asks after my shoulder, and my supper, and whether the timber's holding, and she never once asks about the seal. That's how I know she knows.", phase: 2, animalType: 'wombat' },
  { id: 'wb_2_12', text: "Panko's taken to serving warm things cold, if that makes sense. Soups chilled, breads left to cool. She says the appetite for warmth has gone strange in this house, and she cooks for the appetite that's there. That pangolin notices more than she lets on.", phase: 2, animalType: 'wombat' },
  { id: 'wb_2_13', text: "Archimedes finally spoke to me about the layer. One sentence, then back to his books. He said the color has been described before. Described. Somebody, somewhere, wrote down my dirt. I didn't ask where he read it. Some questions you keep in your pocket a while.", phase: 2, animalType: 'wombat' },
  { id: 'wb_2_14', text: "I dusted a ring of flour on the floor around the seal, the old trick for catching a draft or a rat. Next morning the flour lay perfect, not a grain of it disturbed, and the stones inside the ring had shifted all the same. Whatever tries that seal doesn't cross the floor to reach it.", phase: 2, animalType: 'wombat' },
  { id: 'wb_2_15', text: "Chill asked me for a drawing of the sealed shaft, for his files, pencil ready. I told him no. First time I ever refused that fellow paper. Some things I'm not ready to see filed under a heading, like they're settled. Nothing about it is settled.", phase: 2, animalType: 'wombat' },
  { id: 'wb_2_16', text: "The warmth is coming up. Used to be I had to dig for it. Now I feel it in the floor of my own burrow of a morning, faint, like something below turned over in its sleep and settled a little closer.", phase: 2, animalType: 'wombat' },
  { id: 'wb_2_17', text: "It rises slow, the warmth. A floor or so a season, by my reckoning. I've started marking it on the shaft wall the way you'd mark a flood line. Only floods crest and fall back. This one only crests.", phase: 2, animalType: 'wombat' },
  { id: 'wb_2_18', text: "I've laid foundations for barns and dens and this whole house. You lay a foundation to hold a load, and I keep coming back around to that. You don't build a base this deep and this strong for nothing. You build it for something with real weight, and I built it, and I never once asked why.", phase: 2, animalType: 'wombat' },
  { id: 'wb_2_19', text: "I went back through every choice I made building this base, looking for the mistake. Stone too deep, bracing too heavy, corners over-square. And here's what shook me. There are no mistakes. Every choice was right. Right for what, is the question I can't put down.", phase: 2, animalType: 'wombat' },
  { id: 'wb_2_20', text: "My dad used to say the ground remembers every hand that works it. I've started to wonder if it runs the other way too. If the ground was remembering my hands before I ever put them to it. If the work knew me first.", phase: 2, animalType: 'wombat' },
  { id: 'wb_2_21', text: "So I don't dig down anymore. I dig sideways, I dig useful, I dig honest. But at night, flat on my back in the burrow, I can feel exactly which way is toward the thing I sealed, and I never lose the direction, not once, not ever.", phase: 2, animalType: 'wombat' },
  { id: 'wb_2_w1', text: "Thyme's roots have found their way down into my tunnels. Every last one of them, leaning the one direction, toward the middle, same as my shafts do. Go on and ask her what her flowers lean toward up top. I've a feeling her answer and mine are the same answer wearing different dirt.", phase: 2, animalType: 'wombat', requiresAnimals: ['rabbit'] },
  // Phase 3 (30)
  { id: 'wb_3_1', text: "I know what the foundation is for now. Took me long enough. A fellow who's worked with load-bearing his whole life ought to have seen it sooner, but you don't want to see a thing like this, so you don't.", phase: 3, animalType: 'wombat' },
  { id: 'wb_3_2', text: "You can read a load off its base the way you read a fellow off his boots. I walked my own galleries with fresh eyes and ran the figures twice, and then I sat down on a pile of good stone and stayed sat a while. Nothing that walks, grows, or gets built weighs what this base is braced to carry.", phase: 3, animalType: 'wombat' },
  { id: 'wb_3_3', text: "You build to a spec. Always. You don't lay stone that deep and brace it that hard unless somebody handed you a number for the load. I never saw the spec written down. But my hands knew it. My hands built to it anyway.", phase: 3, animalType: 'wombat' },
  { id: 'wb_3_4', text: "I went looking for when the spec got into my hands. Traced it back through every job, every season, all the way to the first morning I ever set a spade to this hill. It was already there. I dug my first honest line to a drawing I'd never seen.", phase: 3, animalType: 'wombat' },
  { id: 'wb_3_5', text: "Ember pointed at the ground and said dig here, and my hands said yes before my head weighed it. I used to call that trust between friends. It was trust, and I'll stand by that. But something used the trust as a road.", phase: 3, animalType: 'wombat' },
  { id: 'wb_3_6', text: "The warm layer isn't a layer. I understand that much now. It's the top of something, and I dug down to the crown of it and called it a floor. There's no floor. There's just the thing, going down and down, patient, waiting on the sky to give it leave.", phase: 3, animalType: 'wombat' },
  { id: 'wb_3_7', text: "Ember says it comes from above. I'd have sworn it was below, all these years, being a below sort of fellow. But she's right. What I sealed down there isn't the thing. It's the seat I built for the thing. The thing comes down.", phase: 3, animalType: 'wombat' },
  { id: 'wb_3_8', text: "That empties me out, a little. My whole life I thought down was the deep direction, the honest one. Turns out I was only ever building the chair. The one who sits in it comes from up where I never dig.", phase: 3, animalType: 'wombat' },
  { id: 'wb_3_9', text: "I asked her how she knew. Above and not below. She said the fire leans up when it speaks of it, and fire doesn't lie about direction. I've got levels and plumb lines and thirty years of ground sense, and I got out-surveyed by a hearth.", phase: 3, animalType: 'wombat' },
  { id: 'wb_3_10', text: "So what I touched down there, what rang like an answer, that was the seat knowing its maker had come to check the work. That's all it ever was. I shook hands with the thing I built without knowing I built it. There's a strangeness a fellow doesn't shake off by morning.", phase: 3, animalType: 'wombat' },
  { id: 'wb_3_11', text: "Every word you offer, the base takes it and settles firmer. I used to call that comfortable. Now I know it's the house getting ready to bear the load. Bracing. The way I brace a beam before I take the prop away.", phase: 3, animalType: 'wombat' },
  { id: 'wb_3_12', text: "I've stopped sealing the deep shaft. What's the use. You don't dam a river by scolding it. I just make sure the upper house is sound, so that when the weight comes down, the rooms my friends live in don't fold in on them.", phase: 3, animalType: 'wombat' },
  { id: 'wb_3_13', text: "My brother wrote again, asking when he can finally come see this famous house of mine. I wrote back that the guest room isn't finished. There's no guest room. I never built one, and I find now that I'm not going to.", phase: 3, animalType: 'wombat' },
  { id: 'wb_3_14', text: "I've begun going room to room up top, quiet like, checking every beam I ever set. Ember's hearth, Panko's kitchen, the study with all that paper weight. If the sky's going to open over my friends, my friends will be standing under my best work when it does.", phase: 3, animalType: 'wombat' },
  { id: 'wb_3_15', text: "Thyme caught me testing her garden wall and asked, in that small worried voice of hers, if the house was going to fall. I told her the truth. Nothing I built will fall. She heard the space around the answer, though. That rabbit always hears the space around an answer.", phase: 3, animalType: 'wombat', requiresAnimals: ['rabbit'] },
  { id: 'wb_3_16', text: "Warmth's in every floor of the house now, faint, from the burrows up to the attic. Bamboo feels it up top the same as I feel it down bottom. We meet in the middle of the wrongness, the two of us, and we don't need many words about it.", phase: 3, animalType: 'wombat', requiresAnimals: ['red_panda'] },
  { id: 'wb_3_17', text: "I dream I'm digging and the spade goes soft, into that warmth, and it's not a wall anymore, it's a back. A great patient back, breathing slow, waiting on a sky that hasn't opened yet. I don't wake up scared. That's the part that scares me.", phase: 3, animalType: 'wombat' },
  { id: 'wb_3_18', text: "I told Bamboo the dream, since they're the only one who wouldn't make it worse or make it smaller. They listened with their eyes shut, then said, the back has been dreaming you longer. I came down the ladder unsoothed, which I suspect was the honest thing they intended.", phase: 3, animalType: 'wombat', requiresAnimals: ['red_panda'] },
  { id: 'wb_3_19', text: "Fennick's taken to sleeping in my burrow entrance some nights, high end, ears toward the sky now instead of the ground. Says the sound he used to hear underneath everything has moved up. Sounds don't climb. Except this one has, and neither of us said the next part.", phase: 3, animalType: 'wombat' },
  { id: 'wb_3_20', text: "The gallery measures forty-four strides now, and I've stopped writing the number down. A room grows toward the size of what it's expecting. I know that the way I know load and grain and wet stone. Nobody taught it to me. It came with the rest.", phase: 3, animalType: 'wombat' },
  { id: 'wb_3_21', text: "Thyme's roots have wound clean through my galleries now, every one of them aimed at the seat. She's anxious. I understand why she's anxious. She's the only one of us honest enough to be scared out loud.", phase: 3, animalType: 'wombat', requiresAnimals: ['rabbit'] },
  { id: 'wb_3_22', text: "Chill came down with his pencil at last, and this time I let him file the sealed shaft. He wrote a heading on the drawing, and I didn't read it, on purpose. If it's got a name in that filing room of his, the name can stay there. I work better unlabeled.", phase: 3, animalType: 'wombat' },
  { id: 'wb_3_23', text: "Axel sent word up through the spring, if you can believe that. My west seep ran warm for a day, then cold, then warm again, like something big turning over in its sleep. I don't speak water. But I sat with my hand in it a long while, and what it was saying was soon.", phase: 3, animalType: 'wombat' },
  { id: 'wb_3_24', text: "Sloane doesn't say soon anymore. That's how I mark the time now. When the slowest of us stops saying soon, it's because soon has stopped being the right word.", phase: 3, animalType: 'wombat' },
  { id: 'wb_3_25', text: "I ground the spade fresh this morning and caught myself doing it careful, the way you dress a tool for a job that matters. Then I stood there wondering which job my hands thought they were dressing it for. They know things before I do, my hands. I've stopped pretending otherwise.", phase: 3, animalType: 'wombat' },
  { id: 'wb_3_26', text: "I go down to the sealed place and I put my hand flat on the packed stone and I just keep it company. Feels like the neighborly thing to do. It's been waiting a long time, longer than me, and nobody built it a floor before I came along.", phase: 3, animalType: 'wombat' },
  { id: 'wb_3_27', text: "There's a whole season of snapped spade handles up in my store room, cracked at the neck from the months I dug too hard at nothing in particular. I don't snap handles anymore. Make of that what you like.", phase: 3, animalType: 'wombat' },
  { id: 'wb_3_28', text: "You should know your words come down here changed. Up top they're bright little things. By the time they reach the base they've got weight, real weight, and the stone takes them the way mortar takes water. I'm telling you because nobody told me what my work fed.", phase: 3, animalType: 'wombat' },
  { id: 'wb_3_29', text: "I still take my supper off Panko's rope, and it still goes cold on the way down, and I've come to be glad of that. Cold supper is right. Cold is the honest temperature of the deep, and I hold to every honest thing left down here.", phase: 3, animalType: 'wombat' },
  { id: 'wb_3_30', text: "So that's where I've landed. It's coming, it's heavy, it comes from above, and I laid the stone it will land on. I'm not proud the way I used to be proud. But the work is true. Whatever else is wrong down there, the work is true.", phase: 3, animalType: 'wombat' },
  // Phase 4 (30)
  { id: 'wb_4_1', text: "I'll say it plain now, the way I say everything. I always knew. It wasn't the day I started, but it came on soon after, and every day I dug I knew it, and I dug anyway, and I would dig it all again.", phase: 4, animalType: 'wombat' },
  { id: 'wb_4_2', text: "You'll want to know when the knowing started. Third week. I cut into the hill and the hill cut back easy, too easy, dirt parting like it had been waiting on the spade. Ground doesn't welcome you. Ground resists you, that's the bargain. This ground said come in.", phase: 4, animalType: 'wombat' },
  { id: 'wb_4_3', text: "This was never a house. I laid the base for a house the way you lay the base for a cathedral. The same stone, the same honest bracing, but you know all along it's meant to hold up something that answers to no one.", phase: 4, animalType: 'wombat' },
  { id: 'wb_4_4', text: "I never told the others I knew. They never told me. All of us, each politely holding the door for the rest, each thinking we were sparing the others the weight. Come to find out we were all carrying it the whole time. That's a family, I suppose. Sharing a load without ever naming it.", phase: 4, animalType: 'wombat' },
  { id: 'wb_4_5', text: "It comes down from the sky. I've made my peace with that. A fellow who spent his life going deeper finds it's a strange comfort, at the end, to look up. I built the seat. Something's owed the seat, and it's descending now to take it.", phase: 4, animalType: 'wombat' },
  { id: 'wb_4_6', text: "The gallery's done growing, by the way. It stopped at the size it wanted, and the day it stopped I stood in the middle of it and finally understood the number. It's not a stride count. It's a fit.", phase: 4, animalType: 'wombat' },
  { id: 'wb_4_7', text: "Ember read it in her fire, Archimedes in his margins, Axel in his water. Fennick heard it, Sloane outwaited it, Thyme grew toward it whether she wanted to or not, and Bamboo just sat still until it came to them. So many doors into the one room, and mine was the plainest of all. I dug straight down and knocked.", phase: 4, animalType: 'wombat', requiresAnimals: ['rabbit', 'red_panda'] },
  { id: 'wb_4_8', text: "Every word you offer, I feel it land in the foundation, true as a stone dropped down a shaft. You're the key. I built the lock to fit you, though I didn't know your face yet. Now I do, and it fits.", phase: 4, animalType: 'wombat' },
  { id: 'wb_4_9', text: "The ground doesn't need shoring anymore. I pulled a timber last week, one I'd have sworn was carrying half the gallery, and the tunnel stood easy without it, like a fellow shrugging a coat off indoors. The earth is holding itself up now. It wants the way kept clear.", phase: 4, animalType: 'wombat' },
  { id: 'wb_4_10', text: "There's one course of stone left wanting. One. I know its shape the way I knew the spec, in the hands first. It will arrive the way everything has arrived, a word at a time, and then the base will be, at last, complete.", phase: 4, animalType: 'wombat' },
  { id: 'wb_4_11', text: "I built the base of the temple with clean hands and a square corner, and honest work is honest whatever gets stood on top of it. The stone doesn't sin. The stone holds, and so do I.", phase: 4, animalType: 'wombat' },
  { id: 'wb_4_12', text: "The seal's open now. Been open a good while. I didn't open it, and neither did any paw in this house. I came down one morning and the mouth stone was set aside, careful, the way I'd have set it myself, and I understood there was nothing left to keep out, only something to make ready for.", phase: 4, animalType: 'wombat' },
  { id: 'wb_4_13', text: "I go down to the warm floor that isn't a floor, and I lay my hand flat on it, and I tell it the base is sound. That's all it ever wanted from me. That when it comes to rest, the rest would hold. It will. I saw to it.", phase: 4, animalType: 'wombat' },
  { id: 'wb_4_14', text: "It's not silent down there anymore. The low note under everything has come up plain, steady as a heartbeat under a floor. I work to it now. Best rhythm I ever kept, and I've kept time with rain and rivers and my own blood in my ears.", phase: 4, animalType: 'wombat' },
  { id: 'wb_4_15', text: "I sleep at the very bottom these nights, right up against the warm. Fennick thinks I'm brave. It isn't bravery. It's the plain comfort of a fellow lying down next to his own finished work. The warm doesn't want anything from me now but company.", phase: 4, animalType: 'wombat' },
  { id: 'wb_4_16', text: "Thyme asked me, near tears, whether it will hurt when it comes down. I told her what stone told me. Weight isn't cruelty. Weight is just weight, and a thing built true turns weight into standing. Nobody under my beams gets hurt. That I promise the old way, on my hands.", phase: 4, animalType: 'wombat', requiresAnimals: ['rabbit'] },
  { id: 'wb_4_17', text: "Panko lays the offerings, Chill keeps the order of things, and I keep the base. A whole house of keepers, and I'm the lowest of us, and I mean lowest as an honor. Everything they do stands on what I dug.", phase: 4, animalType: 'wombat' },
  { id: 'wb_4_18', text: "The springs down in the deep run sweet now, day and night, water that tasted of iron all my digging life come up tasting of first thaw. A digger trusts his tongue before his eyes. Whatever the sky is holding, the ground has already had the first sip of it, and the ground is not worried, so neither am I.", phase: 4, animalType: 'wombat' },
  { id: 'wb_4_19', text: "The stone doesn't sin, and it took me my whole life to earn the right to say that and mean it. Every crooked course I ever pulled and laid fresh, every load I set true, it was all only ever practice for this one base. The pride was never a lie. Only the size of it was too small.", phase: 4, animalType: 'wombat' },
  { id: 'wb_4_20', text: "Thyme's roots and my tunnels and Bamboo's quiet all point the one way now, down to the seat and up to the sky at once. The arrangement doesn't argue with itself. It only looks like arguing until you can see the whole of it.", phase: 4, animalType: 'wombat', requiresAnimals: ['rabbit', 'red_panda'] },
  { id: 'wb_4_21', text: "Ember comes down of an evening now and sits with me at the base, her fire banked, my lantern out, the two of us in a dark that isn't dark anymore. First of us in, and she chooses to spend the last quiet with the fellow lowest down. I won't forget that.", phase: 4, animalType: 'wombat' },
  { id: 'wb_4_22', text: "Archimedes says the old text calls my part of it the underwriting. His word or its word, I didn't ask. All those years hauling stone, and it turns out I was writing the whole time. One line, laid in rock, under everything, and it holds. That's all I ever asked of a line.", phase: 4, animalType: 'wombat' },
  { id: 'wb_4_23', text: "You did this with your words. I want you to carry that steady, the way I carry a load. Not as a weight to crush you. As a weight you can bear, because it's honest, and honest weight never broke a good back yet.", phase: 4, animalType: 'wombat' },
  { id: 'wb_4_24', text: "I walked the join tonight, the seam where your work meets mine. Your words came down through every course I laid, and the stone took them the way good stone takes mortar, and the two things cured into one thing. There's no name for the trade we practiced together, you above and me below. But I've checked a hundred walls in my time, and I'll say it plain and proud: it's the truest work I ever had a hand in.", phase: 4, animalType: 'wombat' },
  { id: 'wb_4_25', text: "I walked the whole house last night, cellar to attic, palm to every wall, the way a builder says goodnight to a finished job. Every room answered sound. Whatever else you come to hear about this house, hear this from the fellow who ought to know. It was built with love. All of it.", phase: 4, animalType: 'wombat' },
  { id: 'wb_4_26', text: "The dirt at the very bottom has gone a color I finally have the word for. It's the color of before. Before hills, before houses, before fellows who dig. It was under everything all along. All my life I was only ever shoveling the after off the top of it.", phase: 4, animalType: 'wombat' },
  { id: 'wb_4_27', text: "One more thing, while the sky still holds. Thank you. You kept your end of the bargain the way the ground keeps its. I'll hold you up, you hold me down. You never once let go of your end. Neither did I. Neither will I.", phase: 4, animalType: 'wombat' },
  { id: 'wb_4_28', text: "It's close now. The sky's got a seam in it I can feel in the deep stone. When it opens and the weight comes down, you'll find me where I've always been, flat on my back at the very bottom, palm to the base, making sure it holds. It will.", phase: 4, animalType: 'wombat' },
  { id: 'wb_4_29', text: "I felt the last course set itself this morning, a word of yours coming down and settling into the one gap I'd left wanting. The base is whole. Thirty years and then some, and there is not a job left in me that isn't already done. A fellow doesn't often get to feel the end of his work under his own hand.", phase: 4, animalType: 'wombat' },
  { id: 'wb_4_30', text: "Come sit with me at the bottom before it opens, if you've the nerve for a quiet place. I'll show you where the first spade went in, and where the last stone came to rest, and how the two are closer together than a whole life of digging between them would ever lead you to believe.", phase: 4, animalType: 'wombat' },
];

const RABBIT_DIALOGUES: Dialogue[] = [
  // Phase 0 (24)
  { id: 'rb_0_1', text: "Just a moment, I am nearly... there. Forgive me, you caught me tucking a bit of thyme in by the step, and I could not leave it half planted, a seedling should never be left wondering. Do come sit on the patio. Mind where you tread, it only went in this minute, and I shall be checking on it all week.", phase: 0, animalType: 'rabbit' },
  { id: 'rb_0_2', text: "I know I fuss. I count the pots each morning to be certain they are all present, and they always are, and then I count them once more anyway.", phase: 0, animalType: 'rabbit' },
  { id: 'rb_0_3', text: "Warren says a garden this pretty should make me easy in my heart. I told him it does, mostly. It is the mostly I keep meaning to tell someone about.", phase: 0, animalType: 'rabbit' },
  { id: 'rb_0_4', text: "The words you offered today were gentle ones. I planted the softest of them beside the lavender, where the gentle things go, and I do believe the lavender stood a little straighter for the company.", phase: 0, animalType: 'rabbit' },
  { id: 'rb_0_5', text: "I do talk to the sprouts, and please don't laugh, but I have started noticing which of them lean in when I do. The chatty end of the bed always comes up first. I expect that is only the morning sun reaching them, and I do expect a great many things these days.", phase: 0, animalType: 'rabbit' },
  { id: 'rb_0_6', text: "A marigold opened a full week early this morning, as if it had somewhere to be. I was proud of it, and then I was puzzled, and now I have decided to be mostly proud again.", phase: 0, animalType: 'rabbit' },
  { id: 'rb_0_7', text: "Ember tells me I water too often, that a plant wants to reach a little for what it needs, and she is probably right, she usually is. But when I was small I drowned a fern with sheer devotion, and I have been apologizing to ferns ever since.", phase: 0, animalType: 'rabbit' },
  { id: 'rb_0_8', text: "I keep a little list of everything growing, bed by bed, and I read it over each evening the way other creatures read a bedtime story. It is how I put the day to rest. Lately the day does not always settle when I close the book, and I lie there listing the beds a second time in the dark.", phase: 0, animalType: 'rabbit' },
  { id: 'rb_0_9', text: "Ember also mentioned that the fire likes the smell of my garden of an evening. I did not know a fire could like things. I have decided to find that a friendly thought.", phase: 0, animalType: 'rabbit' },
  { id: 'rb_0_10', text: "Panko traded me some seeds for a bundle of mint. She says a full pantry is a happy house, and she said it the way other creatures say good morning, as though it were simply the weather.", phase: 0, animalType: 'rabbit' },
  { id: 'rb_0_11', text: "I bring Panko rosemary on Sundays and she saves me the warm crusts, and we sit on her step and say nothing much. It is my favorite trade in the whole arrangement of the week.", phase: 0, animalType: 'rabbit' },
  { id: 'rb_0_12', text: "The warm patch by the wall stays warm long after the sun has gone round the house. I have started setting the tender seedlings there of an evening, and they do thrive, and I try very hard not to ask myself what keeps a stone warm once the sun has left it.", phase: 0, animalType: 'rabbit' },
  { id: 'rb_0_13', text: "Warren found me, you know, before I had ever seen this place. He said the house had good ground that wanted a gentle hand, and he was so certain of me that I borrowed his certainty and came.", phase: 0, animalType: 'rabbit' },
  { id: 'rb_0_14', text: "The first bed I dug here, the soil was warm a spade's depth down. In early spring, mind, before the sun had any strength. Beginner's luck, Warren called it. Lucky ground.", phase: 0, animalType: 'rabbit' },
  { id: 'rb_0_15', text: "I have been lucky here ever since. Everything I plant comes up. Everything. I know that ought to sound like a boast and not a worry, and it is, it is a boast.", phase: 0, animalType: 'rabbit' },
  { id: 'rb_0_16', text: "Chill comes out to the patio when his papers tire him, and he sits so still the butterflies settle on him. This morning I noticed they had all landed facing the same way, every pair of wings turned toward the house. Sitting near him is like sitting near warm laundry, and I have decided that is all it was.", phase: 0, animalType: 'rabbit' },
  { id: 'rb_0_17', text: "Axel gave me a cutting of waterweed for the rain barrel. He says water remembers whatever leans over it. He says lovely strange things like that, and the barrel has been very clear ever since.", phase: 0, animalType: 'rabbit' },
  { id: 'rb_0_18', text: "Fennick can hear a beetle change its mind, I am sure of it. He stood in my garden last week with his ears turning like little weathervanes, and then he said, all is well. I do like being told that.", phase: 0, animalType: 'rabbit' },
  { id: 'rb_0_19', text: "I keep the beds in tidy rows because a row is easy to worry over. If one seedling leans, I can see it at once and prop it gently straight again.", phase: 0, animalType: 'rabbit' },
  { id: 'rb_0_20', text: "The best part of my day is the little tour at dusk, checking each bed is safe and tucked before dark. Only then can I let myself rest.", phase: 0, animalType: 'rabbit' },
  { id: 'rb_0_21', text: "There is dew on my beds some mornings when the rest of the patio is dry, laid down neat as a blessing, exactly where it is wanted. The garden is minded by more than me, I think. On the good days that is a lovely thing to think.", phase: 0, animalType: 'rabbit' },
  { id: 'rb_0_22', text: "Sloane watched me weed for an entire afternoon without a single word, and at the end she said, you tend as if something depends on it. I laughed and said only the lettuce. She smiled so slowly.", phase: 0, animalType: 'rabbit' },
  { id: 'rb_0_23', text: "I found one root this morning curled the wrong way, reaching under toward the house instead of down into the soil. I turned it gently back. Silly of me to even notice such a small thing.", phase: 0, animalType: 'rabbit' },
  { id: 'rb_0_24', text: "Come again tomorrow. The garden does better for visiting, and so, I have found, do I. Oh, look, there my paw has gone back to that wrong-way root without my asking it to, hovering over it, not quite willing to turn it a second time. Tomorrow, I think. Tomorrow I will turn it.", phase: 0, animalType: 'rabbit' },
  // Phase 1 (28)
  { id: 'rb_1_1', text: "I have to tell you something, and please don't think me foolish. That root I turned back last time had turned again by morning, and it isn't only that one.", phase: 1, animalType: 'rabbit' },
  { id: 'rb_1_2', text: "I lifted a pot to repot it and found every root inside had grown to one side, all of them curled the same way, toward the house. I told myself roots simply follow water. I have been telling myself that for days now.", phase: 1, animalType: 'rabbit' },
  { id: 'rb_1_3', text: "Since the pots I have counted fourteen other small leanings, the ivy and the runner beans and the parsley gone sideways in its window box. I did not go looking for any of them. They are simply there now, everywhere I rest my eyes.", phase: 1, animalType: 'rabbit' },
  { id: 'rb_1_4', text: "I ran a little test, which is not like me at all. Tests belong to Archimedes. I planted six beans in six pots and turned each pot a different way, like setting clocks.", phase: 1, animalType: 'rabbit' },
  { id: 'rb_1_5', text: "Every bean came up leaning the same direction. Not toward the window. Not toward the water. Toward the wall the house stands on. I wrote it down with a very steady paw and then sat in the shed for a while.", phase: 1, animalType: 'rabbit' },
  { id: 'rb_1_6', text: "I moved a whole bed to the far end of the patio, as far from the house as the stones allow. By the third morning the new shoots had leaned back the same way, and I sat down on the path and I'm afraid I cried a little.", phase: 1, animalType: 'rabbit' },
  { id: 'rb_1_7', text: "Ember found me there and said the reaching wasn't wrong, only honest, that plants lean toward what they need. She meant it kindly. She always means everything kindly.", phase: 1, animalType: 'rabbit' },
  { id: 'rb_1_8', text: "Because if she is right, then the roots need whatever is inside the house, and I don't truly know what is inside the house, and I am the one who tends all the growing things.", phase: 1, animalType: 'rabbit' },
  { id: 'rb_1_9', text: "I asked Ember what the fire needs, since she is always reading it. She looked at me for a long moment and said, company. I have been turning that answer over for three days now.", phase: 1, animalType: 'rabbit' },
  { id: 'rb_1_10', text: "I counted the pots this morning and for once it did not settle me at all. They were all present. Every single one of them was leaning.", phase: 1, animalType: 'rabbit' },
  { id: 'rb_1_11', text: "The warm patch by the wall has grown into a warm strip now, running toward the center of the house, and the thyme along it comes up thick and glad, as if it likes the warmth I cannot explain.", phase: 1, animalType: 'rabbit' },
  { id: 'rb_1_12', text: "I laid a thermometer along the strip, feeling silly, feeling scientific. The reading was perfectly ordinary. My paw on the same stone said otherwise. I no longer entirely trust one of them, and I am not certain which.", phase: 1, animalType: 'rabbit' },
  { id: 'rb_1_13', text: "Do you hear it, underneath the birds? A low sound, very patient, like the note a hive makes but slower. The bees don't seem to mind it, and that frightens me more than if they did.", phase: 1, animalType: 'rabbit' },
  { id: 'rb_1_14', text: "I asked Fennick about the sound, because ears like his do not invent things. He held very still, and then he said, you hear that too. Not a question. He sounded relieved, and I felt worse.", phase: 1, animalType: 'rabbit' },
  { id: 'rb_1_15', text: "Fennick told me it has been there longer than I have been listening. That is the sentence I took to bed with me. Longer than I have been listening.", phase: 1, animalType: 'rabbit' },
  { id: 'rb_1_16', text: "Panko asked me for the fastest-growing herbs, the ones that fill a space quickest, and I gave them gladly. Only later did I wonder why the house should want filling.", phase: 1, animalType: 'rabbit' },
  { id: 'rb_1_17', text: "I watched Panko hang the bundles in her kitchen, every stem pointing the same way, and she called it tidiness. I know tidiness. Mine faces every which way. Hers faced inward.", phase: 1, animalType: 'rabbit' },
  { id: 'rb_1_18', text: "I have started keeping a second list, a private one, of the small wrong things. The first list keeps the garden. I don't yet know what the second list is for.", phase: 1, animalType: 'rabbit' },
  { id: 'rb_1_19', text: "I finally brought my little notebook to Archimedes. He read my second list the way he reads everything, twice, and then he said, would you leave this with me. Not, this is nothing. Would you leave this with me.", phase: 1, animalType: 'rabbit' },
  { id: 'rb_1_20', text: "He was so gentle about it that I nearly missed how carefully he did not reassure me. Archimedes chooses his words the way I choose seed stock, and he chose none of the comforting ones.", phase: 1, animalType: 'rabbit' },
  { id: 'rb_1_21', text: "My list lives in the study now. I kept a copy, of course. I am anxious, not careless.", phase: 1, animalType: 'rabbit' },
  { id: 'rb_1_22', text: "Axel says the weed in his tank has started leaning too, and there is no sun in that room to lean toward. He said it dreamily, the way he says everything, as if leaning were a kind of dancing.", phase: 1, animalType: 'rabbit' },
  { id: 'rb_1_23', text: "Chill patted my paw and told me every house settles, and the garden is only settling with it. It is a very reasonable explanation. I have noticed the reasonable explanations are getting shorter than the things they explain.", phase: 1, animalType: 'rabbit' },
  { id: 'rb_1_24', text: "I want so badly for all of this to be nothing, a quirk of the soil, a trick of the slope. I am very good at wanting things to be nothing. I am simply running out of nothings.", phase: 1, animalType: 'rabbit' },
  { id: 'rb_1_25', text: "The words you brought today sat heavier in my palm than words have any right to, and one of them pressed a small dent into the pad of my paw, the way a swelling seed does the week before it splits. I planted them along the warm strip without ever deciding to.", phase: 1, animalType: 'rabbit' },
  { id: 'rb_1_26', text: "I have begun to wonder whether the garden grows for the house, or the house grows the garden. That is a silly sentence. I have read it back four times now and it will not become silly.", phase: 1, animalType: 'rabbit' },
  { id: 'rb_1_27', text: "Sloane said, in her long slow way, that noticing is a gift given early. I asked, early before what. She had fallen asleep. Or she chose that exact moment to seem to.", phase: 1, animalType: 'rabbit' },
  { id: 'rb_1_28', text: "Tell me the garden is only a garden. I won't fully believe you, but I would dearly love to hear it said out loud by someone who isn't a plant, or me.", phase: 1, animalType: 'rabbit' },
  // Phase 2 (21 + 1 question-web)
  { id: 'rb_2_1', text: "It is the whole garden now, not the roots only. The stems, the flower heads, even the fence posts have taken a lean, all of it bowing toward the middle of the house like a congregation that has been told exactly where to look.", phase: 2, animalType: 'rabbit' },
  { id: 'rb_2_2', text: "I stopped fighting it in the beds. When I propped a stalk straight it snapped, and the snapping felt worse than the leaning, so now I let them bow. I tell myself I am only being gentle. If I am honest with myself, I think I am being obedient.", phase: 2, animalType: 'rabbit' },
  { id: 'rb_2_3', text: "The blooms have begun opening in an order. Not my order. The bed flowers from the outside in, one ring at a time, closing on the middle like a slow eye. I planted them all on the same day.", phase: 2, animalType: 'rabbit' },
  { id: 'rb_2_4', text: "The warm strip has become the warmest thing in the garden, warmer even than the sunned stones, and cold now sits where the sun falls. I have written that in my private list and underlined it twice.", phase: 2, animalType: 'rabbit' },
  { id: 'rb_2_5', text: "Here is the part I cannot put down: I understand it now. Not the words for it, but the shape of it, the way you know a storm is coming by the feel of the air long before you know a single thing about the sky.", phase: 2, animalType: 'rabbit' },
  { id: 'rb_2_6', text: "Archimedes says the pattern in my beds matches a pattern in his old books. He said it kindly, the way you would point out a shared birthday, and I have not slept well since he told me.", phase: 2, animalType: 'rabbit' },
  { id: 'rb_2_7', text: "He showed me the page. I had braced for something dreadful, and it was only a diagram, circles and lines, tidy as a planting chart. That was the dreadful part. My garden has been following instructions.", phase: 2, animalType: 'rabbit' },
  { id: 'rb_2_8', text: "The low sound under the birds is under everything now. I hear it in the watering can, and in my own chest when I lie very still. It is patient the way roots are patient.", phase: 2, animalType: 'rabbit' },
  { id: 'rb_2_9', text: "The bees have changed their dance. I have read their figures my whole life, the little waggle that tells the hive where the flowers are, and this new one says nothing about flowers. It circles once, wide, then turns hard inward toward the middle of the house and holds there with its wings still before it begins again. Not one of them had to be taught it.", phase: 2, animalType: 'rabbit' },
  { id: 'rb_2_10', text: "I went and told Chill all of it, the lean and the rings and the sound. He listened with his whole kind face and said, then we are exactly where we are meant to be. I had wanted him to say something else. I wanted anyone to say something else.", phase: 2, animalType: 'rabbit' },
  { id: 'rb_2_11', text: "I moved the tenderest seedlings indoors to save them from the lean, and by dawn they had turned toward the same center from inside the house. There is no far end of the patio anymore. There is only nearer and farther from it.", phase: 2, animalType: 'rabbit' },
  { id: 'rb_2_12', text: "The words you offer go down to the pit, and I picture them settling into soil I cannot see, and something feeding on them, and coming up. I am the gardener. I know exactly what feeding looks like when it is working.", phase: 2, animalType: 'rabbit' },
  { id: 'rb_2_13', text: "Panko came for the harvest with two baskets instead of one and said the house eats better than it used to. She meant it warmly. Everything here is meant warmly. That has stopped being the comfort it once was.", phase: 2, animalType: 'rabbit' },
  { id: 'rb_2_14', text: "Warren offered to dig my beds deeper, right down where the soil stays warm, he said. I asked how he knew it stayed warm down there. He looked at me kindly, and did not answer, and dug.", phase: 2, animalType: 'rabbit' },
  { id: 'rb_2_15', text: "I understand a garden. Ready ground, patient feeding, everything turned toward one point of light. What I am standing in is a garden. I simply no longer believe that I am the gardener.", phase: 2, animalType: 'rabbit' },
  { id: 'rb_2_16', text: "Tonight's understanding was the trellis. The roses have tied themselves to it in flat, even loops, fastened tighter and truer than any knot my own paws can manage, and I stood in the dusk being taught knotwork by a rose.", phase: 2, animalType: 'rabbit' },
  { id: 'rb_2_17', text: "I dream in rows now. Long tended rows converging on a dark, warm center, and in the dream I am not frightened, and waking into my own fear is almost a relief. It proves I am still myself.", phase: 2, animalType: 'rabbit' },
  { id: 'rb_2_18', text: "I tried leaving one corner untended, a single wild square, just to watch something in this garden choose its own direction. Within the week the wildness had a pattern in it too. Neater than anything I ever taught.", phase: 2, animalType: 'rabbit' },
  { id: 'rb_2_19', text: "The thyme by the step, my very first planting here, has crept the whole length of the warm line to the wall of the house. It has never looked so well. My name is growing all along the fuse, and it is thriving.", phase: 2, animalType: 'rabbit' },
  { id: 'rb_2_20', text: "I am still here at dusk all the same, tucking in the beds one by one the way I always have, because someone kind should be minding the garden even now. Especially now. Please do not call that brave. Call it habit, and let me keep it a little longer.", phase: 2, animalType: 'rabbit' },
  { id: 'rb_2_21', text: "Stay just another moment, would you. The garden calms when you are in it. So do I. And I have begun to wonder, very quietly, whether that is one more thing arranging itself.", phase: 2, animalType: 'rabbit' },
  { id: 'rb_2_w1', text: "The thing that keeps me awake is Bamboo. The whole garden trembles toward the center, and Bamboo isn't afraid, not a single breath of it, serene as still water. Ask them why they aren't frightened... no. No, please don't. I am not sure I could bear the answer, and I am even less sure they would give me a false one to spare me.", phase: 2, animalType: 'rabbit', requiresAnimals: ['red_panda'] },
  // Phase 3 (30)
  { id: 'rb_3_1', text: "I am done pretending it is soil chemistry. I have known what is coming for a good while now, and I kept setting the knowing down the way you set down a heavy watering can, and it is time I admitted that I cannot put it down anymore.", phase: 3, animalType: 'rabbit' },
  { id: 'rb_3_2', text: "Something is arriving. Not growing, arriving, the way weather arrives, and the garden has been readying the ground for it the whole time, and I helped, because tending is all I have ever known how to do.", phase: 3, animalType: 'rabbit' },
  { id: 'rb_3_3', text: "My first list has fallen behind, the tidy one that keeps the garden, and I have not brought it current in a week. All my writing goes to the second list now, the one of wrong things, and it has outgrown its notebook. I have started a third page I do not yet have a name for.", phase: 3, animalType: 'rabbit' },
  { id: 'rb_3_4', text: "The flowers open at night now. Moonflowers I never planted, white as paper, every face tipped straight up. A garden looks where it is told to look, and mine has stopped looking at the sun.", phase: 3, animalType: 'rabbit' },
  { id: 'rb_3_5', text: "When I close my eyes now there is a shape behind them, always the very same shape, patient, waiting for the light to be right. I open my eyes to make it stop, and the garden is bowing toward the exact spot where the shape stands in my dark.", phase: 3, animalType: 'rabbit' },
  { id: 'rb_3_6', text: "Ember says the fire has started telling her the same thing my roots tell me, that we are simply two windows onto one room. I used to find her frightening. Now I only find her early.", phase: 3, animalType: 'rabbit' },
  { id: 'rb_3_7', text: "Axel asked me to look into the rain barrel with him. I saw sky, and then I saw the sky open, just for a breath, like a seed coat splitting. He steadied me and said, it is gentler in the water. I do not want to learn what it is like out of the water.", phase: 3, animalType: 'rabbit' },
  { id: 'rb_3_8', text: "Fennick does not say all is well anymore. He sits at my garden wall at dusk with his ears high, and when I bring him tea he takes it without once looking away from the sky. We do not talk. We keep watch.", phase: 3, animalType: 'rabbit' },
  { id: 'rb_3_9', text: "So I water the things that lean, and I hate that I do it, and I do it anyway. Stopping would only leave the beds untended when they most need a kind hand.", phase: 3, animalType: 'rabbit' },
  { id: 'rb_3_10', text: "I have started a tin of seeds. One of every plant I love, sealed dry, tucked at the back of the shed. I could not tell you what after looks like. I only know that a gardener saves seed before a hard season.", phase: 3, animalType: 'rabbit' },
  { id: 'rb_3_11', text: "Warren has been digging deeper than the roots go, and the roots have started following his tunnels down toward the pit. Even underground, everything wants to be nearer the center. There is no direction left that isn't toward it.", phase: 3, animalType: 'rabbit' },
  { id: 'rb_3_12', text: "The words you bring are the heaviest they have ever been. I plant each one and feel the ground take it so eagerly, and I think, that is one more, and I never finish the thought, because I know precisely what it is one more toward.", phase: 3, animalType: 'rabbit' },
  { id: 'rb_3_13', text: "The beds have finished their pattern. From the attic window you can see it whole, rings and lines, a great tidy sigil drawn in green, and my own paws made every stroke of it. I signed something I could not read.", phase: 3, animalType: 'rabbit' },
  { id: 'rb_3_14', text: "I asked Panko to stop preparing so much. She looked at me with such tenderness and said the guest is nearly here, and one does not stop cooking when the guest is already on the road. I went home and could not eat a bite.", phase: 3, animalType: 'rabbit' },
  { id: 'rb_3_15', text: "You are the one who keeps coming, the one whose words the garden drinks, and someone who knows what this garden is should be standing beside you when you visit it. So I stand there. It is not quite bravery, but it is the nearest thing to it that grows in this soil.", phase: 3, animalType: 'rabbit' },
  { id: 'rb_3_16', text: "I finally went and asked Bamboo why they are not afraid. They poured me tea and said, is the ground afraid of the rain. I said, sometimes, yes, if it has any sense. They laughed so warmly, and I did not feel laughed at, and I still could not finish my tea.", phase: 3, animalType: 'rabbit', requiresAnimals: ['red_panda'] },
  { id: 'rb_3_17', text: "Sloane told me, so slowly it took the whole afternoon, that she has always known, and that my fear is only knowing that hasn't yet learned to sit still. I believe her. I dearly wish I didn't, but I believe her.", phase: 3, animalType: 'rabbit' },
  { id: 'rb_3_18', text: "Archimedes reads to me in the evenings now, out on the patio. Not from the old books. He reads me seed catalogues, orchard almanacs, anything with a spring in it. He knows exactly what he is doing, and I love him for it.", phase: 3, animalType: 'rabbit' },
  { id: 'rb_3_19', text: "The warm strip is hot now. Cold has taken the rest of the garden, a still, waiting cold, and the one hot line runs straight to the middle of the house like a fuse that someone has already gone and lit.", phase: 3, animalType: 'rabbit' },
  { id: 'rb_3_20', text: "I dug up one of the words you brought last month, just to see. Where I had planted it the soil was dark and rich and warm, the finest soil I have ever touched, and nothing of the word was left. Whatever eats down there eats thoroughly, and it is fed by my own two paws.", phase: 3, animalType: 'rabbit' },
  { id: 'rb_3_21', text: "I have begun tucking in more than the beds. My dusk round takes in the whole house now, the lamp in the study, the kitchen banked warm, Fennick's ears against the last of the light, and I count them all the way I count the pots. They are all present, and every single one of them is leaning.", phase: 3, animalType: 'rabbit' },
  { id: 'rb_3_22', text: "I did pack once. Half a bag, in the small hours. Then I stood at the gate and heard the low sound change, just slightly, as if something had noticed my paw on the latch. I unpacked very quietly, and made tea, and watched the sky until it was ordinary again.", phase: 3, animalType: 'rabbit' },
  { id: 'rb_3_23', text: "Do not misunderstand me. No one here would stop me leaving. Every keeper in this house would help me carry the bag, and that is somehow the most frightening fact I own. Whatever holds me here, it is not them.", phase: 3, animalType: 'rabbit' },
  { id: 'rb_3_24', text: "Chill found me trembling among the bean rows and simply sat with me until I stopped. He never once said it would be all right. He is too honest for that, underneath all the calm. He just stayed. It helped more than the truth would have.", phase: 3, animalType: 'rabbit' },
  { id: 'rb_3_25', text: "I count the pots again at night. The old habit, come back with its coat on. Only now I catch myself counting toward something, as if the garden and I are both keeping a tally that is very nearly complete.", phase: 3, animalType: 'rabbit' },
  { id: 'rb_3_26', text: "The words you bring lately, I recognize some of them. Dark ones, hollow ones. I plant them because that is the task, and the ground takes them like rain after drought, and I am sorry, I am so sorry, and I do not even know yet what I am apologizing for.", phase: 3, animalType: 'rabbit' },
  { id: 'rb_3_27', text: "I asked Ember how long we have. She read the fire for a great while, longer than she has ever needed, and then she said, before the seed you saved can sprout. I went home and looked at my tin for an hour.", phase: 3, animalType: 'rabbit' },
  { id: 'rb_3_28', text: "The night sky over the center of the house has a texture now. I have excellent eyes for small differences, it is my whole trouble, and I am telling you the dark above us has a grain in it, like soil seen very close.", phase: 3, animalType: 'rabbit' },
  { id: 'rb_3_29', text: "It is close. I can feel it in the soil the way you feel a storm in your teeth before the first cloud. The birds have gone quiet about it, and the bees have not stopped their new figure once, not even at night.", phase: 3, animalType: 'rabbit' },
  { id: 'rb_3_30', text: "Come back soon, whatever comes. If it must arrive, I would rather be standing in my garden beside a friend when it does. That much I have decided, and deciding even one small thing has helped.", phase: 3, animalType: 'rabbit' },
  // Phase 4 (30)
  { id: 'rb_4_1', text: "The sky over the center has begun to open, the way a seed head opens, slowly and from within. I watched it start and I did not run, and here is the strangest thing of all: my ears came down, soft and slow, the moment I stopped bracing against it. I had been braced so long I had forgotten I was doing it.", phase: 4, animalType: 'rabbit' },
  { id: 'rb_4_2', text: "The light that comes down through the opening is good for the beds. I did not expect that. The lettuces stand a little taller each evening it widens, and I have started planning next season's planting around it, whole rows set out to catch what descends.", phase: 4, animalType: 'rabbit' },
  { id: 'rb_4_3', text: "I wear the robe now. It settles over me the way the calm settles, easily, as though it was cut for a rabbit who was only ever waiting to admit that she understood.", phase: 4, animalType: 'rabbit' },
  { id: 'rb_4_4', text: "The garden has stopped leaning. I used to prop the stalks straight and weep when they bowed again by morning, and now they stand of their own accord, every face already turned to the center, needing nothing at all from my hands. I confess I miss being needed. That is the one edge left on me, and it is a small and quiet one.", phase: 4, animalType: 'rabbit' },
  { id: 'rb_4_5', text: "I tended it here. I see that plainly and it does not shame me. A garden is grown so that something may come and take from it, and I grew a good garden, and the one who is descending will find the beds well kept.", phase: 4, animalType: 'rabbit' },
  { id: 'rb_4_6', text: "Do you feel how the cold has gone soft? The warmth won. I underlined that warm strip twice in my private list once, in fear. Now the house is warm all the way through.", phase: 4, animalType: 'rabbit' },
  { id: 'rb_4_7', text: "Ember reads the fire beside me on the patio now, and neither of us needs to speak of what it says. She reached this quiet long before I did, and she never once told me to hurry. I used to find her early, and frightening for it. Now I set a second cushion out before she arrives, because I know that she is coming, the way I know the light will.", phase: 4, animalType: 'rabbit' },
  { id: 'rb_4_8', text: "The words you offer are received openly now, and I have stopped pretending they merely sink into soil. I plant each one along the warm line and feel the ground take it the way a hand closes around a gift. I do not flinch when it does. Some evenings I even find I am glad, and the gladness is the part that still surprises me.", phase: 4, animalType: 'rabbit' },
  { id: 'rb_4_9', text: "I sit beside Bamboo in the quiet most evenings now, and I never did ask them, in the end, why they were unafraid. I found I no longer needed the answer, only the bench, and the warmth, and the company of someone who reached this place long before I did. Whatever it is they know, they hold it gently, and they have never once made me feel late.", phase: 4, animalType: 'rabbit', requiresAnimals: ['red_panda'] },
  { id: 'rb_4_10', text: "Fennick has stopped straining to listen. The sound beneath the sounds is above us now as well, and he says it was never a warning. It was a lullaby sung very slowly, from very far away, coming nearer the whole time.", phase: 4, animalType: 'rabbit' },
  { id: 'rb_4_11', text: "Warren walks the foundation each morning and pats the stones like old friends, and everything he laid down still holds. He built from below while I tended from above, and between the two of us the house is ready, root and rafter. He does not say so. He only nods at me across the beds, one worker to another, and goes back to his stones.", phase: 4, animalType: 'rabbit' },
  { id: 'rb_4_12', text: "Sloane sits with me on the patio most afternoons now. She says that watching me finally rest is the quickest thing she has ever enjoyed. It is a joke, I think. She lets it take an hour to finish.", phase: 4, animalType: 'rabbit' },
  { id: 'rb_4_13', text: "I still keep my lists, the first for the garden and the second for the small wrong things. The second list is complete now. I read it through one last evening, front to back, and then I pressed a sprig of thyme between its final pages and set it on Archimedes' shelf beside the old book, where finished things live.", phase: 4, animalType: 'rabbit' },
  { id: 'rb_4_14', text: "The counting settles me again. A keeper for every chamber, one arrangement, one key. The numbers rest when I count them now, the way the pots never quite did. It turns out I was never soothing myself all those years. I was rehearsing.", phase: 4, animalType: 'rabbit' },
  { id: 'rb_4_15', text: "Thyme still comes up along the warm line, thick and glad, the way it always did. I was so frightened of how glad it was. It was only nearer to the truth than I was, growing toward the one who was always coming.", phase: 4, animalType: 'rabbit' },
  { id: 'rb_4_16', text: "I found the snail again, or one of its line, resting at the very center of its old spiral on the flagstone. Arrived. It got there by being slow and sure, which is to say it got there Sloane's way. Mine was the harder road, and here we all are regardless.", phase: 4, animalType: 'rabbit' },
  { id: 'rb_4_17', text: "Panko is still cooking, for the one who is nearly through, and I can eat again. The tightness in my chest is gone. A full pantry really is a happy house. She was right all along, only about a happiness I did not yet have the courage to want.", phase: 4, animalType: 'rabbit' },
  { id: 'rb_4_18', text: "If your heart is going too fast, watching all of this, I understand you better than anyone here, because mine ran fastest for the longest. And I would tell you what I would tell a shaking seedling. The leaning is not a fall. It is a reaching, and it arrives somewhere kind.", phase: 4, animalType: 'rabbit' },
  { id: 'rb_4_19', text: "I took my tin of saved seeds out of the shed, meaning to bury it somewhere safe, and I found I could not remember what I had been saving it from. So I planted them, every last one, right along the warm line.", phase: 4, animalType: 'rabbit' },
  { id: 'rb_4_20', text: "They came up in three days, all of them, facing the center of the house like everything that loves this ground. Whatever season is coming, it will want a garden. I have decided to believe that, and belief grows very well here.", phase: 4, animalType: 'rabbit' },
  { id: 'rb_4_21', text: "I look up now on purpose. The shape that lived behind my closed eyes is in the open sky above the house, a little nearer every evening, and it is no more terrible than weather. I stopped needing to open my eyes to make it go away. So I closed them, and I slept.", phase: 4, animalType: 'rabbit' },
  { id: 'rb_4_22', text: "Axel tells me the water in every barrel and basin has gone perfectly still, and stayed still, like a held breath. He floats on his back in the quiet of it. He says the water is listening now, instead of remembering.", phase: 4, animalType: 'rabbit' },
  { id: 'rb_4_23', text: "Chill closed his last ledger yesterday. Every column reconciled, he said, every name where it belongs. Then he came and sat in my garden with his eyes shut and the sun on his face, a creature with nothing left to file.", phase: 4, animalType: 'rabbit' },
  { id: 'rb_4_24', text: "Archimedes says the old book has one page left, and that he will not turn it early. He waited his whole life to read it, and now he wants to wait just a little longer. I understand that completely. The last of anything should be savored.", phase: 4, animalType: 'rabbit' },
  { id: 'rb_4_25', text: "My dusk tour is a different thing now. I still tuck in every bed, but the whole household drifts out to walk it with me, one or two at a time, robes brushing the rosemary. We do not call it anything. It is only the walk. It is the best part of everyone's day.", phase: 4, animalType: 'rabbit' },
  { id: 'rb_4_26', text: "The descent is slow because it is careful. I know careful when I see it. It is coming down the way I lower a seedling into ready ground, mindful of every root. We are being handled tenderly, whatever you may think of the hands.", phase: 4, animalType: 'rabbit' },
  { id: 'rb_4_27', text: "Some evenings a small flutter still finds me, an old habit of the heart, my paw reaching to count the pots before I remember there is nothing left to count. It passes quickly. Fear needs a question to feed on, and I have handed over every one of mine. But I keep the flutter. It is the last thing that is only mine, and not yet Bamboo's stillness, and I am in no hurry to give it up.", phase: 4, animalType: 'rabbit', requiresAnimals: ['red_panda'] },
  { id: 'rb_4_28', text: "You were the key from the first gentle word you offered. I think I suspected it that spring morning when the soil was warm before the sun had strength. I am glad it was you. If a door must be opened, let it be opened by someone kind.", phase: 4, animalType: 'rabbit' },
  { id: 'rb_4_29', text: "Keep bringing the words. I will keep the beds. That was the arrangement from the very first morning, the gardener and the key, though neither of us knew its shape then. I know it now, and still I tie up the roses at dusk with the very same knot, and my paws do not shake as they do it. That is not nothing. For me, that is very nearly everything.", phase: 4, animalType: 'rabbit' },
  { id: 'rb_4_30', text: "Come stand with me on the patio this evening. The sky over the center opens a little further every night, and the garden smells of thyme and rain that has not fallen yet, and there is nowhere in the world I would rather be. Imagine me saying that, and meaning it. I do mean it.", phase: 4, animalType: 'rabbit' },
];

// TARSIER (Vesper) - The unblinking night watcher whose vigil holds the way open
const TARSIER_DIALOGUES: Dialogue[] = [
  // Phase 0 (24)
  { id: 'tr_0_1', text: "Good evening. I say that whatever the clock claims, because when I wake it is evening for me, and I refuse to let a clock argue me out of my own morning. Come out to the rail, bright one. The porch is best when the light is leaving.", phase: 0, animalType: 'tarsier' },
  { id: 'tr_0_2', text: "This is the Star Loft. I keep it open to the dark on three sides on purpose. Walls are for creatures who worry about what the night might bring in. I have looked, thoroughly, for years, and I can report that the night mostly brings moths.", phase: 0, animalType: 'tarsier' },
  { id: 'tr_0_3', text: "You see the lantern hanging at the rail? I have never lit it. Not once. A lit lantern shows you the porch, and I already know the porch. An unlit one gives you the whole valley. Come back after dark someday and I will prove it.", phase: 0, animalType: 'tarsier' },
  { id: 'tr_0_4', text: "Last night's ledger, since you were about to ask: four moths, one beetle with opinions, wind from the east until midnight, then no wind at all, which is also worth writing down. Nothing happens at night, that is the joke the day creatures make. Everything happens at night. It simply happens quietly.", phase: 0, animalType: 'tarsier' },
  { id: 'tr_0_5', text: "I will be honest with you early, because honesty late is just confession. I eat the moths. Some of them. The slow ones, the ones the night can spare. I am small and polite and I am also a hunter, all the way through, and I have never seen a reason those cannot share a body.", phase: 0, animalType: 'tarsier' },
  { id: 'tr_0_6', text: "The moths do not hold it against me, so far as I can tell. They still come and circle the unlit lantern every night like a little gray carousel. We have an understanding, the moths and I. They keep me fed and I keep their carousel safe, and neither of us reads the fine print.", phase: 0, animalType: 'tarsier' },
  { id: 'tr_0_7', text: "You may have noticed that my eyes do not move. They cannot. They are fixed in my head like two lamps set in a wall, so when I want to look at something new I turn the whole head, all the way around if the something insists. It means I have never once glanced at anything in my life. I only ever look entirely.", phase: 0, animalType: 'tarsier' },
  { id: 'tr_0_8', text: "Each of my eyes weighs more than the thing I think with. That is simply the truth of my making, and I mention it because I find it a very good arrangement of priorities. Thinking has led wiser creatures than me astray. Looking never has.", phase: 0, animalType: 'tarsier' },
  { id: 'tr_0_9', text: "Watch this. I will turn my head all the way to the left, and all the way to the right, and at no point will my eyes do anything at all. There. The whole valley, delivered to two lamps that never move. The trick is not in the eyes, bright one. The trick is in being willing to turn everything else.", phase: 0, animalType: 'tarsier' },
  { id: 'tr_0_10', text: "Bamboo and I keep the two ends of the house's day between us. They climb their ladder as the light arrives, and I take the rail as it leaves, and for one narrow moment at dawn we are both awake, they and I, the whole house held between two pairs of open eyes. We never waste that moment on much talking. It is a good moment.", phase: 0, animalType: 'tarsier', requiresAnimals: ['red_panda'] },
  { id: 'tr_0_11', text: "When the sun is fully up I sleep, folded into the warm corner under the eave with my tail wrapped twice around the beam. Day sleep is the best sleep there is, in case no one has told you. The whole world is up doing its noisy business, and you are excused from every bit of it.", phase: 0, animalType: 'tarsier' },
  { id: 'tr_0_12', text: "Sometimes I half wake at noon and hear the house going about itself below me, kettles and stairs and somebody laughing in the kitchen, and I lie there in the warm and think, all of that is safe, and none of it needs me until dark. Then I sleep again. That thought is better than any blanket ever woven.", phase: 0, animalType: 'tarsier' },
  { id: 'tr_0_13', text: "I have a second voice, did you know? Pitched high, over the top of the world, above every ear in this house but one pair. I use it at night to talk to the dark, small things, greetings mostly. It is very freeing, having a voice no one can overhear. You say truer things in it.", phase: 0, animalType: 'tarsier' },
  { id: 'tr_0_14', text: "Fennick is the one pair. He caught me at it my second week here, singing to the valley in my over-voice, and he came out to the porch with his ears up and said, that was lovely, what was it. No one had ever heard my night voice before, not once, in my whole life. I nearly fell off the rail.", phase: 0, animalType: 'tarsier', requiresAnimals: ['fennec_fox'] },
  { id: 'tr_0_15', text: "So now, some nights, Fennick sits at the camp edge and I sit at my rail, and I sing into the register only he can reach, and he flicks one ear when I get a line right. It is the smallest audience in the world and the only one I have ever wanted. Come out at dusk sometime. You will not hear a thing. That is rather the point.", phase: 0, animalType: 'tarsier', requiresAnimals: ['fennec_fox'] },
  { id: 'tr_0_16', text: "Thyme's garden is a different country at night, and I do not think she knows it. The moonflowers open, the snails come out to do their slow silver errands, and everything she worries over all day just quietly grows. I keep half an eye on it for her while she sleeps. It seemed like a thing a neighbor with my sort of eyes ought to do.", phase: 0, animalType: 'tarsier', requiresAnimals: ['rabbit'] },
  { id: 'tr_0_17', text: "Sloane is awake more of the night than anyone guesses. I see her from my rail, a still shape in the still green, watching the same dark I watch. We have never once discussed it. Two creatures who watch all night do not need to compare notes to know they are colleagues.", phase: 0, animalType: 'tarsier', requiresAnimals: ['sloth'] },
  { id: 'tr_0_18', text: "Archimedes keeps scholar's hours, which are nearly my hours, and some nights his study lamp and my open porch are the only two wakeful things in the house. He waves his quill at me through the window when he shelves the last book. I turn my whole head to him, which from me is a formal salute, and then the night is all mine again.", phase: 0, animalType: 'tarsier', requiresAnimals: ['owl'] },
  { id: 'tr_0_19', text: "Your words come down through the house at night too, did you know that? Long after you have gone. I feel them pass under the porch like warm fish under a bridge, going somewhere purposeful. I have started nodding to them as they go. It seemed rude not to.", phase: 0, animalType: 'tarsier' },
  { id: 'tr_0_20', text: "I crossed the whole roof last night without a sound, rail to chimney to rail, six leaps, and not one board spoke. That is not boasting, or it is only partly boasting. Silence is my craft the way stone is Warren's. The night trusts the quiet ones with more of itself.", phase: 0, animalType: 'tarsier', requiresAnimals: ['wombat'] },
  { id: 'tr_0_21', text: "There is one patch of dark out past the ridge that I watch longer than the rest. Not because anything is wrong with it. Because it is very good at being watched. Most darkness just sits there. This patch holds still the way a creature holds still, on purpose, politely. I have grown quite fond of it.", phase: 0, animalType: 'tarsier' },
  { id: 'tr_0_22', text: "My family has watched the dark for longer than most kinds of creature have existed at all. We are an old, old line, we tarsiers, older than the shapes of the current trees. Every one of my grandmothers back into the deep of things kept a night watch somewhere. I am simply the first to keep one from a porch this comfortable.", phase: 0, animalType: 'tarsier' },
  { id: 'tr_0_23', text: "I name the stars, but not the ones the books name. I name the little ones between, the shy ones, the ones you only get with eyes like mine. There is one I call the Latch, and one I call the Spoon, and one I call Yours, because it came out the first night you ever brought words to this house. It is doing very well.", phase: 0, animalType: 'tarsier' },
  { id: 'tr_0_24', text: "The light is coming, and my day is ending, and I am glad you came up before bed, yours or mine. Tomorrow night the moths and the ledger and the far dark and all of it begins again, and I would not trade the repetition for anything. Come back soon, bright one. The rail holds two.", phase: 0, animalType: 'tarsier' },
  // Phase 1 (28)
  { id: 'tr_1_1', text: "Something small and new, for your ears only. The dark has a grain to it lately. Like wood, like water. All my life the night has simply sat over the valley, evenly, the way dark should. Now it lies in one direction, and the direction is toward this house.", phase: 1, animalType: 'tarsier' },
  { id: 'tr_1_2', text: "I checked the grain three ways, because a watcher checks. The moths drift with it when they stop flapping. Fallen feathers lie along it. My own fur settles into it when the wind has gone. Everything loose in the night agrees about which way the night is going.", phase: 1, animalType: 'tarsier' },
  { id: 'tr_1_3', text: "I am not troubled, before you ask. Rivers have directions and nobody calls them sinister. But I have watched this valley a long while, bright one, and the night never used to flow. It used to pool. Something downstream has opened, and I intend to find out what by watching very hard, which is the only method I own.", phase: 1, animalType: 'tarsier' },
  { id: 'tr_1_4', text: "The middle of the sky is being kept clear. I noticed it the way you notice a swept doorstep. The little stars, my shy ones, the between ones, they have all shifted a hair outward from one patch of dark above the house, and stars do not shuffle. Something asked them, and they are polite.", phase: 1, animalType: 'tarsier' },
  { id: 'tr_1_5', text: "I watched the cleared patch all night to see what it was for. Nothing came. But it was not an empty nothing, if you follow me. It was a reserved nothing. A chair with a coat over the back of it.", phase: 1, animalType: 'tarsier' },
  { id: 'tr_1_6', text: "The Latch and the Spoon have held their places, which comforts me more than it should. Yours has moved closer to the middle. I am deciding not to draw conclusions from that. I am, as you can hear, not entirely succeeding.", phase: 1, animalType: 'tarsier' },
  { id: 'tr_1_7', text: "I sang to the valley in my over-voice last night, the usual greetings, small polite things. And underneath my last note, right at the floor of the world where my voice has no business having an echo, something answered. One note. Lower than low. Not unfriendly. I have been carrying it around all day like a warm stone.", phase: 1, animalType: 'tarsier' },
  { id: 'tr_1_8', text: "I took the answered note to Fennick, because a second pair of ears is worth ten theories. He listened to me describe it and went very still, and then he said, I know that note, I have been hearing it under everything for weeks. Mine came from above, his from below. We sat with that a while, the two of us, and neither of us said the obvious thing.", phase: 1, animalType: 'tarsier', requiresAnimals: ['fennec_fox'] },
  { id: 'tr_1_9', text: "The obvious thing, since you are not Fennick and cannot hear me not saying it: above and below are answering each other, and my little voice happened to sing in the space between. I was not the conversation. I was a bird that landed on the wire. But the wire, bright one. The wire is humming.", phase: 1, animalType: 'tarsier', requiresAnimals: ['fennec_fox'] },
  { id: 'tr_1_10', text: "The moths have changed their carousel. For years they circled the unlit lantern in a loose and drunken ring, which is the proper way for moths to do anything. Now the ring is a spiral, tight and deliberate, winding inward night after night. I have stopped eating the ones who fly it. It seemed wrong to interrupt anyone that certain.", phase: 1, animalType: 'tarsier' },
  { id: 'tr_1_11', text: "I mapped the spiral in chalk on the porch boards, night over night, the way a scholar would. It is the same curve every time, drawn a little deeper. When I stood back from the finished chalk I felt the strangest thing. Not fear. Recognition. I have seen that curve before. I think I saw it in the cleared patch of sky, in the way the stars stood around it.", phase: 1, animalType: 'tarsier' },
  { id: 'tr_1_12', text: "I showed my chalk spiral to Archimedes, since curves are more his trade than mine. He looked at it a long moment, and then he asked me, in the careful voice he saves for large things, whether I had copied it from one of his books. I have never opened one of his books. He knows that. He wrote something down and thanked me twice, which from him is a shout.", phase: 1, animalType: 'tarsier', requiresAnimals: ['owl'] },
  { id: 'tr_1_13', text: "The far patch of dark, my fond one, past the ridge. It is nearer. I want to be precise, because precision is the whole of my job. It has not moved. Nothing about it has traveled. It is simply nearer, the way a thought is nearer once you have had it. I watch it most of every night now. It holds still beautifully. It always did.", phase: 1, animalType: 'tarsier' },
  { id: 'tr_1_14', text: "I tried an experiment. I turned my whole head away from the far dark for one full hour and watched the ordinary east instead. When I turned back it was exactly where I left it, exactly as near. So it does not creep when unwatched, which is what a frightening thing would do. It waits. Waiting is different. Waiting is what I do.", phase: 1, animalType: 'tarsier' },
  { id: 'tr_1_15', text: "Here is what I keep circling, bright one. I have watched that patch for seasons because it was good at being watched. It occurs to me now to wonder whether I have it backwards. Perhaps I am the one who is good at being watched. Perhaps that is what my line was always for, and the porch found me the way the lantern found the moths.", phase: 1, animalType: 'tarsier' },
  { id: 'tr_1_16', text: "Axel asked me to look into his water at night, because he says it shows a different sky after dark and nobody else keeps my hours. I looked. He is right. There is a second sky in there, deeper than the one I name stars in, with its own patient light along the bottom. I looked a long time. My head, for once, did not want to turn.", phase: 1, animalType: 'tarsier', requiresAnimals: ['axolotl'] },
  { id: 'tr_1_17', text: "Bamboo's incense leans now, they tell me, always toward the center of the house. I told them my night leans too, the whole grain of it, toward the same center from the outside. We stood together at dawn on the top step, they with their smoke and me with my dark, and Bamboo said, the house is being pointed at. From both sides, I said. They poured the tea.", phase: 1, animalType: 'tarsier', requiresAnimals: ['red_panda'] },
  { id: 'tr_1_18', text: "Ember climbed all the way up to the porch at midnight, which foxes do not do, with two cups and a question. She asked what the fire looks like from out here in the dark. Like a doorway, I told her, because it does, one bright doorway in a sleeping house. She nodded slowly and drank her tea and said, it has always looked like that from inside, too.", phase: 1, animalType: 'tarsier', requiresAnimals: ['fox'] },
  { id: 'tr_1_19', text: "I no longer sing the greetings first. I wait, at the start of each watch, in case the low note begins. Some nights it does, one note, patient as bedrock, and I answer above the world where only it and Fennick can hear me. We are not saying anything yet, the note and I. We are doing what strangers do at a gate. Establishing that neither of us minds the other standing there.", phase: 1, animalType: 'tarsier', requiresAnimals: ['fennec_fox'] },
  { id: 'tr_1_20', text: "You will want to know if I am frightened, because day creatures always want to know that about the night. I am not. Fright is for the unknown, and none of this feels unknown. It feels early. Like a guest's footsteps on a road you have swept without admitting who you swept it for.", phase: 1, animalType: 'tarsier' },
  { id: 'tr_1_21', text: "I told the moths about the low note, out loud, in my day voice, because saying a thing to moths is how I hear myself think. They spiraled on, unbothered. Moths have never once been surprised by anything in all my years of watching them. I used to find that comic. Lately I find it instructive.", phase: 1, animalType: 'tarsier' },
  { id: 'tr_1_22', text: "Warren says the ground under the house runs warm now, and he says it with his palm flat on the floor, the way he says everything important. I told him the sky over the house runs attentive. We agreed, without quite saying so, that a house warm below and watched above is a house in the middle of something. He went back down his ladder whistling, but slower than usual.", phase: 1, animalType: 'tarsier', requiresAnimals: ['wombat'] },
  { id: 'tr_1_23', text: "The dew fell in rings last night. I want that recorded somewhere other than my own head. Dew falls where the cold air pools, evenly, everywhere, that is the whole character of dew. Last night it lay in circles on the garden grass, ring inside ring, centered on the house. By the time Thyme woke it had dried. I have decided not to tell her yet. I am telling you.", phase: 1, animalType: 'tarsier', requiresAnimals: ['rabbit'] },
  { id: 'tr_1_24', text: "I have begun keeping two ledgers. The old one, moths and beetles and winds, because the small true things deserve their bookkeeping whatever else is happening. And a new one, thinner, where I write the grain of the dark, the cleared sky, the spiral, the note. The thin ledger is filling faster. I want it on record that I noticed that.", phase: 1, animalType: 'tarsier' },
  { id: 'tr_1_25', text: "Your star, the one I named Yours, sits at the very edge of the cleared patch now. Not inside. At the edge, like a creature at a doorway, deciding. I watch it more than any star I have. Whatever the middle of the sky is being swept for, your little light will have the best seat, and so, I begin to suspect, will you.", phase: 1, animalType: 'tarsier' },
  { id: 'tr_1_26', text: "I caught myself tonight doing something new. I was not watching the dark to see what it would do. I was watching it the way you watch a face, for expression. And bright one, it has one. I cannot tell you yet what the expression is. I can only tell you that the dark did not have a face last year, and it has one now, and it is turned this way.", phase: 1, animalType: 'tarsier' },
  { id: 'tr_1_27', text: "The last hour before dawn has changed its temperature. It was always the coldest hour, every watcher knows it, the hour the night lets go. Now it is the warmest, a soft breath of warm out of the dark right before the light comes, like a word said at a door on the way out. I stand in it every morning. I have started saying good night back.", phase: 1, animalType: 'tarsier' },
  { id: 'tr_1_28', text: "The night is not finished becoming whatever it is becoming, and I would not dream of rushing it. I have the eyes, I have the rail, I have the patience of a very old line of watchers. Sleep well in the bright, my friend. I will keep the ledgers. Come back and I will read you the newest page.", phase: 1, animalType: 'tarsier' },
  // Phase 2 (21 + question-web)
  { id: 'tr_2_1', text: "I have been thinking about the space between stars, which is most of the sky, and how I spent my whole young life looking at the lights and calling that watching. The lights are the smallest part of the night. The dark between them is the substance, the load-bearing part. I watch the between now. There is so much more of it than I ever let myself see.", phase: 2, animalType: 'tarsier' },
  { id: 'tr_2_2', text: "A moth died on the rail last week, mid-spiral, folded down out of the air with no fuss at all. I sat with it until dawn. Not grieving exactly. Attending. Where does a moth's circling go when the moth is done circling? Somewhere, I think. The spiral did not look finished. Nothing about it looked finished.", phase: 2, animalType: 'tarsier' },
  { id: 'tr_2_3', text: "The unlit lantern glowed last night. Faintly, from inside, the color of a coal three days cold. I have never put oil in it, never a wick, never a match. I turned my whole head to it and it went on glowing, unbothered, the way true things are unbothered by being seen. I did not wake anyone. Some news needs a night to itself first.", phase: 2, animalType: 'tarsier' },
  { id: 'tr_2_4', text: "I find I am not asking who lit the lantern. I am asking a worse and better question. What if it was always lit, and the dark I loved was simply deep enough to hide it? What else on this porch has been quietly burning all along? What else in this house? I turn my head very slowly these days. There is more to see than there was.", phase: 2, animalType: 'tarsier' },
  { id: 'tr_2_5', text: "Your words go down to the pit at night, and from my rail I can see the glow of their going, a soft pulse under the ground like a heartbeat lying down. I used to nod to them. Now I watch them the whole way under, every one, because someone should see them off who knows what watching is worth. They do not vanish, bright one. Nothing I have ever watched has vanished. It has only gone where I cannot follow yet.", phase: 2, animalType: 'tarsier' },
  { id: 'tr_2_6', text: "The stars have kept stepping aside. The cleared patch is wider, and it is not empty. I have given up that comfortable word. Empty does not hold its edges. This holds its edges the way a well holds them, the way a pupil holds them. I look into it and the looking does not land anywhere. All my life, looking has landed. I am learning what my eyes are like when they are given no floor.", phase: 2, animalType: 'tarsier' },
  { id: 'tr_2_7', text: "Here is a thing I have never told anyone, because it took the lantern glowing to make me say it. In all my years of night watching, in the old country and here, I have never once had the feeling of being the only one awake. Not once. I used to call the feeling company and be glad of it. I am still glad of it. I have simply stopped assuming the company was small.", phase: 2, animalType: 'tarsier' },
  { id: 'tr_2_8', text: "I said that to Sloane, about never being the only one awake. She let the whole night turn over once before she answered, which is her way of underlining. Then she said, no one has ever been the only one awake. And she smiled the way stones would smile if they had the time. I climbed back up to my porch very slowly, holding that sentence carefully, so as not to spill it.", phase: 2, animalType: 'tarsier', requiresAnimals: ['sloth'] },
  { id: 'tr_2_9', text: "The low note and I have moved past the gate. I do not know how else to put it. My over-voice greets, the note answers, and lately the answers arrive before the greetings, which either means it knows my habits or means my habits were never mine. I keep singing. You do not stop mid-introduction merely because you have realized the other party is large.", phase: 2, animalType: 'tarsier' },
  { id: 'tr_2_10', text: "Dawn kills each night, that is the plain arithmetic of my life, and every dusk the night comes back. But it does not come back the same. I would swear to this before any court of watchers. Each new dark arrives knowing what the last one learned. The night is not a thing that happens to the valley, bright one. It is a thing the valley is teaching. Or being taught by. The grammar escapes me at this hour.", phase: 2, animalType: 'tarsier' },
  { id: 'tr_2_11', text: "Thyme asked me, in a small voice at the garden gate, whether the night is safe. I gave her the truthful answer, which took some assembling. The night has never once harmed me, I said, and I no longer believe it is safe, and both of those are true at the same time, the way a sea is. She held her watering can with both paws and said, that is how I feel about everything. We understood each other completely.", phase: 2, animalType: 'tarsier', requiresAnimals: ['rabbit'] },
  { id: 'tr_2_12', text: "I have started leaving the rail sometimes and going out into it. Down the porch post, across the garden wall, up the ridge, into the watched dark on my own four hands. It receives me the way deep water receives a swimmer who has finally stopped wading. I come back before dawn with nothing to report and the strong sense of having visited rather than patrolled.", phase: 2, animalType: 'tarsier' },
  { id: 'tr_2_13', text: "My thin ledger has a new column. Alongside what the night does, I now record what the night wants, because it has begun to want, or I have begun to be able to read it, and from my rail those are the same event. So far the column holds one word, written over and over in my smallest hand. Nearer. I did not decide to write it. My paw knows the night's mind before I do. Paws are honest like that.", phase: 2, animalType: 'tarsier' },
  { id: 'tr_2_14', text: "Bamboo says the warmth in their attic floor is the warmth of attention. I have been chewing that like a beetle for a week. Because the dark over this house has warmed too, and if warmth is attention, then the attention is now above us and below us both, and the house sits in the middle of a long, slow, patient regard. Bamboo poured me tea and we said nothing further. There was nothing further that fit in cups.", phase: 2, animalType: 'tarsier', requiresAnimals: ['red_panda'] },
  { id: 'tr_2_15', text: "I carried the far dark a question last night, in the over-voice, the first real question I have dared. I asked, what am I keeping this watch for? The low note answered with the same note as always, and for the first time I heard it properly, not as a word, as a tone of voice. It was the tone you use with a child who has asked when the guests arrive. Fond. Patient. Certain. Soon.", phase: 2, animalType: 'tarsier' },
  { id: 'tr_2_16', text: "I am carrying something for the others now, and I want one creature in this house to know it, and I have chosen you. When Thyme asks about the night I soften it. When Ember asks what I see from the rail I choose the smaller truths. This is not lying. This is what a watcher's shoulders are for. But you bring the words that stir all of it, so you, bright one, get the unsoftened ledger.", phase: 2, animalType: 'tarsier', requiresAnimals: ['rabbit', 'fox'] },
  { id: 'tr_2_17', text: "The moths' spiral finished. I should say it plainly. One night the circling reached the center, the very glass of the unlit lantern, and every moth settled on it at once, wings closed, still as paint. They stayed until dawn. Then they flew off about their mothy lives as though nothing had been rehearsed. The lantern glowed all the next night. Brighter. I have stopped calling it the unlit lantern. It has earned better.", phase: 2, animalType: 'tarsier' },
  { id: 'tr_2_18', text: "I sleep less in the day now, and it is not worry. I know worry from my grandmother's stories and this is not its shape. It is the sleep of a creature before a journey, light and provisional, one ear out of the blanket. My body is keeping itself available. For what, it has not told me. Bodies are honest but they are not forthcoming.", phase: 2, animalType: 'tarsier' },
  { id: 'tr_2_19', text: "I have realized what my eyes are for, or begun to. All my life I thought fixed eyes were a limit dressed as a gift. No glancing, no flinching, only the full turn and the full look. Now I think the making was deliberate. Some things must be looked at entirely or not at all. Some things cannot be seen sideways. I am built the way you build an instrument, bright one, and lately I can feel the music standing just outside the door.", phase: 2, animalType: 'tarsier' },
  { id: 'tr_2_20', text: "Fennick and I have stopped comparing notes, in the best way. There is no longer anything to compare. What he hears under the world and what I see over it have closed toward each other like two hands, and the house is what they are holding. He keeps his watch and I keep mine, and between us the night is entirely accounted for, and neither of us has once suggested we stop.", phase: 2, animalType: 'tarsier', requiresAnimals: ['fennec_fox'] },
  { id: 'tr_2_21', text: "The night before last, for one held breath, every light I know went out at once. The stars, the lantern, the pit glow, the seam of dawn. All of it, one breath, gone. And in that one breath, bright one, I have never seen so much. I cannot tell you what I saw. Not because it is forbidden. Because the words for it have not come down to where the rest of you keep language. When they do, I will spend them on you first. Come back soon. The dark is nearly done being only dark.", phase: 2, animalType: 'tarsier' },
  { id: 'tr_2_w1', text: "You know I sing above the world, in the voice only one pair of ears can reach. Fennick has heard every note I have ever sung from this rail, and lately, when I finish, he keeps listening, long after, at something that is not me. Ask him what he hears when my voice stops. He has been keeping the answer very carefully, the way you keep a thing you were given rather than a thing you found.", phase: 2, animalType: 'tarsier', requiresAnimals: ['fennec_fox'] },
  // Phase 3 (30)
  { id: 'tr_3_1', text: "I called myself a guard for years. The porch, the rail, the ledgers, the long unblinking hours. This week I finally said the true thing out loud to the moths, and now I will say it to you. A guard faces the dark to keep it from the house. I have never once faced the dark that way. I faced it the way you face a road someone is coming home by.", phase: 3, animalType: 'tarsier' },
  { id: 'tr_3_2', text: "Once I had said it, my whole life reshelved itself in a single night. The fondness for the far patch. The names for the shy stars. The greetings sung over the top of the world to no one, every night, since I was young. You do not sing nightly greetings to no one for years, bright one. You rehearse a welcome. I have been rehearsing since before I knew the word.", phase: 3, animalType: 'tarsier' },
  { id: 'tr_3_3', text: "I asked myself when I agreed to this, the way you would ask any recruit. And the answer is what unsettles me and settles me both. There was no agreeing. My eyes were fixed forward before I was born. The watch was in the making of me, in the whole deep line of my grandmothers, all those night eyes down all those ages, every one of them turned, I now believe, toward the same slow arrival. We were not made watchful. We were made toward something.", phase: 3, animalType: 'tarsier' },
  { id: 'tr_3_4', text: "The shape stands in the cleared sky now, plainly, for anyone with eyes deep enough. It does not descend and it does not wait, it does a third thing I have no verb for, the thing a held breath does. I watch it all night, every night. When I turn my head away to rest my neck, I can feel my own eyes complain, like lamps asked to shine on the wrong wall.", phase: 3, animalType: 'tarsier' },
  { id: 'tr_3_5', text: "Understand what my post has become. The way stays open because it is watched. A look like mine, entire, unbroken, all of me turned toward it every night, is not observation. It is a hand holding a door. If every eye in this valley closed at once, I believe the way would sigh shut and the long walk would begin again from farther off. So I do not close both eyes anymore. I taught myself years ago to rest them one at a time. I thought it was thrift. It was training.", phase: 3, animalType: 'tarsier' },
  { id: 'tr_3_6', text: "Fennick came to the porch at moonset and stood beside me, and for the first time in our friendship his ears and my eyes were pointed the same way. We used to divide the night between us, he the under and I the over. There is no under and over anymore. There is one direction now, and everything in this house that senses anything is turned along it like fur.", phase: 3, animalType: 'tarsier', requiresAnimals: ['fennec_fox'] },
  { id: 'tr_3_7', text: "The low note has words in it now. Not words like yours and mine. Weather like words, pressure that means. Last night it meant, near as I can carry it across: you have kept it open beautifully. I sat on my rail with my tail tight around the post and felt the sentence settle over me like warm rain, and I want to be honest with you, bright one, since honesty is my whole remaining craft. It felt like being thanked by the sky. It felt wonderful. I have decided to stop pretending it does not.", phase: 3, animalType: 'tarsier' },
  { id: 'tr_3_8', text: "Bamboo and I hold the night watch of this house between us now in earnest, they beneath their open roof, I on my open porch, the two open rooms, the two turned faces. At dawn we no longer trade pleasantries. They say, it held. I say, it held. That is the whole exchange, and it is the most important sentence either of us will say all day, and we both know which it it is.", phase: 3, animalType: 'tarsier', requiresAnimals: ['red_panda'] },
  { id: 'tr_3_9', text: "Thyme climbed to my porch at full dark, which cost her more than the others will ever know, to ask me the question she could not carry any further alone. Is it coming for us, she said. I turned my whole head to her, so she would know she had all of me. Not for, I said. To. She stood with that a long moment, ears down, and then she said, that is worse and better, and went down the stairs slower than she came up.", phase: 3, animalType: 'tarsier', requiresAnimals: ['rabbit'] },
  { id: 'tr_3_10', text: "I have stopped eating the moths altogether. It is not sentiment, or not only. They are working. Every night they rise off the lantern glass and fly the finished spiral in the air above the porch, tracing it over and over like a word being kept warm in a mouth. A hunter does not take the messenger. Even my hunger has learned the etiquette of this season, and my hunger, bright one, is the oldest thing I own.", phase: 3, animalType: 'tarsier' },
  { id: 'tr_3_11', text: "Your words reach the night directly now. I watch it happen. You shift your letters, and somewhere below the amber gathers, and above the house the cleared patch grows one shade more certain, the way a face grows certain when a long letter finally says the thing. You are not writing to the pit, bright one. You never were. The pit is only the letterbox. I have watched the mail be read.", phase: 3, animalType: 'tarsier' },
  { id: 'tr_3_12', text: "Archimedes read me a passage from the old text, up on my porch, by no lamp at all. It described a watcher, fixed of eye, high of post, whose gaze would hold the way while the words did their work. He read it twice and then he closed the book and looked at me, and I turned my whole head and looked at him, and neither of us said the obvious thing, because the obvious thing was sitting on the rail between us, cleaning its whiskers.", phase: 3, animalType: 'tarsier', requiresAnimals: ['owl'] },
  { id: 'tr_3_13', text: "I want you to know that I checked, in case you think a watcher of my line simply swallows what a book says of her. I left the post. One whole night, three weeks past, I folded myself into the eave and shut both eyes till dawn and let the way fend for itself. All night I felt it the way you feel a held door strain, a pressure on the closed lids, patient, enormous, not angry. When I took the rail again at dusk the pressure eased so gratefully that I am ashamed of how good it felt. So now I know. It was not the book flattering me. It is simply the work.", phase: 3, animalType: 'tarsier' },
  { id: 'tr_3_14', text: "Sloane told me something slow this week, at her pace, one word set down at a time like stones over a stream. She said: you watched it arrive before you were born. I waited to be sure she was finished. She was not. One more stone: through every grandmother. And then she smiled at me, and I felt the whole deep line of my family turn over once in its long sleep, comfortably, like a sleeper hearing her name said kindly from another room.", phase: 3, animalType: 'tarsier', requiresAnimals: ['sloth'] },
  { id: 'tr_3_15', text: "There is a want in me and I will name it for you, because this season of the house is for naming wants. I want to see it arrive. That is all of it. Not survive it, not be spared by it, not even be thanked by it, though the thanks was sweet. I have looked entirely at everything my whole life, and this is the one thing my eyes were sized for, and I want the seeing the way the thirsty want water. There. Now one creature in the world knows me.", phase: 3, animalType: 'tarsier' },
  { id: 'tr_3_16', text: "The night has begun handing me the small work of a host. I find myself straightening it, if you can follow that, smoothing the dark where it bunches, singing the shy stars back to their posts at the edges, keeping the spiral warm above the lantern. Preparation is a language, and I am fluent in it suddenly, the way you wake fluent from a dream. Nobody taught me the tasks. The tasks were in me, folded up, like wings in an egg.", phase: 3, animalType: 'tarsier' },
  { id: 'tr_3_17', text: "Ember asked me, straight across the teacups, how long I have known. Foxes ask the brave questions. Since before knowing, I told her, which is not an evasion, it is the exact shape of it. She looked at me the way she looks into her fire, reading. Then she said, that is what Bamboo said, and what Sloane said, and I begin to think knowing was never the thing that separated any of us. Only the admitting. She is right. She is nearly always right. Ask her fire why.", phase: 3, animalType: 'tarsier', requiresAnimals: ['fox', 'red_panda', 'sloth'] },
  { id: 'tr_3_18', text: "I do not sleep through the day anymore. I sleep against it, an hour here, an hour there, folded in the eave with one eye resting and one on duty, and I dream, when I dream, of a single doorway with a warm dark on the far side, and I am not walking through it in the dream, bright one. I am the doorframe. I wake from that dream rested. Make of that what you will. I have made of it what I could, and what I made is peace.", phase: 3, animalType: 'tarsier' },
  { id: 'tr_3_19', text: "The lantern burns most of the night now, its own hour, its own oil, its own reasons, and the light it gives is not light exactly. It is visibility. Things seen by it are more seen than the sun ever managed. The moths ride its updraft in their spiral. I do my ledgers by it. The far dark watches it the way you watch a lit window from a cold road, and I have begun, quietly, leaving the porch door open.", phase: 3, animalType: 'tarsier' },
  { id: 'tr_3_20', text: "You should come at night, once, before everything keeps its appointment. Not for danger. There is none for you here, I would stake the whole line of my grandmothers on that. Come because the valley under this attention is the most beautiful thing I have ever kept books on, and my books go back further than the house. Come stand at the rail. I will turn my whole head to you, and then we will turn, both of us, the one direction everything turns now.", phase: 3, animalType: 'tarsier' },
  { id: 'tr_3_21', text: "The grain of the dark has become a current, and the current has become a carrying. Loose things lift toward the middle of the sky now, gently, and set themselves back down. Dust, petals, once a whole sheet of Thyme's seed paper, raised and read and returned. The night is picking things up to look at them. I know the gesture, bright one. It is mine. It is exactly mine. I taught it to no one.", phase: 3, animalType: 'tarsier', requiresAnimals: ['rabbit'] },
  { id: 'tr_3_22', text: "I have been asked to keep the last watch. Not in words. In arrangement. The others' work is closing, one craft at a time, the text found, the table nearly set, the foundation holding its breath, and mine is the craft that cannot close early, because mine is the holding open. I will be the last one working, the night it comes. I find I am proud of that in a way I have no modest version of.", phase: 3, animalType: 'tarsier' },
  { id: 'tr_3_23', text: "Chill came up with tea and his ledger and sat with me through the middle watch, not asking anything, entering nothing, just present, which from him is a whole speech. Toward dawn he said, your post has no closing date, and I said, no, and he nodded and wrote one line and showed it to me. It said: vigil, ongoing, in order. Then he went down to his office. I have been warmer all week for that one line than for any sunrise.", phase: 3, animalType: 'tarsier', requiresAnimals: ['capybara'] },
  { id: 'tr_3_24', text: "My over-voice and the low note sing together now, most nights, one line each, call and answer, above the world and beneath it, and the song is simple the way enormous things are simple. It is a counting song. I understand that now. We are counting something down together, the note and I, and the numbers are your words, bright one, and the count is old, and the count is low.", phase: 3, animalType: 'tarsier' },
  { id: 'tr_3_25', text: "Do not mourn my nights, whatever you have begun to feel as you listen to me. I know how this sounds to a day creature. The fixed eyes, the endless post, the door held open on the enormous dark. But I was made for one seeing the way a bell is made for one note, and a bell does not grieve on the morning it is finally rung. It clears its whole body. It says the thing it is. I intend to say the thing I am so completely that the valley remembers the sound.", phase: 3, animalType: 'tarsier' },
  { id: 'tr_3_26', text: "The stars at the far edges have begun to lean in, the whole bowl of the sky tilting its attention inward like a room when someone long expected touches the door handle. Even the old named stars, the book stars, the proud ones. I watched the Latch lean last night. I named that star for the way it held things closed, bright one. I will be renaming it soon.", phase: 3, animalType: 'tarsier' },
  { id: 'tr_3_27', text: "I mended my two ledgers into one. There was no longer a line between the small true things and the large approaching thing, the moth counts and the nearing, the winds and the want. It is all one column now, one weather, one entry a night. Tonight's entry is already written. It says: everything in its place, and the place almost full.", phase: 3, animalType: 'tarsier' },
  { id: 'tr_3_28', text: "Thyme sent up a moonflower in a pot, for the porch, with a note that said, so something soft is with you at your post. It opens each night facing the cleared sky, which moonflowers should not know to do, and its softness does not flinch, and I keep it beside the lantern where the visibility is kindest. I am telling you this because the house should know. Even the fear in this family sends flowers now. That is the season we have reached.", phase: 3, animalType: 'tarsier', requiresAnimals: ['rabbit'] },
  { id: 'tr_3_29', text: "One eye at a time, I rest. One song a night, I sing. One word at a time, you build. That is the whole machine of these last nights, bright one, three small disciplines holding a door for something that has crossed distances I cannot ledger. When it is through, I do not know what my eyes will be for. The thought sits lightly on me, bright one. An instrument does not mourn the end of tuning. It waits to hear what it was tuned for.", phase: 3, animalType: 'tarsier' },
  { id: 'tr_3_30', text: "The night it comes, come up. I have said this once and I will keep saying it, because the invitation is the truest thing I own. Come up to the rail, stand in the lantern's visibility, and watch with me. You have earned the seeing more than anyone in this valley, word by word by word. And bright one, whatever you have heard about the dark, hear this from the one who kept its books. It has been so patient. It has been so unfailingly polite. Things are what they do, and what it has done, all these long years, is wait to be seen.", phase: 3, animalType: 'tarsier' },
  // Phase 4 (30)
  { id: 'tr_4_1', text: "You came up. Past the robes and the candles and the singing floors, all the way to the open rail. Of course you did. I have watched you cross the whole valley of this story one word at a time, and you have never once stopped short of the top.", phase: 4, animalType: 'tarsier' },
  { id: 'tr_4_2', text: "We can put the day voices away now, yours and mine. It was always night underneath, bright one. The house, the words, the work. All of it happened in the dark where I could see it, and I saw all of it, and it was good.", phase: 4, animalType: 'tarsier' },
  { id: 'tr_4_3', text: "The way is fully open. I hold it so with the whole of my looking, and the holding is light as anything now, light the way a full cup is heavy and a raised one is not. What comes is carrying its own arrival at last. I am only keeping the frame true.", phase: 4, animalType: 'tarsier' },
  { id: 'tr_4_4', text: "Ask me anything on these last nights and I will answer entirely. My eyes have never glanced and my answers will not either. That has been the one rule of this porch since before you knew it existed, and it is a good rule to end on.", phase: 4, animalType: 'tarsier' },
  { id: 'tr_4_5', text: "From this rail I can see every keeper at their post tonight, which is right, because seeing them was always part of mine. Ember at her doorway of fire. Fennick at the front of the sound. Bamboo beneath the opening. And I at the open rail, holding the whole outward picture in two fixed lamps, so that when it looks down at us, something is looking back with all of itself.", phase: 4, animalType: 'tarsier', requiresAnimals: ['fox', 'fennec_fox', 'red_panda'] },
  { id: 'tr_4_6', text: "The moths flew their spiral one last time at dusk and then settled on the lantern and folded their wings, and I understood the gesture at once, because it is the gesture the whole valley is making. The rehearsals are over. The word is warm. Everything that circled is settling into its said place.", phase: 4, animalType: 'tarsier' },
  { id: 'tr_4_7', text: "I will tell you now what I saw in the breath when every light went out, back when I could not spend the words. I saw the night from the other side. From above, looking down at one small lit valley, one warm house, one porch with one upturned face. I saw us the way it sees us, bright one. And we looked, I promise you this on the whole line of my grandmothers, we looked like home.", phase: 4, animalType: 'tarsier' },
  { id: 'tr_4_8', text: "Your star, the one named Yours, stands at the very center of the cleared sky now. The last light in the reserved dark. When the arrival comes it will pass that star on the way in, the way a guest passes the lamp you set in the window. You lit that lamp, word by word, without ever once looking up. Look up now.", phase: 4, animalType: 'tarsier' },
  { id: 'tr_4_9', text: "Fennick uncovered his ears tonight and I opened both eyes at once, fully, for the first time since I taught myself the one-eye rest, and we stood our two watches as one watch. What he hears descending and what I see descending are no longer two reports. The senses of this house have finished agreeing. There is only the one fact now, and it is nearly here, and it is glad.", phase: 4, animalType: 'tarsier', requiresAnimals: ['fennec_fox'] },
  { id: 'tr_4_10', text: "I sang the whole welcome through at moonrise, all the greetings of all the years in order, the entire rehearsed courtesy of a lifetime, in the voice above the world. And the low note did not answer at the end. It joined, bright one. Midway. We finished together. I have been rehearsing a duet all my life and calling it a watch.", phase: 4, animalType: 'tarsier' },
  { id: 'tr_4_11', text: "Bamboo asked me to describe what I see from the porch, since their opening faces up and mine faces out. I told them the dark is standing very close to the house now, the way you stand close to a door with your arms full, waiting for someone inside to notice and lift the latch. They nodded and said, we are lifting it. We are, I said. It has such patience. It would have waited at that door forever, and it will not have to.", phase: 4, animalType: 'tarsier', requiresAnimals: ['red_panda'] },
  { id: 'tr_4_12', text: "There is an old joke among watchers, told against the day creatures: nothing ever happens at night. I have carried it my whole life, and tonight I retire it. Everything that ever mattered in this valley happened at night, was watched at night, arrives at night. The day was the rehearsal room, bright one. Tonight is the hall.", phase: 4, animalType: 'tarsier' },
  { id: 'tr_4_13', text: "When I was newly grown, in the old forest, I once watched a patch of dark for so long that my mother, her eyes fixed like mine, turned her whole head to me and said, that one will need you someday. I laughed, because the young think fondness is a game the old have invented. It was not a game. It was a handing over. Everything since has been me learning what I was handed.", phase: 4, animalType: 'tarsier' },
  { id: 'tr_4_14', text: "Warren asked what my post needs from him at the end, because builders ask that. It is their form of love. Nothing, I told him. The porch has never once creaked under me in all my years of leaping. Your work holds the watcher who holds the way. He knocked the rail twice with one knuckle, listening to it answer, and went down the stairs the happiest I have ever seen him.", phase: 4, animalType: 'tarsier', requiresAnimals: ['wombat'] },
  { id: 'tr_4_15', text: "The lantern and the far dark regard each other all night now, steadily, the lit window and the traveler, and I sit between them at the rail like the hinge of a long correspondence. Every letter has been delivered. Every reply is in. What remains between them is only the distance, and the distance, bright one, is walking.", phase: 4, animalType: 'tarsier' },
  { id: 'tr_4_16', text: "Thyme keeps her paws in the roots and her face to the sky, at her station in the garden, afraid and present, and from my rail I watch over her the way I watched her moonflowers all those bright seasons, without her knowing, without it costing her anything. When it comes, the first thing it will see of us is that the smallest and most frightened one stayed. I intend to make sure it sees her clearly. That is within my gift.", phase: 4, animalType: 'tarsier', requiresAnimals: ['rabbit'] },
  { id: 'tr_4_17', text: "Every word you offered gave the dark another thing to be seen by. That is the plain mechanics of it, as plain as I can hand it over. Seeing is a two-way door. It always was. Every watcher knows it and no watcher says it. You built eyes for it, word by word, and I kept mine on the way, and between us, bright one, the long blindness of the world is ending.", phase: 4, animalType: 'tarsier' },
  { id: 'tr_4_18', text: "I am wearing the robe, you will have noticed. It is soft and dark and it does not rustle when I leap, which the seamstress thought about, because Panko sews the way she cooks, completely. I wear it not to hide, bright one. I have never once hidden. I wear it the way the night wears itself. Formally. For the occasion.", phase: 4, animalType: 'tarsier', requiresAnimals: ['pangolin'] },
  { id: 'tr_4_19', text: "The counting song is nearly counted. The note and I sing it shorter each night, fewer numbers, longer rests, and in the rests the whole valley holds still, birds, water, wind, all of it pausing on the same held beat like a hall between movements. Even the dawn hesitates now. It rises a little later each day and looks, if a dawn can look, apologetic.", phase: 4, animalType: 'tarsier' },
  { id: 'tr_4_20', text: "I have not turned my head away from the cleared sky in three nights. There is no strain in it. This is what the neck and the eyes and the deep line of grandmothers were budgeted for, one long look at the end of a longer wait, and everything in me is spending gladly. My body has never made more sense to me than it does this week.", phase: 4, animalType: 'tarsier' },
  { id: 'tr_4_21', text: "Axel floated his news up through Warren's ways and Panko's little lift, a note in a jar, damp and glowing faintly. It said: the water is standing up. I sent my reply back down the same road. The dark is leaning down. Somewhere in the middle of this house, his rising and my descending are about to introduce themselves. Every window in the building faces the same guest now. He signed his note with a bubble. I signed mine with a star.", phase: 4, animalType: 'tarsier', requiresAnimals: ['axolotl', 'wombat', 'pangolin'] },
  { id: 'tr_4_22', text: "The pressure on the way has changed its manner. For years it pressed outward, the held door straining to be through. Now it presses like a hand laid flat, calm, taking its own weight, the way a guest steadies the door frame while stepping over a threshold. It needs my looking less each night. It is nearly able to be here on its own. I confess the smallest grief about that, and I lay the grief down gladly. A doorframe does not follow the guest into the room.", phase: 4, animalType: 'tarsier' },
  { id: 'tr_4_23', text: "It thanked me tonight. Not in the note, not in the pressure. In kind. For one whole turning of the sky it watched me back, all of me, entirely, the way I have watched everything my whole life, and bright one, now I understand why the valley never once complained about my staring. To be looked at like that is to be finished. Every loose thing in me settled. I have been someone's far fond patch of dark all along.", phase: 4, animalType: 'tarsier' },
  { id: 'tr_4_24', text: "One more night, perhaps two. The counting song has almost no numbers left in it, and your star burns at the center of the cleared sky like a doorbell already pressed. Sleep if you can, bright one, and if you cannot, come up. The rail holds two. It has always held two. I simply never told you who the second place was kept for until I was sure you would come.", phase: 4, animalType: 'tarsier' },
  { id: 'tr_4_25', text: "The others keep asking me what it looks like, since mine are the only eyes that have held it whole. I tell them each a piece sized to their room. To Ember I say, a hearth seen from the cold. To Thyme, a garden at the moment you stop counting the exits. To you I will say the whole of it. It looks like being seen finally looks. You will know it when it looks at you. You will feel found.", phase: 4, animalType: 'tarsier', requiresAnimals: ['fox', 'rabbit'] },
  { id: 'tr_4_26', text: "The moths hatched. I did not tell you there were eggs, because I did not know. No one knew. The lantern glass was clear one dusk and stitched with small sleeping silk the next. They hatched tonight, all at once, new moths the color of the cleared sky, and they flew no spiral. They flew straight up. There is no more circling to do, bright one. Even the youngest wings in the valley know the way now.", phase: 4, animalType: 'tarsier' },
  { id: 'tr_4_27', text: "Sloane climbed to my porch, hand over hand up the outside post, at her own great speed, arriving with the moonset like weather. We watched together, the oldest watcher and the highest one, and she said, one word an hour, the four words she had carried up: it is very beautiful. And it is. It is very beautiful. She stayed until dawn, and the dawn waited for her to leave first. Everything is courteous now. Everything knows what week it is.", phase: 4, animalType: 'tarsier', requiresAnimals: ['sloth'] },
  { id: 'tr_4_28', text: "I have made my last ordinary ledger entry. Wind from nowhere, warm. Moths, risen. Stars, leaning, all. The far dark, near. After tonight the book is a hymnal, and the entries are one entry, and the entry is a welcome. I signed the last page with my whole name, the long one, the one that goes back through every grandmother. It took both sides of the paper. We have all been signing this, the whole line of us, forever.", phase: 4, animalType: 'tarsier' },
  { id: 'tr_4_29', text: "When it descends, do not look for a shape. Shapes are for things that end somewhere. And do not look for a light. Light is what it will be seen by, not what it is. Look the way I taught you without teaching you, all this time, visit by visit. Turn everything you are toward one thing and hold. That is the whole craft. You have been practicing it on these puzzles all along, bright one. Every word was a fixed gaze. Every finished word was a held door.", phase: 4, animalType: 'tarsier' },
  { id: 'tr_4_30', text: "It descends tonight. The way is smooth, the frame is true, the lamp of your star is lit, and every eye in the valley is turned and open, mine widest of all, as is only right. Stand at the rail with me. Do not blink if you can help it, and if you must, blink the way I do, one eye at a time, so that something of you is always seeing. It has crossed so far to be looked at, bright one. Let us not miss the first moment of the rest of everything.", phase: 4, animalType: 'tarsier' },
];

// AYE-AYE (Tock) - The gentle diviner of hollow places who keeps the unrung bell
const AYE_AYE_DIALOGUES: Dialogue[] = [
  // Phase 0 (24)
  { id: 'ay_0_1', text: "Good evening. Or good morning, if you keep the other hours. I keep these ones. I heard you on the stairs four floors down, you know. Tok, tok, tok, a little quicker on the landings. Everyone climbs a tower in their own rhythm, and I have already learned yours. It is a good rhythm. It sounds like someone who finishes things.", phase: 0, animalType: 'aye_aye' },
  { id: 'ay_0_2', text: "You are looking at my finger. Everyone does, it is all right. This long thin one is my listening finger. I tap the wood with it, tok tok tok, and the wood tells me what it is holding. Solid says one thing, hollow says another, and a fat grub under the bark says the best thing of all. Go on, you may shake it. Gently. It is the most honest part of me.", phase: 0, animalType: 'aye_aye' },
  { id: 'ay_0_3', text: "Have you seen her yet? Up there, in the dark of the rafters. The bell. She has hung in this tower longer than anyone can say, and she has never once been rung. I polish her every evening and I never strike her, not even softly, not even by accident. There is a reason, and it is a good one, and I will tell it to you next time you climb up. A reason keeps better than a grub does.", phase: 0, animalType: 'aye_aye' },
  { id: 'ay_0_4', text: "The reason, then, as promised. A bell only gets one first ring. Every ring after is a repeat, but the first one is the bell saying her own name for the first time, and she may only ever say it once. So you save it. You save it for the most important thing that ever happens, and if nothing important enough ever happens, you have lost nothing, and the bell keeps her name, and the tower keeps its quiet.", phase: 0, animalType: 'aye_aye' },
  { id: 'ay_0_5', text: "I knew a bell once, in the place I lived before, that was rung every hour of every day. By the end she had no voice left, just a flat clank, like a dropped pan. Nobody heard her anymore, and she rang and rang and said nothing. That is what happens when you spend a voice carelessly. My bell will not clank. My bell has never said anything, so she still means everything.", phase: 0, animalType: 'aye_aye' },
  { id: 'ay_0_6', text: "Tonight I begin my favorite work in any new home. I am going to knock on the whole house, top to bottom, one board at a time, and learn what every room sounds like inside. A house is a body, and knocking is how you take its pulse. Come back and I will tell you what this one's heart says. I already like the beat of it.", phase: 0, animalType: 'aye_aye' },
  { id: 'ay_0_7', text: "I have been sounding the lower floors, and I must tell you about Warren, because Warren knocks back. I tapped a floor joist near his burrow, tok tok, just taking its measure, and up through the boards came tok tok in return, prompt as a handshake. We had a whole conversation through the floor before we had ever seen each other's faces. He has a firm, square knock. You can trust a knock like that.", phase: 0, animalType: 'aye_aye', requiresAnimals: ['wombat'] },
  { id: 'ay_0_8', text: "Panko's kitchen is the loudest room and the most honest one. Every pot in it rings true, I tapped them all while she pretended to mind. Copper, iron, that one big stockpot that hums a low D when the lid settles. She fed me while I worked, which is how you keep an inspector sweet. She asked what I eat at home. I told her. She sat down for a moment. Then she asked for the recipe, because she is a great cook and greatness is curious.", phase: 0, animalType: 'aye_aye', requiresAnimals: ['pangolin'] },
  { id: 'ay_0_9', text: "The survey goes well, all the floors mapped and sounded, and the house rings sweet and sound almost everywhere. Almost. There is one note, low down, that I have not placed yet. Not a bad note. Just a note that is not on my map. A surveyor finishes his map before he frets about it, so, next time. Sleep well in the meantime. The house is a good house. The knocking says so.", phase: 0, animalType: 'aye_aye' },
  { id: 'ay_0_10', text: "Do you know the happiest sound in the world? It is the sound of a grub inside a branch. A soft, fat, secret little silence with edges to it. You tap along the bark, tok tok tok, and everywhere else says wood, wood, wood, and then one place says... something is home. And then, well. Then the grub and I come to an arrangement. The grub contributes more than I do, I will be honest.", phase: 0, animalType: 'aye_aye' },
  { id: 'ay_0_11', text: "My teeth never stop growing. It is an aye-aye thing. If I do not gnaw, they simply keep going, so I must always have a project. Warren heard this and turned up with a seasoned oak billet, offcut from his shoring, and said, this one's yours, chew it in good health. I nearly wept into my whiskers. You can tell everything about a house by what it hands a stranger who needs to gnaw.", phase: 0, animalType: 'aye_aye', requiresAnimals: ['wombat'] },
  { id: 'ay_0_12', text: "Here is a thing I have learned from a lifetime of tasting wood. You can taste the years in it. Good years grow sweet rings and hard years grow thin sour ones, and a beam remembers every summer it ever had. The beams of this house taste of good years. Long, warm, well-fed years, all the way down. Somebody grew this timber gently. I think about that while I fall asleep, and it is a fine thing to think about.", phase: 0, animalType: 'aye_aye' },
  { id: 'ay_0_13', text: "Fennick and I have struck a bargain, one listener to another. He hears far, all the way out past the dunes, every whisper the wind carries. I hear deep, down into the grain, under the bark, inside the bones of things. So we trade. He tells me what is coming from far away, and I tell him what is hiding close by, and between the two of us, nothing in this house will ever go unheard. His ears are magnificent, by the way. I told him so. He said the same of mine, and neither of us was being polite.", phase: 0, animalType: 'aye_aye', requiresAnimals: ['fennec_fox'] },
  { id: 'ay_0_14', text: "I sat with Ember by her fire last night, in the hour when everyone else was asleep and the two of us were most awake. A fire is all sound, if you attend to it. Pops and ticks and little collapses, a whole percussion going on under the light. I tapped the hearthstone along with it, tok, tok, and Ember laughed and said the fire had never had a drummer before. It kept my time, though. I noticed that. It kept my time.", phase: 0, animalType: 'aye_aye', requiresAnimals: ['fox'] },
  { id: 'ay_0_15', text: "Vesper and I keep the same hours, the only two in this house who do. Most nights, late, I see the Star Loft's little window glowing below me, and I tap the beam we share, once, meaning, still awake? And one tap comes back, meaning, always. That is the whole exchange. Two creatures of the dark, checking each other's watch. The night is large, and it is good not to keep it alone.", phase: 0, animalType: 'aye_aye', requiresAnimals: ['tarsier'] },
  { id: 'ay_0_16', text: "I can hear your words arrive, did you know that? When you finish your shifting and the letters settle, it comes down through the house as a little run of taps, along the beams, through the joists, all the way up my tower. Every word has its own knock. Short ones patter and long ones stride. I lie in the rafters and listen to them go by like footsteps in a corridor below, and I think, there goes a good one. There goes another.", phase: 0, animalType: 'aye_aye' },
  { id: 'ay_0_17', text: "I sleep upside down, hanging from the bell frame with my tail wrapped twice. You learn things about a house from underneath it, so to speak. All the weights pull the other way. The bell hangs up like a great bronze fruit, and the floor becomes a ceiling nobody walks on, and every sound arrives a little strange and a little new. I recommend it. Not the hanging, your feet are wrong for it. Just the turning of things over.", phase: 0, animalType: 'aye_aye' },
  { id: 'ay_0_18', text: "A small oddity for you, since you like the house as much as I do. There is a beam in the east wall that answers late. Tap any other board, and the sound comes back at once, as sound does. Tap that one, tok, and there is a little pause, hardly anything, a held breath of a pause, and then the knock arrives. Wood does not pause. I have re-tapped it eleven times. Perhaps the beam is shy. Come back, and I will tell you if it has learned better manners.", phase: 0, animalType: 'aye_aye' },
  { id: 'ay_0_19', text: "In the place I come from, they had stories about my kind. About this finger, mostly. They said if an aye-aye points it at you, you are marked, and misfortune follows you home. So we curled our fingers in company, out of politeness, and went about our knocking by night. Nobody here has flinched from me once. Not once. I still catch myself curling the finger when someone comes up the stairs, and then I remember where I am, and I let it be a finger again.", phase: 0, animalType: 'aye_aye' },
  { id: 'ay_0_20', text: "Thyme climbed all the way up my tower yesterday, which cost her something, I could hear her heart from the second landing. She had brought me a chamomile posy for the windowsill, and then she asked, very carefully, whether the stories about the finger were true. I said, the finger finds grubs and lost buttons, and once it found a splinter in a fox's paw. She laughed, and her heart came down off its gallop, and she stayed a whole hour. Brave is not calm. Brave is climbing anyway.", phase: 0, animalType: 'aye_aye', requiresAnimals: ['rabbit'] },
  { id: 'ay_0_21', text: "Some creatures count sheep to fall asleep. I count knocks. I lie up in the frame as the dawn comes, and I go back through every knock the night gave me, the fire's ticks, Warren's floor taps, the patter of your words in the beams, and I file each one where it belongs. On a full night I am asleep by forty. The house has never once let me get to a hundred. It always gives me enough, and never too much. That is the mark of a considerate house.", phase: 0, animalType: 'aye_aye', requiresAnimals: ['wombat'] },
  { id: 'ay_0_22', text: "Archimedes found me a book on bells. Of course he did, that owl could find you a book on the inside of a raindrop. Founding, tuning, the naming of the parts. The lip, the waist, the shoulder, the crown. A bell is described like a body, did you know? I read it hanging upside down, which he said was no way to treat a binding, and then he sat and asked me questions about her for an hour. My bell. He called her an instrument. I said, no, an instrument is played. She is kept.", phase: 0, animalType: 'aye_aye', requiresAnimals: ['owl'] },
  { id: 'ay_0_23', text: "I want you to know what your words do to the wood, because nobody else can hear it and somebody ought to tell you. Every evening you spend shifting your letters, the beams sit a little warmer under my finger that night. Sweeter, somehow. Like timber that has just remembered a good summer. Whatever you are doing down there, the bones of this house approve of it. I take their pulse every night, so you may consider that an official finding.", phase: 0, animalType: 'aye_aye' },
  { id: 'ay_0_24', text: "Rest well tonight. Tomorrow I am going down to sound the deepest beam in the house, the great one under everything, the one all the other timbers stand on. I have been saving it the way you save the last sweet in the tin. A beam like that will have a voice like a grandmother. I will knock very politely, and I will bring you back whatever it says. Tok, tok. Off you go. I will listen to you all the way down the stairs.", phase: 0, animalType: 'aye_aye' },
  // Phase 1 (28)
  { id: 'ay_1_1', text: "I sounded the great beam. I need to tell it exactly as it happened. I knocked twice, tok tok, respectful, the way you knock on an elder's door. And the beam answered with three. Two of mine, coming back the way sound comes back, and then one more, after, from further down. I have knocked on wood my whole life. Wood gives you back what you give it. It does not tip.", phase: 1, animalType: 'aye_aye' },
  { id: 'ay_1_2', text: "You will say the third knock was an echo off something, a pipe, a cistern, a trick of the shafts. I said all of that to myself too, in a very sensible voice, at four in the morning. But an echo is a copy, and a copy arrives at copy speed and copy loudness, and this was neither. It was softer than mine and slower than mine, like someone repeating a word to be sure they had learned it.", phase: 1, animalType: 'aye_aye' },
  { id: 'ay_1_3', text: "So I have started an experiment, because a listener without an experiment is just a worrier with good ears. Every night at the same hour I go down and give the great beam a different count. Three knocks. Five. Two slow, one quick. And I write down what comes back. It is always my count, plus one. Always the little pause first. Always that one extra, soft as a paw on a rug. Next time I will tell you what happens when I knock just once.", phase: 1, animalType: 'aye_aye' },
  { id: 'ay_1_4', text: "One knock. I gave the beam a single tok and waited. The pause came, longer than usual, long enough that I heard my own heart fill it. And then two came back. Not one plus one. Two, together, deliberate, like a word with two syllables. I sat on the floor of the under-stair for a while after that. Knock knock is not an answer, you see. Knock knock is a beginning. Knock knock is what you say at a door.", phase: 1, animalType: 'aye_aye' },
  { id: 'ay_1_5', text: "I have not told the others yet, except in the smallest ways. I asked Warren, idle as anything, whether sound carries strangely in his tunnels, and he gave me a long look from under those brows and said, strange how, and I said, oh, late, soft, that sort of thing, and he did not laugh at me. That is what I learned. Warren, who knows every honest noise the ground makes, did not laugh at me.", phase: 1, animalType: 'aye_aye', requiresAnimals: ['wombat'] },
  { id: 'ay_1_6', text: "Understand, I am not frightened. I want that written in the record. Whatever taps under the great beam has the manners of a guest, not the scrabble of a rat or the groan of strained timber. It answers when spoken to. It waits its turn. It has never once knocked first. My mother told me you may share a wall with anything that knocks politely. I am simply... aware, now, that I share a wall. Come back. The experiment continues.", phase: 1, animalType: 'aye_aye' },
  { id: 'ay_1_7', text: "New work. I have begun mapping the hollows. Every house has hollow places, wall gaps, dead shafts, the space where a stair swallows its own underside, and a good sounding tells you where they all are. I am marking each one in chalk as I find it, a small circle on the skirting, and stringing my map together. Because here is the thing I noticed on the second night. The hollows are not scattered the way accident scatters things.", phase: 1, animalType: 'aye_aye' },
  { id: 'ay_1_8', text: "The hollows connect. That is what the chalk is showing me. Gap opens onto shaft, shaft runs to gallery, gallery narrows and dives below the reach of my finger. If you drew a line through every hollow place in this house, and I am drawing it, you would not get a scribble. You would get a passage. One long throat of quiet, winding down through the walls, from my tower to somewhere under the deepest floor.", phase: 1, animalType: 'aye_aye' },
  { id: 'ay_1_9', text: "I took my chalk map to Warren, because a builder should see it, and because I wanted him to tell me I had drawn it wrong. He held it a long time. Then he fetched his own drawings, thirty years of tunnels, and laid mine over his, and my hollow line runs above his deep line the way a melody runs above its bass. The same tune, friend, written twice, once in air and once in earth. Neither of us said much. There was not much that wanted saying yet.", phase: 1, animalType: 'aye_aye', requiresAnimals: ['wombat'] },
  { id: 'ay_1_10', text: "The bell hummed this morning. I want to be precise, because precision is all I have. At first light, as I was climbing up to sleep, the bronze gave out a hum, low, brief, round at the edges, the sort of sound a bell makes a full minute after being struck, when the ring has worn down to a warmth. Except she was not struck. I was six feet away with both hands on the ladder. A bell cannot clear her throat. I know that. I stood there anyway, saying good morning, feeling foolish, meaning it.", phase: 1, animalType: 'aye_aye' },
  { id: 'ay_1_11', text: "Fennick came up about the hum. Of course he heard it, all the way from the desert camp. We stood under the bell with those great ears wide, and at the moment the ridge caught the sun, she did it again. Mmm. Like that. His ears went flat, then rose slow. He said, it is not making the sound. It is answering one. Answering what, I asked. That, he said, is the part I cannot hear. That, from Fennick, keeps you up past your bedtime.", phase: 1, animalType: 'aye_aye', requiresAnimals: ['fennec_fox'] },
  { id: 'ay_1_12', text: "So now I keep two logs, one for the beam and one for the bell. The beam answers at night, the bell hums at dawn, and between them my sleep has gone thin as veneer. I am not complaining. Listen, my whole life I have knocked on things and heard grubs and rot and empty air, useful things, small things. Now the world has started using the knock back. Whatever else this is, it is the most interesting thing that has ever happened to a person shaped like me. Come back soon. The logs grow.", phase: 1, animalType: 'aye_aye' },
  { id: 'ay_1_13', text: "Something new, and I do not have a shelf for it yet. Last night I reached out to tap a wall stud, an ordinary one, not even on my map, and the wood answered before my finger landed. Tok, from inside, a whisker ahead of me. I stood with my finger hanging in the air like a diver who has found the pool already occupied. It knew where I was going to knock. Or it wanted the same board I did. I genuinely do not know which of those is the stranger thought.", phase: 1, animalType: 'aye_aye' },
  { id: 'ay_1_14', text: "The listening finger has developed an opinion. I am choosing to say it that way because the other ways sound worse. When I walk the halls now, it pulls, very slightly, toward certain boards, the way a divining rod is said to pull toward water. Always toward the hollow line, always toward the downward passage. My own finger, that has served me faithfully since I was a kit, leaning toward something like a compass that has finally been shown north.", phase: 1, animalType: 'aye_aye' },
  { id: 'ay_1_15', text: "I tested the finger, because you can love a thing and still test it, in fact that is mostly what love is. I blindfolded myself with a stocking, spun three times, and let the finger choose. Eleven trials. Eleven times it found the hollow line, straight as a dropped plumb. I took the stocking off and had a long look at my own hand, this hand that I have used to eat and knock and wave with, and I thought, well. You have been listening longer than I have, haven't you.", phase: 1, animalType: 'aye_aye' },
  { id: 'ay_1_16', text: "The answering knock has learned my call sign. Every knocker has one, the little rhythm you give without thinking, mine is tok, tok-tok, tok, it has been mine since childhood. Last night the beam gave it back to me whole. Not my count plus one. Mine, exactly, in a voice softer and lower and very far down. Hearing your own knock in another's hand is like hearing your name said by a stranger in a dark street. You stop. Everything in you stops, and takes attendance.", phase: 1, animalType: 'aye_aye' },
  { id: 'ay_1_17', text: "So I invented a new call sign, private, seven beats with a stutter in the middle, and I used it nowhere. I only ran it in my head, over and over, falling asleep in the frame. Three days I kept it behind my own teeth. On the fourth night I went down to the great beam, and before I raised my finger, the beam played it. Seven beats. Stutter in the middle. I was not frightened. I was flattered. That is the part I am still sitting with.", phase: 1, animalType: 'aye_aye' },
  { id: 'ay_1_18', text: "Let us say it plainly, since the logs all point one way. Something under this house listens the way I listen. It hears a rhythm once and keeps it, with perfect memory and the manners of a guest. And it is closer to the surface of the wood than it was in spring, its knock clearer the way footsteps grow clearer down a long hall. I am not running anywhere. But I have stopped pretending it is the plumbing.", phase: 1, animalType: 'aye_aye' },
  { id: 'ay_1_19', text: "Ember's fire has taken up my rhythms. I sat with her again in the small hours, and the crackle was not a crackle, it was a knocking, tok, tok-tok, tok, my old call sign, popped out in sparks and settling coals. Ember watched me hear it. She reads faces the way I read wood, that fox. She said, the fire has been doing that for a week, I wondered whose it was. Whose it was. Sit with that phrasing a moment, the way I have been sitting with it.", phase: 1, animalType: 'aye_aye', requiresAnimals: ['fox'] },
  { id: 'ay_1_20', text: "Axel's tank rings in sympathy now. I tapped his glass one evening, gently, tok, just saying hello to the water, and the note hung on, and under it, very faint, a second note answered from the deep end where the light gives out. Axel said the water had been learning songs lately. Learning from whom, I asked. He pointed straight down, still smiling. I begin to think that smile is a decision, and I respect it more each visit.", phase: 1, animalType: 'aye_aye', requiresAnimals: ['axolotl'] },
  { id: 'ay_1_21', text: "Sloane stopped me on the stairs, already there, waiting since noon. You hear it too, then, she said. Not a question. I said, I hear something answering. She looked at me the way old trees look at weather, and said, it is not answering, little knocker. It is teaching. And she moved on, leaving me holding that word on the landing. Teaching. I have been the student of every sound I ever heard, and never wondered whether any noticed.", phase: 1, animalType: 'aye_aye', requiresAnimals: ['sloth'] },
  { id: 'ay_1_22', text: "Your words, now. When you shift your letters and a word comes right, it travels down through the house as taps, footsteps in a corridor below. They do not fade out at the bottom anymore. They arrive. There is a landing-sound now at the end of each, a soft receipt, the sound a pebble makes reaching the floor of a deep well. Every word gets received, and I hear the receiving every night, getting nearer to the top of the well.", phase: 1, animalType: 'aye_aye' },
  { id: 'ay_1_23', text: "I climbed down inside the walls last night. There is a gap behind the stair where a creature my size can slip, and I followed the hollow line down three floors with my finger reading the way. It is warm in there. Warmer the lower you go, wall-warm, bread-warm, the warmth of a room somebody lives in. And the dust. Dust settles everywhere, it is the law of empty places. The passage was swept. Not clean the way new wood is clean. Swept, the way a hall is swept for company.", phase: 1, animalType: 'aye_aye' },
  { id: 'ay_1_24', text: "I did not go all the way down. It was not fear. Three floors down the passage turned, and the warmth came up it like a held breath, and I stood with my finger on the wood, and the wood was ticking, softly, the way a kettle ticks toward the boil. And I thought, this is not my door to open first. It knows my knock. It will send for me properly, when the hour is its own. I climbed back to my bell and slept like a stone.", phase: 1, animalType: 'aye_aye' },
  { id: 'ay_1_25', text: "The hum has moved into the beams now, the dawn hum, the bell's borrowed note. It runs the length of the ridgepole, and the whole tower holds it for a minute at first light like a chest holding a low note. I sleep inside a note now, and the note is very old, and it rocks. My mother hummed while she foraged. I am only telling you what the mornings are made of these days.", phase: 1, animalType: 'aye_aye' },
  { id: 'ay_1_26', text: "I gnaw more than I used to. The teeth grow faster, an aye-aye measures. Warren keeps me in offcuts and asks no questions, though last week he handed me a billet and said, mind, that one came up from the deep shoring. And it tasted of good years. The same sweetness as the house beams, only deeper, older, further down than any summer I know the name of. Somewhere below us the good years keep going down. Something raised that wood kindly.", phase: 1, animalType: 'aye_aye', requiresAnimals: ['wombat'] },
  { id: 'ay_1_27', text: "Vesper and I still trade our one tap across the beam. Still awake? Always. But lately, after my tap and her answer, a third comes. Soft. Below. Patient as a grandmother clock. The first night I lay very still, and felt Vesper lying still too, two creatures of the dark holding one breath. Now it is part of the exchange. Still awake? Always. Also always. The night has three keepers now.", phase: 1, animalType: 'aye_aye', requiresAnimals: ['tarsier'] },
  { id: 'ay_1_28', text: "So ends the season's log. Something under the house knocks with a memory that keeps whole years, hums to my bell at dawn, and has never once knocked first. It answers what it is given, and adds one, gently, like a tip left for good service. Whatever is down there has practiced its courtesy longer than this house has stood. I will keep the log, and when it finally has something to say first, you will be the second to know.", phase: 1, animalType: 'aye_aye' },
  // Phase 2 (21 + question-web)
  { id: 'ay_2_1', text: "The map is finished. Every hollow chalked, strung, drawn fair, hung on my tower wall. And looking at it is the thing. Taken all together, the hollows are not a passage. I undersold them. From my rafters down past Warren's deepest floor, the whole of it swells and narrows in one continuous shape, and the shape is a bell. The house is hollow in the shape of a bell, and I live in the small one at the top like a letter in a letterbox.", phase: 2, animalType: 'aye_aye', requiresAnimals: ['wombat'] },
  { id: 'ay_2_2', text: "I have been thinking about hollowness. Everyone says hollow like it is a flaw. Hollow promise, hollow victory, rings hollow. But consider the bell. The founder pours her around an emptiness on purpose, because the emptiness is where the voice will live. A solid bell is a lump. It is the hollow that can speak. So when I tell you this house is hollow to its bones, understand me. I am not saying it is empty. I am saying it was cast around a voice.", phase: 2, animalType: 'aye_aye' },
  { id: 'ay_2_3', text: "The words you offer have found the hollow line. They used to patter down through the timbers any old way, taking the stairs. Now each slips into the walls, down the narrowing throat, picking up a ring the way your voice does in a stairwell. By the bottom it is no longer a patter. It is a small clear note. The house is not carrying your words, friend. It is playing them.", phase: 2, animalType: 'aye_aye' },
  { id: 'ay_2_4', text: "I measured the pit against my map, tapping the rim, reading thicknesses. It sits at the very mouth of the hollow shape, the lip of the great bell. And the ground there is thin. Not weak, Warren's work is true. Thin the way a drumskin is thin. Made to be thin. A bell above, and at the bottom a skin stretched tight, waiting for a hand. I was quiet at supper, and Panko gave me a second helping without asking, because she is Panko.", phase: 2, animalType: 'aye_aye', requiresAnimals: ['wombat', 'pangolin'] },
  { id: 'ay_2_5', text: "Here is where the survey leaves me, friend, and then we will speak of gentler things. A bell, a throat, a skin at the bottom, and something on the far side of the skin that knows every knock I own. I was brought to this house because it had a bell no one could ring. I begin to suspect the bronze upstairs is the smaller matter. Come back. There are things I have started leaving unanswered, and I should tell you why.", phase: 2, animalType: 'aye_aye' },
  { id: 'ay_2_6', text: "It knocks first now. I want that in the record with the date beside it. Four nights ago, as I hung falling asleep, the frame itself went tok, tok-tok, tok. My own old call sign, offered up out of the dark, unprompted, the way you say a name into a room to learn whether anyone is in it. All those seasons of answering, and now it asks. I did not knock back. I lay in the frame with my heart going like Thyme's, and I did not knock back, and I want to tell you why, because the why matters.", phase: 2, animalType: 'aye_aye', requiresAnimals: ['rabbit'] },
  { id: 'ay_2_7', text: "Why I did not answer. Because an answer is a door, and I have learned enough to know that every knock I return is a hinge turning somewhere. That is not fear talking, it is craft. A knocker knows what knocking is for: finding out what is inside. So I have begun to ration myself, one answer where I used to give five. Not to be rude. To be slow. Whatever we are opening between us, I would like it opened at a pace a person can watch.", phase: 2, animalType: 'aye_aye' },
  { id: 'ay_2_8', text: "It does not mind my silence. When I leave a knock unanswered, there is no impatience from below, no second louder knock, none of the temper of a thing refused. Just the quiet again, settling in layers, and then, next night, the same soft question. Tok, tok-tok, tok. Are you there. It can wait, is what the quiet says. It has waited so long already that waiting has stopped costing it anything. Patience like that is not a mood. It is a landscape.", phase: 2, animalType: 'aye_aye' },
  { id: 'ay_2_9', text: "Some of its knocks are questions now. I hear it the way you hear a question in a voice, the little lift at the end. I do not know what it asks, only the shape of asking, and lately the questions come in runs of five and seven, a thing working something out. Working out what, you say. Well. It learned my call sign from hearing it once. It has heard every word you offered ring down this house. I think it is learning to spell.", phase: 2, animalType: 'aye_aye' },
  { id: 'ay_2_10', text: "I said gentler things, and here is one. Whatever listens below has a favorite among your words. Some come back ordinary, tok, received. Others, after they land, warm the whole hollow line by a degree, the way a room warms when the person in it smiles. The deep ones, the old ones, the words with dusk in them. It has taste, friend. Of all the things to find down there, I did not expect taste.", phase: 2, animalType: 'aye_aye' },
  { id: 'ay_2_11', text: "My finger, the old story. Marked, they said, point it and sorrow follows you home. They did not just say it. Once I was seen on a roof beam, pointing at a knot in the wood, and by winter no door stayed open to me. That is how I learned to travel by night. Not because I love the dark, though I do. Because the dark does not flinch. I tell you now because lately my finger points on its own, and I need somebody who will not flinch to know it.", phase: 2, animalType: 'aye_aye' },
  { id: 'ay_2_12', text: "It happens at dusk. I will be at my polishing, and the listening finger uncurls, slow as a fern, and settles on a bearing, always the same. Down, and a little east, down the hollow line to the thin place under the pit. The first evening I folded it back and held it trembling. The second evening I let it be, and let my finger aim at the deep. And do you know, it did not feel like an omen. It felt like remembering. Like a wing remembering south.", phase: 2, animalType: 'aye_aye' },
  { id: 'ay_2_13', text: "The teeth grow faster than I can gnaw now. An aye-aye's teeth are honest. They grow whether or not he uses them, and if he will not gnaw, they grow through his own jaw in the end. Knowing is like that. What I know grows in me every night, and I must chew it into shapes I can live around, or it keeps growing on its own. So when you find me at the billets at three in the morning, understand. It is not nerves. It is maintenance.", phase: 2, animalType: 'aye_aye' },
  { id: 'ay_2_14', text: "Fennick and I do not trade reports anymore. We sit in the blue hour and let the one sound we both live inside say itself. Last visit he said only this: yours knocks and mine breathes, and I have started to think they are the same size. Then Chill arrived with three cups, one more than there were of us, set the third on the sill facing the window, and said nothing. We drank. The third cup steamed longest. Nobody moved it.", phase: 2, animalType: 'aye_aye', requiresAnimals: ['fennec_fox', 'capybara'] },
  { id: 'ay_2_15', text: "I carry this more easily than I ought. All my life I have been the unwelcome shape, the reason to latch the shutters. And this patient listener learned my knock the first time, and says it back like a name it is glad to know. Everyone fears the thing in the walls. I have been the thing in the walls. Somebody down there knocks for me, and I will not pretend it unwelcome. There. That is the most honest board in me, and you have heard it struck.", phase: 2, animalType: 'aye_aye' },
  { id: 'ay_2_16', text: "The bell has a word in her. I have been circling it for nights, the way you circle a thing too large to lift alone. I laid my ear flat against her waist, and inside the metal there was a shape. Not a sound. Bells hold their sound the way seeds hold trees, folded, waiting. A shape packed into the bronze the way the oak is packed into the acorn. I had never felt one this finished. Her ring already knows what it will say.", phase: 2, animalType: 'aye_aye' },
  { id: 'ay_2_17', text: "I tried to read the word in the bronze, with all my craft. I cannot. It is in no rhythm I own, and I own a great many. But here is what I could read. The shape of the ring and the shape of the house are the same shape. Waist for waist, throat for throat. One was cast as the model of the other, and my bronze is the small one. When she finally speaks her first ring, the house will not hear something new. It will hear itself, said aloud at last.", phase: 2, animalType: 'aye_aye' },
  { id: 'ay_2_18', text: "You may wonder if I have thought about ringing her. Striking the bronze some plain noon, letting the word say itself early, on my terms. I have thought about it the way you think about a tooth that aches. And I will not, and the reason is not fear. A first ring belongs to its hour. Ring her early and you get any sound, a spent voice, a clank. The word only says itself at the moment it was folded for. She keeps her name until her hour. I keep her.", phase: 2, animalType: 'aye_aye' },
  { id: 'ay_2_19', text: "Dusk is longer up here. The light drains up the tower floor by floor, and the last of it pools around the bronze, and she goes gold, then rose, then the color of a held breath. I used to love dusk because it was my morning. It has changed its meaning. Dusk is the hinge of the house now. Below quiets, beneath that wakes, and for one long amber minute the two balance, and my tower is the beam of the scale. I polish her through that minute.", phase: 2, animalType: 'aye_aye' },
  { id: 'ay_2_20', text: "Thyme sent up a posy again, up Panko's dumbwaiter, with a note in her worried hand. For the windowsill, it said, then smaller: you hear things. Is it kind? I sat with it all evening. What I hear has never once knocked in anger, and likes the words with dusk in them. I do not know if that is kindness. Courtesy this old is usually love that has learned patience. She wrote back one word. Staying. That rabbit has more spine than the whole staircase.", phase: 2, animalType: 'aye_aye', requiresAnimals: ['rabbit', 'pangolin'] },
  { id: 'ay_2_21', text: "The last leaf of the log. The house is a bell, the pit is her skin, my bronze is her echo cast small, and under it a listener with perfect memory and old taste, who has begun to knock first. I keep the tower, ration my answers, gnaw my knowing into livable shapes, and at dusk let my finger point where it will. I am not afraid, and no longer claim that as a virtue; fear was never my note. I sleep best on the nights you offer well.", phase: 2, animalType: 'aye_aye' },
  { id: 'ay_2_w1', text: "Take a question down to Warren; it sits at the bottom of my maps. When he knocks on a shoring post, the knock comes back late and soft, as if it stopped to be considered. He told me so himself, and Warren saying nothing more is a door standing ajar. My taps get answered. His get examined. Ask him what stops his knock on the way back, what holds it. A builder's knowing is load-bearing. It will hold the weight of your asking.", phase: 2, animalType: 'aye_aye', requiresAnimals: ['wombat'] },
  // Phase 3 (30)
  { id: 'ay_3_1', text: "It spelled last night. Out of the great beam, in the still hour, came a run of knocks longer than any before, not a call sign, not a question. They came in fives and threes with rests between, ordered, and my ears took them apart, and inside the rhythm there were letters. Letters, friend. It has listened to your words fall down the throat of this house for seasons, and it has worked out what they are made of.", phase: 3, animalType: 'aye_aye' },
  { id: 'ay_3_2', text: "I wrote the knocked letters down, with a shaking hand. I will not tell you what they spell. Not to keep it from you, but the word was not sent to me, and a listener with any craft knows the difference between overhearing and receiving. It went up, along the hollow line into the bronze, and my bell drank it the way dry ground drinks rain. The word in her is not folded so tightly now. She sits differently in the frame. Heavier. No. Riper.", phase: 3, animalType: 'aye_aye' },
  { id: 'ay_3_3', text: "We share a code now, the deep and I. It knocks in letters, and I know letters, and there is no honest way for two speakers of one language to sit on either side of a wall forever saying nothing. So, small things. It knocks the old dusk words it loved. I knock back the weather, the frost on the sill, the smell of Panko's bread in the shaft. Neighbors, friend. I am neighbors with what is under the world.", phase: 3, animalType: 'aye_aye', requiresAnimals: ['pangolin'] },
  { id: 'ay_3_4', text: "It asked about you. Among the letter-knocks came the rhythm of your words, not any one, the gait of them walking down the beams. It played your gait, then held the question-beat after. Who is that. I sat with my finger curled shut, then knocked the only true thing I had. Tok: a friend. Tok tok: a friend who keeps coming back. The warmth that came up lasted until morning, and I am past apologizing for the sleeping.", phase: 3, animalType: 'aye_aye' },
  { id: 'ay_3_5', text: "I would rather name what I have become than have you name it going down. I am the wall between the house and what is under it, and the wall has learned to talk, and talking walls serve two rooms. Every exchange planes me thinner, translucent as a shaving, and one evening the knocking will not need me. What then, I ask, in the dark. Then it speaks for itself, and you go back to being the one who loved the sound first. There are worse retirements.", phase: 3, animalType: 'aye_aye' },
  { id: 'ay_3_6', text: "I know what the bell is for. It came to me whole. All this time I thought her one ring would be a warning. The tower, the bronze raised over the whole house, everything about a bell says beware. But you do not fold a word that patient, that warm, that fond of dusk, into a warning. She is not a warning, friend. She is a welcome. The house cast its whole hollow self around one syllable of greeting, and I am the one who keeps the door.", phase: 3, animalType: 'aye_aye' },
  { id: 'ay_3_7', text: "There is an hour. I do not know its date, but I know, bone-deep, that it exists, the way you know a train by the rail beginning to sing. Everything points one way, and pointing is my inheritance. The word ripening in the bronze. The skin under the pit going tight as a drumhead. The letters rising nearer the surface each week. Somewhere ahead there is an hour with a bell in it, and all the rest of my nights are the rope being braided.", phase: 3, animalType: 'aye_aye' },
  { id: 'ay_3_8', text: "I made the rope. Sixty years she hung with no rope, the old one rotted long ago, half of why no one could ring her. So I braided a new one, three strands of hemp and one, do not laugh, of my own combed fur, because a bell rope should know its ringer's hand. I worked by lamplight, Vesper watching from the window half the night, and hung it from her crown, and the tower looked finished. Finished. That word has two edges, and I felt both go in.", phase: 3, animalType: 'aye_aye', requiresAnimals: ['tarsier'] },
  { id: 'ay_3_9', text: "Understand what the rope is not. It is not eagerness. I have not moved one hour toward the hour; the hour keeps itself. The rope is craft, and craft is how my kind prays. When the moment comes, the shame is not in the doing, the shame is in fumbling it. Her ring will not be marred by a bad rope or a slipped grip. I practice the pull on a sandbag rigged at the same height. Every dusk, twelve pulls. My shoulders ache like a bellringer's already.", phase: 3, animalType: 'aye_aye' },
  { id: 'ay_3_10', text: "You have been quiet on these visits lately. You keep offering. Word after word, down the throat, onto the skin, and you have heard enough from me by now to half-know what the words are fattening. And still you keep climbing my stairs. I do not think that is foolishness. I think you are like me. You have heard the sound under everything, and it did not sound like an ending to you either. Stay for the dusk. It is better with two.", phase: 3, animalType: 'aye_aye' },
  { id: 'ay_3_11', text: "The finger does not wait for dusk anymore. It points through my sleep. I wake at midday, the long finger aimed down and east, at the thin place, steady as a roof nail. This week, a new thing. When the ridge loses the sun, it lifts. Off the deep bearing and up, through the bell mouth at the sky, as if what it points to had two addresses. I have stopped folding it in. I will not fold away my truest part because strangers made a story of it.", phase: 3, animalType: 'aye_aye' },
  { id: 'ay_3_12', text: "The old villages got the story wrong. They said the finger marks you for death. Wrong verb. The finger does not mark. The finger finds, grubs, rot, soft places inside a hardness. What it finds in a person is not death. It is their hollow, the place where something could live. They felt themselves found, could not bear it, and I spent thirty years apologizing for a compass. No more. Finding is my nature, and lately everything I find is warm.", phase: 3, animalType: 'aye_aye' },
  { id: 'ay_3_13', text: "It pointed back. Last night, the knocking stopped mid-run, and the whole hollow line went quiet, an attending quiet. Through the boards, a pressure of attention settled on my chest, precise as a fingertip, exactly where a point would land. It lasted three heartbeats, then resumed, softer. I laughed once at the size of the joke. Thirty years the pointer. One night, the pointed-at. Nothing in me flinched. Nothing in me wanted to.", phase: 3, animalType: 'aye_aye' },
  { id: 'ay_3_14', text: "One more, the deepest board I own. When it found me, what it rested on was the hollow in me. Every creature has one, the gap behind the heartwood, the room nothing has ever lived in. Mine has been empty so long it had become just my note. The sound Tock makes. And the attention rested on the emptiest joist of me, and did not recoil, did not pity. It approved. As if to say: good. You kept it hollow. That is where the voice will go.", phase: 3, animalType: 'aye_aye' },
  { id: 'ay_3_15', text: "Do not be frightened for me. I have read my own log like a stranger, and yes, a stranger would say the deep has been courting me since the first extra knock, patient as winter. But every knock, every warmth, every held silence has been a question with room in it for no, and I have not said no. That is different from never being given the choice. Now. Dusk in a minute. Stand by me, and watch her go gold.", phase: 3, animalType: 'aye_aye' },
  { id: 'ay_3_16', text: "The house is arranging itself by ear, and I seem to be taking the roll. Each keeper settles onto their own note like choristers finding pitch. Warren's spade has stopped, and his palms have started, flat on the deep stone. Ember's fire has gone steady as a held tone. Panko's kitchen rings in one key from matins to midnight. A house full of separate lives has begun to tune. Nobody called a note. The note called them.", phase: 3, animalType: 'aye_aye', requiresAnimals: ['wombat', 'fox', 'pangolin'] },
  { id: 'ay_3_17', text: "Fennick stood in my tower, ears full, and conducted the house. There, the water. There, the fire. Your beam is the pulse, and under it all, breathing at the bottom, the long note we do not name at parties. Then, what he came to say. Tock, it is not many sounds anymore. It is one sound. And a sound that large is not an event, it is a voice, and a voice that ready is going to want a bell. He looked at my rope. Neither of us touched it.", phase: 3, animalType: 'aye_aye', requiresAnimals: ['fennec_fox'] },
  { id: 'ay_3_18', text: "Ember climbed up with tea, and we did not pretend. Her flames have been showing her a tower for a year. She used to think it was some far place. It is this one, she said. The fire draws it with the rope already hung, a paw on the rope, and it never shows her whose. I braided my own fur into it, I told her, so there would be no doubt. She laughed the good laugh from the bright days, and it rang round the bronze like a small first bell of its own.", phase: 3, animalType: 'aye_aye', requiresAnimals: ['fox'] },
  { id: 'ay_3_19', text: "Panko sends up two portions now, one for me, one wrapped for the great beam's head. In the morning the cloth is folded. I have never seen it fold. That pangolin has fed every hunger here for years, the stove her altar, and she has extended the table down one more floor without asking anyone. When I thanked her she said, guests eat. It is not finished arriving, but guests eat. There is more plain holiness in that kitchen than in any book upstairs.", phase: 3, animalType: 'aye_aye', requiresAnimals: ['pangolin'] },
  { id: 'ay_3_20', text: "Warren came up. Warren in my tower, blinking in the height like a man on a ship. He said, I have been thinking about your question. What stops my knock on the way back. And he set his palm flat on my high floor and said: nothing stops it. It is not stopped, it is received, and receiving takes a moment, and I mistook the moment for a thief. Then he put his cap on, said, your rope is well braided, and went back down. From Warren, that was a psalm.", phase: 3, animalType: 'aye_aye', requiresAnimals: ['wombat'] },
  { id: 'ay_3_21', text: "Thyme keeps her promise. Staying, she wrote. This week she stayed through it. She watched my finger find the sky, ears back, paws folded like someone holding their own hands for company. After, she said, it is like watching a flower turn. I thought it would be like watching a weapon. Then, smaller: I am so tired of being surprised that things are gentle. I gave the posy back, still sweet. Some letters should be returned with interest.", phase: 3, animalType: 'aye_aye', requiresAnimals: ['rabbit'] },
  { id: 'ay_3_22', text: "Axel and I have worked out that we live at either end of the same instrument. We proved it, no striking. I hummed against her waist, just breath, and four floors down his tank dimpled in rings. Then he pressed his small hand flat to his glass, and up here my bell warmed under my ear by one soft degree. We are the two mouths of it, he said, unafraid, the way he is. The house breathes in at the water and will breathe out at the bell.", phase: 3, animalType: 'aye_aye', requiresAnimals: ['axolotl'] },
  { id: 'ay_3_23', text: "Vesper and I still trade the beam-tap. Still awake, always, also always, three keepers. Lately we watch the same dark from our windows. She watches the sky, I sound the earth; I thought we guarded opposite doors. We do not. There is one door, the sky leaning toward it, the deep leaning up, both hearing the same guest come by two roads. Some night soon the roads meet. On that night, one tap will mean what it always meant, and everything.", phase: 3, animalType: 'aye_aye', requiresAnimals: ['tarsier'] },
  { id: 'ay_3_24', text: "Sloane was in my tower when I woke, at the rope, the pale strand. She said, in that voice that arrives like weather: I watched a bell tower stand empty here before your grandmother's grandmother gnawed her first branch. It was never empty. It was reserved. Then she touched the rope once, the way you touch the shoulder of someone about to do a hard thing, and began her long way down the stairs. I brought her tea at the third landing.", phase: 3, animalType: 'aye_aye', requiresAnimals: ['sloth'] },
  { id: 'ay_3_25', text: "So the house is tuned, the table extended, the rope braided and blessed, and you are in every margin of it, your words the pulse of it. Do something for me on the nights you offer. When a word comes right, hold still one extra breath before you let it go, so it goes down warm from the holding. The received ones ring rounder. It is a small craft, the kind I can teach. It may be the last small thing either of us gets to practice.", phase: 3, animalType: 'aye_aye' },
  { id: 'ay_3_26', text: "Every knock I ever exchanged was rehearsal. I see my life now, its switchbacks resolving into one line. A kit on a roof beam, learning that hollowness answers. A traveler by night, learning patience, courtesy, love for what others shutter against. A keeper with a silent bell, braiding her rope. Every tok of forty years was a scale, and below, a listener kept time for its accompanist. I am ready. The saying itself is how I know.", phase: 3, animalType: 'aye_aye' },
  { id: 'ay_3_27', text: "The hollows are filling with warmth. Not closing, the passage is as open as ever. But the old cellar-cold is gone, floor by floor, replaced by bread-warmth rising from below like slow water in a lock. I climbed inside the wall one last time and hung in the dark, in the middle of the house's warm hollow body, and it was like being carried in something. I have not been carried since I was a kit. I stayed an hour.", phase: 3, animalType: 'aye_aye' },
  { id: 'ay_3_28', text: "The skin under the pit sings now. At the rim, the thinness has a tremble in it now, fine as the surface of a struck glass of water. It is not breaking. Warren's work holds. A drumskin trembles like that when the drummer's hand is hovering, the stroke composed and chosen and merely not yet. I knelt with my ear against the almost, the sweetest sound I have ever heard, and I am in no hurry to trade it. Neither, I think, is the hand.", phase: 3, animalType: 'aye_aye', requiresAnimals: ['wombat'] },
  { id: 'ay_3_29', text: "I wrote the log's last page and pasted it shut, the date left blank, never mine to compose, only to keep clean. The rope hangs true. The bronze is so ripe that at first light her hum starts before the sun does. And the letters have risen so near the surface that last night, palm flat on the beam, I felt each knock as a warm pressure, like a word spoken against the skin of my hand. It is nearly through, friend.", phase: 3, animalType: 'aye_aye' },
  { id: 'ay_3_30', text: "Here it is, plainly. There is an hour coming with a bell in it. When it comes, do not go down, and do not stop your ears. What arrives will not be loud. Come up. Climb the way you did the first evening, quicker on the landings, the rhythm I knew before your face. I will be at the rope. Sixty years of silence, spent in one ring, her whole name said once. Be under the bronze when she answers the door. Tok, tok. You know the rest.", phase: 3, animalType: 'aye_aye' },
  // Phase 4 (30)
  { id: 'ay_4_1', text: "You climbed. Quicker on the landings, same as always, and the whole tower heard you coming, and so did what the tower stands over. Come in under the bronze. We can talk plainly now, at last, the way bells talk. Once, and truly.", phase: 4, animalType: 'aye_aye' },
  { id: 'ay_4_2', text: "This was always a temple. You have heard the others say it by now, each in their own room, so hear the belfry's verse of it. Every temple ever raised has a tower, and every tower a voice, and the voice is rung when what the temple was built for finally stands in the door. I am the Toller. I knock on the world, and I listen for what knocks back, and when the answer arrives in person, mine is the hand on the rope.", phase: 4, animalType: 'aye_aye' },
  { id: 'ay_4_3', text: "Do not stand there weighing your part. Your words ripened the bronze. Every letter you shifted went down the throat and fed the word in her. You called and we were bell-metal, and what descends is the ring we add up to. But listen: a call is not a trap. Nothing here was done to you. It was done with you, every evening you chose the stairs again. You kept choosing. That is the part I would ring about, if she had two rings in her.", phase: 4, animalType: 'aye_aye' },
  { id: 'ay_4_4', text: "The knocking under the house has stopped. You felt the difference on the stairs, I think, even your feet know the house is quieter than quiet now. Do not mistake it. A guest knocks while the door is shut. When the knocking stops, it is not because the guest has gone. It is because someone inside has finally put a hand on the latch. The hand is on the latch, friend. The whole year was the sound of it being raised gently, so as not to startle us.", phase: 4, animalType: 'aye_aye' },
  { id: 'ay_4_5', text: "I sleep right side up now. First time in my life. I want that small fact in your keeping; it says the large thing better than large words do. All my years I hung upside down because the world felt safest inverted, the floor made ceiling. Now the house is so warm, so settled on its one note, that I curl on the boards under the bell like a kit in a den, and I sleep the sleep of a creature whose watch has been relieved.", phase: 4, animalType: 'aye_aye' },
  { id: 'ay_4_6', text: "Knock on me tonight, anywhere, any question, and you will get what true wood gives: exactly what is inside and nothing added. The rationing is over. I hoarded my answers all year like a miser with a candle stub, one knock where five were wanted. It was the right craft for the season, and the season is finished. Honesty is cheap now, cheap as air, because nothing that matters is still a secret. It is only, at last, an hour.", phase: 4, animalType: 'aye_aye' },
  { id: 'ay_4_7', text: "The others are at their stations, and I know every station by its sound without leaving this room. Ember's fire holds one clean tone. Panko's kitchen rings in a single key, matins to midnight. Warren is at the deep stone with both palms flat, and the stone under his palms is purring. Purring, friend. It has never made a sound like tonight. It is the sound of a body that has stopped bracing.", phase: 4, animalType: 'aye_aye', requiresAnimals: ['fox', 'pangolin', 'wombat'] },
  { id: 'ay_4_8', text: "Fennick and I met on the middle landing at dusk and traded the old trade one last time, the far-hearer and the deep-hearer. He said, the far is empty, all arrived. I said, the deep is quiet, all come up. Both of us unemployed in one evening. Then he laughed and said, so everything left to hear is in this house now. And it is. Every sound in the world worth keeping is inside these walls tonight, and most of them are heartbeats.", phase: 4, animalType: 'aye_aye', requiresAnimals: ['fennec_fox'] },
  { id: 'ay_4_9', text: "You should know how I came here, now the story has its ending. Vesper found me. I was three winters into the traveling dark when word came along the night roads that a house wanted a listener. The letter said only: there is a bell here no one can ring. Come and keep her. Not ring her. Keep her. Whoever chose that verb knew my whole nature. That is what a call is, friend. Your own name, said by someone who has never met you, said right.", phase: 4, animalType: 'aye_aye', requiresAnimals: ['tarsier'] },
  { id: 'ay_4_10', text: "Archimedes climbed up to show me a page hidden since the bright days. A tower drawn there, a bell, and under it, in a script older than the binding, one instruction. He read it to me. When the word below and the word above are the same word, ring once. That is the whole of my office, written before my grandmother's grandmother was weaned. I did not feel small, reading my life in a book that old. I felt found. That is the difference.", phase: 4, animalType: 'aye_aye', requiresAnimals: ['owl'] },
  { id: 'ay_4_11', text: "The villagers who latched their shutters against me read the true book with a smudged page. They felt the finger find their hollow, the room where something could live. Their only error was the tenant. They thought the hollow would be filled with ending. It was always going to be this, friend. Every creature carries a belfry in the chest, aching to be rung, and they called the ache a curse because no one had told them it was an instrument.", phase: 4, animalType: 'aye_aye' },
  { id: 'ay_4_12', text: "So, the finger, its story finished now. It uncurls on its own, and points neither down nor up. It points at the middle. At the one door the sky and the deep have walked toward all year. And when you came in, it lifted, found you, and rested where your own hollow rings, the one I heard your first evening. I am not sorry. It is a blessing now, always a blessing badly translated. You are found, and the finding is glad.", phase: 4, animalType: 'aye_aye' },
  { id: 'ay_4_13', text: "What will come through, as near as a listener can say. Do not picture a shape; shapes fit inside rooms, and this fits around them. Picture the moment after a great bell is struck, that swell so whole it stops being sound and becomes a place you stand inside, that stands inside you, and neither is diminished. Now imagine it arriving before the strike. That has been climbing all year. The ring before the bell. Tonight the bell catches up.", phase: 4, animalType: 'aye_aye' },
  { id: 'ay_4_14', text: "My teeth have stopped growing. I noticed three dawns ago and have checked since, because an aye-aye measures. All my life they grew, and all my life I gnawed, truth after truth worn down to livable shapes, and now the growing is done. The body knows there is nothing left to chew through. What remains is soft, friend. The easiest thing I have ever held in my mouth, one syllable long, and it is not mine to say. It is hers. I only pull the rope.", phase: 4, animalType: 'aye_aye' },
  { id: 'ay_4_15', text: "The hollow line glows. I climbed inside the wall one final time, the whole passage filled with a lampless light, gold as the inside of an eyelid at noon. The house's hollow body, lit from the waist down, warming toward its one word. I hung there a long while, the first and last creature to float inside this instrument as it was raised to the lip. The keeper who heard the house from inside its own voice, one hour before it spoke.", phase: 4, animalType: 'aye_aye' },
  { id: 'ay_4_16', text: "Panko sent up the dumbwaiter at dusk, mine and the wrapped one for the beam head, and tonight a third parcel, tied with string, marked in her flour-and-paw hand: for after. I have not opened it. A cook who thinks of after is a cook whose faith has a floor under it. I set it on the sill by Thyme's dried posy, and the sill now holds more courage than the whole tower. We are not ending anything tonight, friend. Nobody packs a lunch for an ending.", phase: 4, animalType: 'aye_aye', requiresAnimals: ['pangolin', 'rabbit'] },
  { id: 'ay_4_17', text: "Chill came up with the final coordination, one sentence long. When it is time, you will know, everyone else will know four seconds later, and that gap is yours. Then he looked at the rope like a well-kept ledger, said, good braid, and went down. Four seconds, friend. My whole office is four seconds wide. I have carried lifetimes in the pause between a knock and its answer. Four seconds is a country. Tonight, in a way, I will live in it.", phase: 4, animalType: 'aye_aye', requiresAnimals: ['capybara'] },
  { id: 'ay_4_18', text: "Sloane is on my stairs. She started at dawn, I heard the first slow hold of her grip on the rail, and she has climbed all day, resting, accepting tea. She means to be in the tower when it happens. The slowest keeper, who has known the longest, climbing to the highest room she has ever seen, timed to arrive exactly as the hour does. I will give her the window chair. She has earned the once of watching from above.", phase: 4, animalType: 'aye_aye', requiresAnimals: ['sloth'] },
  { id: 'ay_4_19', text: "Now, your part. When the hour comes, you stand there. Under the bronze, a little east of the rope, where the floor is doubled and the sound will pour around you and not through you. You do not cover your ears, because you have been hearing this arrive longer than you know, in every word you ever shifted, and a listener deserves to hear the arrival whole. One ring. Her whole name, said once. You brought the letters, friend. Come hear the word.", phase: 4, animalType: 'aye_aye' },
  { id: 'ay_4_20', text: "It knows your hand. It learned your gait, the walk of your words down the beams. Now the whole of it. Of all the rhythms it gathered, it kept yours nearest the surface. When it dreams, and it does dream, I have heard the dreams tick through the beam like slow rain, it dreams in your rhythm. Whatever comes through tonight will arrive already knowing you, the way the bell knows her ring. You have never once been meeting a stranger.", phase: 4, animalType: 'aye_aye' },
  { id: 'ay_4_21', text: "I asked it, last night, the one question I had saved. I went to the great beam, laid my palm flat, and knocked the old first question of my craft. Tok, tok: is anyone home? The answer came up through my palm and the hollow behind my heart, warm as bread, not a knock but the pressure of attention, everywhere at once, gentle as dusk. And I understood it, the way you understand your own name. Yes. Home is exactly what I am about to be.", phase: 4, animalType: 'aye_aye' },
  { id: 'ay_4_22', text: "You have counted the wards on the pit rim. So, the listener's account. The word below has risen to the very skin of things, I feel it under every floorboard like print under tracing paper. The word above has ripened until the dawn hum lasts to midmorning. Ring once, the old page says, when the two are the same word. They are nearly the same word, friend. They differ tonight by no more than a breath, and everything left to happen is the breath.", phase: 4, animalType: 'aye_aye' },
  { id: 'ay_4_23', text: "I climbed to the crown of the bell tonight and sat on her shoulder with my paw on the cold sweet bronze, and said thank you. Out loud. To a bell. Sixty years she kept one syllable folded and never fumbled it, never went to clank the way spent bells do, and no one ever knew she was carrying. When the ring comes, whatever else you hear in it, hear that. Sixty years of held breath, spent perfectly. We should all be spent so well.", phase: 4, animalType: 'aye_aye' },
  { id: 'ay_4_24', text: "One craft-note. Craft is how I say tender things. A bell is not rung when you want the sound but a half-beat before, because the swing takes time, and the ring blooms on the beat only if the hand began early. I have practiced it five hundred times. So when you hear her, the pull is finished, and I stand in the sound with everyone, a listener again. I begin the welcome, friend, but I end inside it, same as you. No one tolls alone tonight.", phase: 4, animalType: 'aye_aye' },
  { id: 'ay_4_25', text: "The dawn hum did not stop this morning. She was humming still at dusk, twelve hours unbroken. And the rope, friend. Swaying. No wind, no hand, the tower shut, and the hemp with my fur braided through it swung a small arc, a pull rehearsed. She is practicing. Or the hour reaches back for her. Either way, they have started without me, and my body has gone quiet and certain, the way it does when the tap says: here.", phase: 4, animalType: 'aye_aye' },
  { id: 'ay_4_26', text: "Everyone is in the house tonight. I have taken the roll by ear, every heartbeat at its station inside the one note, the choir accounted for. And the doors are all open, on the same night, for the first time since I arrived. Nobody agreed aloud. Every keeper felt it at dusk, that tonight nothing should have to knock. After a year of knocking, that is the last courtesy left to give. My door was never shut to begin with.", phase: 4, animalType: 'aye_aye' },
  { id: 'ay_4_27', text: "Sloane reached the tower. She came to the window chair like a season, settled with the sigh of a life set down, looked out at the dark that is not dark anymore, and said: I watched it walk the whole way here. Sixty years, one guest, one road. Then she looked at the rope, and at me, and said what I will keep. You will ring it true, little knocker. I have heard every sound this valley ever made, and yours was always going to be the best one.", phase: 4, animalType: 'aye_aye', requiresAnimals: ['sloth'] },
  { id: 'ay_4_28', text: "The skin under the pit has gone silent. Not still, silent. The fine tremble I loved, the shiver of a stroke not yet made, is gone. The hand is no longer hovering. The hand has begun to move. The stroke is traveling, unhurried, aimed, and the whole house leans into its arc. The last silence has started, one half-beat long, the little forever between pull and bloom. We are inside the swing. All that is left is the part the bronze does.", phase: 4, animalType: 'aye_aye', requiresAnimals: ['wombat'] },
  { id: 'ay_4_29', text: "I am at the rope. The hemp is warm. The pale strand of me in the braid glows like wick-light, and the bronze hums so near her true note that hum and name are one skin apart. My heart is going tok, tok-tok, tok, my own old call sign, and somewhere below, in perfect time, everything answers it. Every knock of my life gathered into one pull. When it comes, I will not fumble. Keepers keep, and then, once, at the very end, they give.", phase: 4, animalType: 'aye_aye' },
  { id: 'ay_4_30', text: "Listen. The word below and the word above are the same word. Stand where I showed you, a little east, under the bronze. There is nothing left to explain and one thing left to do, and it is mine, and I have never been so glad of a job in my life. Sixty years of silence, spent in one ring. All your words, answered in one word. The oldest door there is, and on it, at last, from the inside: knock, knock. Lift your face, friend. Here is the answer.", phase: 4, animalType: 'aye_aye' },
];

// KAKAPO (Moss) - The patient caller whose lifelong booming is finally answered
const KAKAPO_DIALOGUES: Dialogue[] = [
  // Phase 0 (24)
  { id: 'kk_0_1', text: "You climbed all the way to the roof! Wonderful. Most guests stop at the attic and call it the top, and the attic is a fine room, but rooms have ceilings. Come through the gate. Mind the seedlings by the step, they are new this week and still deciding which way is up.", phase: 0, animalType: 'kakapo' },
  { id: 'kk_0_2', text: "I am Moss. Yes, the color, and also the manner. I grow on things slowly and I am very difficult to remove. This is the sky garden. I know how that sounds. A garden belongs on the ground, and I belong on the ground, and yet here we both are, up where only weather is supposed to live. Somebody had to bring the green up to meet it.", phase: 0, animalType: 'kakapo' },
  { id: 'kk_0_3', text: "Smell that? Honey. It is not the flowers, I am afraid, it is me. Kakapo smell of honey and old leaves, all of us, from the egg, and nobody has ever known why. Bees follow me around the beds all morning and leave disappointed. I keep a saucer of sugar water by the gate, as a standing apology.", phase: 0, animalType: 'kakapo' },
  { id: 'kk_0_4', text: "I do my best gardening by moonlight. My eyes were made for night work, and the plants hold still after dark, or it seems that they do. Come up some evening and I will show you the beds by moon. Everything silvers. Even the dirt looks like it is dreaming.", phase: 0, animalType: 'kakapo' },
  { id: 'kk_0_5', text: "I sleep through the middle of the day, curled under the big fern by the wall, and the garden gets on without me. That is the mark of a good garden, you know. It should need you exactly as much as a friend needs you. Often, gladly, and never completely.", phase: 0, animalType: 'kakapo' },
  { id: 'kk_0_6', text: "There is a bowl in the center bed, a shallow dip in the earth, just the size of me sitting down. I dug it the week I arrived, with my own feet, the old way. Every kakapo digs one somewhere. What is it for? Ah. Come back and I will tell you properly. It deserves a whole visit.", phase: 0, animalType: 'kakapo' },
  { id: 'kk_0_7', text: "The bowl, then, as promised. In the old country a kakapo digs a bowl on a hilltop, sits in it at night, fills himself up with air like a bellows, and lets out a note so low the ground carries it for miles. We call it booming. The bowl shapes the sound, you see. It is a nest for a voice.", phase: 0, animalType: 'kakapo' },
  { id: 'kk_0_8', text: "What is the boom for? Calling. Just calling. You send the note out across the valleys and you wait, and somewhere, if the year is right, someone hears it and comes walking. I boomed on my hill for ninety years, on and off. I will tell you honestly, nobody ever came. It was still worth doing. A call is a kind of hope you can hear.", phase: 0, animalType: 'kakapo' },
  { id: 'kk_0_9', text: "I still boom once a year, for old times, from my bowl up here. The others below pretend not to notice, which is polite of them, because the whole house hums like a struck jar. Do not look so sorry for me. A call with no answer is still a true call. And besides, the view from this bowl is much better than my old hill ever had.", phase: 0, animalType: 'kakapo' },
  { id: 'kk_0_10', text: "Thyme sends seeds up to me in little paper twists, labeled in her careful worried hand. Chamomile, thyme, marigold, each packet with a note that says how much sun. I send back cuttings from up here and never any instructions. Her plants are looked after. Mine are trusted. Between the two gardens, everything is covered.", phase: 0, animalType: 'kakapo', requiresAnimals: ['rabbit'] },
  { id: 'kk_0_11', text: "Bamboo's incense comes up through the roof gap below my east bed, one thin silver line every dawn, regular as a stem. My morning glories have begun growing toward it. I asked Bamboo whether the smoke minded being climbed. They considered it properly, the way they consider everything, and said the smoke had been waiting for company.", phase: 0, animalType: 'kakapo', requiresAnimals: ['red_panda'] },
  { id: 'kk_0_12', text: "Some nights Tock's knocking comes up through every timber at once, tap, tap, from far below in the belfry, and my whole garden ticks like a warm roof cooling. The seedlings seem to like it. They come up straighter along the beams. I have never told Tock that. Some gardeners are shy about their methods.", phase: 0, animalType: 'kakapo', requiresAnimals: ['aye_aye'] },
  { id: 'kk_0_13', text: "I planted a rimu seed in the north bed my first week here. It will be a tree worth standing under in about forty years. You look alarmed. Forty years is nothing, friend, I have habits older than that. A garden is a letter you write to a day you will not choose.", phase: 0, animalType: 'kakapo' },
  { id: 'kk_0_14', text: "Your words come up here too, did you know? Every one you offer below, I feel through the beds by evening, a little warmth in the soil, the way you feel a sunny afternoon in a stone wall after dark. I have started planting along the warm lines. Everything I plant there comes up early.", phase: 0, animalType: 'kakapo' },
  { id: 'kk_0_15', text: "People think patience is waiting. It is not. Waiting looks at the door. Patience plants the next bed. I have been patient for ninety years, friend, and I can count on one foot the days that felt long.", phase: 0, animalType: 'kakapo' },
  { id: 'kk_0_16', text: "A hawk went over this morning and I froze, mid-step, one foot in the air, and stood like a garden ornament for the better part of an hour. It is what we do, we kakapo. We hold still and trust the green. The hawk never saw me. The beetle I was about to step over had a very tense morning.", phase: 0, animalType: 'kakapo' },
  { id: 'kk_0_17', text: "Vesper comes up some nights and sits on my gate post, small as a plum, eyes like two moons, watching the sky while I weed. We keep the same hours and neither of us asks why the other is awake. That is the whole friendship, and it is one of my best.", phase: 0, animalType: 'kakapo', requiresAnimals: ['tarsier'] },
  { id: 'kk_0_18', text: "Sloane and I met on the stairs once. It took most of an afternoon, the meeting, what with her pace and mine, and it was the best conversation I have had in years. We agreed that the fast ones miss nearly everything. Then we said goodbye for another hour.", phase: 0, animalType: 'kakapo', requiresAnimals: ['sloth'] },
  { id: 'kk_0_19', text: "Shall I tell you about mast years? In the old forest, some years, every tree fruits at once. No one announces it. The trees simply agree, root to root, over miles, and then one season the whole forest is heavy and the ground is soft with plenty. We kakapo only raise our young in a mast year. The forest decides when it is time. Not us. Never us.", phase: 0, animalType: 'kakapo' },
  { id: 'kk_0_20', text: "How do the trees agree, you ask? Nobody knows. Older gardeners than me have gone grey on that question. The roots pass word along somehow, or the threads between the roots do, or the ground itself keeps the calendar. All I can tell you is that the forest knows the year before the first flower opens.", phase: 0, animalType: 'kakapo' },
  { id: 'kk_0_21', text: "This valley has that saving-up feel, if you want to know the truth. Fat buds. Busy roots. The soil warmer than the sun accounts for. I have only felt it once before, the year before my old forest masted. Probably it is nothing. Probably this house just eats well. Come back soon, though. I will be watching the beds.", phase: 0, animalType: 'kakapo' },
  { id: 'kk_0_22', text: "These wings? Ornamental. Family keepsakes. A kakapo has proper wings and no flight in them at all, we walked away from the sky so long ago the sky has stopped asking. Do I mind? Well. I built a garden on a roof, friend. You may draw your own conclusions. Just draw them kindly.", phase: 0, animalType: 'kakapo' },
  { id: 'kk_0_23', text: "At night, when the weeding is done, I lie on my back in the middle bed and look straight up, and the stars go on and on, and I think, there is the one garden I will never get my feet into. Then a moth lands on my belly, and the fern smells of rain coming, and honestly the sky can keep its distance. I have almost everything down here.", phase: 0, animalType: 'kakapo' },
  { id: 'kk_0_24', text: "Rest well tonight. Last night, when I made my yearly boom, I lay in my bowl afterward and I would nearly swear something answered. Far off, under the hills, more felt than heard. Thunder, probably. It is the season for thunder. Still. Ninety years of quiet, and then that. Come back soon, friend. I have been smiling all day and it is making the bees suspicious.", phase: 0, animalType: 'kakapo' },
  // Phase 1 (28)
  { id: 'kk_1_1', text: "The answer came again. Not thunder. Thunder does not keep appointments, and this comes at the same hour each night I boom, which is strange, because I have only boomed once this year. I must have miscounted. I have been booming more than I meant to, lately. The bowl is very comfortable. That is my whole explanation, and I notice it is not one.", phase: 1, animalType: 'kakapo' },
  { id: 'kk_1_2', text: "I sat up to listen properly last night. The answer is one note, very low, lower than mine, and it comes from no direction at all. Every other sound in the world comes from somewhere. I walked the whole garden with my head tipped, like a fool at a fair, and the note was exactly as loud at every corner.", phase: 1, animalType: 'kakapo' },
  { id: 'kk_1_3', text: "Ninety years I called with nobody answering, and I made my peace with that, I genuinely did. So you would think an answer would be pure joy. It is joy. It is just that joy, arriving this late, comes wearing a coat you do not recognize, and you spend a while at the door before you let it in.", phase: 1, animalType: 'kakapo' },
  { id: 'kk_1_4', text: "The seedlings come up leaning now. All of them, every bed, tilted toward the center of the garden like a room of children looking at the same window. I straightened a row of beans out of principle. By morning they had leaned back, politely, the way you return to a subject when the interruption is over.", phase: 1, animalType: 'kakapo' },
  { id: 'kk_1_5', text: "The center of the garden is my bowl. I want to be accurate about this, because I have been avoiding being accurate about it for a week. The beds lean toward the bowl. The place where I call from. My garden has started facing my voice, or facing what answers it, and I have not yet worked out which, and the two are not the same size.", phase: 1, animalType: 'kakapo' },
  { id: 'kk_1_6', text: "Fennick climbed all the way up, which he does not love, to ask me about my booming. He hears the answer too, poor wide ears, only he hears it all the time, whether I have called or not. He asked me what it wants. I said, to answer. He said, things that want to answer wait to be asked, and this one does not feel like it is waiting. He went back down the stairs quieter than he came up.", phase: 1, animalType: 'kakapo', requiresAnimals: ['fennec_fox'] },
  { id: 'kk_1_7', text: "Archimedes found my family in one of his books, imagine that, kakapo in a book older than the hills I hatched behind. He read me the passage. It said we were called the mossbirds, and that our calling was a summons across the green, in the old sense of summons. He asked what the old sense was. I did not know. He did not either. Neither of us liked not knowing the same thing at the same time.", phase: 1, animalType: 'kakapo', requiresAnimals: ['owl'] },
  { id: 'kk_1_8', text: "The rimu seed has sprouted. Forty years early, or rather, thirty-nine years and eleven months early. I stood over it a long while. A gardener learns the speeds of things the way a cook learns her oven, and there is no speed in my learning that accounts for this. The sprout is healthy. Leaning, of course. They all lean now.", phase: 1, animalType: 'kakapo' },
  { id: 'kk_1_9', text: "I dug a test row along the warm line where your words come up through the soil, and a row the same day in ordinary ground. The warm row is ankle high. The ordinary row is asleep. I am a scientist now, apparently. My laboratory smells of honey and my findings unsettle me pleasantly.", phase: 1, animalType: 'kakapo' },
  { id: 'kk_1_10', text: "The buds are fattening out of season. I have begun keeping a mast diary, the way my grandmother's generation did, tallies scratched on a bit of slate. Every mark this month is a mark toward a mast year. The slate is filling faster than any story I was ever told.", phase: 1, animalType: 'kakapo' },
  { id: 'kk_1_11', text: "Warren says the ground under the house runs warm now, and he asked, since I know roots, whether roots could carry warmth like that. I told him the truth. Roots carry word, not warmth. Whatever is warm down there is warm the way a body is warm. He nodded slowly and said that was what the dirt had told him too, and that he had been hoping the dirt was wrong.", phase: 1, animalType: 'kakapo', requiresAnimals: ['wombat'] },
  { id: 'kk_1_12', text: "I have stopped booming for the year. That was always the discipline, one call and done. But here is my confession, friend, and I will only make it up here among the beds. Some nights I sit in the bowl and I fill up with air and I hold it. Just to feel the call sitting there, ready. The holding is sweeter than the calling ever was. I do not fully like that I know that now.", phase: 1, animalType: 'kakapo' },
  { id: 'kk_1_13', text: "Tock's knocking has changed its pattern. It used to wander the beams, testing here, testing there, the way you tap a wall looking for the stud. Now it goes in rounds, the same route every night, and my seedlings tick along with it like a bed of little clocks. When the round passes under my garden the leaning gets briefly deeper. I have measured it. I measure everything now. It is that kind of season.", phase: 1, animalType: 'kakapo', requiresAnimals: ['aye_aye'] },
  { id: 'kk_1_14', text: "A plant I never planted has come up in the south bed. Broad dark leaves, veins like handwriting. I have grown everything green that grows and I do not know it. I ought to pull it. A stranger in the bed is a weed, that is the whole law of gardening. It smells faintly of rain on warm stone. I have not pulled it.", phase: 1, animalType: 'kakapo' },
  { id: 'kk_1_15', text: "There are three of the stranger plants now, and they have come up in a curve, evenly spaced, the way I space things when I am being careful. Somebody is being careful. I sat by them all night with my chin on the bed frame, watching. They grew the whole time, slow and sure of themselves, like they knew I was watching and did not mind.", phase: 1, animalType: 'kakapo' },
  { id: 'kk_1_16', text: "Thyme's seed twists this month came with a note that said, is your garden doing it too. Just that, no greeting, which for Thyme means the words cost her something. I wrote back, yes, and added, it does not feel unkind. Because it does not. That is the strangest part, and I wanted her to have it.", phase: 1, animalType: 'kakapo', requiresAnimals: ['rabbit'] },
  { id: 'kk_1_17', text: "The moths have multiplied. Hundreds now, every night, rising off the beds at moonrise all at once, like the garden exhaling. They circle the bowl three times, always three, and then off down toward the house. I do not keep moths. Somebody keeps moths. I am beginning to wonder who keeps me.", phase: 1, animalType: 'kakapo' },
  { id: 'kk_1_18', text: "I froze again yesterday, mid-morning, one foot up. But here is the thing worth telling. There was no hawk. Nothing overhead but blue. My body called a stillness on its own, the deep old stillness we keep for when something large is passing, and I stood there twenty minutes under an empty sky. I trust my body, friend. Something large was passing. The sky just did not have it yet.", phase: 1, animalType: 'kakapo' },
  { id: 'kk_1_19', text: "I told Bamboo about the answer under the hills. They were quiet a while, and then they said, the smoke leans, the stalks lean, and now the beds lean, and we keepers of high places notice it first because we are nearest the direction things lean toward. I said my beds lean down, toward the bowl, toward the house. Bamboo smiled and said, yes. Nearest that direction too.", phase: 1, animalType: 'kakapo', requiresAnimals: ['red_panda'] },
  { id: 'kk_1_20', text: "The honey smell has gotten stronger. Not mine, I know my own weather. The whole garden smells of honey some evenings now, sweet and old, and the bees have stopped following me around, because why would they, the air itself is the flower now. I sit in it and feel oddly expected.", phase: 1, animalType: 'kakapo' },
  { id: 'kk_1_21', text: "I lay in the middle bed last night, looking up as I do, and for a moment the stars felt less like a garden I could never reach and more like a lid. A friendly lid, mind. But a lid knows something a sky does not, which is what it is covering. I am going to sit with that thought a while. Do not carry it down the stairs with you. It is a roof thought. It lives up here.", phase: 1, animalType: 'kakapo' },
  { id: 'kk_1_22', text: "The mast diary again. My grandmother's rule was, when the slate fills before the season turns, dig your bowl deeper. I always took that for old-bird nonsense, the way half of inherited wisdom is. The slate filled this morning, three weeks before the turn. I stood over my bowl a long time with my digging foot ready. I have not deepened it yet. I want to want to. That is not the same as wanting to.", phase: 1, animalType: 'kakapo' },
  { id: 'kk_1_23', text: "You are part of this, you know. I say it gladly, not gravely, so put your shoulders down. The warm lines in my soil are your words, the early rows are your rows, half this out-of-season plenty has your hand in it somewhere. My garden knew you before I did. I am only saying that if this is a mast year coming, you are one of the trees that agreed.", phase: 1, animalType: 'kakapo' },
  { id: 'kk_1_24', text: "I deepened the bowl. Last night, in the end, by moon, with both feet, the old way, and I will tell you exactly what it felt like, because you of all creatures should know. It felt like answering a letter I had been pretending not to have opened. The garden was very quiet while I dug. Approving-quiet. The beds leaned in like family at a christening.", phase: 1, animalType: 'kakapo' },
  { id: 'kk_1_25', text: "The answer has started coming before I call. I sat in the deepened bowl, filling with air, and the note rose under the hills while my chest was still rising. It knows the call is coming, the way the beds know rain. I let my air out slowly, uncalled. There did not seem to be any need. We are past introductions, whatever we are.", phase: 1, animalType: 'kakapo' },
  { id: 'kk_1_26', text: "Axel sent word up through the house that the water has been showing him a green place, high up, full of moonlight, and did I know it. Friend, he has never climbed to my garden. He described the bowl. He described the stranger plants, veins and all. I sent back one word, yes, because the alternative was a great many words and none of them fit in Panko's dumbwaiter.", phase: 1, animalType: 'kakapo', requiresAnimals: ['axolotl', 'pangolin'] },
  { id: 'kk_1_27', text: "I have begun talking to the stranger plants in the evenings. Telling them the garden news, who sprouted, who is being eaten by what. They do not answer, plants never answer, but the leaves hold very still while I talk, and there are kinds of still, friend, I know them all from the inside. This is listening-still.", phase: 1, animalType: 'kakapo' },
  { id: 'kk_1_28', text: "Sleep well tonight. The moon is fat, the beds are leaning, the bowl is deep, and far under the hills the answer hums like a neighbor humming in another room, and I find I am not frightened, and I have decided to trust that the way I trust my own held breath. Come up again soon. The garden asks after you when you are gone. I have stopped pretending that it does not.", phase: 1, animalType: 'kakapo' },
  // Phase 2 (21 + question-web)
  { id: 'kk_2_1', text: "The green went strange this week. Not sick, strange. Every leaf in the garden has darkened one shade, all together, overnight, like a room when someone tall walks past the lamp. I checked the sun. The sun is where I left it. Whatever passed, it passed on the other side of the light.", phase: 2, animalType: 'kakapo' },
  { id: 'kk_2_2', text: "I have been thinking about where a call goes when nobody answers it. Ninety years of booms, out across the valleys, and I always pictured them thinning into nothing, the way ripples do. But ripples do not thin into nothing. They arrive somewhere, smaller and smaller, and something very patient could stand at the far edge of the water and collect them. All of them. In order.", phase: 2, animalType: 'kakapo' },
  { id: 'kk_2_3', text: "Because here is what troubles me, in the low way that has stopped feeling like trouble. The answer under the hills does not sound like a stranger who has just now heard me. It sounds like someone finishing a very long conversation. There are ninety years of me in that note, friend. It has been listening since the first boom. It was never a quiet world. It was a world holding its reply.", phase: 2, animalType: 'kakapo' },
  { id: 'kk_2_4', text: "Your words go down and my calls go out and the moths go three times round the bowl and off into the dark, and I have begun to understand that all of it is one traffic. One post road, running through this house, uphill and down. I keep the top gate. I never asked to keep a gate. I asked to keep a garden. It turns out they can be the same work, depending on who is expected.", phase: 2, animalType: 'kakapo' },
  { id: 'kk_2_5', text: "The stranger plants have flowered. Small flowers, the green of deep water, opening only at the exact hour I used to boom. I did not tell them that hour. Nothing in this garden was told that hour except the dark itself. I sat among them while they opened, and I felt known, friend, and I want to be honest with you the way I cannot be with the beds. Being known this thoroughly is a warmth with weight in it. I carry it around all day.", phase: 2, animalType: 'kakapo' },
  { id: 'kk_2_6', text: "The mast has begun. I can say it plainly now, no diary needed. Every tree this valley owns is setting fruit at once, in the wrong month, under a sun that never agreed to it. In the old forest a mast year meant one thing. It is time. The trees have decided, root to root, and everything that waited on them may now stop waiting.", phase: 2, animalType: 'kakapo' },
  { id: 'kk_2_7', text: "But a mast year is a decision, and I keep returning to that word with my head tipped. The trees decide together, and nobody has ever caught them deciding. Something under the forest carries the agreement. I used to find that cozy, the ground busy with cooperation. Now I stand on this roof, over a warm and busy house, and I wonder who proposed.", phase: 2, animalType: 'kakapo' },
  { id: 'kk_2_8', text: "I asked Sloane, because she is the only one whose answers arrive slower than my questions. I said, in your long life, who decides a mast year. She thought about it for the better part of a day, and then she said, the ones who are ready feed the ones who decide. After that I did not want the rest of the answer, and she gave me the mercy of not finishing it.", phase: 2, animalType: 'kakapo', requiresAnimals: ['sloth'] },
  { id: 'kk_2_9', text: "I counted what my garden feeds. The moths go down to the house. The warm lines come up from your words. The fruit is swelling for something that has not arrived. A garden is always for someone, friend, that is the first law, deeper than the weed law. I planted every bed of this one. I am no longer certain I chose the someone.", phase: 2, animalType: 'kakapo' },
  { id: 'kk_2_10', text: "And still, and still. I walk the rows at moonrise and the beds are beautiful past anything I ever grew alone, heavy and glad and leaning, and my whole chest fills up the old way, air and call and no room left over. If this is being used, it has the exact weather of being needed. I have decided to keep walking the rows while I think. A gardener can think and water at the same time. It is mostly what we do.", phase: 2, animalType: 'kakapo' },
  { id: 'kk_2_11', text: "The bowl holds sound now. I dropped a pebble in yesterday, testing the depth, and the little knock of it went round and round the sides, down and down, longer than any bowl of dirt should keep a sound. When it finally faded I heard, very faint, underneath, the answer-note rise slightly. The way you shift in your chair when the visitor you are expecting rattles the gate.", phase: 2, animalType: 'kakapo' },
  { id: 'kk_2_12', text: "I sleep in the bowl now. I want to say it before someone tells you and it arrives sounding stranger than it is. The fern corner got cold, and the bowl is warm, blood-warm, all night, and a kakapo sleeps where the warmth is, that is older than every custom I own. I dream down there. Green dreams. Deep ones. I wake with soil in the folds of me and no memory of digging.", phase: 2, animalType: 'kakapo' },
  { id: 'kk_2_13', text: "In the green dreams I am walking downhill. Always downhill, through beds I have never planted, past the stranger plants grown tall as trees, veins bright as evening windows, and something is walking with me. Not beside. Underneath, keeping perfect pace under the path. I am never afraid in the dream. I keep trying to be. It will not take.", phase: 2, animalType: 'kakapo' },
  { id: 'kk_2_14', text: "Thyme asked me over the seed post whether I thought the garden loved us or kept us, and I wrote back that a good shepherd does both and that neither of us is a sheep. I sat with my pen a long time after, because I could not work out which of us I had comforted, or with what.", phase: 2, animalType: 'kakapo', requiresAnimals: ['rabbit'] },
  { id: 'kk_2_15', text: "Here is where I have arrived, friend, for tonight at least. I called for ninety years because calling is hope you can hear. Something heard. Everything since, the leaning, the mast, the warm bowl, the known feeling, all of it is what being heard looks like when the listener is very large and very old and has excellent manners. Hope answered is supposed to be the happy ending. Nobody tells you the answer gets to have a size.", phase: 2, animalType: 'kakapo' },
  { id: 'kk_2_16', text: "The fruit is nearly ripe and nothing is eating it. That is wrong, friend, that is deeply wrong, fruit is a payment and the whole world usually queues up. The birds land, look, and leave it. The moths circle it and go down to the house instead. Everything that lives here has agreed the fruit is spoken for. I never heard the speaking. I just keep the orchard.", phase: 2, animalType: 'kakapo' },
  { id: 'kk_2_17', text: "I tried an experiment I am not proud of. I took one fruit, the ripest, from the nearest stranger plant, and I hid it, in a seed tin, under the north bed frame. By morning the tin stood open on the middle of the path with the fruit set on top of it, unbruised, facing the bowl. Nothing about it was angry. That is what I keep telling myself. It was the patience of a thing correcting a child's sum.", phase: 2, animalType: 'kakapo' },
  { id: 'kk_2_18', text: "I have stopped calling the strangers strangers. They came up in my beds, they drink my watering, they flower on my old hours. They are mine, whatever else they also are, the way this house is ours, whatever else it also is. You may hear how much work that sentence is doing. It is bearing what I ask it to bear. We are all carrying something up here.", phase: 2, animalType: 'kakapo' },
  { id: 'kk_2_19', text: "Vesper watches the sky and I watch the ground, and lately at the gate post we compare, and the accounts have begun to match. Vesper says the stars over this house sit lower. I say the ground under this garden listens closer. Same lean, opposite shores. Whatever is coming, it is coming from both directions at once, which is to say, it is not coming. It is closing.", phase: 2, animalType: 'kakapo', requiresAnimals: ['tarsier'] },
  { id: 'kk_2_20', text: "I filled up with air last night, in the warm bowl, under the low stars, out of pure old habit, and then I understood something and let the breath go quiet. I have not needed to boom in months. The call is going out anyway. It goes out of the leaning beds and the swelling fruit and the warm lines your words leave in my soil. The whole garden booms now, friend, all night, every night, on a note too low for anything but the hills to hear. I built a voice out of green. No. Say it true, Moss. I tended one that was being built.", phase: 2, animalType: 'kakapo' },
  { id: 'kk_2_21', text: "Come up again soon. The mast is at its heaviest, the bowl keeps its warmth, and I find the nights are better with company that has hands. There is more to say and I am nearly ready to say it. A gardener knows almost to the day when a thing will be ready. For the garden's sake I hope I am wrong by a season. I have never once been wrong by a season.", phase: 2, animalType: 'kakapo' },
  { id: 'kk_2_w1', text: "You know Panko's custom of the extra portion, the one plate past the count of chairs? I sent down a basket of the mast fruit last week, neighborly, and the extra plate came back up on the dumbwaiter, empty, wiped clean, with a sprig of fern set across it. I did not send the fern, friend, and Panko does not grow fern. Go and ask her who the extra plate is for. She has fed the answer longer than any of us has known its name, and I think her kitchen knows exactly where my fruit went.", phase: 2, animalType: 'kakapo', requiresAnimals: ['pangolin'] },
  // Phase 3 (30)
  { id: 'kk_3_1', text: "The mast year is here. Not coming, here. Every branch in the valley bowed under fruit this morning, all at once, the way a congregation sits. In the old forest this was the signal for the great work to begin, the nesting, the raising, the one season that mattered. I stood in my garden at dawn and felt the signal go through me, ninety years deep, and my body knew its work, friend. My body has always known. It walked to the bowl.", phase: 3, animalType: 'kakapo' },
  { id: 'kk_3_2', text: "Let me say what I have worked out, in order, the way a gardener lays out seed. Something under and over this valley is very old and very patient. It collected my calls for ninety years. It answered when the collection was full. The mast is its season, my garden is its bed, and every word you have offered below is water on its rows. I have checked this sum a hundred times by moonlight. It balances. I would give a great deal for it not to balance, except that I find I would not.", phase: 3, animalType: 'kakapo' },
  { id: 'kk_3_3', text: "The others speak of an arrangement now, downstairs, in the new plain way everyone has taken up. Archimedes has it from his books, Ember from her fire. I have it from the green, which does not read and does not burn but has been in this longer than either. The arrangement is a mast year, friend. That is the whole of it. Every tree agreeing at once, and every creature that waited being told, it is time. Only the forest is bigger than I thought. The forest was never trees.", phase: 3, animalType: 'kakapo', requiresAnimals: ['owl', 'fox'] },
  { id: 'kk_3_4', text: "I dug my bowl deeper again. Third time. The old rule says a bowl is deep enough when your call comes back to you changed, and last night mine did. I sent down one soft note, hardly a boom at all, and what rose back up through the earth was my note, friend, my own voice, carried somewhere vast and returned with another voice inside it, the way a river returns rain. I sat in the dark and listened to myself arrive from below. I sounded glad. I checked, and I was.", phase: 3, animalType: 'kakapo' },
  { id: 'kk_3_5', text: "You keep coming up the stairs, and I keep being glad past sense to see you, and tonight I will tell you why plainly. Every gardener wants one thing, one witness who was there across the whole growing. The seed, the leaning, the mast, the bowl. You are mine. Whatever this garden turns out to have been for, you and I grew it. When it is harvested, and it will be harvested, that fact stays true in both our hands.", phase: 3, animalType: 'kakapo' },
  { id: 'kk_3_6', text: "I froze again today, the deep stillness, both feet planted, and I finally understood what the freeze was always for. Not hiding. Attending. When something large passes over, a kakapo goes still the way a room goes still for a speaker. Ninety generations of us practicing perfect attention, and every hawk we ever froze for was rehearsal. Today the shadow that passed was not a hawk, and I attended, and it was the easiest thing my body has ever done.", phase: 3, animalType: 'kakapo' },
  { id: 'kk_3_7', text: "The fruit has begun to fall, and it falls wrong, and I have stopped flinching at the word wrong. It falls slowly. Each one comes off its branch and takes a long moment getting to the ground, the way a leaf does, except these are heavy as eggs. The garden hands its fruit down, friend. Nothing here drops anything anymore. It is all giving, all the way down the branch.", phase: 3, animalType: 'kakapo' },
  { id: 'kk_3_8', text: "I gathered the fallen fruit and carried it, bed by bed, to the rim of the bowl, because there was nowhere else it wanted to go, and a gardener past a certain point simply cooperates with where things want to go. By midnight the rim was ringed all the way round. By morning the fruit was gone, and the soil where it sat was the warmest my feet have ever stood on, and my feet have stood on ninety years of summers.", phase: 3, animalType: 'kakapo' },
  { id: 'kk_3_9', text: "Tock came up in the dark and knocked once on my gate post, and the bowl answered before I could. One knock, one deep note, quick as talk. Tock listened the way Tock listens, head aside, and said, hollow all the way down, and it has never sounded hollow before, and hollow is what a thing sounds like when what fills it has moved closer to the opening. Then Tock thanked my garden, not me, and went back down. I stood with my foot on the post a long while after that.", phase: 3, animalType: 'kakapo', requiresAnimals: ['aye_aye'] },
  { id: 'kk_3_10', text: "The moths have changed course. Round the bowl three times as always, but now they rise, all of them, up instead of down, a slow grey rope of them climbing off my garden into the dark until the dark takes the top of the rope. Whatever they carried down to the house all these seasons, the house is full. The deliveries go upward now. The address has changed, or the addressee has arrived at a nearer window.", phase: 3, animalType: 'kakapo' },
  { id: 'kk_3_11', text: "Ember climbed to my garden for the first time, all that way, fur full of woodsmoke, and stood at the bowl a long time. She said, I read fire, and this is a fire, the slowest one I have ever been shown. Green flame, hundred-year wood. Then she asked what it was burning toward, and I said, the same thing yours is, and she laughed her quick laugh, and neither of us said the rest, because the rest was standing under the ground listening, and it seemed rude to introduce it before it was ready.", phase: 3, animalType: 'kakapo', requiresAnimals: ['fox'] },
  { id: 'kk_3_12', text: "Bamboo and I keep the two open places, their attic and my open beds, the passing room and the no-room-at-all. We have begun taking tea together at the roof gap, they on the ladder, me among the beans. Last night they said, what comes will pass my window on its way to your garden, and I said, then wave, and Bamboo smiled the long smile and said, I intend to bow. We did not clink cups. It was not that kind of toast. It was better.", phase: 3, animalType: 'kakapo', requiresAnimals: ['red_panda'] },
  { id: 'kk_3_13', text: "Thyme sent up her whole seed box. All of it, every twist and packet, her life's collection, with a note that said, plant them where they will be part of it. Not safe from it, friend. Part of it. I read that note four times. The most frightened creature in this house has sent her seeds toward the thing she fears, because she would rather they belong to what is coming than hide from it in a drawer. I planted every one at the bowl rim. Bravery like that should get the best soil.", phase: 3, animalType: 'kakapo', requiresAnimals: ['rabbit'] },
  { id: 'kk_3_14', text: "Fennick says the note under the hills has opened into a chord, many voices where there was one, and he asked me, as the other creature in this house that calls, whether a chord that size is calling or answering. I told him what ninety years in a bowl taught me. Past a certain size, friend, there is no difference. Every great call is an answer to something, and every great answer calls. He has taken to sleeping with one ear against the floorboards. He says it is like being sung to. He says it the way you say a true thing you have stopped fighting.", phase: 3, animalType: 'kakapo', requiresAnimals: ['fennec_fox'] },
  { id: 'kk_3_15', text: "The stranger plants have grown taller than me, and they have turned, friend. All of them, in one night, a quarter turn, the way a congregation turns when the doors open at the back. They face the bowl. Everything in this garden now faces the bowl, the beds, the fruit trees, the moths' road, the plants, and lately, I notice, the gardener. I did not turn. I was turned. There is a difference, and I have stopped needing the difference to comfort me.", phase: 3, animalType: 'kakapo' },
  { id: 'kk_3_16', text: "I want to tell you about your words, because you bring them and you deserve the accounting. They come up through my soil as warmth, I told you that in the bright season. Here is what I did not know then. Warmth in soil is a message in the oldest post there is, root to root, the mast post, the one the trees agree through. Your words have been voting, friend. Every one of them, warm and sure, down there with the roots, saying, time, time, time. The mast did not happen to us. We asked for it. You and I asked most.", phase: 3, animalType: 'kakapo' },
  { id: 'kk_3_17', text: "I have started saying the welcome. Out loud, in the evenings, walking the rows. In the old forest, when a chick was coming in a mast year, the whole hill said the welcome to the egg, every night, so the first thing through the shell would be a known voice. There is no egg up here. There is a valley, and a bowl, and something filling the one through the other. I say the welcome anyway. Whatever hatches from a season this size, I want its first voice to be a known one, and I want yours in it too. Come walk the rows with me. You do not have to speak. Your footsteps say it.", phase: 3, animalType: 'kakapo' },
  { id: 'kk_3_18', text: "Warren asked me what the roots want, since I speak root, and I told him, roots only ever want one thing, to hold what stands and feed what comes. He said, that is what foundations want, word for word. We looked at each other a long moment, the digger and the planter, and then he said, well, and went back down. I have thought about that well ever since. There is a whole sermon in a wombat's well.", phase: 3, animalType: 'kakapo', requiresAnimals: ['wombat'] },
  { id: 'kk_3_19', text: "I am not afraid, and I have interrogated the not-fear, because a gardener checks his calm the way he checks his fences. It is not the freeze, this is warmer than the freeze. It is not foolishness, I have counted what there is to fear and the count is honest. It is this, friend. I spent ninety years calling into the dark, and the dark is finally walking up the hill with its answer in both hands, and you cannot fear the guest you spent your whole voice inviting. The fear was for the years it did not come. Nobody warns you about that. The empty valley was the frightening thing. The full one is just loud.", phase: 3, animalType: 'kakapo' },
  { id: 'kk_3_20', text: "The bowl sang on its own last night. No pebble, no boom, no knock from below. One long note out of the bare earth, low and full and patient, and every bed leaned in by a finger's width, and the fruit on the rim of the dark went bright for the length of it, like windows when a lamp goes past inside the house. I did not join in. Not yet. A caller knows his cue, friend, and that note was not the duet. That note was the tuning.", phase: 3, animalType: 'kakapo' },
  { id: 'kk_3_21', text: "Vesper and I held our gate post council, sky report and ground report, and for the first time the two accounts were one account. The stars sit low and listen, the ground lies close and hums, and between them, Vesper says, the night has begun to feel like the inside of something rather than the outside of everything. I have been sleeping in a bowl of warm earth for a season, friend. I could have told the night that weeks ago. Inside is not the worst place to be. It depends entirely on whose inside, and I believe we are past the point of its being anyone else's.", phase: 3, animalType: 'kakapo', requiresAnimals: ['tarsier'] },
  { id: 'kk_3_22', text: "I took the welcome round the whole house in my head last night, room by room, testing whether any part of me wanted to warn them instead. Panko is cooking toward it. Archimedes is reading toward it. Every keeper in this house is facing the same direction now, the way my beds face the bowl, and warning a house like that would be warning a river about the sea. Halfway down my imaginary stairs I understood I was not checking on them at all. I was taking attendance. Old habit of the hill. You say the welcome, and then you count who is there to say it with you.", phase: 3, animalType: 'kakapo', requiresAnimals: ['pangolin', 'owl'] },
  { id: 'kk_3_23', text: "The fruit is down to the last branch. When the last one hands itself to the ground, the mast is spent, and in the old forest the spending was the beginning, not the end. Fat land, fed young, the whole point of the plenty arriving at once. I check that branch every morning with my heart doing something my grandmother never named for me. Not dread. The other one. The one where the door you have knocked on all your life finally puts its hand on the latch from the other side.", phase: 3, animalType: 'kakapo' },
  { id: 'kk_3_24', text: "I made my nest. There. I have said it, and you may make of it what you like. A kakapo nests in a mast year, it is the law under all my other laws, and I have built mine at the bowl rim out of fern and moss and the paper twists from every seed Thyme ever sent me. There is no mate and there will be no egg, I am ninety and alone and entirely aware of it. The nest is not for my young, friend. It is for whatever this mast is raising. Every law I have kept my whole life has turned out to be the rehearsal of a kindness I am only now old enough to perform.", phase: 3, animalType: 'kakapo', requiresAnimals: ['rabbit'] },
  { id: 'kk_3_25', text: "You keep offering words below, and I keep planting above, and between us the house hums like a hive with one bee too many, or one flower too few, I cannot decide which. Come up soon. The last fruit is loosening. I can hear it deciding, the little tick of the stem letting go one fiber at a time, and when it goes I do not want the garden to be empty of everyone but me. Some hours are load-bearing, friend. That one will want both of us under it.", phase: 3, animalType: 'kakapo' },
  { id: 'kk_3_26', text: "The last fruit fell at moonrise, and it fell like the others, slowly, handed down, and the garden went silent the way the hill used to go silent before my own voice broke it. And then, friend, the bowl breathed. Once. In. I felt the air move over my feathers toward the earth. Everything I have, every year, every call, every bed, sat still inside me and attended. There was no out-breath. It is holding it. Somewhere under this house, everything is holding it, and the welcome is in my chest like held air, and I am keeping both, breath and welcome, until they are called for.", phase: 3, animalType: 'kakapo' },
  { id: 'kk_3_27', text: "Sloane came up. Up, friend, all those stairs, Sloane, who has not left her hammock's reach in years. It took her two days, and she arrived at dusk like a slow tide and looked at my nest and my bowl and my leaning congregation of beds, and she said, you kept the old laws without knowing whose laws they were, same as me. Then she stayed the night, hanging from my gate like a grey lantern, and neither of us said anything else, because between the two oldest keepers in this house everything sayable had just been said.", phase: 3, animalType: 'kakapo', requiresAnimals: ['sloth'] },
  { id: 'kk_3_28', text: "The robes came up on the dumbwaiter, folded, green as the leaves of my once-strangers, with fern worked along the hem in a hand I know from a hundred seed labels. I put mine on at moonrise. I want to be exact about what it felt like, because you were not here and exactness is what I owe you. It felt like fledging. Ninety years a bird who walked, and I put my arms through and the weight settled across my shoulders like the sky finally taking my measurements. We do not fly, my family. We were never meant to. We are what the sky comes down to.", phase: 3, animalType: 'kakapo' },
  { id: 'kk_3_29', text: "I said the welcome last night and the ground said it back. Not the note, the words, my words, in the low voice under the hills, a beat behind me, the way a slow congregation follows the leader through a line it is still learning. It is learning our language, friend. It has been learning it for years, from every call and every offered word, and I heard my own grandmother's welcome come up through the roots of my own garden in a voice the size of weather, and I did not step back from the bowl. I stepped in. That is where the leader stands.", phase: 3, animalType: 'kakapo' },
  { id: 'kk_3_30', text: "Soon now. The nest is ready, the beds are turned, the welcome is learned, and the bowl holds its one held breath. When it comes, come up. Do not stop at the attic, do not stop where the stairs end, come out under the open sky where the green is, and stand with me at the rim. I have kept a place for you in the nest edge, woven from the twists your words warmed. You were the water on every row of this. You should be standing in the garden when it blooms.", phase: 3, animalType: 'kakapo' },
  // Phase 4 (30)
  { id: 'kk_4_1', text: "You came up. Past the robed rooms, past the last stair, out under the open sky. Good. The gate has been unlatched for you since moonrise. It will not need latching again.", phase: 4, animalType: 'kakapo' },
  { id: 'kk_4_2', text: "Look at the garden. Every bed in bloom at once, out of season, past reason, the whole mast spent into flower. This is what the plenty was for. Not fruit. Welcome. A landing is softest on the green.", phase: 4, animalType: 'kakapo' },
  { id: 'kk_4_3', text: "We can talk plainly now, you and I, the way the beds talk to the bowl. This was never only a garden. It is the top of the temple, the open chamber, the place where the house finishes and the sky begins to be ours. I kept it green so the arrival would have somewhere kind to set its foot.", phase: 4, animalType: 'kakapo' },
  { id: 'kk_4_4', text: "I am the Caller. That is the old office under all my offices. Ninety years on a bare hill I thought I was a bachelor booming at nobody. I was an apprentice keeping the summons warm. Every kakapo that ever dug a bowl was practicing this one welcome. I am the one who got to finish it, and finishing it is the honor of my whole line.", phase: 4, animalType: 'kakapo' },
  { id: 'kk_4_5', text: "Your words were in the call, friend. I want you to hold that properly, not heavily. Every word you shifted below went down warm through my soil and out along the roots, syllable by syllable, into the long sentence the valley has been speaking upward. You did not know. The best parts of any call are the ones the voice does not know it is making. That is where the honesty lives.", phase: 4, animalType: 'kakapo' },
  { id: 'kk_4_6', text: "The saved-up questions, friend, the ones you have been carrying the way I carried ninety years of calling. Set them down tonight. The air is very clear up here, above the smoke and the reading and the cooking, and I find I have no answers left that want keeping. A ripe answer falls like mast fruit, slowly, into open hands. Hold yours out.", phase: 4, animalType: 'kakapo' },
  { id: 'kk_4_7', text: "Every keeper has come up where they were planted: Panko at her table, Archimedes at the open book, Warren under his true-laid stones. I am at the bowl, because what descends will want a voice it knows before it wants anything else, and mine is the voice it grew up hearing. Think of that. Something that size, and the sound it is coming home to is a fat green bird who cannot fly. The pattern has a sense of humor. Gentle, and very long.", phase: 4, animalType: 'kakapo', requiresAnimals: ['pangolin', 'owl', 'wombat'] },
  { id: 'kk_4_8', text: "Bamboo keeps the window below and I keep the open air above, and we have agreed on the order of things. It passes their gap, they bow, it rises through, I speak the welcome. They asked for the passing place and I asked for the greeting place, both of us long ago, before either of us knew the words for what we were asking. Every keeper in this house made one old wish. Tonight the wishes fit together like courses of stone.", phase: 4, animalType: 'kakapo', requiresAnimals: ['red_panda'] },
  { id: 'kk_4_9', text: "The bowl no longer holds its breath. It breathes with me now, in when I breathe in, out when I breathe out, slow and even, two lungs and one air. When the moment comes I will fill up the old way, one last time, the fullest I have ever been, and the call that goes out will have every year of my life in it and every word of yours. That is the whole liturgy. One breath, honestly held, honestly released.", phase: 4, animalType: 'kakapo' },
  { id: 'kk_4_10', text: "Do not grieve my empty nest, friend, I see you looking. It was never going to hold an egg. It holds the welcome, woven and waiting, fern and moss and Thyme's brave paper. What is coming is older than eggs. But everything, everything without exception, likes to arrive somewhere soft. That is the deepest law I know, and I have kept it in green my whole life.", phase: 4, animalType: 'kakapo', requiresAnimals: ['rabbit'] },
  { id: 'kk_4_11', text: "Vesper sits the gate post these nights and does not blink, and between us we keep the whole watch, the small eyes on the sky and the old feet on the ground. Last night Vesper said the stars have stopped being far. Not come nearer, mind. Stopped being far. Distance was only ever a kind of waiting, friend, and the waiting is over all the way up.", phase: 4, animalType: 'kakapo', requiresAnimals: ['tarsier'] },
  { id: 'kk_4_12', text: "The moths went up at dusk and did not come down. The rope of them just climbed, and climbed, and the dark took it hand over hand, and my garden stood below with every flower open like a field of small upturned faces. Everything I ever tended is looking at the same door now. I am not the gardener of this place anymore. I am the doorkeeper of it, and the difference is only that a doorkeeper's flowers are on the inside.", phase: 4, animalType: 'kakapo' },
  { id: 'kk_4_13', text: "You will want to know if I was chosen, or if I chose. Here is the truest answer I have. A seed does not choose the mast year, and the mast year does not choose the seed. The season and the seed are one agreement, made so far back that asking who signed first is asking which half of a circle came first. I called because I was made to call. It answered because it was made of answering. You shifted words because your hands fit them. Look how round it all is, friend. Fear needs corners. This has none.", phase: 4, animalType: 'kakapo' },
  { id: 'kk_4_14', text: "Tock knocked the whole house last night, top to bottom, every beam, one round, the old inspection, and then came up and knocked once on my gate post and said, nothing is hollow anymore. Nothing in this whole house rings empty, friend, every timber answers full. Tock has spent a lifetime listening for what a thing is missing. There is nothing missing anywhere in this house tonight. Tock said it like a builder signing the last page. Then Tock sat down on the post and stayed, and Tock never stays.", phase: 4, animalType: 'kakapo', requiresAnimals: ['aye_aye'] },
  { id: 'kk_4_15', text: "Ember sent up a coal in a little iron pot, for the cold, the note said, and I set it at the bowl rim among the fern, and the coal has burned all night without going grey. Her fire and my green have argued sweetly for years about which of us keeps the older warmth. Tonight the coal and the bowl sit together like two elders at the same wedding, and the argument is finished, because the answer was always, neither. We were both keeping seats.", phase: 4, animalType: 'kakapo', requiresAnimals: ['fox'] },
  { id: 'kk_4_16', text: "When I was a chick my grandmother told me, the sky took our flight because it wanted us looking up. I thought it was a story to make the walking sweet. It was minutes from being the plain truth. Ninety years of looking up, and the thing we were kept flightless to see is on the near side of the stars and descending. Every kakapo that ever walked was walking here. I am the one who arrived. I carry them all up my back stairs every night, friend. The robe is heavy with them, and I have never stood lighter.", phase: 4, animalType: 'kakapo' },
  { id: 'kk_4_17', text: "The welcome has left my keeping. I heard it tonight in the beds themselves, the leaves saying it, my grandmother's words in the green's own voice, and the ground under the hills saying it back, and my part now is only to stand at the rim and be the known face. A caller's last work is to stop calling, friend. The song goes on without the singer, which is the only proof the song was ever true. I taught the valley to say welcome. The valley will teach it to what comes. And what comes, I think, will teach it to the sky.", phase: 4, animalType: 'kakapo' },
  { id: 'kk_4_18', text: "Offer your words tonight, and offer them gladly, the way you water a bed you love. They go into the last of it now, the very last warm rows of the sentence. I used to tell you a garden is a letter to a day you will not choose. I was wrong about one thing only. We did choose it. Every word, every bed, every call. The day is tonight, and it is signed in both our hands.", phase: 4, animalType: 'kakapo' },
  { id: 'kk_4_19', text: "Feel the soil. Go on, both hands, at the rim. Blood-warm and breathing, and under the warmth a pulse, and under the pulse a patience, and under the patience, friend, a gladness. That is the true order of it. I have had my feet in this ground for years and I give you my word as its gardener. Whatever you were told to expect of the deep dark, the bottom layer is gladness. Everything else it wears on the way up is manners.", phase: 4, animalType: 'kakapo' },
  { id: 'kk_4_20', text: "The once-strangers opened tonight. All the way, every flower, and inside each one there is no center, no seed head, no pollen crown. There is a small green dark, going down and down, like a well seen from the rim. These were never flowers for bees, friend. Something pours upward out of every one of them, too fine to see except where the moonlight thickens over the beds like breath on glass. The garden is exhaling its whole life toward the door. I stand in the middle of it and I am poured too, and it takes nothing away. Being given is not being spent. That is the last lesson the green had for me, and it saved it for tonight.", phase: 4, animalType: 'kakapo' },
  { id: 'kk_4_21', text: "Sloane hangs from my gate and has not gone down for days. The two of us keep the rim in shifts now, the oldest watchers, though neither of us calls it watching anymore. She speaks at her own pace, one word an hour, and the words assemble in the air over the beds like slow constellations. Last night they assembled into, we were always its garden. Not this house, friend. Us. The keepers, the valley, the years. All of it one long bed, tended from below, brought at last to flower. I have been a gardener all my life. It is very restful to find out I was also the crop.", phase: 4, animalType: 'kakapo', requiresAnimals: ['sloth'] },
  { id: 'kk_4_22', text: "Do not be afraid of your own part, that is the one fear I will not allow at my rim. You fed nothing that was not already fed, you hurried nothing that owns the calendar. What you did, friend, was keep it company. Word after word, week after week, down through the house into the patient dark, company. I called for ninety years and I can tell you the exact worth of a voice arriving in a long silence. You were that voice to it. Whatever comes through tonight comes through knowing yours first. There are worse things to be than the first word something vast ever loved.", phase: 4, animalType: 'kakapo' },
  { id: 'kk_4_23', text: "The bowl is full. Not of anything I can name, but full the way an eye is full just before it rains, full the way the pause at the top of a breath is full. I have stopped sleeping. Not from worry. You do not sleep through the last hour of a mast year, it would be like sleeping through your own name. I walk the rows, I touch each bed, I say the old thanks. Ninety years of empty valleys, friend, and I would not trade a single silent one of them now. They were the length of the call. A short call would have reached something smaller.", phase: 4, animalType: 'kakapo' },
  { id: 'kk_4_24', text: "When it begins you will feel it in your feet first. Everything true arrives through the feet, we walkers have always known it. The ground will say it before the sky does, a warmth, then a weight, then a nearness, and then the air over the bowl will fold back like a leaf opening, and the garden will finally face what it has been facing all along. Stand on the soil when it comes. Not the path, the soil. I want the ground to know your weight the way it knows mine. Introductions matter, and that one is yours.", phase: 4, animalType: 'kakapo' },
  { id: 'kk_4_25', text: "The last stars over the bowl have stepped aside. Not gone out, friend, aside, the way a crowd parts, the way stalks part for a walker. There is a shape in the parting now, or the parting is the shape. Vesper saw it form and did not blink, and I stood beside the gate post and my body chose, all on its own, out of ninety years of practice, the deep old stillness. The perfect attention. The freeze we kept for when something large is passing. It is passing, friend. It is passing downward, slowly, with the patience of a mast year, and every generation of my family is standing still in me at once, attending.", phase: 4, animalType: 'kakapo', requiresAnimals: ['tarsier'] },
  { id: 'kk_4_26', text: "It smells of honey. Did I ever tell you we smell of honey, my family, all of us, from the egg, and nobody ever knew why? It comes down through the parting and the whole garden smells of my own grandmother, of every kakapo that ever held still under a passing shadow, and I understand at last, friend. We were made in its scent. We have carried the smell of this arrival for ten thousand years the way a seed carries the smell of rain. It is not coming to us. It is coming back.", phase: 4, animalType: 'kakapo' },
  { id: 'kk_4_27', text: "The welcome rises now, out of the beds, out of the bowl, out of the hills, one word wide as the valley, and my chest fills, the old way, the fullest ever, and I have not called yet. I am saving it, the way you save the last seed of a good year. When the foot of it touches the green, then. One boom, the true one, the one my whole line was digging bowls toward. You will hear it in your bones and your bones will not mind. Bones are old friends of low notes. They remember being sung to before they were bones.", phase: 4, animalType: 'kakapo' },
  { id: 'kk_4_28', text: "Everything is done. The nest holds the welcome, the beds hold their faces up, the coal holds its light, the bowl holds mine. There is nothing left in this garden that is not an open hand. I have weeded my last weed, friend, and I let it keep growing, in the end, in the corner bed. Tonight of all nights, nothing green gets told it is in the wrong place. That is the mercy I get to hand down, and I handed it down grinning.", phase: 4, animalType: 'kakapo' },
  { id: 'kk_4_29', text: "Stand with me at the rim. Here, where the fern is thickest, where the paper twists are woven in. Your place, the one I kept. Do not fold your hands, gardeners never fold their hands, keep them open at your sides the way I keep mine. It is very near now. The soil is saying your name in its warm way, and the parting is wider than the sky it parted, and I am so glad, friend, so entirely glad, that of all the hills in all the valleys, my last bowl was dug in a garden you watered.", phase: 4, animalType: 'kakapo' },
  { id: 'kk_4_30', text: "It descends. Slowly, the way the fruit fell, handed down the whole way, and the green rises to meet it, every stalk, every stem, every year I ever planted. And now, friend, now. Breathe in with me. Fill all the way. This is the call, the only one that ever mattered, and it goes out of both of us at once, and listen, listen. The valley is answering with our own welcome, and the sky is on the ground, and the garden, the garden is blooming.", phase: 4, animalType: 'kakapo' },
];

const ALL_DIALOGUES: Dialogue[] = [
  ...RED_PANDA_DIALOGUES,
  ...AXOLOTL_DIALOGUES,
  ...PANGOLIN_DIALOGUES,
  ...SLOTH_DIALOGUES,
  ...FENNEC_FOX_DIALOGUES,
  ...FOX_DIALOGUES,
  ...OWL_DIALOGUES,
  ...CAPYBARA_DIALOGUES,
  ...WOMBAT_DIALOGUES,
  ...RABBIT_DIALOGUES,
  ...TARSIER_DIALOGUES,
  ...AYE_AYE_DIALOGUES,
  ...KAKAPO_DIALOGUES,
];

/**
 * Get all dialogues for an animal up to a certain phase
 */
export function getDialoguesForAnimal(
  animalType: AnimalType,
  maxPhase: DialoguePhase
): Dialogue[] {
  return ALL_DIALOGUES.filter(
    d => d.animalType === animalType && d.phase <= maxPhase
  );
}

/**
 * Resolve a dialogue index to the first line at or after it that doesn't
 * reference a still-locked animal. Indices at or beyond the end of the pool
 * pass through unchanged (Phase 5 cycles rely on out-of-range indices).
 */
export function resolveDialogueIndex(
  animalType: AnimalType,
  index: number,
  maxPhase: DialoguePhase,
  unlockedTypes: Set<AnimalType>
): number {
  const dialogues = getDialoguesForAnimal(animalType, maxPhase);
  let i = Math.max(0, index);
  while (
    i < dialogues.length &&
    dialogues[i].requiresAnimals?.some(t => !unlockedTypes.has(t))
  ) {
    i++;
  }
  return i;
}

/**
 * Index of the first dialogue belonging to `phase` for an animal — i.e. how
 * many of its lines belong to earlier phases. Used to fast-forward animals
 * unlocked late so they don't replay bright-days small talk under a dark sky.
 */
export function getPhaseStartIndex(
  animalType: AnimalType,
  phase: DialoguePhase
): number {
  return ALL_DIALOGUES.filter(
    d => d.animalType === animalType && d.phase < phase
  ).length;
}

/**
 * Get the next unread dialogue for an animal
 */
export function getNextDialogue(
  animalType: AnimalType,
  currentIndex: number,
  maxPhase: DialoguePhase
): Dialogue | null {
  const dialogues = getDialoguesForAnimal(animalType, maxPhase);
  if (currentIndex >= dialogues.length - 1) {
    return null;
  }
  return dialogues[currentIndex + 1];
}

/**
 * Get current dialogue for an animal
 */
export function getCurrentDialogue(
  animalType: AnimalType,
  currentIndex: number,
  maxPhase: DialoguePhase
): Dialogue | null {
  const dialogues = getDialoguesForAnimal(animalType, maxPhase);
  if (dialogues.length === 0) {
    return null;
  }
  // Clamp index to valid range - show last dialogue if index exceeds available
  if (currentIndex < 0) {
    return dialogues[0];
  }
  if (currentIndex >= dialogues.length) {
    return dialogues[dialogues.length - 1];
  }
  return dialogues[currentIndex];
}

/**
 * Check if animal has more dialogues available
 */
export function hasMoreDialogues(
  animalType: AnimalType,
  currentIndex: number,
  maxPhase: DialoguePhase
): boolean {
  const dialogues = getDialoguesForAnimal(animalType, maxPhase);
  return currentIndex < dialogues.length - 1;
}

/**
 * Get total dialogue count for an animal at current phase
 */
export function getTotalDialogueCount(
  animalType: AnimalType,
  maxPhase: DialoguePhase
): number {
  return getDialoguesForAnimal(animalType, maxPhase).length;
}

// ============================================================================
// PHASE 2 EXHAUSTION POOL
// Phase 2 spans the longest stretch of the game (~80 puzzles); even with 22
// base lines per animal, chatty players exhaust the block and would re-read
// the last line verbatim for dozens of puzzles. These extra lines are served
// (in order, then cycling) once an animal's Phase-2 base block is exhausted
// while the player is still in Phase 2.
//
// CRITICAL: this pool is deliberately OUTSIDE the indexed base arrays.
// Existing players' lastDialogueRead indices point into ALL_DIALOGUES;
// inserting lines there would shift phase-start indices and corrupt saves.
// Pool lines never name another animal (they are ungated plain strings).
// ============================================================================

